class A4ControlError(RuntimeError):
    """Fail-closed control-contract violation."""


class A4EvalCursorAbsentError(A4ControlError):
    """Exact protocol signal: the current RUNNING eval has no committed cursor."""


def _linux_o_path_flag() -> int:
    """Return Linux O_PATH for CPython builds that omit the symbol."""

    if not sys.platform.startswith("linux") or not hasattr(os, "O_NOFOLLOW"):
        raise A4ControlError("DESCRIPTOR_WALK_PLATFORM_UNSUPPORTED")
    return int(getattr(os, "O_PATH", 0o10000000))


