def _require(condition: bool, message: str) -> None:
    if not condition:
        raise A4ControlError(message)


def _canonical_file_bytes(value: Any) -> bytes:
    return canonical_json_bytes(value) + b"\n"


def _with_semantic_sha(value: Mapping[str, Any], field: str) -> dict[str, Any]:
    payload = dict(value)
    _require(field not in payload, f"semantic hash field already present: {field}")
    payload[field] = semantic_sha256(payload, excluded_fields=(field,))
    return payload


def _read_canonical_json(path: Path, *, max_bytes: int = 256 * 1024 * 1024) -> tuple[Any, bytes]:
    data, _record = read_regular_bytes(path, max_bytes=max_bytes, require_nlink_one=True)
    try:
        value = json.loads(data.decode("utf-8", "strict"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise A4ControlError(f"invalid JSON artifact: {path}") from exc
    _require(data == _canonical_file_bytes(value), f"non-canonical JSON artifact: {path}")
    return value, data


def _read_canonical_json_without_newline(
    path: Path,
    *,
    max_bytes: int = 256 * 1024 * 1024,
) -> tuple[Any, bytes, dict[str, Any]]:
    """Read forward-owned canonical JSON, whose writer omits the file newline."""

    data, record = read_regular_bytes(
        path,
        max_bytes=max_bytes,
        require_nlink_one=True,
    )
    try:
        value = json.loads(data.decode("utf-8", "strict"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise A4ControlError(f"invalid no-newline JSON artifact: {path}") from exc
    _require(
        data == canonical_json_bytes(value),
        f"non-canonical no-newline JSON artifact: {path}",
    )
    return value, data, dict(record)


def _read_canonical_line(path: Path) -> tuple[dict[str, Any], bytes]:
    data, _record = read_regular_bytes(path, require_nlink_one=True)
    _require(data.endswith(b"\n") and data.count(b"\n") == 1, f"one JSONL record required: {path}")
    encoded = data[:-1]
    try:
        value = json.loads(encoded.decode("utf-8", "strict"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise A4ControlError(f"invalid JSONL artifact: {path}") from exc
    _require(isinstance(value, dict), f"JSONL object required: {path}")
    _require(encoded == canonical_json_bytes(value), f"non-canonical JSONL artifact: {path}")
    return value, data


def _path_is_within(parent: Path, child: Path) -> bool:
    try:
        child.relative_to(parent)
        return True
    except ValueError:
        return False


def _assert_safe_path_chain(path: Path) -> None:
    absolute = path if path.is_absolute() else path.absolute()
    current = Path(absolute.anchor)
    for component in absolute.parts[1:]:
        current /= component
        if not os.path.lexists(current):
            continue
        current_stat = current.lstat()
        _require(not stat.S_ISLNK(current_stat.st_mode), f"symlink path component forbidden: {current}")


def _open_directory(path: Path) -> int:
    _assert_safe_path_chain(path)
    _linux_o_path_flag()
    flags = (
        os.O_RDONLY
        | getattr(os, "O_CLOEXEC", 0)
        | os.O_DIRECTORY
        | os.O_NOFOLLOW
    )
    fd = os.open(path, flags)
    fst = os.fstat(fd)
    lst = path.lstat()
    if (
        not stat.S_ISDIR(fst.st_mode)
        or stat.S_ISLNK(lst.st_mode)
        or (fst.st_dev, fst.st_ino) != (lst.st_dev, lst.st_ino)
    ):
        os.close(fd)
        raise A4ControlError(f"stable directory required: {path}")
    return fd


def _fd_mount_id(fd: int) -> int:
    info_fd = os.open(
        f"/proc/self/fdinfo/{fd}",
        os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
    )
    try:
        raw = b""
        while True:
            chunk = os.read(info_fd, 8192)
            if not chunk:
                break
            raw += chunk
            _require(len(raw) <= 64 * 1024, "fdinfo exceeds limit")
    finally:
        os.close(info_fd)
    for line in raw.decode("ascii", "strict").splitlines():
        if line.startswith("mnt_id:"):
            value = line.split(":", 1)[1].strip()
            _require(value.isdigit(), "invalid fd mount id")
            return int(value)
    raise A4ControlError("fd mount id missing")


def _read_bound_regular(
    root: Path,
    relative: str,
    *,
    max_bytes: int,
    forbidden_identities: Optional[set[tuple[int, int]]] = None,
) -> tuple[bytes, dict[str, Any]]:
    """Open-by-dirfd with one mount identity and reject aliases before read."""

    o_path_flag = _linux_o_path_flag()
    rel = Path(relative)
    _require(
        relative == rel.as_posix()
        and not rel.is_absolute()
        and rel.parts
        and ".." not in rel.parts
        and "." not in rel.parts,
        f"unsafe bound relative path: {relative}",
    )
    root_fd = _open_directory(root)
    current_fd = root_fd
    root_stat = os.fstat(root_fd)
    root_mount = _fd_mount_id(root_fd)
    try:
        for component in rel.parts[:-1]:
            flags = (
                os.O_RDONLY
                | getattr(os, "O_CLOEXEC", 0)
                | os.O_DIRECTORY
                | os.O_NOFOLLOW
            )
            child_fd = os.open(component, flags, dir_fd=current_fd)
            child = os.fstat(child_fd)
            named = os.stat(component, dir_fd=current_fd, follow_symlinks=False)
            try:
                _require(stat.S_ISDIR(child.st_mode), "bound path component is not a directory")
                _require(
                    (child.st_dev, child.st_ino) == (named.st_dev, named.st_ino),
                    "bound directory identity race",
                )
                _require(child.st_dev == root_stat.st_dev, "bound path crosses device")
                _require(_fd_mount_id(child_fd) == root_mount, "bound path crosses mount")
            except BaseException:
                os.close(child_fd)
                raise
            if current_fd != root_fd:
                os.close(current_fd)
            current_fd = child_fd
        name = rel.parts[-1]
        named = os.stat(name, dir_fd=current_fd, follow_symlinks=False)
        _require(stat.S_ISREG(named.st_mode), "bound target is not regular")
        _require(named.st_nlink == 1, "bound target must have one hard link")
        _require(named.st_dev == root_stat.st_dev, "bound target crosses device")
        _require(named.st_size <= max_bytes, "bound target exceeds read cap")
        forbidden = forbidden_identities or set()
        _require(
            (int(named.st_dev), int(named.st_ino)) not in forbidden,
            "bound target aliases forbidden inode before metadata bind",
        )
        path_flags = (
            o_path_flag
            | getattr(os, "O_CLOEXEC", 0)
            | os.O_NOFOLLOW
        )
        path_fd = os.open(name, path_flags, dir_fd=current_fd)
        try:
            pinned = os.fstat(path_fd)
            _require(
                (pinned.st_dev, pinned.st_ino) == (named.st_dev, named.st_ino),
                "bound target metadata-bind identity race",
            )
            _require(
                pinned.st_nlink == 1 and stat.S_ISREG(pinned.st_mode),
                "bound target type drift before content open",
            )
            _require(
                pinned.st_dev == root_stat.st_dev
                and _fd_mount_id(path_fd) == root_mount,
                "bound target metadata bind crosses mount/device",
            )
            _require(
                pinned.st_size <= max_bytes,
                "bound target exceeds read cap before content open",
            )
            _require(
                (int(pinned.st_dev), int(pinned.st_ino)) not in forbidden,
                "bound target aliases forbidden inode after metadata bind",
            )
            content_fd = os.open(
                f"/proc/self/fd/{path_fd}",
                os.O_RDONLY | getattr(os, "O_CLOEXEC", 0),
            )
            try:
                before = os.fstat(content_fd)
                stable = (
                    "st_dev",
                    "st_ino",
                    "st_size",
                    "st_mtime_ns",
                    "st_ctime_ns",
                    "st_mode",
                    "st_nlink",
                )
                _require(
                    all(
                        getattr(before, field) == getattr(pinned, field)
                        for field in stable
                    ),
                    "bound content descriptor differs from metadata bind",
                )
                _require(
                    before.st_nlink == 1 and stat.S_ISREG(before.st_mode),
                    "bound target type drift at content open",
                )
                _require(
                    _fd_mount_id(content_fd) == root_mount,
                    "bound content descriptor crosses mount",
                )
                _require(
                    before.st_size <= max_bytes,
                    "bound target exceeds read cap at content open",
                )
                chunks: list[bytes] = []
                total = 0
                while True:
                    chunk = os.read(
                        content_fd,
                        min(1024 * 1024, max_bytes - total + 1),
                    )
                    if not chunk:
                        break
                    total += len(chunk)
                    _require(total <= max_bytes, "bound target exceeds read cap")
                    chunks.append(chunk)
                after = os.fstat(content_fd)
                pinned_after = os.fstat(path_fd)
                _require(
                    all(
                        getattr(before, field) == getattr(after, field)
                        == getattr(pinned_after, field)
                        for field in stable
                    ),
                    "bound target changed during read",
                )
                data = b"".join(chunks)
                _require(len(data) == after.st_size, "bound target short read")
                return data, {
                    "sha256": bytes_sha256(data),
                    "size_bytes": len(data),
                    "device": int(after.st_dev),
                    "inode": int(after.st_ino),
                    "nlink": int(after.st_nlink),
                    "mode": oct(stat.S_IMODE(after.st_mode)),
                    "mount_id": root_mount,
                }
            finally:
                os.close(content_fd)
        finally:
            os.close(path_fd)
    finally:
        if current_fd != root_fd:
            os.close(current_fd)
        os.close(root_fd)


def _read_bound_canonical_json(
    root: Path,
    relative: str,
    *,
    max_bytes: int,
    forbidden_identities: Optional[set[tuple[int, int]]] = None,
) -> tuple[Any, bytes, dict[str, Any]]:
    data, record = _read_bound_regular(
        root,
        relative,
        max_bytes=max_bytes,
        forbidden_identities=forbidden_identities,
    )
    try:
        value = json.loads(data.decode("utf-8", "strict"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise A4ControlError(f"invalid bound JSON: {root}/{relative}") from exc
    _require(data == _canonical_file_bytes(value), "bound JSON is not canonical")
    return value, data, record


def _read_exact_reviewed_json_object(
    root: Path,
    relative: str,
    *,
    expected_sha256: str,
    max_bytes: int,
    forbidden_identities: Optional[set[tuple[int, int]]] = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Hash a descriptor-bound reviewed file before any JSON decoding."""

    _require(
        isinstance(expected_sha256, str)
        and HEX64.fullmatch(expected_sha256) is not None,
        "reviewed JSON expected hash is invalid",
    )
    data, record = _read_bound_regular(
        root,
        relative,
        max_bytes=max_bytes,
        forbidden_identities=forbidden_identities,
    )
    _require(
        record["sha256"] == expected_sha256,
        f"reviewed JSON hash drift before decode: {relative}",
    )
    def reject_duplicates(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
        value: dict[str, Any] = {}
        for key, item in pairs:
            if key in value:
                raise ValueError(f"duplicate reviewed JSON key: {key}")
            value[key] = item
        return value

    def reject_nonfinite(token: str) -> None:
        raise ValueError(f"non-finite reviewed JSON number: {token}")

    try:
        value = json.loads(
            data.decode("utf-8", "strict"),
            object_pairs_hook=reject_duplicates,
            parse_constant=reject_nonfinite,
        )
    except (UnicodeDecodeError, json.JSONDecodeError, ValueError) as exc:
        raise A4ControlError(
            f"invalid exact reviewed JSON: {root}/{relative}"
        ) from exc
    _require(isinstance(value, dict), "exact reviewed JSON must be an object")
    return dict(value), record


def _assert_failed_a4_source_inode_absent(tree_root: Mapping[str, Any]) -> None:
    """Allow path reuse only when the quarantined failed inode stays absent."""

    if not os.path.lexists(CONTROL_ROOT):
        return
    current = CONTROL_ROOT.lstat()
    _require(
        stat.S_ISDIR(current.st_mode)
        and (int(current.st_dev), int(current.st_ino))
        != (tree_root.get("device"), tree_root.get("inode")),
        "failed A4 source inode returned to the live control root",
    )


