def _assert_a4_import_bytecode_absent() -> dict[str, Any]:
    """Reject every cache root/direct bytecode file in the six import roots."""

    _require(
        tuple(
            (package_root / "__pycache__")
            .relative_to(REPO_ROOT)
            .as_posix()
            for package_root in A4_IMPORT_BYTECODE_PACKAGE_ROOTS
        )
        == A4_IMPORT_BYTECODE_CACHE_RELATIVES,
        "A4 bytecode package/cache root binding",
    )
    for package_root, cache_relative in zip(
        A4_IMPORT_BYTECODE_PACKAGE_ROOTS,
        A4_IMPORT_BYTECODE_CACHE_RELATIVES,
    ):
        _assert_safe_path_chain(package_root)
        package_identity = package_root.lstat()
        _require(
            stat.S_ISDIR(package_identity.st_mode),
            f"A4 bytecode package root is not a directory: {package_root}",
        )
        cache_root = REPO_ROOT / cache_relative
        _require(
            not os.path.lexists(cache_root),
            f"A4 import bytecode cache root is present: {cache_root}",
        )
        with os.scandir(package_root) as iterator:
            direct_names = sorted(entry.name for entry in iterator)
        _require(
            not any(name.endswith(".pyc") for name in direct_names),
            f"A4 direct import bytecode is present: {package_root}",
        )
    return {
        "package_roots": [str(path) for path in A4_IMPORT_BYTECODE_PACKAGE_ROOTS],
        "cache_roots": list(A4_IMPORT_BYTECODE_CACHE_RELATIVES),
        "residual_cache_root_count": 0,
        "residual_direct_pyc_count": 0,
    }


def _rehash_a4_bytecode_quarantine() -> dict[str, Any]:
    """Rebuild the exact reversible quarantine inventory from its bytes."""

    quarantine_root = A4_BYTECODE_QUARANTINE_ROOT
    _require(
        not _path_is_within(REPO_ROOT, quarantine_root)
        and all(
            not _path_is_within(package_root, quarantine_root)
            for package_root in A4_IMPORT_BYTECODE_PACKAGE_ROOTS
        ),
        "A4 bytecode quarantine must be outside repo import roots",
    )
    _assert_safe_path_chain(quarantine_root)
    quarantine_identity = quarantine_root.lstat()
    _require(
        stat.S_ISDIR(quarantine_identity.st_mode),
        "A4 bytecode quarantine root is not a directory",
    )
    allowed_directories: set[str] = set()
    for cache_relative in A4_IMPORT_BYTECODE_CACHE_RELATIVES:
        current = Path()
        for part in Path(cache_relative).parts:
            current /= part
            allowed_directories.add(current.as_posix())

    observed_directories: set[str] = set()
    sha256sum_lines: list[bytes] = []
    file_count = 0
    total_bytes = 0
    cache_tags: set[str] = set()
    stack = [quarantine_root]
    while stack:
        directory = stack.pop()
        with os.scandir(directory) as iterator:
            entries = sorted(iterator, key=lambda entry: entry.name)
        child_directories: list[Path] = []
        for entry in entries:
            path = Path(entry.path)
            relative = path.relative_to(quarantine_root).as_posix()
            _require(
                not entry.is_symlink(),
                f"symlink forbidden in A4 bytecode quarantine: {relative}",
            )
            if entry.is_dir(follow_symlinks=False):
                _require(
                    relative in allowed_directories,
                    f"unexpected A4 bytecode quarantine directory: {relative}",
                )
                observed_directories.add(relative)
                child_directories.append(path)
                continue
            _require(
                entry.is_file(follow_symlinks=False)
                and Path(relative).parent.as_posix()
                in A4_IMPORT_BYTECODE_CACHE_RELATIVES
                and path.suffix == ".pyc",
                f"unexpected A4 bytecode quarantine object: {relative}",
            )
            data, record = read_regular_bytes(
                path,
                max_bytes=16 * 1024 * 1024,
                require_nlink_one=True,
            )
            tag_match = re.search(r"\.([A-Za-z0-9_-]+)\.pyc$", path.name)
            _require(
                tag_match is not None,
                f"A4 quarantined bytecode cache tag missing: {relative}",
            )
            cache_tags.add(tag_match.group(1))
            sha256sum_lines.append(
                f"{record['sha256']}  {relative}\n".encode("utf-8")
            )
            file_count += 1
            total_bytes += len(data)
        stack.extend(reversed(child_directories))
    _require(
        observed_directories == allowed_directories,
        "A4 bytecode quarantine directory closure",
    )
    inventory_sha256 = bytes_sha256(b"".join(sorted(sha256sum_lines)))
    _require(
        inventory_sha256 == A4_BYTECODE_QUARANTINE_INVENTORY_SHA256
        and file_count == A4_BYTECODE_QUARANTINE_FILE_COUNT
        and total_bytes == A4_BYTECODE_QUARANTINE_TOTAL_BYTES
        and cache_tags == {"cpython-313", "cpython-39"},
        "A4 bytecode quarantine inventory drift",
    )
    absence = _assert_a4_import_bytecode_absent()
    return {
        "quarantine_root": str(quarantine_root),
        "inventory_sha256": inventory_sha256,
        "inventory_count": file_count,
        "total_bytes": total_bytes,
        "source_cache_tags": sorted(cache_tags),
        "import_root_scope": list(A4_IMPORT_BYTECODE_CACHE_RELATIVES),
        "quarantine_root_outside_repo_import_tree": True,
        "residual_import_root_pyc_count": 0,
        "absence_registry": absence,
    }


def _validate_prebootstrap_audit() -> dict[str, Any]:
    """Bind the recorded pre-A4 authoring exceptions without reopening lineage artifacts."""

    relative = A4_PREBOOTSTRAP_AUDIT.relative_to(REPO_ROOT).as_posix()
    a3_root = A3_SUPERSEDED_CONTROL if A3_SUPERSEDED_CONTROL.is_dir() else CONTROL_ROOT
    payload, encoded, record = _read_bound_canonical_json(
        REPO_ROOT,
        relative,
        max_bytes=4 * 1024 * 1024,
        forbidden_identities=_protected_identities_from_a3(a3_root),
    )
    _require(isinstance(payload, dict), "pre-A4 audit object required")
    _require(payload.get("schema_version") == "c28f_a4_prebootstrap_audit_v1", "pre-A4 audit schema")
    _require(payload.get("goal_id") == GOAL_ID, "pre-A4 audit Goal")
    events = payload.get("events")
    _require(isinstance(events, list) and len(events) == 6, "pre-A4 audit event closure")
    by_id = {
        event.get("event_id"): event
        for event in events
        if isinstance(event, dict) and isinstance(event.get("event_id"), str)
    }
    _require(
        set(by_id)
        == {
            "PRE_A4_CONTROL_CONTRACT_GAP_001",
            "PRE_A4_STATIC_SEARCH_SCOPE_EXCEPTION_001",
            "PRE_A4_STATIC_SEARCH_SCOPE_EXCEPTION_002",
            "PRE_A4_BYTECODE_QUARANTINE_001",
            "PRE_A4_FAILED_G0_A4_QUARANTINE_001",
            "PRE_A4_FAILED_PRE_G1_A4_QUARANTINE_001",
        },
        "pre-A4 audit event identities",
    )
    search_exception = by_id["PRE_A4_STATIC_SEARCH_SCOPE_EXCEPTION_002"]
    _require(
        search_exception.get("current_disposition")
        == "RECORDED_PRE_A4_AUTHORING_EXCEPTION_ARTIFACT_EXCLUDED_FROM_ALL_LINEAGE_CONTINUE",
        "pre-A4 search exception disposition",
    )
    _require(
        search_exception.get("continuation_basis")
        == {
            "conditional_instruction": "先评估影响，如果无影响，就继续",
            "conditional_instruction_sha256": (
                "219ebc00ed159d20487064f1294a6e4ed569187d5ffd46fd27eb16427251f332"
            ),
            "condition_assessment": "SCIENTIFIC_IMPACT_NONE",
        },
        "pre-A4 continuation basis",
    )
    _require(
        search_exception.get("protected_content_stream_open_count") == "NONZERO_UNQUANTIFIED",
        "pre-A4 search exception open status",
    )
    _require(
        search_exception.get("scientific_decision_impact") == "NONE"
        and search_exception.get("model_forward_evaluations") == 0
        and search_exception.get("real_data_optimizer_updates") == 0,
        "pre-A4 search exception scientific disposition",
    )
    bytecode_event = by_id["PRE_A4_BYTECODE_QUARANTINE_001"]
    _require(
        bytecode_event
        == {
            "a4_python_executed_or_imported_during_quarantine": False,
            "action": (
                "MOVED_EXACT_PREEXISTING_PYC_SET_TO_REVERSIBLE_QUARANTINE_"
                "BEFORE_ANY_A4_PYTHON_EXECUTION"
            ),
            "current_disposition": (
                "QUARANTINED_OUTSIDE_IMPORT_ROOT_PENDING_FINAL_STATIC_REVIEW"
            ),
            "event_id": "PRE_A4_BYTECODE_QUARANTINE_001",
            "import_root_scope": list(A4_IMPORT_BYTECODE_CACHE_RELATIVES),
            "inventory_count": A4_BYTECODE_QUARANTINE_FILE_COUNT,
            "inventory_sha256": A4_BYTECODE_QUARANTINE_INVENTORY_SHA256,
            "model_forward_evaluations": 0,
            "protected_content_opens": 0,
            "quarantine_root": str(A4_BYTECODE_QUARANTINE_ROOT),
            "quarantine_root_outside_repo_import_tree": True,
            "real_data_optimizer_updates": 0,
            "residual_import_root_pyc_count": 0,
            "source_cache_tags_observed": ["cpython-313", "cpython-39"],
            "total_bytes": A4_BYTECODE_QUARANTINE_TOTAL_BYTES,
        },
        "pre-A4 bytecode quarantine event exact contract",
    )
    bytecode_quarantine = _rehash_a4_bytecode_quarantine()
    failed_a4_quarantine = _validate_failed_a4_quarantine_evidence()
    failed_pre_g1_quarantine = _validate_failed_pre_g1_quarantine_evidence()
    _require(
        by_id["PRE_A4_FAILED_G0_A4_QUARANTINE_001"]
        == failed_a4_quarantine,
        "pre-A4 failed genesis quarantine event exact contract",
    )
    _require(
        by_id["PRE_A4_FAILED_PRE_G1_A4_QUARANTINE_001"]
        == failed_pre_g1_quarantine,
        "pre-A4 failed pre-G1 quarantine event exact contract",
    )
    return {
        "path": relative,
        "sha256": record["sha256"],
        "size_bytes": len(encoded),
        "event_ids": sorted(by_id),
        "historical_content_open_status": "NONZERO_UNQUANTIFIED_RECORDED_EXCEPTION",
        "lineage_disposition": "EXCLUDED_FROM_ALL_A4_BASELINE_AND_REPLAY_LINEAGE",
        "excluded_path_prefixes": list(PRE_A4_LINEAGE_EXCLUDED_PREFIXES),
        "bytecode_quarantine": bytecode_quarantine,
        "failed_a4_quarantine": failed_a4_quarantine,
        "failed_pre_g1_quarantine": failed_pre_g1_quarantine,
    }


def _directory_identity(path: Path) -> dict[str, Any]:
    identity = lstat_identity(path)
    _require(identity["type"] == "directory", f"directory required: {path}")
    return {
        "device": int(identity["device"]),
        "inode": int(identity["inode"]),
        "mode": identity["mode"],
        "nlink": int(identity["nlink"]),
        "type": "directory",
    }


def _writer_lock_identity(fd: int, path: Path) -> dict[str, Any]:
    fst = os.fstat(fd)
    lst = path.lstat()
    _require(stat.S_ISREG(fst.st_mode), "writer lock must be a regular file")
    _require(not stat.S_ISLNK(lst.st_mode), "writer lock cannot be a symlink")
    _require(fst.st_nlink == 1, "writer lock must have one hard link")
    _require((fst.st_dev, fst.st_ino) == (lst.st_dev, lst.st_ino), "writer lock identity drift")
    os.lseek(fd, 0, os.SEEK_SET)
    data = os.read(fd, 128)
    _require(data == LOCK_HEADER, "writer lock header mismatch")
    return {
        "device": int(fst.st_dev),
        "inode": int(fst.st_ino),
        "mode": oct(stat.S_IMODE(fst.st_mode)),
        "nlink": int(fst.st_nlink),
        "header_sha256": bytes_sha256(data),
    }


def _acquire_fixed_writer(path: Path) -> tuple[int, dict[str, Any]]:
    _assert_safe_path_chain(path)
    flags = os.O_RDWR | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(path, flags)
    try:
        fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        return fd, _writer_lock_identity(fd, path)
    except BaseException:
        os.close(fd)
        raise


def _release_fixed_writer(fd: int) -> None:
    try:
        fcntl.flock(fd, fcntl.LOCK_UN)
    finally:
        os.close(fd)


def _walk_tree(
    root: Path,
    *,
    opaque_directories: Optional[set[str]] = None,
) -> tuple[list[str], list[dict[str, Any]], str]:
    """Return a symlink-free, content-addressed tree manifest.

    Directory paths exclude the root itself.  File records require nlink=1.
    """

    _assert_safe_path_chain(root)
    root_identity = root.lstat()
    _require(stat.S_ISDIR(root_identity.st_mode), f"tree root must be a directory: {root}")
    opaque = opaque_directories or set()
    directories: list[str] = []
    files: list[dict[str, Any]] = []
    stack = [root]
    while stack:
        directory = stack.pop()
        with os.scandir(directory) as iterator:
            entries = sorted(iterator, key=lambda item: item.name)
        child_directories: list[Path] = []
        for entry in entries:
            path = Path(entry.path)
            relative = path.relative_to(root).as_posix()
            _require(not entry.is_symlink(), f"tree symlink forbidden: {path}")
            if entry.is_dir(follow_symlinks=False):
                directories.append(relative)
                if relative not in opaque:
                    child_directories.append(path)
            elif entry.is_file(follow_symlinks=False):
                data, record = read_regular_bytes(path, require_nlink_one=True)
                files.append(
                    {
                        "path": relative,
                        "size_bytes": len(data),
                        "sha256": record["sha256"],
                    }
                )
            else:
                raise A4ControlError(f"unsupported object in control tree: {path}")
        stack.extend(reversed(child_directories))
    directories.sort()
    files.sort(key=lambda item: item["path"])
    domain = {
        "schema": "c28f_content_tree_v1",
        "directories": directories,
        "files": files,
    }
    return directories, files, bytes_sha256(canonical_json_bytes(domain))


def _opaque_inbox_file_count() -> int:
    """Count untrusted inbox files by lstat only; never open their content."""

    count = 0
    stack = [CONTROL_ROOT / "inbox"]
    while stack:
        directory = stack.pop()
        _assert_safe_path_chain(directory)
        with os.scandir(directory) as iterator:
            entries = sorted(iterator, key=lambda item: item.name)
        for entry in entries:
            _require(not entry.is_symlink(), f"untrusted inbox symlink forbidden: {entry.path}")
            if entry.is_dir(follow_symlinks=False):
                stack.append(Path(entry.path))
            elif entry.is_file(follow_symlinks=False):
                identity = Path(entry.path).lstat()
                _require(identity.st_nlink == 1, f"untrusted inbox hardlink forbidden: {entry.path}")
                count += 1
            else:
                raise A4ControlError(f"unsupported untrusted inbox object: {entry.path}")
    return count


def _expected_a3_namespace(event: Mapping[str, Any], state: Mapping[str, Any]) -> tuple[set[str], set[str]]:
    output_hashes = event.get("output_hashes")
    _require(isinstance(output_hashes, dict), "A3 event output_hashes missing")
    registry_names = {
        name for name in output_hashes if name not in {"artifact_manifest.root.sha256"}
    }
    expected_files = set(_A3_TOP_LEVEL_FILES)
    for name in registry_names:
        _require("/" not in name and name.endswith(".json"), f"unsafe A3 registry name: {name}")
        safe_name = name[:-5]
        expected_files.add(f"registry_records/000000_{safe_name}_{output_hashes[name]}.json")
    expected_files.update(
        {
            f"transactions/{A3_TRANSACTION_ID}/plan.json",
            f"state_records/000000_{state['state_sha256']}.json",
            f"event_records/000000_{event['event_sha256']}.jsonl",
        }
    )
    expected_directories = {
        "event_records",
        "registry_records",
        "state_records",
        "transactions",
        f"transactions/{A3_TRANSACTION_ID}",
    }
    return expected_files, expected_directories


def _validate_a3_heartbeat(root: Path, intent: Mapping[str, Any]) -> dict[str, Any]:
    heartbeat, _encoded = _read_canonical_json(root / "single_writer.heartbeat.json")
    required = {
        "schema_version",
        "goal_id",
        "lease_id",
        "lease_lineage_root_id",
        "status",
        "pid",
        "boot_id",
        "process_start_ticks",
        "action",
        "acquired_at_ns",
        "heartbeat_at_ns",
    }
    allowed = required | {"hostname", "previous_owner", "phase", "last_action_result"}
    _require(
        isinstance(heartbeat, dict)
        and required.issubset(heartbeat)
        and set(heartbeat).issubset(allowed),
        "A3 heartbeat schema missing",
    )
    _require(heartbeat["schema_version"] == "c28f_single_writer_lease_v2", "A3 heartbeat version")
    _require(heartbeat["goal_id"] == GOAL_ID, "A3 heartbeat Goal mismatch")
    _require(heartbeat["status"] == "IDLE", "A3 must be IDLE before supersession")
    _require(heartbeat["action"] == "G0_SCOPE_LOCK_ATTEMPT_3", "A3 heartbeat action mismatch")
    _require(
        heartbeat["lease_lineage_root_id"] == intent["writer_lease"]["lease_lineage_root_id"],
        "A3 writer lineage mismatch",
    )
    _require(isinstance(heartbeat["lease_id"], str) and HEX32.fullmatch(heartbeat["lease_id"]), "A3 lease id")
    _require(type(heartbeat["pid"]) is int and type(heartbeat["process_start_ticks"]) is int, "A3 process id")
    _require(type(heartbeat["acquired_at_ns"]) is int and type(heartbeat["heartbeat_at_ns"]) is int, "A3 times")
    _require(heartbeat.get("last_action_result") == "OK", "A3 last action was not successful")
    return heartbeat


def verify_a3_valid_nonextensible_closure(
    root: Path,
    *,
    held_writer_fd: Optional[int] = None,
) -> dict[str, Any]:
    """Verify A3 without importing or invoking the legacy namespace verifier."""

    _require(root in {CONTROL_ROOT, A3_SUPERSEDED_CONTROL}, f"unexpected A3 root: {root}")
    own_fd = held_writer_fd is None
    if own_fd:
        held_writer_fd, lock_identity = _acquire_fixed_writer(root / "single_writer.lock")
    else:
        _require(held_writer_fd is not None, "held A3 writer descriptor is required")
        lock_identity = _writer_lock_identity(held_writer_fd, root / "single_writer.lock")
    try:
        intent, intent_bytes = _read_canonical_json(root / "g0_bootstrap_intent.json")
        _require(bytes_sha256(intent_bytes) == A3_INTENT_FILE_SHA256, "A3 intent file hash mismatch")
        _require(isinstance(intent, dict), "A3 intent must be an object")
        _require(intent.get("attempt_id") == A3_ATTEMPT_ID, "A3 attempt mismatch")
        _require(intent.get("transaction_id") == A3_TRANSACTION_ID, "A3 transaction mismatch")
        _require(intent.get("goal_id") == GOAL_ID, "A3 Goal mismatch")
        _require(intent.get("intent_sha256") == A3_INTENT_SEMANTIC_SHA256, "A3 intent semantic lock")
        _require(
            semantic_sha256(intent, excluded_fields=("intent_sha256",)) == A3_INTENT_SEMANTIC_SHA256,
            "A3 intent semantic hash mismatch",
        )
        intent_root, _record = read_regular_bytes(
            root / "g0_bootstrap_intent.root.sha256", max_bytes=128, require_nlink_one=True
        )
        _require(intent_root == (A3_INTENT_FILE_SHA256 + "\n").encode("ascii"), "A3 intent detached root")
        _require(
            intent["bootstrap_business_inventory"]["business_delta_sha256"]
            == A3_BUSINESS_DELTA_SHA256,
            "A3 parent business lock mismatch",
        )

        expected_lock = intent["writer_lease"]
        for field in ("device", "inode", "mode", "nlink", "header_sha256"):
            _require(lock_identity[field] == expected_lock[field], f"A3 writer lock mismatch: {field}")
        heartbeat = _validate_a3_heartbeat(root, intent)

        state, state_bytes = _read_canonical_json(root / "GOAL_STATE.json")
        _require(bytes_sha256(state_bytes) == A3_STATE_FILE_SHA256, "A3 state file hash mismatch")
        _require(state.get("state_sha256") == A3_STATE_SHA256, "A3 state identity mismatch")
        _require(
            semantic_sha256(state, excluded_fields=("state_sha256",)) == A3_STATE_SHA256,
            "A3 state semantic hash mismatch",
        )
        required_state = {
            "attempt_id": A3_ATTEMPT_ID,
            "transaction_id": A3_TRANSACTION_ID,
            "goal_id": GOAL_ID,
            "status": "PREFLIGHT_OK",
            "stage": "G0",
            "next_action": "G1_FAIL_CLOSED_GUARD",
            "next_action_is_unique": True,
            "transition_seq": 0,
            "protected_model_evals": 0,
            "real_data_optimizer_updates": 0,
            "expected_goal_delta_sha256": A3_BUSINESS_DELTA_SHA256,
        }
        for field, expected in required_state.items():
            _require(state.get(field) == expected, f"A3 state field mismatch: {field}")
        _require(state.get("eval_token_states") == {"F0_A": "UNISSUED", "F0_B": "UNISSUED"}, "A3 tokens")
        _require(state.get("authority_summary") == AUTHORITY_SUMMARY, "A3 authority summary")

        event, event_bytes = _read_canonical_line(root / "GOAL_EVENTS.jsonl")
        _require(bytes_sha256(event_bytes) == A3_EVENT_FILE_SHA256, "A3 event file hash mismatch")
        _require(event.get("event_sha256") == A3_EVENT_SHA256, "A3 event identity mismatch")
        _require(
            semantic_sha256(event, excluded_fields=("event_sha256",)) == A3_EVENT_SHA256,
            "A3 event semantic hash mismatch",
        )
        _require(event.get("seq") == 0 and event.get("prev_event_sha256") is None, "A3 GENESIS chain")
        _require(event.get("attempt_id") == A3_ATTEMPT_ID, "A3 event attempt mismatch")
        _require(event.get("transaction_id") == A3_TRANSACTION_ID, "A3 event transaction mismatch")
        _require(event.get("expected_next_state_sha256") == A3_STATE_SHA256, "A3 event/state binding")
        _require(
            event.get("expected_goal_delta_sha256") == A3_BUSINESS_DELTA_SHA256,
            "A3 event/business binding",
        )
        _require(event.get("next_action") == "G1_FAIL_CLOSED_GUARD", "A3 event next action")

        state_record, _record = read_regular_bytes(
            root / "state_records" / f"000000_{A3_STATE_SHA256}.json",
            require_nlink_one=True,
        )
        event_record, _record = read_regular_bytes(
            root / "event_records" / f"000000_{A3_EVENT_SHA256}.jsonl",
            require_nlink_one=True,
        )
        _require(state_record == state_bytes, "A3 immutable state record mismatch")
        _require(event_record == event_bytes, "A3 immutable event record mismatch")

        plan, plan_bytes = _read_canonical_json(
            root / "transactions" / A3_TRANSACTION_ID / "plan.json"
        )
        _require(plan.get("transaction_id") == A3_TRANSACTION_ID, "A3 plan transaction mismatch")
        _require(plan.get("expected_state_sha256") == A3_STATE_SHA256, "A3 plan state mismatch")
        _require(
            plan.get("expected_business_delta_sha256") == A3_BUSINESS_DELTA_SHA256,
            "A3 plan business mismatch",
        )
        _require(
            plan.get("plan_sha256")
            == semantic_sha256(plan, excluded_fields=("plan_sha256",)),
            "A3 plan semantic hash mismatch",
        )
        _require(
            bytes_sha256(plan_bytes) == event["input_hashes"]["transaction_plan_file"],
            "A3 event/plan file binding",
        )

        for name, expected_sha in event["output_hashes"].items():
            data, record = read_regular_bytes(root / name, require_nlink_one=True)
            _require(record["sha256"] == expected_sha, f"A3 output hash mismatch: {name}")
            if name.endswith(".json"):
                payload = json.loads(data.decode("utf-8", "strict"))
                _require(data == _canonical_file_bytes(payload), f"A3 output non-canonical: {name}")
            if name != "artifact_manifest.root.sha256":
                safe_name = name[:-5]
                sidecar, _sidecar_record = read_regular_bytes(
                    root / "registry_records" / f"000000_{safe_name}_{expected_sha}.json",
                    require_nlink_one=True,
                )
                _require(sidecar == data, f"A3 registry sidecar mismatch: {name}")
        artifact, artifact_record = read_regular_bytes(
            root / "artifact_manifest.json", require_nlink_one=True
        )
        artifact_root, _record = read_regular_bytes(
            root / "artifact_manifest.root.sha256", max_bytes=128, require_nlink_one=True
        )
        _require(
            artifact_root == (artifact_record["sha256"] + "\n").encode("ascii"),
            "A3 artifact detached root mismatch",
        )
        _require(bool(artifact), "A3 artifact manifest cannot be empty")
        continuation, continuation_record = read_regular_bytes(
            root / "CONTINUATION.md", require_nlink_one=True
        )
        _require(bool(continuation), "A3 continuation cannot be empty")
        _require(
            continuation_record["sha256"] == A3_CONTINUATION_FILE_SHA256,
            "A3 continuation hash mismatch",
        )

        directories, files, tree_sha = _walk_tree(root)
        expected_files, expected_directories = _expected_a3_namespace(event, state)
        actual_files = {item["path"] for item in files}
        _require(actual_files == expected_files, "A3 file namespace is not exact")
        _require(set(directories) == expected_directories, "A3 directory namespace is not exact")
        _require(len(files) == 29 and len(directories) == 5, "A3 namespace cardinality mismatch")
        return {
            "schema_version": "c28f_a3_valid_nonextensible_closure_v1",
            "goal_id": GOAL_ID,
            "attempt_id": A3_ATTEMPT_ID,
            "transaction_id": A3_TRANSACTION_ID,
            "status": "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE",
            "parent_status_before_seal": "PREFLIGHT_OK",
            "parent_next_action_before_seal": "G1_FAIL_CLOSED_GUARD",
            "state_sha256": A3_STATE_SHA256,
            "event_sha256": A3_EVENT_SHA256,
            "business_delta_sha256": A3_BUSINESS_DELTA_SHA256,
            "control_tree_sha256": tree_sha,
            "file_count": len(files),
            "directory_count": len(directories),
            "root_identity": _directory_identity(root),
            "writer_lock_identity": lock_identity,
            "heartbeat_status": heartbeat["status"],
            "model_forward_evaluations": 0,
            "real_data_optimizer_updates": 0,
            "scientific_impact": "NONE",
        }
    finally:
        if own_fd and held_writer_fd is not None:
            _release_fixed_writer(held_writer_fd)


def _validate_review_party(
    records: Any,
    *,
    verdict: str,
    label: str,
    reviewed_files_sha256: str,
    receipt_review_subject_sha256: Optional[str] = None,
    minimum_count: int = 2,
    allow_main_thread_author: bool = False,
) -> set[str]:
    _require(
        isinstance(records, list) and len(records) >= minimum_count,
        f"at least {minimum_count} {label} required",
    )
    tasks: set[str] = set()
    for record in records:
        _require(isinstance(record, dict), f"invalid {label} record")
        exact_fields = {"task", "verdict", "reviewed_files_sha256"}
        if receipt_review_subject_sha256 is not None:
            exact_fields.add("receipt_review_subject_sha256")
        _require(set(record) == exact_fields, f"unexpected {label} fields")
        task = record.get("task")
        _require(
            isinstance(task, str)
            and (task.startswith("/root/") or task == "/root"),
            f"invalid {label} task",
        )
        _require(
            task not in A4_AUTHOR_TASKS
            or (allow_main_thread_author and task == "/root"),
            f"A4 author cannot be a {label}",
        )
        _require(record.get("verdict") == verdict, f"non-GO {label} verdict")
        _require(
            record.get("reviewed_files_sha256") == reviewed_files_sha256,
            f"{label} is not bound to final file hashes",
        )
        if receipt_review_subject_sha256 is not None:
            _require(
                record.get("receipt_review_subject_sha256")
                == receipt_review_subject_sha256,
                f"{label} is not bound to the exact receipt subject",
            )
        tasks.add(task)
    _require(len(tasks) == len(records), f"duplicate {label} task")
    return tasks


def _validate_a4_user_authorization_fixture() -> dict[str, Any]:
    protected = _protected_identities_from_a3(
        A3_SUPERSEDED_CONTROL
        if A3_SUPERSEDED_CONTROL.is_dir()
        else CONTROL_ROOT
    )
    relative = A4_USER_AUTHORIZATION_FIXTURE.relative_to(
        REPO_ROOT
    ).as_posix()
    value, encoded, record = _read_bound_canonical_json(
        REPO_ROOT,
        relative,
        max_bytes=64 * 1024,
        forbidden_identities=protected,
    )
    expected_scope = {
        "allow_control_contract_repair": True,
        "allow_establish_g0_a4": True,
        "allow_resume_existing_f0_f1_goal": True,
        "allow_supersede_valid_nonextensible_g0_a3": True,
        "allow_train_jsonl_descriptor_bound_index_bootstrap": True,
        "auth_f2_f5_prototype": False,
        "auth_f6_mechanism": False,
        "auth_f8_formal": False,
        "auth_git_branch_create_switch": False,
        "auth_git_commit": False,
        "auth_git_push_pr": False,
        "auth_holdout_official": False,
        "auth_protected_id_mapping_only": True,
        "index_bootstrap": {
            "allowed_decoded_fields": [
                "desc_id", "line_boundary", "offset", "length",
            ],
            "allowed_source_path": str(TRAIN_JSONL),
            "descriptor_bound": True,
            "full_file_sha256_same_pass": True,
            "model_forward_allowed": False,
            "official_eval_allowed": False,
            "physical_content_open_count": 1,
            "protected_eval_allowed": False,
            "read_only": True,
        },
        "post_index_access": {
            "allowed_query_roles": [
                "calib_select", "train_fit", "train_fit_route_dev",
            ],
            "allowed_role_projection_fields_by_purpose": {
                "FORWARD_QUERY_IDENTITY": [
                    "desc_id", "type", "desc_raw_json_sha256",
                ],
                "POST_FORWARD_EVAL_STATS": [
                    "desc_id", "desc", "type", "ts", "vid_name",
                ],
                "TRAIN_FIT_ROLE_MAPPING": ["desc_id", "vid_name"],
            },
            "all_field_decodes_separately_accounted": True,
            "all_physical_opens_separately_accounted": True,
            "exact_manifest_membership_required": True,
            "holdout_access_allowed": False,
            "official_access_allowed": False,
            "protected_id_mapping_only": {
                "allowed_fields": ["desc_id", "vid_name"],
                "exact_protected_desc_manifest_union_required": True,
                "model_forward_allowed": False,
            },
            "protected_model_eval_allowed": False,
            "random_access_only": True,
        },
        "real_data_optimizer_updates": 0,
    }
    authorizations = value.get("user_authorizations") if isinstance(value, dict) else None
    _require(
        isinstance(value, dict)
        and set(value)
        == {
            "schema_version", "goal_id", "source", "interpretation",
            "user_authorizations", "authorization_scope",
        }
        and value["schema_version"] == "c28f_a4_user_authorization_v2"
        and value["goal_id"] == GOAL_ID
        and value["source"] == "conversation_user_messages"
        and isinstance(value["interpretation"], str)
        and bool(value["interpretation"])
        and value["authorization_scope"] == expected_scope
        and authorizations
        == [
            {
                "authorization_id": "G0_A4_STRICT_REPAIR",
                "text": USER_A4_AUTHORIZATION_TEXT,
                "text_sha256": USER_A4_AUTHORIZATION_SHA256,
            },
            {
                "authorization_id": (
                    "TRAIN_JSONL_DESCRIPTOR_BOUND_INDEX_BOOTSTRAP"
                ),
                "text": TRAIN_JSONL_INDEX_AUTHORIZATION_TEXT,
                "text_sha256": TRAIN_JSONL_INDEX_AUTHORIZATION_SHA256,
            },
        ]
        and USER_A4_AUTHORIZATION_SHA256
        == bytes_sha256(USER_A4_AUTHORIZATION_TEXT.encode("utf-8"))
        and TRAIN_JSONL_INDEX_AUTHORIZATION_SHA256
        == bytes_sha256(TRAIN_JSONL_INDEX_AUTHORIZATION_TEXT.encode("utf-8")),
        "A4 user authorization v2 fixture exact contract",
    )
    return {
        "payload": dict(value),
        "file_sha256": record["sha256"],
        "size_bytes": len(encoded),
        "authorization_set_sha256": bytes_sha256(
            canonical_json_bytes(authorizations)
        ),
    }


def _a4_authorization_v2_binding() -> dict[str, Any]:
    fixture = _validate_a4_user_authorization_fixture()
    base = {
        "schema_version": "c28f_a4_authorization_binding_v2",
        "fixture_path": A4_USER_AUTHORIZATION_FIXTURE.relative_to(
            REPO_ROOT
        ).as_posix(),
        "fixture_file_sha256": fixture["file_sha256"],
        "fixture_size_bytes": fixture["size_bytes"],
        "fixture_schema_version": fixture["payload"]["schema_version"],
        "authorization_set_sha256": fixture[
            "authorization_set_sha256"
        ],
        "user_authorizations": fixture["payload"]["user_authorizations"],
    }
    return {**base, "binding_sha256": semantic_sha256(base)}


def _read_a4_pinned_git_blob(relative: str) -> bytes:
    """Read one exact reviewed source blob from the fixed parent commit."""

    _require(
        relative in A4_PINNED_GIT_REVIEWED_FILES,
        "unapproved A4 pinned Git source path",
    )
    try:
        completed = subprocess.run(
            ["git", "cat-file", "blob", f"{EXPECTED_HEAD}:{relative}"],
            cwd=REPO_ROOT,
            check=False,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=30,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise A4ControlError(
            f"cannot read fixed Git source blob: {relative}"
        ) from exc
    _require(
        completed.returncode == 0
        and bool(completed.stdout)
        and len(completed.stdout) <= 64 * 1024 * 1024,
        f"fixed Git source blob unavailable: {relative}",
    )
    return completed.stdout


def validate_a4_static_review_receipt() -> dict[str, Any]:
    a3_root = A3_SUPERSEDED_CONTROL if A3_SUPERSEDED_CONTROL.is_dir() else CONTROL_ROOT
    protected = _protected_identities_from_a3(a3_root)
    receipt_relative = A4_REVIEW_RECEIPT.relative_to(REPO_ROOT).as_posix()
    receipt, receipt_bytes, _receipt_record = _read_bound_canonical_json(
        REPO_ROOT,
        receipt_relative,
        max_bytes=4 * 1024 * 1024,
        forbidden_identities=protected,
    )
    _require(isinstance(receipt, dict), "A4 review receipt must be an object")
    _require(receipt.get("schema_version") == "c28f_a4_static_review_receipt_v5", "A4 receipt schema")
    _require(receipt.get("status") == "STATIC_GO", "A4 receipt status")
    _require(
        receipt.get("review_policy")
        == "SINGLE_MAIN_THREAD_STATIC_REVIEW_USER_WAIVER_V1"
        and receipt.get("user_waiver")
        == {
            "instruction": "把双静态审核取消",
            "scope": "DUAL_STATIC_AND_RECEIPT_REVIEW_REQUIREMENTS",
        },
        "A4 explicit user review-policy waiver",
    )
    _require(receipt.get("constraints") == REQUIRED_REVIEW_CONSTRAINTS, "A4 review constraints")
    prebootstrap_audit = _validate_prebootstrap_audit()
    prebootstrap_binding = {
        "path": prebootstrap_audit["path"],
        "sha256": prebootstrap_audit["sha256"],
        "size_bytes": prebootstrap_audit["size_bytes"],
        "event_ids": prebootstrap_audit["event_ids"],
        "failed_a4_quarantine_evidence_sha256": semantic_sha256(
            prebootstrap_audit["failed_a4_quarantine"]
        ),
        "failed_pre_g1_quarantine_evidence_sha256": semantic_sha256(
            prebootstrap_audit["failed_pre_g1_quarantine"]
        ),
    }
    _require(
        receipt.get("prebootstrap_audit_binding") == prebootstrap_binding,
        "A4 review receipt does not bind the prebootstrap exception audit",
    )
    _require(
        receipt.get("authority_hashes")
        == {
            "blueprint": EXPECTED_BLUEPRINT_SHA256,
            "goal_contract": EXPECTED_GOAL_CONTRACT_SHA256,
            "handoff": EXPECTED_HANDOFF_SHA256,
        },
        "A4 review authority hashes",
    )
    _require(
        receipt.get("authorization_v2_binding_sha256")
        == _a4_authorization_v2_binding()["binding_sha256"],
        "A4 review authorization-v2 binding mismatch",
    )
    _require(
        receipt.get("a3_parent")
        == {
            "attempt_id": A3_ATTEMPT_ID,
            "state_sha256": A3_STATE_SHA256,
            "event_sha256": A3_EVENT_SHA256,
            "business_delta_sha256": A3_BUSINESS_DELTA_SHA256,
            "disposition": "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE",
        },
        "A4 review parent lock mismatch",
    )
    _require(
        receipt.get("author_tasks") == sorted(A4_AUTHOR_TASKS),
        "A4 receipt author set mismatch",
    )
    reviewed = receipt.get("reviewed_files")
    _require(isinstance(reviewed, dict) and reviewed, "A4 reviewed_files missing")
    _require(set(reviewed) == A4_REQUIRED_REVIEWED_FILES, "A4 final reviewed-file set is not exact")
    reviewed_files_sha256 = bytes_sha256(canonical_json_bytes(dict(sorted(reviewed.items()))))
    _require(
        receipt.get("reviewed_files_sha256") == reviewed_files_sha256,
        "A4 reviewed-file map hash mismatch",
    )
    pinned_git_reviewed_files = dict(
        sorted(
            (path, reviewed[path])
            for path in A4_PINNED_GIT_REVIEWED_FILES
        )
    )
    inherited_reviewed_files = dict(
        sorted(
            (path, reviewed[path])
            for path in A4_INHERITED_REVIEWED_FILES
        )
    )
    added_reviewed_files = dict(
        sorted(
            (path, reviewed[path])
            for path in A4_REQUIRED_REVIEWED_FILES
            - A4_INHERITED_REVIEWED_FILES
        )
    )
    _require(
        receipt.get("reviewed_file_count") == A4_REVIEWED_FILE_COUNT
        and len(reviewed) == A4_REVIEWED_FILE_COUNT,
        "A4 reviewed file-count classification",
    )
    receipt_subject = dict(receipt)
    receipt_subject.pop("receipt_reviewers", None)
    receipt_subject.pop("receipt_review_subject_sha256", None)
    receipt_review_subject_sha256 = semantic_sha256(receipt_subject)
    _require(
        receipt.get("receipt_review_subject_sha256")
        == receipt_review_subject_sha256,
        "A4 receipt-review subject hash mismatch",
    )
    static_tasks = _validate_review_party(
        receipt.get("reviewers"),
        verdict="STATIC_GO",
        label="static reviewers",
        reviewed_files_sha256=reviewed_files_sha256,
        minimum_count=1,
        allow_main_thread_author=True,
    )
    _require(static_tasks == {"/root"}, "A4 single main-thread reviewer binding")
    _require(
        receipt.get("receipt_reviewers") == [],
        "A4 receipt review waived by explicit user instruction",
    )
    reviewed_records: dict[str, Any] = {}
    for relative, digest in reviewed.items():
        _require(isinstance(relative, str) and relative == Path(relative).as_posix(), "non-canonical review path")
        _require(".." not in Path(relative).parts and not Path(relative).is_absolute(), "unsafe review path")
        absolute = REPO_ROOT / relative
        allowed = _path_is_within(CODE_ROOT, absolute) or _path_is_within(TEST_ROOT, absolute)
        allowed = allowed or absolute == ENTRYPOINT
        allowed = allowed or relative in A4_PINNED_GIT_REVIEWED_FILES
        _require(allowed and absolute != A4_REVIEW_RECEIPT, f"review path outside code/test domain: {relative}")
        _require(isinstance(digest, str) and HEX64.fullmatch(digest), f"invalid reviewed hash: {relative}")
        data, record = _read_bound_regular(
            REPO_ROOT,
            relative,
            max_bytes=64 * 1024 * 1024,
            forbidden_identities=protected,
        )
        _require(bool(data) and record["sha256"] == digest, f"reviewed file drift: {relative}")
        if relative in A4_PINNED_GIT_REVIEWED_FILES:
            git_blob = _read_a4_pinned_git_blob(relative)
            _require(
                git_blob == data
                and bytes_sha256(git_blob) == digest,
                f"reviewed pinned Git source drift: {relative}",
            )
        reviewed_records[relative] = {
            "path": relative,
            "type": "regular_file",
            "size_bytes": len(data),
            "sha256": record["sha256"],
        }
    parent_intent, _intent_bytes, _intent_record = (
        _read_bound_canonical_json(
            a3_root,
            "g0_bootstrap_intent.json",
            max_bytes=8 * 1024 * 1024,
        )
    )
    parent_records = {
        item["path"]: dict(item)
        for item in parent_intent["bootstrap_business_inventory"][
            "entries"
        ]
        if not _excluded_from_a4_lineage(str(item["path"]))
    }
    inherited_records = {
        path: reviewed_records[path]
        for path in sorted(A4_INHERITED_REVIEWED_FILES)
    }
    added_records = {
        path: reviewed_records[path]
        for path in sorted(
            A4_REQUIRED_REVIEWED_FILES - A4_INHERITED_REVIEWED_FILES
        )
    }
    _require(
        all(
            path in parent_records
            and parent_records[path] == record
            for path, record in inherited_records.items()
        ),
        "A4 inherited dependency drift from sealed A3 parent",
    )
    _require(
        set(parent_records).isdisjoint(added_records),
        "A4 added review file replaces sealed A3 business",
    )
    _require(
        added_records[prebootstrap_audit["path"]]
        == {
            "path": prebootstrap_audit["path"],
            "type": "regular_file",
            "size_bytes": prebootstrap_audit["size_bytes"],
            "sha256": prebootstrap_audit["sha256"],
        },
        "A4 reviewed prebootstrap audit record",
    )
    return {
        "payload": receipt,
        "file_sha256": bytes_sha256(receipt_bytes),
        "size_bytes": len(receipt_bytes),
        "reviewed_records": reviewed_records,
        "inherited_reviewed_records": inherited_records,
        "added_reviewed_records": added_records,
    }


def read_g2_reviewed_metric_fixtures(
    *,
    bootstrap_lease: BootstrapLease,
) -> tuple[dict[str, Any], dict[str, Any]]:
    """Read only the two exact reviewed G2 fixtures under controller authority."""

    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "READ_G2_REVIEWED_METRIC_FIXTURES",
    ) as lease:
        verified = verify_a4_state(bootstrap_lease, active_lease=lease)
        _require(
            verified.get("status") == "FIREWALL_OK"
            and verified.get("next_action") == G2_ACTION
            and verified.get("next_action_is_unique") is True,
            "reviewed G2 fixtures require the exact G2 tail",
        )
        review = validate_a4_static_review_receipt()
        reviewed_files = review["payload"]["reviewed_files"]
        _require(
            isinstance(reviewed_files, dict)
            and all(
                relative in reviewed_files
                for relative in G2_REVIEWED_METRIC_FIXTURE_RELATIVES
            ),
            "G2 fixture review bindings are incomplete",
        )
        forbidden = _protected_identities_from_a3()
        values: list[dict[str, Any]] = []
        for relative in G2_REVIEWED_METRIC_FIXTURE_RELATIVES:
            value, _record = _read_exact_reviewed_json_object(
                REPO_ROOT,
                relative,
                expected_sha256=reviewed_files[relative],
                max_bytes=G2_REVIEWED_METRIC_FIXTURE_MAX_BYTES,
                forbidden_identities=forbidden,
            )
            values.append(value)
        verify_a4_state(bootstrap_lease, active_lease=lease)
        _require(len(values) == 2, "G2 fixture read cardinality")
        return values[0], values[1]


def _rebuild_reviewed_drift_exception(*, a3_root: Path) -> tuple[dict[str, Any], dict[str, Any]]:
    intent, _intent_bytes, _intent_record = _read_bound_canonical_json(
        a3_root,
        "g0_bootstrap_intent.json",
        max_bytes=8 * 1024 * 1024,
    )
    parent_inventory = intent["bootstrap_business_inventory"]
    _require(parent_inventory["business_delta_sha256"] == A3_BUSINESS_DELTA_SHA256, "A3 inventory")
    review = validate_a4_static_review_receipt()
    authorization_v2 = _a4_authorization_v2_binding()
    receipt_relative = A4_REVIEW_RECEIPT.relative_to(REPO_ROOT).as_posix()
    inherited_records = dict(review["inherited_reviewed_records"])
    added_records = dict(review["added_reviewed_records"])
    added_records[receipt_relative] = {
        "path": receipt_relative,
        "type": "regular_file",
        "size_bytes": review["size_bytes"],
        "sha256": review["file_sha256"],
    }
    audit = _validate_prebootstrap_audit()
    parent = {
        item["path"]: item
        for item in parent_inventory["entries"]
        if not _excluded_from_a4_lineage(str(item["path"]))
    }
    _require(
        all(
            path in parent and parent[path] == record
            for path, record in inherited_records.items()
        ),
        "inherited reviewed dependency differs from A3 parent",
    )
    _require(set(parent).isdisjoint(added_records), "reviewed drift attempts to replace A3 business")
    predicted_inventory = _inventory_from_entries(
        list(parent.values()) + list(added_records.values())
    )
    exception_base = {
        "schema_version": "c28f_reviewed_drift_exception_v2",
        "reason": "A3_GENESIS_DID_NOT_PRECOMMIT_AN_EXTENSIBLE_STAGE_CONTROLLER",
        "authorization": {
            "text": USER_A4_AUTHORIZATION_TEXT,
            "text_sha256": USER_A4_AUTHORIZATION_SHA256,
        },
        "authorization_v2_binding": authorization_v2,
        "parent_attempt_id": A3_ATTEMPT_ID,
        "parent_business_delta_sha256": A3_BUSINESS_DELTA_SHA256,
        "observed_pre_supersession_business_delta_sha256": predicted_inventory[
            "business_delta_sha256"
        ],
        "added_paths": sorted(added_records),
        "inherited_reviewed_paths": sorted(inherited_records),
        "inherited_reviewed_records": dict(sorted(inherited_records.items())),
        "inherited_reviewed_records_sha256": bytes_sha256(
            canonical_json_bytes(dict(sorted(inherited_records.items())))
        ),
        "added_records": dict(sorted(added_records.items())),
        "added_records_sha256": bytes_sha256(
            canonical_json_bytes(dict(sorted(added_records.items())))
        ),
        "reviewed_files": dict(sorted(review["payload"]["reviewed_files"].items())),
        "static_review_receipt_sha256": review["file_sha256"],
        "prebootstrap_audit": audit,
        "exclusions_enforced_for_a4_scientific_lineage": True,
        "pre_a4_content_open_exception_recorded": True,
        "existing_parent_file_mutations": 0,
        "existing_parent_file_deletions": 0,
        "scientific_impact": "NONE",
        "model_forward_evaluations": 0,
        "protected_content_opens_during_reviewed_drift_validation": 0,
        "real_data_optimizer_updates": 0,
    }
    return _with_semantic_sha(exception_base, "exception_sha256"), predicted_inventory


def verify_reviewed_drift_exception(
    a3_closure: Mapping[str, Any],
    *,
    a3_root: Path = CONTROL_ROOT,
) -> dict[str, Any]:
    _require(a3_closure.get("status") == "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE", "A3 closure")
    exception, predicted_inventory = _rebuild_reviewed_drift_exception(a3_root=a3_root)
    observed_without_a3 = _a4_business_inventory(
        forbidden_identities=_protected_identities_from_a3(a3_root)
    )
    _require(
        observed_without_a3 == predicted_inventory,
        "observed reviewed drift differs from exact rebuilt pre-supersession inventory",
    )
    return exception


def _rename_noreplace(source_parent: Path, source_name: str, target_parent: Path, target_name: str) -> None:
    source_fd = _open_directory(source_parent)
    target_fd = _open_directory(target_parent)
    try:
        libc = ctypes.CDLL(None, use_errno=True)
        renameat2 = getattr(libc, "renameat2", None)
        _require(renameat2 is not None, "renameat2 is required for A3 supersession")
        renameat2.argtypes = [ctypes.c_int, ctypes.c_char_p, ctypes.c_int, ctypes.c_char_p, ctypes.c_uint]
        renameat2.restype = ctypes.c_int
        result = renameat2(
            source_fd,
            os.fsencode(source_name),
            target_fd,
            os.fsencode(target_name),
            1,  # RENAME_NOREPLACE
        )
        if result != 0:
            error = ctypes.get_errno()
            if error == errno.EEXIST:
                raise A4ControlError("A3 supersession destination already exists")
            raise OSError(error, os.strerror(error))
        os.fsync(source_fd)
        os.fsync(target_fd)
    finally:
        os.close(target_fd)
        os.close(source_fd)


def _ensure_empty_supersession_target_parent() -> None:
    ensure_directory(A3_SUPERSEDED_PARENT)
    _assert_safe_path_chain(A3_SUPERSEDED_PARENT)
    identity = A3_SUPERSEDED_PARENT.lstat()
    _require(stat.S_ISDIR(identity.st_mode), "supersession target parent is not a directory")
    with os.scandir(A3_SUPERSEDED_PARENT) as iterator:
        entries = sorted(entry.name for entry in iterator)
    _require(entries == [], f"supersession target parent is polluted: {entries}")
    _require(
        identity.st_dev == REPORT_ROOT.lstat().st_dev,
        "supersession target parent crosses device",
    )


def _install_capability_file(path: Path, data: bytes) -> None:
    """Install an immutable file under the already-held bootstrap/old-writer locks."""

    _assert_safe_path_chain(path.parent)
    parent_fd = _open_directory(path.parent)
    digest = bytes_sha256(data)
    tmp_name = f".{path.name}.capability.{digest}"
    flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    try:
        try:
            tmp_fd = os.open(tmp_name, flags, 0o600, dir_fd=parent_fd)
        except FileExistsError:
            tmp_fd = None
            stale_fd = os.open(
                tmp_name,
                os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
                dir_fd=parent_fd,
            )
            try:
                stale_data = b""
                while True:
                    chunk = os.read(stale_fd, 1024 * 1024)
                    if not chunk:
                        break
                    stale_data += chunk
            finally:
                os.close(stale_fd)
            if stale_data != data:
                try:
                    os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
                except FileNotFoundError:
                    os.unlink(tmp_name, dir_fd=parent_fd)
                    os.fsync(parent_fd)
                    tmp_fd = os.open(tmp_name, flags, 0o600, dir_fd=parent_fd)
                else:
                    raise A4ControlError("receipt recovery temp differs beside installed target")
        if tmp_fd is not None:
            try:
                view = memoryview(data)
                offset = 0
                while offset < len(view):
                    written = os.write(tmp_fd, view[offset:])
                    _require(written > 0, "receipt write made no progress")
                    offset += written
                os.fsync(tmp_fd)
            finally:
                os.close(tmp_fd)
        temp_fd = os.open(
            tmp_name,
            os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | getattr(os, "O_NOFOLLOW", 0),
            dir_fd=parent_fd,
        )
        try:
            temp_data = b""
            while True:
                chunk = os.read(temp_fd, 1024 * 1024)
                if not chunk:
                    break
                temp_data += chunk
            _require(temp_data == data, "receipt recovery temp mismatch")
        finally:
            os.close(temp_fd)
        try:
            os.link(tmp_name, path.name, src_dir_fd=parent_fd, dst_dir_fd=parent_fd, follow_symlinks=False)
        except FileExistsError:
            try:
                os.unlink(tmp_name, dir_fd=parent_fd)
            except FileNotFoundError:
                pass
            os.fsync(parent_fd)
            existing, _record = read_regular_bytes(path, require_nlink_one=True)
            _require(existing == data, "immutable receipt target differs")
        else:
            os.fsync(parent_fd)
            os.unlink(tmp_name, dir_fd=parent_fd)
        os.fsync(parent_fd)
    finally:
        os.close(parent_fd)


def _finalize_capability_link(path: Path) -> None:
    """Remove only a same-inode deterministic receipt temp left after link+fsync."""

    parent_fd = _open_directory(path.parent)
    prefix = f".{path.name}.capability."
    try:
        target = os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
        _require(stat.S_ISREG(target.st_mode), "capability target must be regular")
        with os.scandir(path.parent) as iterator:
            temps = sorted(entry.name for entry in iterator if entry.name.startswith(prefix))
        _require(len(temps) <= 1, "multiple capability recovery temps")
        if temps:
            temp = os.stat(temps[0], dir_fd=parent_fd, follow_symlinks=False)
            _require(
                (temp.st_dev, temp.st_ino) == (target.st_dev, target.st_ino),
                "capability recovery temp is not target hardlink",
            )
            os.unlink(temps[0], dir_fd=parent_fd)
            os.fsync(parent_fd)
        final = os.stat(path.name, dir_fd=parent_fd, follow_symlinks=False)
        _require(final.st_nlink == 1, "capability target must have one hard link")
    finally:
        os.close(parent_fd)


def _build_supersession_receipt(
    closure: Mapping[str, Any],
    reviewed_exception: Mapping[str, Any],
) -> dict[str, Any]:
    receipt_base = {
        "schema_version": "c28f_g0_a3_valid_supersession_receipt_v1",
        "goal_id": GOAL_ID,
        "authorization": {
            "text": USER_A4_AUTHORIZATION_TEXT,
            "text_sha256": USER_A4_AUTHORIZATION_SHA256,
        },
        "authorization_v2_binding": _a4_authorization_v2_binding(),
        "attempt_id": A3_ATTEMPT_ID,
        "transaction_id": A3_TRANSACTION_ID,
        "source_control_root": str(CONTROL_ROOT),
        "superseded_control_root": str(A3_SUPERSEDED_CONTROL),
        "disposition": "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE",
        "parent_status_before_seal": "PREFLIGHT_OK",
        "parent_next_action_before_seal": "G1_FAIL_CLOSED_GUARD",
        "state_sha256": A3_STATE_SHA256,
        "event_sha256": A3_EVENT_SHA256,
        "business_delta_sha256": A3_BUSINESS_DELTA_SHA256,
        "control_tree_sha256": closure["control_tree_sha256"],
        "control_tree_file_count": closure["file_count"],
        "control_tree_directory_count": closure["directory_count"],
        "preserved_root_identity": closure["root_identity"],
        "old_writer_lock_identity": closure["writer_lock_identity"],
        "old_writer_lock_held_through_receipt": True,
        "bootstrap_lock_held_through_receipt": True,
        "migration_method": "renameat2(RENAME_NOREPLACE)",
        "source_parent_fsynced": True,
        "target_parent_fsynced": True,
        "target_precondition": "MUST_BE_ABSENT",
        "reviewed_drift_exception": reviewed_exception,
        "prebootstrap_audit": _validate_prebootstrap_audit(),
        "valid_parent_not_quarantine": True,
        "scientific_impact": "NONE",
        "model_forward_evaluations": 0,
        "protected_content_opens_during_supersession": 0,
        "real_data_optimizer_updates": 0,
        "eval_token_states": {"F0_A": "UNISSUED", "F0_B": "UNISSUED"},
    }
    return _with_semantic_sha(receipt_base, "receipt_sha256")


def _read_a3_carry_forward_locked() -> dict[str, Any]:
    payloads: dict[str, Any] = {}
    for name in ("authority_ledger.json", "budget.json", "gate_registry.json"):
        payload, encoded, record = _read_bound_canonical_json(
            A3_SUPERSEDED_CONTROL,
            name,
            max_bytes=8 * 1024 * 1024,
        )
        payloads[name] = {
            "payload": payload,
            "file_sha256": record["sha256"],
            "size_bytes": len(encoded),
        }
    return payloads


def _validate_frozen_a3_supersession_receipt(
    receipt: Mapping[str, Any],
    *,
    receipt_file_sha256: str,
    closure: Mapping[str, Any],
) -> None:
    """Validate the immutable A3 receipt without consulting mutable A4 review state."""

    _require(
        receipt_file_sha256 == A3_SUPERSESSION_RECEIPT_FILE_SHA256,
        "frozen A3 supersession receipt file hash",
    )
    _require(
        receipt.get("receipt_sha256") == A3_SUPERSESSION_RECEIPT_SHA256
        == semantic_sha256(receipt, excluded_fields=("receipt_sha256",)),
        "frozen A3 supersession receipt self hash",
    )
    _require(
        {
            "schema_version": receipt.get("schema_version"),
            "goal_id": receipt.get("goal_id"),
            "attempt_id": receipt.get("attempt_id"),
            "transaction_id": receipt.get("transaction_id"),
            "source_control_root": receipt.get("source_control_root"),
            "superseded_control_root": receipt.get("superseded_control_root"),
            "disposition": receipt.get("disposition"),
            "parent_status_before_seal": receipt.get("parent_status_before_seal"),
            "parent_next_action_before_seal": receipt.get("parent_next_action_before_seal"),
            "state_sha256": receipt.get("state_sha256"),
            "event_sha256": receipt.get("event_sha256"),
            "business_delta_sha256": receipt.get("business_delta_sha256"),
        }
        == {
            "schema_version": "c28f_g0_a3_valid_supersession_receipt_v1",
            "goal_id": GOAL_ID,
            "attempt_id": A3_ATTEMPT_ID,
            "transaction_id": A3_TRANSACTION_ID,
            "source_control_root": str(CONTROL_ROOT),
            "superseded_control_root": str(A3_SUPERSEDED_CONTROL),
            "disposition": "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE",
            "parent_status_before_seal": "PREFLIGHT_OK",
            "parent_next_action_before_seal": "G1_FAIL_CLOSED_GUARD",
            "state_sha256": A3_STATE_SHA256,
            "event_sha256": A3_EVENT_SHA256,
            "business_delta_sha256": A3_BUSINESS_DELTA_SHA256,
        },
        "frozen A3 supersession receipt identity",
    )
    _require(
        receipt.get("authorization")
        == {
            "text": USER_A4_AUTHORIZATION_TEXT,
            "text_sha256": USER_A4_AUTHORIZATION_SHA256,
        }
        and isinstance(receipt.get("authorization_v2_binding"), dict)
        and receipt["authorization_v2_binding"].get("binding_sha256")
        == A3_SUPERSESSION_AUTHORIZATION_V2_BINDING_SHA256,
        "frozen A3 supersession authorization",
    )
    _require(
        receipt.get("control_tree_sha256") == closure.get("control_tree_sha256")
        and receipt.get("control_tree_file_count") == closure.get("file_count")
        and receipt.get("control_tree_directory_count") == closure.get("directory_count")
        and receipt.get("preserved_root_identity") == closure.get("root_identity")
        and receipt.get("old_writer_lock_identity") == closure.get("writer_lock_identity"),
        "frozen A3 supersession closure binding",
    )
    audit = receipt.get("prebootstrap_audit")
    reviewed_exception = receipt.get("reviewed_drift_exception")
    _require(
        isinstance(audit, dict)
        and audit.get("sha256") == A3_SUPERSESSION_PREBOOTSTRAP_AUDIT_SHA256
        and audit.get("event_ids") == list(A3_SUPERSESSION_PREBOOTSTRAP_EVENT_IDS),
        "frozen A3 supersession prebootstrap audit",
    )
    _require(
        isinstance(reviewed_exception, dict)
        and reviewed_exception.get("exception_sha256")
        == A3_SUPERSESSION_EXCEPTION_SHA256
        == semantic_sha256(
            reviewed_exception,
            excluded_fields=("exception_sha256",),
        )
        and reviewed_exception.get("static_review_receipt_sha256")
        == A3_SUPERSESSION_STATIC_REVIEW_RECEIPT_SHA256
        and reviewed_exception.get("prebootstrap_audit") == audit,
        "frozen A3 reviewed-drift exception",
    )
    _require(
        all(
            receipt.get(field) is True
            for field in (
                "old_writer_lock_held_through_receipt",
                "bootstrap_lock_held_through_receipt",
                "source_parent_fsynced",
                "target_parent_fsynced",
                "valid_parent_not_quarantine",
            )
        )
        and receipt.get("migration_method") == "renameat2(RENAME_NOREPLACE)"
        and receipt.get("target_precondition") == "MUST_BE_ABSENT"
        and receipt.get("scientific_impact") == "NONE"
        and receipt.get("model_forward_evaluations") == 0
        and receipt.get("protected_content_opens_during_supersession") == 0
        and receipt.get("real_data_optimizer_updates") == 0
        and receipt.get("eval_token_states")
        == {"F0_A": "UNISSUED", "F0_B": "UNISSUED"},
        "frozen A3 supersession safety assertions",
    )


def _validate_supersession_receipt(bootstrap_lease: BootstrapLease) -> dict[str, Any]:
    bootstrap_lease.assert_active_capability()
    _require(A3_SUPERSEDED_CONTROL.is_dir(), "superseded A3 control tree missing")
    writer_fd: Optional[int] = None
    try:
        writer_fd, _identity = _acquire_fixed_writer(A3_SUPERSEDED_CONTROL / "single_writer.lock")
        _finalize_capability_link(A3_SUPERSESSION_RECEIPT)
        closure = verify_a3_valid_nonextensible_closure(
            A3_SUPERSEDED_CONTROL,
            held_writer_fd=writer_fd,
        )
        protected = _protected_identities_from_a3(A3_SUPERSEDED_CONTROL)
        receipt, receipt_bytes, receipt_record = _read_bound_canonical_json(
            A3_SUPERSEDED_PARENT,
            "SUPERSESSION_RECEIPT.json",
            max_bytes=4 * 1024 * 1024,
            forbidden_identities=protected,
        )
        _validate_frozen_a3_supersession_receipt(
            receipt,
            receipt_file_sha256=receipt_record["sha256"],
            closure=closure,
        )
        carry_forward = _read_a3_carry_forward_locked()
        bootstrap_lease.assert_active_capability()
        _writer_lock_identity(writer_fd, A3_SUPERSEDED_CONTROL / "single_writer.lock")
        return {
            "closure": closure,
            "payload": receipt,
            "file_sha256": receipt_record["sha256"],
            "size_bytes": len(receipt_bytes),
            "carry_forward": carry_forward,
        }
    finally:
        if writer_fd is not None:
            _release_fixed_writer(writer_fd)


def seal_a3_as_valid_nonextensible(bootstrap_lease: BootstrapLease) -> dict[str, Any]:
    """Atomically move A3 to the non-quarantine superseded namespace."""

    bootstrap_lease.assert_active_capability()
    _require(CONTROL_ROOT.is_dir(), "live A3 control root missing")
    _require(not os.path.lexists(A3_SUPERSEDED_CONTROL), "superseded A3 target must be absent")
    old_writer_fd, _identity = _acquire_fixed_writer(CONTROL_ROOT / "single_writer.lock")
    try:
        closure = verify_a3_valid_nonextensible_closure(
            CONTROL_ROOT,
            held_writer_fd=old_writer_fd,
        )
        reviewed_exception = verify_reviewed_drift_exception(closure)
        _ensure_empty_supersession_target_parent()
        source_parent_identity = _directory_identity(REPORT_ROOT)
        target_parent_identity = _directory_identity(A3_SUPERSEDED_PARENT)
        _require(
            source_parent_identity["device"] == target_parent_identity["device"],
            "A3 supersession must remain on one filesystem",
        )
        root_identity_before = closure["root_identity"]
        bootstrap_lease.assert_active_capability()
        _writer_lock_identity(old_writer_fd, CONTROL_ROOT / "single_writer.lock")
        _rename_noreplace(REPORT_ROOT, "goal_control", A3_SUPERSEDED_PARENT, "goal_control")
        bootstrap_lease.assert_active_capability()
        _require(_directory_identity(A3_SUPERSEDED_CONTROL) == root_identity_before, "A3 rename identity")
        _writer_lock_identity(old_writer_fd, A3_SUPERSEDED_CONTROL / "single_writer.lock")
        post_closure = verify_a3_valid_nonextensible_closure(
            A3_SUPERSEDED_CONTROL,
            held_writer_fd=old_writer_fd,
        )
        _require(post_closure["control_tree_sha256"] == closure["control_tree_sha256"], "A3 tree changed")
        receipt = _build_supersession_receipt(post_closure, reviewed_exception)
        _install_capability_file(A3_SUPERSESSION_RECEIPT, _canonical_file_bytes(receipt))
        fsync_directory(REPORT_ROOT)
        fsync_directory(A3_SUPERSEDED_PARENT)
        bootstrap_lease.assert_active_capability()
        _writer_lock_identity(old_writer_fd, A3_SUPERSEDED_CONTROL / "single_writer.lock")
        receipt_payload, receipt_bytes, receipt_record = _read_bound_canonical_json(
            A3_SUPERSEDED_PARENT,
            "SUPERSESSION_RECEIPT.json",
            max_bytes=4 * 1024 * 1024,
            forbidden_identities=_protected_identities_from_a3(A3_SUPERSEDED_CONTROL),
        )
        _require(receipt_payload == receipt, "new supersession receipt differs from full rebuild")
        carry_forward = _read_a3_carry_forward_locked()
        return {
            "closure": post_closure,
            "payload": receipt_payload,
            "file_sha256": receipt_record["sha256"],
            "size_bytes": len(receipt_bytes),
            "carry_forward": carry_forward,
        }
    finally:
        _release_fixed_writer(old_writer_fd)


def _hash_authority_files() -> dict[str, Any]:
    authorities = {
        "goal_contract": (GOAL_CONTRACT, EXPECTED_GOAL_CONTRACT_SHA256),
        "blueprint": (BLUEPRINT, EXPECTED_BLUEPRINT_SHA256),
        "handoff": (HANDOFF, EXPECTED_HANDOFF_SHA256),
        "checkpoint": (CHECKPOINT, EXPECTED_CHECKPOINT_SHA256),
    }
    records: dict[str, Any] = {}
    for name, (path, expected_sha) in authorities.items():
        data, record = read_regular_bytes(path, require_nlink_one=True)
        _require(record["sha256"] == expected_sha, f"authority drift: {name}")
        records[name] = {
            "path": str(path),
            "sha256": record["sha256"],
            "size_bytes": len(data),
            "device": int(record["device"]),
            "inode": int(record["inode"]),
            "access_mode": "FULL_BYTES_SHA256_ONLY",
            "bytes_hashed": len(data),
            "deserialized": False,
            "model_forward": False,
        }
    return records


def _validate_authority_files_without_checkpoint_rehash(records: Mapping[str, Any]) -> None:
    expected = {
        "goal_contract": (GOAL_CONTRACT, EXPECTED_GOAL_CONTRACT_SHA256),
        "blueprint": (BLUEPRINT, EXPECTED_BLUEPRINT_SHA256),
        "handoff": (HANDOFF, EXPECTED_HANDOFF_SHA256),
        "checkpoint": (CHECKPOINT, EXPECTED_CHECKPOINT_SHA256),
    }
    _require(set(records) == set(expected), "authority record set mismatch")
    for name, (path, expected_sha) in expected.items():
        declared = records[name]
        _require(declared.get("path") == str(path), f"authority path drift: {name}")
        _require(declared.get("sha256") == expected_sha, f"authority hash declaration: {name}")
        _require(declared.get("access_mode") == "FULL_BYTES_SHA256_ONLY", f"authority access mode: {name}")
        _require(declared.get("bytes_hashed") == declared.get("size_bytes"), f"authority byte count: {name}")
        _require(declared.get("deserialized") is False, f"authority deserialize flag: {name}")
        _require(declared.get("model_forward") is False, f"authority forward flag: {name}")
        if name == "checkpoint":
            identity = lstat_identity(path)
            _require(
                identity["type"] == "file"
                and identity["nlink"] == 1
                and identity["size_bytes"] == declared["size_bytes"]
                and int(identity["device"]) == declared["device"]
                and int(identity["inode"]) == declared["inode"],
                "checkpoint metadata drift after recorded full hash",
            )
        else:
            data, observed = read_regular_bytes(path, require_nlink_one=True)
            _require(
                observed["sha256"] == expected_sha
                and len(data) == declared["size_bytes"]
                and int(observed["device"]) == declared["device"]
                and int(observed["inode"]) == declared["inode"],
                f"authority drift: {name}",
            )


def _git_identity() -> dict[str, str]:
    values: dict[str, str] = {}
    commands = {
        "branch": ["git", "branch", "--show-current"],
        "head": ["git", "rev-parse", "HEAD"],
    }
    for name, argv in commands.items():
        try:
            completed = subprocess.run(
                argv,
                cwd=REPO_ROOT,
                check=False,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                timeout=30,
            )
        except (OSError, subprocess.TimeoutExpired) as exc:
            raise A4ControlError(f"cannot obtain git {name}") from exc
        _require(completed.returncode == 0, f"cannot obtain git {name}")
        try:
            value = completed.stdout.decode("utf-8", "strict").strip()
        except UnicodeDecodeError as exc:
            raise A4ControlError(f"non-UTF8 git {name}") from exc
        _require(bool(value) and "\n" not in value, f"invalid git {name}")
        values[name] = value
    _require(values["branch"] == "c28e-code-review-clip-late-interaction", "branch drift")
    _require(values["head"] == "3ee00135cc00c9763d616fa1b49c64206742a007", "HEAD drift")
    return values


def _protected_identities_from_a3(
    root: Path = A3_SUPERSEDED_CONTROL,
) -> set[tuple[int, int]]:
    _require(root in {CONTROL_ROOT, A3_SUPERSEDED_CONTROL}, "unexpected A3 metadata root")
    intent, _encoded, _record = _read_bound_canonical_json(
        root,
        "g0_bootstrap_intent.json",
        max_bytes=8 * 1024 * 1024,
    )
    records = intent["immutable_lock"]["protected_registry"]["records"]
    _require(isinstance(records, list), "A3 protected metadata registry missing")
    identities: set[tuple[int, int]] = set()
    for record in records:
        if not isinstance(record, dict) or not record.get("exists"):
            continue
        device = record.get("device")
        inode = record.get("inode")
        if type(device) is int and type(inode) is int:
            identities.add((device, inode))
    _require(bool(identities), "A3 protected inode registry is unexpectedly empty")
    return identities


def _a4_business_inventory(
    *, forbidden_identities: set[tuple[int, int]]
) -> dict[str, Any]:
    """Hash only A4 lineage bytes; excluded history is skipped before content open."""

    _assert_a4_import_bytecode_absent()
    paths: list[Path] = []
    for root in (CODE_ROOT, TEST_ROOT, REPORT_ROOT, CACHE_ROOT, CHECKPOINT_ROOT):
        if not os.path.lexists(root):
            continue
        root_identity = root.lstat()
        _require(stat.S_ISDIR(root_identity.st_mode), f"business root is not a directory: {root}")
        stack = [root]
        while stack:
            directory = stack.pop()
            with os.scandir(directory) as iterator:
                entries = sorted(iterator, key=lambda entry: entry.name)
            child_directories: list[Path] = []
            for entry in entries:
                path = Path(entry.path)
                relative = path.relative_to(REPO_ROOT).as_posix()
                _require(not entry.is_symlink(), f"business symlink forbidden: {path}")
                if _excluded_from_a4_lineage(relative):
                    continue
                if path == CONTROL_ROOT or CONTROL_ROOT in path.parents:
                    continue
                if entry.is_dir(follow_symlinks=False):
                    _require(entry.name != "__pycache__", f"bytecode cache forbidden: {path}")
                    child_directories.append(path)
                elif entry.is_file(follow_symlinks=False):
                    _require(path.suffix != ".pyc", f"Python bytecode forbidden: {path}")
                    if path != BOOTSTRAP_LOCK and ".tmp." not in path.name:
                        paths.append(path)
                else:
                    raise A4ControlError(f"unsupported business object: {path}")
            stack.extend(reversed(child_directories))
    if os.path.lexists(ENTRYPOINT):
        paths.append(ENTRYPOINT)
    paths.extend(
        REPO_ROOT / relative
        for relative in sorted(A4_PINNED_GIT_REVIEWED_FILES)
    )
    entries: list[dict[str, Any]] = []
    for path in sorted(set(paths), key=lambda item: item.relative_to(REPO_ROOT).as_posix()):
        identity = path.lstat()
        _require(
            stat.S_ISREG(identity.st_mode) and identity.st_nlink == 1,
            f"single-link business file required: {path}",
        )
        _require(
            (int(identity.st_dev), int(identity.st_ino)) not in forbidden_identities,
            f"business file aliases protected inode before content open: {path}",
        )
        data, record = read_regular_bytes(path, require_nlink_one=True)
        entries.append(
            {
                "path": path.relative_to(REPO_ROOT).as_posix(),
                "type": "regular_file",
                "size_bytes": len(data),
                "sha256": record["sha256"],
            }
        )
    return _inventory_from_entries(entries)


def _excluded_from_a4_lineage(relative: str) -> bool:
    """Return before any content open for exact sealed/history exclusion domains."""

    archive_parent = A3_SUPERSEDED_PARENT.relative_to(REPO_ROOT).as_posix()
    archive_prefix = archive_parent + "/"
    if relative == archive_parent or relative.startswith(archive_prefix):
        return True
    parts = Path(relative).parts
    report_parts = REPORT_ROOT.relative_to(REPO_ROOT).parts
    report_suffix = parts[len(report_parts) :] if parts[: len(report_parts)] == report_parts else ()
    if len(report_suffix) >= 5:
        attempt_id, output_name, stage, repeated_attempt_id, run_id = (
            report_suffix[:5]
        )
        if (
            A4_ATTEMPT_RE.fullmatch(attempt_id) is not None
            and repeated_attempt_id == attempt_id
            and output_name == "stage_outputs"
            and stage in {"G3_F0_A", "G5_F0_B"}
            and re.fullmatch(r"EVAL-TOKEN-[0-9a-f]{32}", run_id)
            is not None
        ):
            return True
    cache_parts = CACHE_ROOT.relative_to(REPO_ROOT).parts
    cache_suffix = parts[len(cache_parts) :] if parts[: len(cache_parts)] == cache_parts else ()
    if (
        len(cache_suffix) >= 3
        and A4_ATTEMPT_RE.fullmatch(cache_suffix[0]) is not None
        and cache_suffix[1] == "encoded_corpus"
        and HEX64.fullmatch(cache_suffix[2]) is not None
    ):
        return True
    if (
        len(parts) >= 3
        and parts[0] == CACHE_ROOT.relative_to(REPO_ROOT).as_posix()
        and A4_ATTEMPT_RE.fullmatch(parts[1]) is not None
        and parts[2] == "g6_synthetic_recovery"
    ):
        return True
    return any(
        relative == prefix.rstrip("/") or relative.startswith(prefix)
        for prefix in PRE_A4_LINEAGE_EXCLUDED_PREFIXES
    )


def _a4_writer_binding(lease: WriterLease) -> dict[str, Any]:
    binding = lease.fixed_lock_identity()
    _require(binding["path"] == str(CONTROL_ROOT / "single_writer.lock"), "A4 writer path")
    _require(binding["nlink"] == 1, "A4 writer nlink")
    return binding


def _validate_producer_argv(
    producer_argv: Sequence[str],
    producer_raw_argv: Sequence[str],
) -> None:
    expected_action = "G0_A4_SUPERSEDE_AND_INIT"
    for label, argv in (("canonical", producer_argv), ("kernel", producer_raw_argv)):
        _require(len(argv) == 5, f"A4 {label} argv length")
        _require(argv[1] == "-B", f"A4 {label} argv lacks -B")
        _require(argv[-2:] == ["--action", expected_action], f"A4 {label} action mismatch")
        _require(Path(argv[0]).is_absolute() and Path(argv[2]).is_absolute(), f"A4 {label} paths")
        _require(
            Path(argv[2]).resolve(strict=True) == (CODE_ROOT / "a4_runner.py"),
            f"A4 {label} runner",
        )
    _require(
        Path(producer_argv[0]).resolve(strict=True) == Path(producer_argv[0]),
        "canonical Python executable is not resolved",
    )
    _require(
        Path(producer_raw_argv[0]).resolve(strict=True) == Path(producer_argv[0]),
        "canonical/kernel Python mismatch",
    )
    _require(
        Path(producer_raw_argv[2]).resolve(strict=True) == Path(producer_argv[2]),
        "canonical/kernel runner mismatch",
    )


def _build_a4_intent(
    producer_argv: Sequence[str],
    producer_raw_argv: Sequence[str],
    lease: WriterLease,
    supersession: Mapping[str, Any],
) -> dict[str, Any]:
    review = validate_a4_static_review_receipt()
    authorization_v2 = _a4_authorization_v2_binding()
    prebootstrap_audit = _validate_prebootstrap_audit()
    authorities = _hash_authority_files()
    git = _git_identity()
    protected_identities = _protected_identities_from_a3()
    inventory = _a4_business_inventory(forbidden_identities=protected_identities)
    parent_exception = supersession["payload"]["reviewed_drift_exception"]
    _require(
        parent_exception["static_review_receipt_sha256"]
        == A3_SUPERSESSION_STATIC_REVIEW_RECEIPT_SHA256,
        "A3 supersession exception review lineage",
    )
    _require(
        USER_A4_AUTHORIZATION_SHA256 == bytes_sha256(USER_A4_AUTHORIZATION_TEXT.encode("utf-8")),
        "compiled authorization hash mismatch",
    )
    now_ns = time.time_ns()
    now_text = f"unix-ns:{now_ns}"
    base = {
        "schema_version": "c28f_g0_a4_bootstrap_intent_v1",
        "goal_id": GOAL_ID,
        "goal_objective": GOAL_OBJECTIVE,
        "goal_objective_sha256": bytes_sha256(GOAL_OBJECTIVE.encode("utf-8")),
        "attempt_id": f"G0-A4-{uuid.uuid4().hex}",
        "transaction_id": f"G0-A4-TXN-{uuid.uuid4().hex}",
        "created_at": now_text,
        "created_at_ns": now_ns,
        "producer_argv": list(producer_argv),
        "producer_raw_argv": list(producer_raw_argv),
        "producer_argv_sha256": bytes_sha256(canonical_json_bytes(list(producer_argv))),
        "producer_raw_argv_sha256": bytes_sha256(canonical_json_bytes(list(producer_raw_argv))),
        "writer_lease": _a4_writer_binding(lease),
        "authorization": {
            "text": USER_A4_AUTHORIZATION_TEXT,
            "text_sha256": USER_A4_AUTHORIZATION_SHA256,
        },
        "authorization_v2_binding": authorization_v2,
        "parent_a3": {
            "attempt_id": A3_ATTEMPT_ID,
            "transaction_id": A3_TRANSACTION_ID,
            "state_sha256": A3_STATE_SHA256,
            "event_sha256": A3_EVENT_SHA256,
            "business_delta_sha256": A3_BUSINESS_DELTA_SHA256,
            "control_tree_sha256": supersession["closure"]["control_tree_sha256"],
            "disposition": "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE",
            "supersession_receipt_sha256": supersession["file_sha256"],
        },
        "reviewed_drift_exception": parent_exception,
        "a3_carry_forward": supersession["carry_forward"],
        "static_review_receipt": {
            "path": str(A4_REVIEW_RECEIPT),
            "sha256": review["file_sha256"],
            "size_bytes": review["size_bytes"],
        },
        "prebootstrap_audit": prebootstrap_audit,
        "authority_files": authorities,
        "git_identity": git,
        "bootstrap_lock": {
            "path": str(BOOTSTRAP_LOCK),
            "required": True,
        },
        "bootstrap_business_inventory": inventory,
        "protected_alias_guard": {
            "source": "A3_STAT_ONLY_PROTECTED_METADATA_REGISTRY",
            "forbidden_identity_count": len(protected_identities),
            "protected_content_opened": False,
        },
        "formal_data_policy": "STRICT_CORE_ONLY",
        "u_formal_updates": 17_360,
        "eval_token_states": {"F0_A": "UNISSUED", "F0_B": "UNISSUED"},
        "model_forward_evaluations": 0,
        "protected_content_opens_current_attempt": 0,
        "real_data_optimizer_updates": 0,
    }
    return _with_semantic_sha(base, "intent_sha256")


def _validate_a4_intent(
    intent: Mapping[str, Any],
    producer_argv: Optional[Sequence[str]] = None,
    producer_raw_argv: Optional[Sequence[str]] = None,
) -> None:
    _require(intent.get("schema_version") == "c28f_g0_a4_bootstrap_intent_v1", "A4 intent schema")
    _require(intent.get("goal_id") == GOAL_ID, "A4 intent Goal")
    _require(isinstance(intent.get("attempt_id"), str) and intent["attempt_id"].startswith("G0-A4-"), "A4 attempt")
    _require(
        isinstance(intent.get("transaction_id"), str)
        and intent["transaction_id"].startswith("G0-A4-TXN-"),
        "A4 transaction",
    )
    _require(
        intent.get("intent_sha256")
        == semantic_sha256(dict(intent), excluded_fields=("intent_sha256",)),
        "A4 intent semantic hash",
    )
    _require(
        intent.get("authorization")
        == {"text": USER_A4_AUTHORIZATION_TEXT, "text_sha256": USER_A4_AUTHORIZATION_SHA256},
        "A4 intent authorization",
    )
    _require(
        intent.get("authorization_v2_binding")
        == _a4_authorization_v2_binding(),
        "A4 intent authorization-v2 binding",
    )
    _require(intent.get("formal_data_policy") == "STRICT_CORE_ONLY", "A4 policy")
    _require(intent.get("u_formal_updates") == 17_360, "A4 formal update lock")
    _require(intent.get("eval_token_states") == {"F0_A": "UNISSUED", "F0_B": "UNISSUED"}, "A4 tokens")
    _require(intent.get("model_forward_evaluations") == 0, "A4 model eval count")
    _require(intent.get("real_data_optimizer_updates") == 0, "A4 optimizer count")
    _require(intent.get("prebootstrap_audit") == _validate_prebootstrap_audit(), "A4 audit binding")
    _require(
        intent.get("parent_a3", {}).get("disposition")
        == "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE",
        "A4 parent disposition",
    )
    if producer_argv is not None:
        _require(intent.get("producer_argv") == list(producer_argv), "A4 recovery canonical argv")
    if producer_raw_argv is not None:
        _require(intent.get("producer_raw_argv") == list(producer_raw_argv), "A4 recovery kernel argv")


def _rebuild_and_validate_a4_intent(
    intent: Mapping[str, Any],
    *,
    supersession: Mapping[str, Any],
    writer_binding: Mapping[str, Any],
    expected_bootstrap_inventory: Mapping[str, Any],
) -> None:
    _validate_a4_intent(intent)
    _require(A4_ATTEMPT_RE.fullmatch(str(intent.get("attempt_id"))) is not None, "A4 attempt ID format")
    _require(
        A4_GENESIS_TXN_RE.fullmatch(str(intent.get("transaction_id"))) is not None,
        "A4 GENESIS transaction ID format",
    )
    _require(type(intent.get("created_at_ns")) is int and intent["created_at_ns"] > 0, "A4 created_at_ns")
    _require(intent.get("created_at") == f"unix-ns:{intent['created_at_ns']}", "A4 created_at binding")
    _validate_producer_argv(intent["producer_argv"], intent["producer_raw_argv"])
    # The current receipt may itself be a replacement recorded by an online
    # code-change contract.  Validate its live contents here, but rebuild the
    # immutable GENESIS intent with its historical receipt binding below.
    validate_a4_static_review_receipt()
    authorization_v2 = _a4_authorization_v2_binding()
    prebootstrap_audit = _validate_prebootstrap_audit()
    _validate_authority_files_without_checkpoint_rehash(intent["authority_files"])
    _require(_git_identity() == intent["git_identity"], "A4 intent git identity drift")
    _require(intent.get("writer_lease") == dict(writer_binding), "A4 intent writer binding drift")
    _require(
        intent.get("bootstrap_business_inventory") == dict(expected_bootstrap_inventory),
        "A4 intent bootstrap inventory drift",
    )
    protected_count = len(_protected_identities_from_a3())
    parent_exception = supersession["payload"]["reviewed_drift_exception"]
    expected_base = {
        "schema_version": "c28f_g0_a4_bootstrap_intent_v1",
        "goal_id": GOAL_ID,
        "goal_objective": GOAL_OBJECTIVE,
        "goal_objective_sha256": bytes_sha256(GOAL_OBJECTIVE.encode("utf-8")),
        "attempt_id": intent["attempt_id"],
        "transaction_id": intent["transaction_id"],
        "created_at": intent["created_at"],
        "created_at_ns": intent["created_at_ns"],
        "producer_argv": intent["producer_argv"],
        "producer_raw_argv": intent["producer_raw_argv"],
        "producer_argv_sha256": bytes_sha256(canonical_json_bytes(intent["producer_argv"])),
        "producer_raw_argv_sha256": bytes_sha256(canonical_json_bytes(intent["producer_raw_argv"])),
        "writer_lease": dict(writer_binding),
        "authorization": {
            "text": USER_A4_AUTHORIZATION_TEXT,
            "text_sha256": USER_A4_AUTHORIZATION_SHA256,
        },
        "authorization_v2_binding": authorization_v2,
        "parent_a3": {
            "attempt_id": A3_ATTEMPT_ID,
            "transaction_id": A3_TRANSACTION_ID,
            "state_sha256": A3_STATE_SHA256,
            "event_sha256": A3_EVENT_SHA256,
            "business_delta_sha256": A3_BUSINESS_DELTA_SHA256,
            "control_tree_sha256": supersession["closure"]["control_tree_sha256"],
            "disposition": "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE",
            "supersession_receipt_sha256": supersession["file_sha256"],
        },
        "reviewed_drift_exception": parent_exception,
        "a3_carry_forward": supersession["carry_forward"],
        "static_review_receipt": {
            "path": intent["static_review_receipt"]["path"],
            "sha256": intent["static_review_receipt"]["sha256"],
            "size_bytes": intent["static_review_receipt"]["size_bytes"],
        },
        "prebootstrap_audit": prebootstrap_audit,
        "authority_files": intent["authority_files"],
        "git_identity": intent["git_identity"],
        "bootstrap_lock": {"path": str(BOOTSTRAP_LOCK), "required": True},
        "bootstrap_business_inventory": dict(expected_bootstrap_inventory),
        "protected_alias_guard": {
            "source": "A3_STAT_ONLY_PROTECTED_METADATA_REGISTRY",
            "forbidden_identity_count": protected_count,
            "protected_content_opened": False,
        },
        "formal_data_policy": "STRICT_CORE_ONLY",
        "u_formal_updates": 17_360,
        "eval_token_states": {"F0_A": "UNISSUED", "F0_B": "UNISSUED"},
        "model_forward_evaluations": 0,
        "protected_content_opens_current_attempt": 0,
        "real_data_optimizer_updates": 0,
    }
    expected = _with_semantic_sha(expected_base, "intent_sha256")
    _require(dict(intent) == expected, "A4 intent differs from full rebuild")


def _write_or_load_a4_intent(
    producer_argv: Sequence[str],
    producer_raw_argv: Sequence[str],
    lease: WriterLease,
    supersession: Mapping[str, Any],
) -> dict[str, Any]:
    intent_path = CONTROL_ROOT / "a4_bootstrap_intent.json"
    root_path = CONTROL_ROOT / "a4_bootstrap_intent.root.sha256"
    writer_binding = _a4_writer_binding(lease)
    current_inventory = _a4_business_inventory(
        forbidden_identities=_protected_identities_from_a3()
    )
    if os.path.lexists(intent_path):
        intent, intent_bytes = _read_canonical_json(intent_path)
        _validate_a4_intent(intent, producer_argv, producer_raw_argv)
    else:
        intent = _build_a4_intent(
            producer_argv,
            producer_raw_argv,
            lease,
            supersession,
        )
        intent_bytes = _canonical_file_bytes(intent)
        atomic_write_immutable(intent_path, intent_bytes, lease=lease)
    _rebuild_and_validate_a4_intent(
        intent,
        supersession=supersession,
        writer_binding=writer_binding,
        expected_bootstrap_inventory=current_inventory,
    )
    root_bytes = (bytes_sha256(intent_bytes) + "\n").encode("ascii")
    atomic_write_immutable(root_path, root_bytes, lease=lease)
    return intent


def _ledger_entry(
    *,
    ledger: str,
    action: str,
    attempt_id: str,
    transaction_id: str,
    facts: Mapping[str, Any],
    seq: int = 0,
    previous_sha256: Optional[str] = None,
) -> dict[str, Any]:
    _require(ledger in {"access", "evaluation", "mutation"}, f"unsupported ledger: {ledger}")
    _require(type(seq) is int and seq >= 0, "ledger seq")
    base = {
        "schema_version": "c28f_append_only_ledger_entry_v1",
        "ledger": ledger,
        "seq": seq,
        "goal_id": GOAL_ID,
        "attempt_id": attempt_id,
        "transaction_id": transaction_id,
        "action": action,
        "previous_entry_sha256": previous_sha256,
        "facts": dict(facts),
    }
    return _with_semantic_sha(base, "entry_sha256")


def _g1_write_root_paths(intent: Mapping[str, Any]) -> dict[str, Path]:
    attempt_id = str(intent["attempt_id"])
    return {
        "g1-write-cache": CACHE_ROOT / attempt_id,
        "g1-write-output": REPORT_ROOT / attempt_id / "stage_outputs",
        "g1-write-tmp": REPORT_ROOT / attempt_id / "runtime_tmp",
    }


def _precommit_g1_write_roots(
    intent: Mapping[str, Any],
    lease: WriterLease,
    bootstrap_lease: BootstrapLease,
) -> list[dict[str, Any]]:
    """Recoverably create the three pristine write-root inodes before GENESIS."""

    paths = _g1_write_root_paths(intent)
    _require(
        all(
            left == right
            or (
                not _path_is_within(left, right)
                and not _path_is_within(right, left)
            )
            for left in paths.values()
            for right in paths.values()
        ),
        "G1 write roots overlap",
    )
    _assert_dual_live_capability(bootstrap_lease, lease)
    for path in paths.values():
        ensure_directory(path)
    roots = [
        FrozenCanonicalRoot.capture(root_id, str(path), ("WRITE",))
        for root_id, path in sorted(paths.items())
    ]
    _require(
        len({(root.device, root.inode) for root in roots}) == 3,
        "G1 write roots physically alias",
    )
    for root in roots:
        _require(root.nlink == 2, f"G1 write root is not pristine: {root.root_id}")
        with os.scandir(root.canonical_path) as iterator:
            _require(not any(True for _entry in iterator), f"G1 write root is not empty: {root.root_id}")
        fsync_directory(Path(root.canonical_path))
    _assert_dual_live_capability(bootstrap_lease, lease)
    return [dict(root.as_dict()) for root in sorted(roots, key=lambda item: item.root_id)]


def _g1_existing_registry(name: str) -> Optional[dict[str, Any]]:
    path = CONTROL_ROOT / name
    if not os.path.lexists(path):
        return None
    payload, encoded = _read_canonical_json(path)
    _require(isinstance(payload, dict), f"existing G1 registry object: {name}")
    _require(encoded == _canonical_file_bytes(payload), f"existing G1 registry canonical: {name}")
    return dict(payload)


def _g1_budget_payload(intent: Mapping[str, Any]) -> dict[str, Any]:
    carried = intent["a3_carry_forward"]["budget.json"]["payload"]["eval_tokens"]
    tokens = []
    for token_name in ("F0_A", "F0_B"):
        record = carried[token_name]
        _require(record.get("state") == "UNISSUED", f"G1 carried token state: {token_name}")
        tokens.append(
            {
                "token_id": record["token_id"],
                "purpose": record["purpose"],
                "state": "UNISSUED",
                "max_uses": 1,
                "use_count": 0,
                "reserved_eval_id": None,
            }
        )
    return {"tokens": sorted(tokens, key=lambda item: item["token_id"])}


def _g1_request_fingerprint(values: Mapping[str, Any]) -> str:
    redacted = {
        str(key): ("<NULL>" if value is None else str(value))
        for key, value in sorted(values.items())
    }
    return bytes_sha256(canonical_json_bytes(redacted))


def _g1_ledger_row(
    *,
    intent: Mapping[str, Any],
    authority_id: str,
    scope_id: str,
    seq: int,
    event_type: str,
    reason_code: str,
    observed_at_ns: int,
    details: Mapping[str, Any],
    previous: Optional[str],
) -> dict[str, Any]:
    fingerprint_fields: dict[str, Any]
    if seq == 1:
        fingerprint_fields = {
            "scope_id": scope_id,
            "goal_id": GOAL_ID,
            "authority_id": authority_id,
        }
    else:
        fingerprint_fields = {
            "scope_id": scope_id,
            "instrumentation_complete": True,
            "unmediated_content_open_count": 0,
        }
    base = {
        "schema_version": LEDGER_SCHEMA_VERSION,
        "scope_id": scope_id,
        "goal_id": GOAL_ID,
        "authority_id": authority_id,
        "seq": seq,
        "observed_at_ns": observed_at_ns,
        "event_type": event_type,
        "decision": "ALLOW",
        "reason_code": reason_code,
        "classification": "CONTROL",
        "request_fingerprint": _g1_request_fingerprint(fingerprint_fields),
        "counters": {
            "content_open_count": 0,
            "content_bytes_read": 0,
            "content_bytes_written": 0,
            "lmdb_transaction_open_count": 0,
            "model_forward_count": 0,
            "protected_metadata_descriptor_open_count": 0,
        },
        "details": dict(details),
        "prev_event_sha256": previous,
    }
    return _with_semantic_sha(base, "event_sha256")


def _build_g1_registry_authority(intent: Mapping[str, Any]) -> dict[str, Any]:
    existing = _g1_existing_registry("g1_registry_authority.json")
    if existing is not None:
        _require(
            existing.get("schema_version")
            == "c28f_g0_expected_g1_registry_authority_v1"
            and existing.get("goal_id") == GOAL_ID
            and existing.get("authority_sha256")
            == semantic_sha256(existing, excluded_fields=("authority_sha256",)),
            "existing G1 authority registry",
        )
        _protected_id_mapping_manifest_contract(existing)
        train_rules = [
            rule
            for rule in existing["canonical_path_map"]["forbidden_registry"]
            if rule.get("rule_id")
            == "g1-protected-train-id-mapping-source"
            and rule.get("canonical_path") == str(TRAIN_JSONL)
        ]
        _require(len(train_rules) == 1, "existing G1 train mapping source")
        return existing
    write_roots = [
        FrozenCanonicalRoot.capture(root_id, str(path), ("WRITE",))
        for root_id, path in sorted(_g1_write_root_paths(intent).items())
    ]
    _require(all(root.nlink == 2 for root in write_roots), "G1 write root pristine nlink")
    read_root = FrozenCanonicalRoot.capture(
        "g1-read-split-metadata",
        str(SPLIT_ROOT),
        ("READ_METADATA",),
    )
    rules = (
        FrozenPathRule.capture_metadata_only(
            "g1-protected-calib-holdout",
            str(CALIB_HOLDOUT_MANIFEST),
            scope="EXACT",
            classification="PROTECTED_DATA",
            approved_content_sha256=PROTECTED_ID_MAPPING_MANIFEST_SPECS[0][
                "content_sha256"
            ],
        ),
        FrozenPathRule.capture_metadata_only(
            "g1-protected-pseudo-official",
            str(PSEUDO_OFFICIAL_MANIFEST),
            scope="EXACT",
            classification="PROTECTED_DATA",
            approved_content_sha256=PROTECTED_ID_MAPPING_MANIFEST_SPECS[1][
                "content_sha256"
            ],
        ),
        FrozenPathRule.capture_metadata_only(
            "g1-protected-train-id-mapping-source",
            str(TRAIN_JSONL),
            scope="EXACT",
            classification="PROTECTED_DATA",
        ),
        FrozenPathRule.capture_metadata_only(
            "g1-protected-official-val-jsonl",
            str(PROTECTED_VAL_JSONL),
            scope="EXACT",
            classification="PROTECTED_DATA",
        ),
        FrozenPathRule.capture_metadata_only(
            "g1-protected-historical-prediction",
            str(PROTECTED_HISTORICAL_C28C_RESULTS),
            scope="EXACT",
            classification="PROTECTED_PREDICTION",
        ),
    )
    authority_id = "G1-AUTHORITY-" + bytes_sha256(
        canonical_json_bytes(
            {
                "goal_id": GOAL_ID,
                "attempt_id": intent["attempt_id"],
                "transaction_id": intent["transaction_id"],
            }
        )
    )[:32]
    budget_payload = _g1_budget_payload(intent)
    f0a = next(
        item
        for item in budget_payload["tokens"]
        if item["purpose"] == "F0_A_TEACHER_FREE_CALIB_SELECT_FORENSICS"
    )
    capability_base = {
        "split_id": "calib_select",
        "split_manifest_sha256": "b2c2a6ec3386d1ff7a3ffd409a8b0f3859ddfb7edddab34d607981b0345a467d",
        "purpose": f0a["purpose"],
        "goal_id": GOAL_ID,
        "authority_id": authority_id,
        "budget_token_id": f0a["token_id"],
        "protected": False,
        "query_entity_namespace": "query_desc_id",
        "candidate_corpus_manifest_sha256": TRAIN_CORPUS_VIDEO_ID_ORDER_SHA256,
        "allow_model_forward": True,
    }
    capability = SplitCapability(
        capability_id="G1-SPLIT-CAP-" + semantic_sha256(capability_base)[:32],
        **capability_base,
    )
    split_registry = SplitAuthorizationRegistry(
        goal_id=GOAL_ID,
        authority_id=authority_id,
        capabilities=(capability,),
        forbidden_split_aliases=(
            "calib_holdout",
            "official",
            "pseudo_official_holdout",
        ),
    ).registry()
    probe = FrozenPathRule.capture_metadata_only(
        "g1-train-fit-metadata-probe",
        str(TRAIN_FIT_MANIFEST),
        scope="EXACT",
        classification="PROTECTED_DATA",
    )
    probe_identity = {
        "device": probe.device,
        "inode": probe.inode,
        "mount_id": probe.mount_id,
        "object_kind": probe.object_kind,
        "size_bytes": probe.size_bytes,
        "mtime_ns": probe.mtime_ns,
        "nlink": probe.nlink,
    }
    roots = tuple([read_root] + write_roots)
    base = {
        "schema_version": "c28f_g0_expected_g1_registry_authority_v1",
        "goal_id": GOAL_ID,
        "authority_id": authority_id,
        "canonical_path_map": canonical_path_map(roots, rules),
        "split_registry": split_registry,
        "write_root_roles": {
            "output": "g1-write-output",
            "cache": "g1-write-cache",
            "tmp": "g1-write-tmp",
        },
        "expected_mount_ids": sorted(
            {root.mount_id for root in roots} | {rule.mount_id for rule in rules}
        ),
        "metadata_path_probe": {
            "request_id": "G1-METADATA-PATH-PROBE",
            "root_id": read_root.root_id,
            "path": str(TRAIN_FIT_MANIFEST),
            "expected_kind": "FILE",
            "purpose": "G1_METADATA_ONLY_DESCRIPTOR_PROBE",
            "expected_descriptor_identity": probe_identity,
            "expected_descriptor_identity_sha256": semantic_sha256(probe_identity),
        },
        "metadata_eval_request": {
            "request_id": "G1-METADATA-EVAL-DRY-RUN",
            "capability_id": capability.capability_id,
            "split_id": capability.split_id,
            "split_manifest_sha256": capability.split_manifest_sha256,
            "purpose": capability.purpose,
            "goal_id": GOAL_ID,
            "authority_id": authority_id,
            "budget_token_id": capability.budget_token_id,
            "candidate_corpus_manifest_sha256": capability.candidate_corpus_manifest_sha256,
            "mode": "METADATA_DRY_RUN",
            "eval_id": "G1-METADATA-EVAL-NO-TOKEN-CONSUME",
        },
        "protected_id_mapping_manifest_contract": {
            "schema_version": (
                "c28f_a4_protected_id_mapping_manifest_contract_v1"
            ),
            "manifests": [
                dict(spec) for spec in PROTECTED_ID_MAPPING_MANIFEST_SPECS
            ],
            "union_count": PROTECTED_ID_MAPPING_UNION_COUNT,
            "union_sha256": PROTECTED_ID_MAPPING_UNION_SHA256,
            "selection_rule": (
                "CANONICAL_SORTED_UNIQUE_UNION_CALIB_HOLDOUT_AND_"
                "PSEUDO_OFFICIAL_HOLDOUT"
            ),
        },
        "eval_budget_sha256": bytes_sha256(canonical_json_bytes(budget_payload)),
        "negative_suite_sha256": G1_NEGATIVE_SUITE_SHA256,
    }
    return {**base, "authority_sha256": semantic_sha256(base)}


def _build_g1_global_snapshot(
    intent: Mapping[str, Any],
    authority: Mapping[str, Any],
) -> dict[str, Any]:
    existing = _g1_existing_registry("g1_global_ledger_snapshot.json")
    if existing is not None:
        _require(
            existing.get("schema_version")
            == "c28f_g1_persisted_global_ledger_snapshot_v2"
            and existing.get("snapshot_sha256")
            == semantic_sha256(existing, excluded_fields=("snapshot_sha256",)),
            "existing G1 global snapshot",
        )
        return existing
    authority_id = str(authority["authority_id"])
    scope_id = f"{intent['attempt_id']}-G0-PRECOMMITTED-GLOBAL"
    opened = _g1_ledger_row(
        intent=intent,
        authority_id=authority_id,
        scope_id=scope_id,
        seq=1,
        event_type="LEDGER_SCOPE_OPENED",
        reason_code="SCOPE_OPEN",
        observed_at_ns=int(intent["created_at_ns"]),
        details={"instrumentation_contract": "PREOPEN_MEDIATION_REQUIRED"},
        previous=None,
    )
    closed = _g1_ledger_row(
        intent=intent,
        authority_id=authority_id,
        scope_id=scope_id,
        seq=2,
        event_type="LEDGER_SCOPE_CLOSED",
        reason_code="SCOPE_CLOSE",
        observed_at_ns=int(intent["created_at_ns"]) + 1,
        details={
            "instrumentation_complete": True,
            "unmediated_content_open_count": 0,
        },
        previous=opened["event_sha256"],
    )
    base = {
        "schema_version": "c28f_g1_persisted_global_ledger_snapshot_v2",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "authority_id": authority_id,
        "committed_control_transaction_id": intent["transaction_id"],
        "ledger_scope_id": scope_id,
        "ledger_rows": [opened, closed],
        "incidents": [],
        "real_data_optimizer_updates": 0,
        "persistence_status": "PRECOMMITTED_IN_G0_A4_GENESIS_REGISTRY",
        "persistence_transaction_id": intent["transaction_id"],
    }
    return {**base, "snapshot_sha256": semantic_sha256(base)}


def _source_file_sha256(path: Path) -> str:
    _data, record = read_regular_bytes(path, require_nlink_one=True)
    return str(record["sha256"])


def _build_g1_mediation_registry(intent: Mapping[str, Any]) -> dict[str, Any]:
    existing = _g1_existing_registry("g1_mediation_registry.json")
    if existing is not None:
        _require(
            existing.get("registry_sha256")
            == semantic_sha256(existing, excluded_fields=("registry_sha256",)),
            "existing G1 mediation registry",
        )
        return existing
    base = {
        "schema_version": "c28f_a4_g1_mediation_registry_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "implementation": "A4G1LedgerController",
        "control_source_sha256": _source_file_sha256(CODE_ROOT / "a4_control.py"),
        "security_source_sha256": _source_file_sha256(CODE_ROOT / "a4_security.py"),
        "exact_surface": [
            "assert_all_ledgers_closed",
            "close_mediated_ledger",
            "open_mediated_ledger",
        ],
        "observer_contract": {
            "content_and_model_counts_derived_from_ledger_rows": True,
            "data_loader_and_output_calls_controller_counted": True,
            "unmediated_content_open_count_must_equal_zero": True,
            "literal_zero_fabrication_forbidden": True,
        },
    }
    return {**base, "registry_sha256": semantic_sha256(base)}


def _build_g1_probe_registry(intent: Mapping[str, Any]) -> dict[str, Any]:
    existing = _g1_existing_registry("g1_probe_detector_registry.json")
    if existing is not None:
        _require(
            existing.get("registry_sha256")
            == semantic_sha256(existing, excluded_fields=("registry_sha256",)),
            "existing G1 probe registry",
        )
        return existing
    base = {
        "schema_version": "c28f_a4_g1_probe_detector_registry_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "negative_suite_sha256": G1_NEGATIVE_SUITE_SHA256,
        "probe_reason_codes": dict(sorted(REQUIRED_G1_NEGATIVE_PROBES.items())),
        "control_source_sha256": _source_file_sha256(CODE_ROOT / "a4_control.py"),
        "security_source_sha256": _source_file_sha256(CODE_ROOT / "a4_security.py"),
        "stages_source_sha256": _source_file_sha256(CODE_ROOT / "a4_stages.py"),
    }
    return {**base, "registry_sha256": semantic_sha256(base)}


def _frozen_a3_permission_records() -> dict[str, dict[str, Any]]:
    """Return the exact A3 permission ledger carried into A4 Genesis."""

    return {
        "AUTH_F0_F1_IMPLEMENTATION": {
            "state": "ACTIVE",
            "value": True,
            "source": "explicit_goal_start",
        },
        "AUTH_PROTECTED_ID_MAPPING_ONLY": {
            "state": "ACTIVE",
            "value": True,
            "scope": (
                "desc_id_to_video_id_only_no_text_timestamp_feature_label_metric"
            ),
            "source": "goal_launch_contract_executed_by_user",
        },
        **{
            name: {"state": "UNGRANTED", "value": False}
            for name in (
                "AUTH_F2_F5_PROTOTYPE",
                "AUTH_F6_MECHANISM",
                "AUTH_F8_FORMAL",
                "AUTH_HOLDOUT_OFFICIAL",
                "AUTH_GIT_BRANCH_CREATE_SWITCH",
                "AUTH_GIT_COMMIT",
                "AUTH_GIT_PUSH_PR",
            )
        },
    }


def _build_a4_registries(intent: Mapping[str, Any]) -> dict[str, Any]:
    carry = intent["a3_carry_forward"]
    old_authority = carry["authority_ledger.json"]["payload"]
    old_budget = carry["budget.json"]["payload"]
    old_gates = carry["gate_registry.json"]["payload"]
    expected_permissions = _frozen_a3_permission_records()
    _require(
        old_authority.get("goal_id") == GOAL_ID
        and old_authority.get("formal_data_policy") == "STRICT_CORE_ONLY"
        and old_authority.get("u_formal_updates") == 17_360
        and old_authority.get("permissions") == expected_permissions,
        "A3 authority permission provenance drift",
    )
    authority_permissions = json.loads(
        canonical_json_bytes(old_authority["permissions"]).decode(
            "utf-8", "strict"
        )
    )
    _require(
        authority_permissions == old_authority["permissions"],
        "A3 authority permission canonical deep copy",
    )
    authority_base = {
        "schema_version": "c28f_a4_authority_ledger_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "formal_data_policy": "STRICT_CORE_ONLY",
        "u_formal_updates": 17_360,
        "permissions": authority_permissions,
        "real_data_training_authorized": old_authority[
            "real_data_training_authorized"
        ],
        "protected_model_evaluation_authorized": old_authority[
            "protected_model_evaluation_authorized"
        ],
        "pre_g0_security_incident": old_authority[
            "pre_g0_security_incident"
        ],
        "continuation_disposition": old_authority[
            "continuation_disposition"
        ],
        "user_a4_authorization": intent["authorization"],
        "user_a4_authorization_v2": intent[
            "authorization_v2_binding"
        ],
        "a3_authority_payload_sha256": semantic_sha256(old_authority),
        "a3_parent_event_sha256": A3_EVENT_SHA256,
        "forbidden_authorities_remain_ungranted": True,
        "reactivation_allowed": True,
    }
    authority = {
        **authority_base,
        "authority_sha256": semantic_sha256(authority_base),
    }
    budget = {
        "schema_version": "c28f_a4_budget_registry_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "eval_tokens": old_budget["eval_tokens"],
        "caps": old_budget["caps"],
        "usage": old_budget["usage"],
        "token_state_machine": old_budget["token_state_machine"],
        "a4_control_repair_consumed_eval_token": False,
        "a4_control_repair_model_forward_evaluations": 0,
        "a4_control_repair_real_data_optimizer_updates": 0,
    }
    _require(
        {name: record["state"] for name, record in budget["eval_tokens"].items()}
        == {"F0_A": "UNISSUED", "F0_B": "UNISSUED"},
        "carried token state drift",
    )
    gates = {
        "schema_version": "c28f_a4_gate_registry_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "completed_gates": ["G0"],
        "current_gate": "G1_FAIL_CLOSED_GUARD",
        "current_gate_is_unique": True,
        "a3_gate_registry": old_gates,
        "control_repair_gate": {
            "name": "G0_A4_EXTENSIBLE_CONTROL_REPAIR",
            "status": "PASS",
            "scientific_impact": "NONE",
        },
    }
    extension = {
        "schema_version": "c28f_a4_control_extension_registry_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "parent_a3": intent["parent_a3"],
        "authorization": intent["authorization"],
        "authorization_v2_binding": intent[
            "authorization_v2_binding"
        ],
        "reviewed_drift_exception": intent["reviewed_drift_exception"],
        "transaction_contract": {
            "state_pointer_commit_marker": "GOAL_STATE.json",
            "event_chain": "append-only semantic-hash chain plus immutable sidecars",
            "registry_versions": "append-only immutable sidecars plus current pointers",
            "ledger_versions": "append-only semantic-hash chains plus immutable sidecars",
            "business_mutations": "intent must bind preimage, exact writes, and postimage before write",
            "single_writer": "bootstrap flock plus fixed-inode writer flock",
        },
    }
    artifacts = {
        "schema_version": "c28f_a4_artifact_manifest_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "business_inventory": intent["bootstrap_business_inventory"],
        "parent_supersession_receipt": intent["parent_a3"]["supersession_receipt_sha256"],
        "static_review_receipt": intent["static_review_receipt"],
        "prebootstrap_audit": intent["prebootstrap_audit"],
        "historical_lineage_excluded_prefixes": list(PRE_A4_LINEAGE_EXCLUDED_PREFIXES),
        "historical_exclusions_applied_before_a4_inventory_content_open": True,
        "protected_content_included": False,
        "historical_prediction_or_result_content_included": False,
    }
    safety = {
        "schema_version": "c28f_a4_safety_registry_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "protected_content_opens_current_attempt": 0,
        "pre_a4_historical_content_open_status": "NONZERO_UNQUANTIFIED_RECORDED_EXCEPTION",
        "prebootstrap_audit_sha256": intent["prebootstrap_audit"]["sha256"],
        "model_forward_evaluations": 0,
        "real_data_optimizer_updates": 0,
        "formal_data_policy": "STRICT_CORE_ONLY",
        "eval_token_states": {"F0_A": "UNISSUED", "F0_B": "UNISSUED"},
        "next_data_action": "G1_FAIL_CLOSED_GUARD",
    }
    g1_authority = _build_g1_registry_authority(intent)
    g1_global = _build_g1_global_snapshot(intent, g1_authority)
    g1_mediation = _build_g1_mediation_registry(intent)
    g1_probe = _build_g1_probe_registry(intent)
    return {
        "authority_ledger.json": authority,
        "budget.json": budget,
        "gate_registry.json": gates,
        "control_extension_registry.json": extension,
        "artifact_manifest.json": artifacts,
        "safety_registry.json": safety,
        "g1_registry_authority.json": g1_authority,
        "g1_global_ledger_snapshot.json": g1_global,
        "g1_mediation_registry.json": g1_mediation,
        "g1_probe_detector_registry.json": g1_probe,
    }


def _build_a4_ledgers(intent: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    checkpoint_access = intent["authority_files"]["checkpoint"]
    common = {
        "attempt_id": intent["attempt_id"],
        "transaction_id": intent["transaction_id"],
        "action": "G0_A4_GENESIS_AFTER_VALID_A3_SUPERSESSION",
    }
    return {
        "access": _ledger_entry(
            ledger="access",
            facts={
                "experiment_data_files_opened": 0,
                "protected_content_opens": 0,
                "historical_prediction_or_result_content_opens_during_a4_genesis": 0,
                "pre_a4_historical_content_open_status": "NONZERO_UNQUANTIFIED_RECORDED_EXCEPTION",
                "prebootstrap_audit_sha256": intent["prebootstrap_audit"]["sha256"],
                "historical_lineage_exclusions_applied_before_a4_inventory_open": True,
                "checkpoint_content_open_count": 1,
                "checkpoint_bytes_hashed_sha256_only": checkpoint_access["bytes_hashed"],
                "checkpoint_sha256": checkpoint_access["sha256"],
                "checkpoint_deserialized": False,
                "checkpoint_model_forward": False,
                "operation": "CONTROL_AND_AUTHORITY_HASHING_NO_DESERIALIZE",
            },
            **common,
        ),
        "evaluation": _ledger_entry(
            ledger="evaluation",
            facts={
                "model_forward_evaluations": 0,
                "real_data_optimizer_updates": 0,
                "eval_token_states": {"F0_A": "UNISSUED", "F0_B": "UNISSUED"},
            },
            **common,
        ),
        "mutation": _ledger_entry(
            ledger="mutation",
            facts={
                "mutation": "A3_VALID_NONEXTENSIBLE_SUPERSESSION_AND_A4_GENESIS",
                "a3_control_tree_sha256": intent["parent_a3"]["control_tree_sha256"],
                "a4_business_delta_sha256": intent["bootstrap_business_inventory"][
                    "business_delta_sha256"
                ],
                "scientific_impact": "NONE",
            },
            **common,
        ),
    }


def _a4_continuation(state: Mapping[str, Any], event: Mapping[str, Any]) -> bytes:
    lines = [
        "# C28F v5 G0-A4 continuation",
        "",
        f"- Goal ID: `{state['goal_id']}`",
        f"- Attempt: `{state['attempt_id']}`",
        f"- Status: `{state['status']}`",
        f"- Unique next action: `{state['next_action']}`",
        f"- State SHA256: `{state['state_sha256']}`",
        f"- Event SHA256: `{event['event_sha256']}`",
        f"- Business delta SHA256: `{state['expected_goal_delta_sha256']}`",
        "- G0-A3 is valid evidence sealed under the superseded namespace; it is not quarantined.",
        "- G0-A4 consumed no evaluation token and performed no model forward or optimizer update.",
        "- Continue only through the state-declared action and the append-only transaction contract.",
        "",
    ]
    return "\n".join(lines).encode("utf-8")


def _prepare_a4_genesis(intent: Mapping[str, Any]) -> dict[str, Any]:
    registries = _build_a4_registries(intent)
    registry_bytes = {name: _canonical_file_bytes(value) for name, value in registries.items()}
    g1_write_root_directory_postimage = sorted(
        (
            dict(record)
            for record in registries["g1_registry_authority.json"][
                "canonical_path_map"
            ]["canonical_roots"]
            if record["operations"] == ["WRITE"]
        ),
        key=lambda item: item["root_id"],
    )
    _require(
        len(g1_write_root_directory_postimage) == 3
        and all(item["nlink"] == 2 for item in g1_write_root_directory_postimage),
        "GENESIS G1 write-root directory postimage",
    )
    ledgers = _build_a4_ledgers(intent)
    ledger_bytes = {name: canonical_json_bytes(value) + b"\n" for name, value in ledgers.items()}
    state_base = {
        "schema_version": "c28f_v5_f0_f1_control_v2",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "transaction_id": intent["transaction_id"],
        "stage": "G0",
        "status": "PREFLIGHT_OK",
        "transition_seq": 0,
        "completed_gates": ["G0"],
        "next_action": "G1_FAIL_CLOSED_GUARD",
        "next_action_is_unique": True,
        "expected_goal_delta_sha256": intent["bootstrap_business_inventory"][
            "business_delta_sha256"
        ],
        "authority_summary": AUTHORITY_SUMMARY,
        "formal_data_policy": "STRICT_CORE_ONLY",
        "u_formal_updates": 17_360,
        "eval_token_states": {"F0_A": "UNISSUED", "F0_B": "UNISSUED"},
        "protected_model_evals": 0,
        "protected_content_opens_current_attempt": 0,
        "real_data_optimizer_updates": 0,
        "parent_a3_disposition": "SEALED_SUPERSEDED_VALID_G0_NONEXTENSIBLE",
        "updated_at": intent["created_at"],
    }
    state = _with_semantic_sha(state_base, "state_sha256")
    registry_hashes = {name: bytes_sha256(data) for name, data in registry_bytes.items()}
    ledger_hashes = {
        f"ledgers/{name}_ledger.jsonl": bytes_sha256(data) for name, data in ledger_bytes.items()
    }
    artifact_root_bytes = (registry_hashes["artifact_manifest.json"] + "\n").encode("ascii")
    plan_base = {
        "schema_version": "c28f_append_only_transaction_plan_v1",
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "transaction_id": intent["transaction_id"],
        "seq": 0,
        "action": "G0_A4_GENESIS_AFTER_VALID_A3_SUPERSESSION",
        "expected_business_preimage_sha256": intent["bootstrap_business_inventory"][
            "business_delta_sha256"
        ],
        "expected_business_postimage_sha256": intent["bootstrap_business_inventory"][
            "business_delta_sha256"
        ],
        "expected_state_sha256": state["state_sha256"],
        "registry_output_hashes": registry_hashes,
        "ledger_output_hashes": ledger_hashes,
        "artifact_manifest_root_sha256": bytes_sha256(artifact_root_bytes),
        "g1_write_root_directory_postimage": g1_write_root_directory_postimage,
        "state_pointer_is_last_commit_marker": True,
    }
    plan = _with_semantic_sha(plan_base, "plan_sha256")
    plan_bytes = _canonical_file_bytes(plan)
    event_base = {
        "schema_version": "c28f_goal_event_v2",
        "seq": 0,
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "transaction_id": intent["transaction_id"],
        "action": "G0_A4_GENESIS_AFTER_VALID_A3_SUPERSESSION",
        "result": "PASS_WITH_AUTHORIZED_REVIEWED_CONTROL_EXTENSION",
        "prev_event_sha256": None,
        "expected_next_state_sha256": state["state_sha256"],
        "expected_goal_delta_sha256": state["expected_goal_delta_sha256"],
        "next_action": state["next_action"],
        "input_hashes": {
            "intent_file": "PENDING_INTENT_FILE_HASH",
            "intent_semantic": intent["intent_sha256"],
            "transaction_plan_file": bytes_sha256(plan_bytes),
            "supersession_receipt": intent["parent_a3"]["supersession_receipt_sha256"],
            "static_review_receipt": intent["static_review_receipt"]["sha256"],
            "goal_contract": EXPECTED_GOAL_CONTRACT_SHA256,
            "blueprint": EXPECTED_BLUEPRINT_SHA256,
            "handoff": EXPECTED_HANDOFF_SHA256,
            "checkpoint": EXPECTED_CHECKPOINT_SHA256,
        },
        "output_hashes": {
            **registry_hashes,
            **ledger_hashes,
            "artifact_manifest.root.sha256": bytes_sha256(artifact_root_bytes),
        },
        "safety_counts": {
            "protected_content_opens": 0,
            "model_forward_evaluations": 0,
            "real_data_optimizer_updates": 0,
        },
    }
    intent_bytes = _canonical_file_bytes(intent)
    event_base["input_hashes"]["intent_file"] = bytes_sha256(intent_bytes)
    event = _with_semantic_sha(event_base, "event_sha256")
    event_bytes = canonical_json_bytes(event) + b"\n"
    state_bytes = _canonical_file_bytes(state)
    continuation = _a4_continuation(state, event)
    return {
        "registries": registries,
        "registry_bytes": registry_bytes,
        "ledgers": ledgers,
        "ledger_bytes": ledger_bytes,
        "artifact_root_bytes": artifact_root_bytes,
        "plan": plan,
        "plan_bytes": plan_bytes,
        "state": state,
        "state_bytes": state_bytes,
        "event": event,
        "event_bytes": event_bytes,
        "continuation": continuation,
    }


def _assert_a4_roundtrip(intent: Mapping[str, Any], prepared: Mapping[str, Any]) -> None:
    reloaded = json.loads(canonical_json_bytes(intent).decode("utf-8"))
    replay = _prepare_a4_genesis(reloaded)
    stable_keys = (
        "registry_bytes",
        "ledger_bytes",
        "artifact_root_bytes",
        "plan_bytes",
        "state_bytes",
        "event_bytes",
        "continuation",
    )
    for key in stable_keys:
        _require(replay[key] == prepared[key], f"A4 builder is not canonical: {key}")


def _assert_dual_live_capability(
    bootstrap_lease: BootstrapLease,
    lease: WriterLease,
) -> None:
    bootstrap_lease.assert_active_capability()
    lease.assert_active_capability()
    _writer_lock_identity(lease.fd, CONTROL_ROOT / "single_writer.lock")  # type: ignore[arg-type]


def _cleanup_control_recovery_temps(lease: WriterLease) -> None:
    lease.assert_active_capability()
    lineage = re.escape(str(lease.record["lease_lineage_root_id"]))
    pattern = re.compile(
        rf"^\..+\.(?:tmp|immutable)\.{lineage}\.[0-9]+\.[0-9a-f]{{32}}$"
    )
    root_device = CONTROL_ROOT.lstat().st_dev
    dirty_parents: set[Path] = set()
    stack = [CONTROL_ROOT]
    while stack:
        directory = stack.pop()
        with os.scandir(directory) as iterator:
            entries = sorted(iterator, key=lambda item: item.name)
        for entry in entries:
            path = Path(entry.path)
            _require(not entry.is_symlink(), f"control recovery symlink forbidden: {path}")
            if entry.is_dir(follow_symlinks=False):
                stack.append(path)
            elif entry.is_file(follow_symlinks=False) and pattern.fullmatch(entry.name):
                identity = path.lstat()
                _require(
                    identity.st_dev == root_device and identity.st_nlink == 1,
                    f"unsafe recovery temp identity: {path}",
                )
                os.unlink(path)
                dirty_parents.add(path.parent)
    for parent in sorted(dirty_parents, key=str):
        fsync_directory(parent)


def _genesis_expected_file_bytes(
    intent: Mapping[str, Any],
    prepared: Mapping[str, Any],
) -> dict[str, Optional[bytes]]:
    intent_bytes = _canonical_file_bytes(intent)
    expected: dict[str, Optional[bytes]] = {
        "a4_bootstrap_intent.json": intent_bytes,
        "a4_bootstrap_intent.root.sha256": (bytes_sha256(intent_bytes) + "\n").encode("ascii"),
        "artifact_manifest.root.sha256": prepared["artifact_root_bytes"],
        "CONTINUATION.md": prepared["continuation"],
        "GOAL_EVENTS.jsonl": prepared["event_bytes"],
        "GOAL_STATE.json": prepared["state_bytes"],
        "single_writer.lock": LOCK_HEADER,
        "single_writer.heartbeat.json": None,
        f"transactions/{intent['transaction_id']}/plan.json": prepared["plan_bytes"],
        f"state_records/000000_{prepared['state']['state_sha256']}.json": prepared["state_bytes"],
        f"event_records/000000_{prepared['event']['event_sha256']}.jsonl": prepared["event_bytes"],
    }
    for name, data in prepared["registry_bytes"].items():
        expected[name] = data
        expected[f"registry_records/000000_{name[:-5]}_{bytes_sha256(data)}.json"] = data
    expected[
        "registry_records/000000_artifact_manifest_root_"
        f"{bytes_sha256(prepared['artifact_root_bytes'])}.sha256"
    ] = prepared["artifact_root_bytes"]
    for ledger, data in prepared["ledger_bytes"].items():
        expected[f"ledgers/{ledger}_ledger.jsonl"] = data
        entry_sha = prepared["ledgers"][ledger]["entry_sha256"]
        expected[f"ledger_records/{ledger}/000000_{entry_sha}.jsonl"] = data
    return expected


def _assert_genesis_partial_namespace(
    intent: Mapping[str, Any],
    prepared: Mapping[str, Any],
    *,
    require_pre_state_complete: bool = False,
) -> None:
    expected_files = _genesis_expected_file_bytes(intent, prepared)
    _final_files, expected_directories = _a4_expected_namespace(intent, prepared)
    directories, files, _tree = _walk_tree(CONTROL_ROOT, opaque_directories={"inbox"})
    actual_files = {item["path"] for item in files}
    actual_directories = set(directories)
    _require(actual_files.issubset(expected_files), "partial GENESIS contains unknown file")
    _require(actual_directories.issubset(expected_directories), "partial GENESIS contains unknown directory")
    for relative in sorted(actual_files):
        expected = expected_files[relative]
        if expected is None:
            continue
        observed, _record = read_regular_bytes(
            CONTROL_ROOT / relative,
            require_nlink_one=True,
        )
        _require(observed == expected, f"partial GENESIS byte mismatch: {relative}")
    if "GOAL_STATE.json" in actual_files:
        _require(actual_files == set(expected_files), "GENESIS state exists before complete file closure")
        _require(actual_directories == expected_directories, "GENESIS state exists before complete dir closure")
    if require_pre_state_complete:
        _require("GOAL_STATE.json" not in actual_files, "GENESIS state installed too early")
        _require(
            actual_files == set(expected_files) - {"GOAL_STATE.json"},
            "GENESIS pre-state file closure incomplete",
        )
        _require(actual_directories == expected_directories, "GENESIS pre-state dir closure incomplete")


def _install_a4_genesis(
    intent: Mapping[str, Any],
    prepared: Mapping[str, Any],
    lease: WriterLease,
    bootstrap_lease: BootstrapLease,
) -> None:
    _cleanup_control_recovery_temps(lease)
    _assert_genesis_partial_namespace(intent, prepared)
    transaction_dir = CONTROL_ROOT / "transactions" / intent["transaction_id"]
    for name, data in prepared["registry_bytes"].items():
        digest = bytes_sha256(data)
        atomic_write_immutable(
            CONTROL_ROOT / "registry_records" / f"000000_{name[:-5]}_{digest}.json",
            data,
            lease=lease,
        )
        atomic_write_bytes(CONTROL_ROOT / name, data, lease=lease, precondition="ABSENT_OR_IDENTICAL")
    atomic_write_immutable(
        CONTROL_ROOT
        / "registry_records"
        / f"000000_artifact_manifest_root_{bytes_sha256(prepared['artifact_root_bytes'])}.sha256",
        prepared["artifact_root_bytes"],
        lease=lease,
    )
    atomic_write_bytes(
        CONTROL_ROOT / "artifact_manifest.root.sha256",
        prepared["artifact_root_bytes"],
        lease=lease,
        precondition="ABSENT_OR_IDENTICAL",
    )
    for ledger, data in prepared["ledger_bytes"].items():
        entry_sha = prepared["ledgers"][ledger]["entry_sha256"]
        atomic_write_immutable(
            CONTROL_ROOT / "ledger_records" / ledger / f"000000_{entry_sha}.jsonl",
            data,
            lease=lease,
        )
        atomic_write_bytes(
            CONTROL_ROOT / "ledgers" / f"{ledger}_ledger.jsonl",
            data,
            lease=lease,
            precondition="ABSENT_OR_IDENTICAL",
        )
    atomic_write_immutable(transaction_dir / "plan.json", prepared["plan_bytes"], lease=lease)
    atomic_write_immutable(
        CONTROL_ROOT
        / "state_records"
        / f"000000_{prepared['state']['state_sha256']}.json",
        prepared["state_bytes"],
        lease=lease,
    )
    atomic_write_immutable(
        CONTROL_ROOT
        / "event_records"
        / f"000000_{prepared['event']['event_sha256']}.jsonl",
        prepared["event_bytes"],
        lease=lease,
    )
    ensure_directory(CONTROL_ROOT / "inbox")
    fsync_directory(CONTROL_ROOT)
    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    atomic_write_bytes(
        CONTROL_ROOT / "GOAL_EVENTS.jsonl",
        prepared["event_bytes"],
        lease=lease,
        precondition="ABSENT_OR_IDENTICAL",
    )
    atomic_write_bytes(
        CONTROL_ROOT / "CONTINUATION.md",
        prepared["continuation"],
        lease=lease,
        precondition="ABSENT_OR_IDENTICAL",
    )
    _assert_genesis_partial_namespace(
        intent,
        prepared,
        require_pre_state_complete=True,
    )
    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    atomic_write_bytes(
        CONTROL_ROOT / "GOAL_STATE.json",
        prepared["state_bytes"],
        lease=lease,
        precondition="ABSENT_OR_IDENTICAL",
    )


def _a4_expected_namespace(
    intent: Mapping[str, Any],
    prepared: Mapping[str, Any],
) -> tuple[set[str], set[str]]:
    files = {
        "a4_bootstrap_intent.json",
        "a4_bootstrap_intent.root.sha256",
        "artifact_manifest.root.sha256",
        "CONTINUATION.md",
        "GOAL_EVENTS.jsonl",
        "GOAL_STATE.json",
        "single_writer.lock",
        "single_writer.heartbeat.json",
        f"transactions/{intent['transaction_id']}/plan.json",
        f"state_records/000000_{prepared['state']['state_sha256']}.json",
        f"event_records/000000_{prepared['event']['event_sha256']}.jsonl",
    }
    for name, data in prepared["registry_bytes"].items():
        files.add(name)
        files.add(f"registry_records/000000_{name[:-5]}_{bytes_sha256(data)}.json")
    files.add(
        "registry_records/000000_artifact_manifest_root_"
        f"{bytes_sha256(prepared['artifact_root_bytes'])}.sha256"
    )
    for ledger, data in prepared["ledger_bytes"].items():
        files.add(f"ledgers/{ledger}_ledger.jsonl")
        files.add(
            f"ledger_records/{ledger}/000000_{prepared['ledgers'][ledger]['entry_sha256']}.jsonl"
        )
    directories = {
        "event_records",
        "registry_records",
        "state_records",
        "transactions",
        f"transactions/{intent['transaction_id']}",
        "ledgers",
        "ledger_records",
        "ledger_records/access",
        "ledger_records/evaluation",
        "ledger_records/mutation",
        "inbox",
    }
    return files, directories


def _validate_a4_heartbeat(
    intent: Mapping[str, Any],
    *,
    active_lease: Optional[WriterLease],
) -> dict[str, Any]:
    heartbeat, _encoded = _read_canonical_json(CONTROL_ROOT / "single_writer.heartbeat.json")
    _require(isinstance(heartbeat, dict), "A4 heartbeat object required")
    required = {
        "schema_version",
        "goal_id",
        "lease_id",
        "lease_lineage_root_id",
        "status",
        "pid",
        "boot_id",
        "process_start_ticks",
        "action",
        "acquired_at_ns",
        "heartbeat_at_ns",
    }
    _require(required.issubset(heartbeat), "A4 heartbeat schema missing")
    _require(heartbeat["schema_version"] == "c28f_single_writer_lease_v2", "A4 heartbeat schema")
    _require(heartbeat["goal_id"] == GOAL_ID, "A4 heartbeat Goal")
    _require(
        heartbeat["lease_lineage_root_id"] == intent["writer_lease"]["lease_lineage_root_id"],
        "A4 heartbeat lineage",
    )
    if active_lease is None:
        _require(heartbeat["status"] == "IDLE", "external A4 verifier requires IDLE writer")
    else:
        active_lease.assert_active_capability()
        _require(heartbeat["status"] == "ACTIVE", "in-process A4 verifier requires ACTIVE writer")
        _require(heartbeat["lease_id"] == active_lease.record["lease_id"], "active A4 lease id")
    return heartbeat


def _validate_semantic_journal(
    data: bytes,
    *,
    hash_field: str,
    previous_field: str,
    expected_kind: Optional[str] = None,
) -> list[dict[str, Any]]:
    _require(bool(data) and data.endswith(b"\n") and b"\n\n" not in data, "invalid journal framing")
    records: list[dict[str, Any]] = []
    previous: Optional[str] = None
    for seq, encoded in enumerate(data[:-1].split(b"\n")):
        try:
            record = json.loads(encoded.decode("utf-8", "strict"))
        except (UnicodeDecodeError, json.JSONDecodeError) as exc:
            raise A4ControlError(f"invalid journal record at seq={seq}") from exc
        _require(isinstance(record, dict), f"journal object required at seq={seq}")
        _require(encoded == canonical_json_bytes(record), f"non-canonical journal record at seq={seq}")
        _require(type(record.get("seq")) is int and record["seq"] == seq, f"journal sequence at {seq}")
        _require(record.get(previous_field) == previous, f"journal previous hash at {seq}")
        _require(
            record.get(hash_field) == semantic_sha256(record, excluded_fields=(hash_field,)),
            f"journal semantic hash at {seq}",
        )
        if expected_kind is not None:
            _require(record.get("ledger") == expected_kind, f"journal ledger kind at {seq}")
        previous = record[hash_field]
        records.append(record)
    return records


def _validate_a4_intent_file() -> tuple[dict[str, Any], bytes]:
    intent, intent_bytes = _read_canonical_json(CONTROL_ROOT / "a4_bootstrap_intent.json")
    _require(isinstance(intent, dict), "A4 intent object required")
    _validate_a4_intent(intent)
    detached, _record = read_regular_bytes(
        CONTROL_ROOT / "a4_bootstrap_intent.root.sha256",
        max_bytes=128,
        require_nlink_one=True,
    )
    _require(detached == (bytes_sha256(intent_bytes) + "\n").encode("ascii"), "A4 intent detached root")
    return intent, intent_bytes


def _validate_code_change_contract_payload(
    contract: Mapping[str, Any],
    *,
    attempt_id: str,
) -> None:
    if contract.get("schema_version") == "c28f_user_authorized_online_code_change_v1":
        required = {
            "schema_version",
            "goal_id",
            "attempt_id",
            "code_change_id",
            "parent_state_sha256",
            "parent_event_sha256",
            "commit_action",
            "resume_action",
            "user_authorization",
            "review_policy",
            "business_preimage_sha256",
            "business_postimage_sha256",
            "files",
            "application_method",
            "code_executed_or_imported_before_commit",
            "code_change_intent_sha256",
        }
        _require(
            frozenset(contract)
            in {frozenset(required), frozenset(required | {"resume_status"})},
            "online code intent fields",
        )
        _require(
            contract.get("goal_id") == GOAL_ID
            and contract.get("attempt_id") == attempt_id,
            "online code intent owner",
        )
        code_change_id = contract.get("code_change_id")
        _require(
            isinstance(code_change_id, str)
            and CODE_CHANGE_ID_RE.fullmatch(code_change_id),
            "online code intent ID",
        )
        identity_seed = {
            key: value
            for key, value in contract.items()
            if key not in {"code_change_id", "code_change_intent_sha256"}
        }
        _require(
            code_change_id
            == f"CODE-CHANGE-{bytes_sha256(canonical_json_bytes(identity_seed))[:32]}",
            "online code intent derived ID",
        )
        _require(
            contract.get("code_change_intent_sha256")
            == semantic_sha256(
                contract,
                excluded_fields=("code_change_intent_sha256",),
            ),
            "online code intent semantic hash",
        )
        _require(
            contract.get("commit_action") == "COMMIT_REVIEWED_CODE_CHANGE",
            "online code intent commit action",
        )
        _require(
            isinstance(contract.get("resume_status", "PREFLIGHT_OK"), str)
            and bool(contract.get("resume_status", "PREFLIGHT_OK")),
            "online code intent resume status",
        )
        authorization = contract.get("user_authorization")
        _require(
            authorization
            == {
                "text": ONLINE_CODE_CHANGE_AUTHORIZATION_TEXT,
                "text_sha256": bytes_sha256(
                    ONLINE_CODE_CHANGE_AUTHORIZATION_TEXT.encode("utf-8")
                ),
            },
            "online code intent user authorization",
        )
        _require(
            contract.get("review_policy") == ONLINE_CODE_CHANGE_REVIEW_POLICY,
            "online code intent deferred review policy",
        )
        _require(
            contract.get("application_method")
            == "direct online replacement of existing regular files",
            "online code intent application method",
        )
        _require(
            contract.get("code_executed_or_imported_before_commit") is True,
            "online code intent execution disclosure",
        )
        _require(
            isinstance(contract.get("business_preimage_sha256"), str)
            and HEX64.fullmatch(contract["business_preimage_sha256"])
            and isinstance(contract.get("business_postimage_sha256"), str)
            and HEX64.fullmatch(contract["business_postimage_sha256"]),
            "online code intent business hashes",
        )
        files = contract.get("files")
        _require(
            isinstance(files, list) and 1 <= len(files) <= MAX_CODE_CHANGE_FILES,
            "online code intent file count",
        )
        destinations: set[str] = set()
        total = 0
        for item in files:
            _require(
                isinstance(item, dict)
                and set(item)
                == {
                    "destination",
                    "operation",
                    "expected_preimage_sha256",
                    "expected_preimage_size_bytes",
                    "sha256",
                    "size_bytes",
                },
                "online code intent file fields",
            )
            destination = item.get("destination")
            _require(
                isinstance(destination, str) and destination not in destinations,
                "online code intent destination",
            )
            _safe_code_destination(destination)
            _require(
                item.get("operation") == "REPLACE_EXISTING",
                "online code intent operation",
            )
            _require(
                isinstance(item.get("expected_preimage_sha256"), str)
                and HEX64.fullmatch(item["expected_preimage_sha256"])
                and isinstance(item.get("sha256"), str)
                and HEX64.fullmatch(item["sha256"]),
                "online code intent file hashes",
            )
            _require(
                type(item.get("expected_preimage_size_bytes")) is int
                and item["expected_preimage_size_bytes"] > 0
                and type(item.get("size_bytes")) is int
                and 0 < item["size_bytes"] <= MAX_CODE_CHANGE_FILE_BYTES,
                "online code intent file sizes",
            )
            _require(
                item["expected_preimage_sha256"] != item["sha256"],
                "online code intent unchanged file",
            )
            total += item["size_bytes"]
            destinations.add(destination)
        _require(total <= MAX_CODE_CHANGE_TOTAL_BYTES, "online code intent total bytes")
        _require(
            files == sorted(files, key=lambda item: item["destination"]),
            "online code intent file order",
        )
        return
    _require(contract.get("schema_version") == "c28f_reviewed_code_change_intent_v1", "code intent schema")
    _require(contract.get("goal_id") == GOAL_ID and contract.get("attempt_id") == attempt_id, "code intent owner")
    code_change_id = contract.get("code_change_id")
    _require(isinstance(code_change_id, str) and CODE_CHANGE_ID_RE.fullmatch(code_change_id), "code intent ID")
    _require(
        contract.get("code_change_intent_sha256")
        == semantic_sha256(contract, excluded_fields=("code_change_intent_sha256",)),
        "code intent semantic hash",
    )
    _require(contract.get("commit_action") == "COMMIT_REVIEWED_CODE_CHANGE", "code intent commit action")
    _require(contract.get("resume_action") == contract.get("prepare_action"), "code intent resume action")
    files = contract.get("files")
    _require(isinstance(files, list) and 1 <= len(files) <= MAX_CODE_CHANGE_FILES, "code intent file count")
    total = 0
    destinations: set[str] = set()
    expected_hashes: dict[str, str] = {}
    for item in files:
        _require(isinstance(item, dict) and item.get("operation") == "ADD", "code intent operation")
        destination = item.get("destination")
        size = item.get("size_bytes")
        digest = item.get("sha256")
        _require(isinstance(destination, str) and destination not in destinations, "code intent destination")
        _safe_code_destination(destination)
        _require(type(size) is int and 0 < size <= MAX_CODE_CHANGE_FILE_BYTES, "code intent file size")
        _require(isinstance(digest, str) and HEX64.fullmatch(digest), "code intent file hash")
        _require(item.get("expected_preimage_sha256") is None, "code intent ADD preimage")
        total += size
        destinations.add(destination)
        expected_hashes[destination] = digest
    _require(total <= MAX_CODE_CHANGE_TOTAL_BYTES, "code intent total bytes")
    _validate_code_change_review_receipt(contract.get("static_review_receipt"), expected_hashes)
    _require(
        contract.get("static_review_receipt_sha256")
        == bytes_sha256(_canonical_file_bytes(contract["static_review_receipt"])),
        "code intent review receipt file hash",
    )


def _load_code_change_contracts(
    *,
    attempt_id: str,
) -> dict[str, dict[str, Any]]:
    contracts: dict[str, dict[str, Any]] = {}
    transactions_root = CONTROL_ROOT / "transactions"
    with os.scandir(transactions_root) as iterator:
        entries = sorted(iterator, key=lambda item: item.name)
    for entry in entries:
        if CODE_CHANGE_ID_RE.fullmatch(entry.name) is None:
            continue
        _require(entry.is_dir(follow_symlinks=False) and not entry.is_symlink(), "code intent dir type")
        with os.scandir(entry.path) as iterator:
            names = sorted(item.name for item in iterator)
        _require(names == ["reviewed_code_change_intent.json"], "code intent dir namespace")
        contract, _encoded = _read_canonical_json(
            Path(entry.path) / "reviewed_code_change_intent.json"
        )
        _require(isinstance(contract, dict), "code intent object")
        _validate_code_change_contract_payload(contract, attempt_id=attempt_id)
        _require(contract["code_change_id"] == entry.name, "code intent path/ID")
        contracts[entry.name] = contract
    return contracts


def _reconstruct_bootstrap_inventory(
    current: Mapping[str, Any],
    contracts: Mapping[str, Mapping[str, Any]],
    stage_contracts: Optional[Mapping[str, Mapping[str, Any]]] = None,
    code_change_order: Optional[Sequence[str]] = None,
) -> dict[str, Any]:
    records = {item["path"]: dict(item) for item in current["entries"]}
    ordered_ids = list(code_change_order or sorted(contracts))
    _require(
        len(ordered_ids) == len(set(ordered_ids))
        and set(ordered_ids) == set(contracts),
        "code reconstruction order",
    )
    for code_change_id in reversed(ordered_ids):
        contract = contracts[code_change_id]
        for item in contract["files"]:
            destination = item["destination"]
            installed = records.get(destination)
            _require(installed is not None, f"installed code output missing: {destination}")
            _require(
                installed["sha256"] == item["sha256"]
                and installed["size_bytes"] == item["size_bytes"],
                f"installed code postimage drift: {destination}",
            )
            if item["operation"] == "ADD":
                records.pop(destination)
            else:
                _require(
                    item["operation"] == "REPLACE_EXISTING",
                    f"unsupported reconstructed code operation: {destination}",
                )
                records[destination] = {
                    "path": destination,
                    "type": "regular_file",
                    "size_bytes": item["expected_preimage_size_bytes"],
                    "sha256": item["expected_preimage_sha256"],
                }
    for contract in (stage_contracts or {}).values():
        for item in contract["output_records"]:
            destination = item["destination"]
            installed = records.get(destination)
            if installed is not None:
                _require(
                    installed["sha256"] == item["sha256"]
                    and installed["size_bytes"] == item["size_bytes"],
                    f"installed stage postimage drift: {destination}",
                )
                records.pop(destination)
    return _inventory_from_entries(list(records.values()))


def _validate_stage_commit_intent(
    contract: Mapping[str, Any],
    *,
    attempt_id: str,
) -> None:
    required = {
        "schema_version",
        "goal_id",
        "attempt_id",
        "stage_commit_id",
        "stage_plan",
        "stage_plan_sha256",
        "output_root",
        "output_records",
        "business_preimage_sha256",
        "business_postimage_sha256",
        "prepare_receipt",
        "stage_commit_intent_sha256",
    }
    _require(set(contract) == required, "stage commit intent fields")
    _require(contract.get("schema_version") == "c28f_a4_stage_commit_intent_v1", "stage intent schema")
    _require(contract.get("goal_id") == GOAL_ID and contract.get("attempt_id") == attempt_id, "stage intent owner")
    stage_commit_id = contract.get("stage_commit_id")
    _require(isinstance(stage_commit_id, str) and STAGE_COMMIT_ID_RE.fullmatch(stage_commit_id), "stage commit ID")
    plan = contract.get("stage_plan")
    _require(isinstance(plan, dict) and plan.get("schema_version") == "c28f_a4_stage_plan_v1", "stage plan schema")
    _require(
        plan.get("stage_plan_sha256")
        == semantic_sha256(plan, excluded_fields=("stage_plan_sha256",))
        == contract.get("stage_plan_sha256"),
        "stage plan semantic hash",
    )
    state_binding = plan.get("state_binding")
    _require(isinstance(state_binding, dict), "stage state binding")
    _require(
        state_binding.get("state_binding_sha256")
        == semantic_sha256(state_binding, excluded_fields=("state_binding_sha256",)),
        "stage state binding semantic hash",
    )
    _require(plan.get("goal_id") == GOAL_ID and plan.get("attempt_id") == attempt_id, "stage plan owner")
    _require(plan.get("action_is_unique") is True and plan.get("commit_eligible") is True, "stage plan eligibility")
    _require(plan.get("business_preimage_sha256") == contract.get("business_preimage_sha256"), "stage plan business preimage")
    output_index = plan.get("output_index")
    records = contract.get("output_records")
    _require(
        isinstance(output_index, dict)
        and isinstance(records, list)
        and 1 <= len(records) <= MAX_STAGE_OUTPUT_FILES,
        "stage output set",
    )
    record_by_relative: dict[str, Any] = {}
    total = 0
    for item in records:
        _require(
            isinstance(item, dict)
            and set(item) == {"relative_path", "destination", "sha256", "size_bytes"},
            "stage output record fields",
        )
        relative = item["relative_path"]
        _require(
            isinstance(relative, str)
            and relative == Path(relative).as_posix()
            and Path(relative).parts
            and Path(relative).parts[0] in {"f0_forensics", "f1_protocol"}
            and ".." not in Path(relative).parts
            and "." not in Path(relative).parts,
            "stage output relative path",
        )
        _require(relative not in record_by_relative, "duplicate stage output path")
        _require(isinstance(item["sha256"], str) and HEX64.fullmatch(item["sha256"]), "stage output hash")
        _require(
            type(item["size_bytes"]) is int
            and 0 < item["size_bytes"] <= MAX_STAGE_OUTPUT_FILE_BYTES,
            "stage output size",
        )
        _require(
            output_index.get(relative)
            == {"sha256": item["sha256"], "size_bytes": item["size_bytes"]},
            "stage output index binding",
        )
        total += item["size_bytes"]
        record_by_relative[relative] = item
    _require(set(output_index) == set(record_by_relative), "stage output index closure")
    _require(total <= MAX_STAGE_OUTPUT_TOTAL_BYTES, "stage output total byte cap")
    output_root = contract.get("output_root")
    _require(
        isinstance(output_root, dict)
        and set(output_root) == {"root_id", "absolute_path"}
        and output_root["root_id"] == state_binding.get("isolated_output_root_id")
        and output_root["absolute_path"] == state_binding.get("isolated_output_root_path"),
        "stage output root binding",
    )
    expected_root = REPORT_ROOT / attempt_id / "stage_outputs"
    _require(output_root["absolute_path"] == str(expected_root), "stage output root is not attempt-isolated")
    for relative, item in record_by_relative.items():
        expected_destination = (expected_root / relative).relative_to(REPO_ROOT).as_posix()
        _require(item["destination"] == expected_destination, "stage output destination binding")
    receipt = contract.get("prepare_receipt")
    _require(isinstance(receipt, dict), "stage prepare receipt")
    receipt_fields = {
        "schema_version", "status", "goal_id", "attempt_id", "stage_action",
        "stage_commit_id", "parent_state_sha256", "parent_event_sha256",
        "business_preimage_sha256", "output_hashes", "static_review_receipt_sha256",
        "stage_plan_sha256", "transaction_id", "receipt_sha256",
    }
    _require(set(receipt) == receipt_fields, "stage prepare receipt fields")
    expected_hashes = {name: item["sha256"] for name, item in sorted(record_by_relative.items())}
    expected_receipt_base = {
        "schema_version": "c28f_a4_stage_prepare_receipt_v1",
        "status": "FSYNCED_PREPARED_AWAITING_OUTPUT_CAS",
        "goal_id": GOAL_ID,
        "attempt_id": attempt_id,
        "stage_action": plan["action"],
        "stage_commit_id": stage_commit_id,
        "parent_state_sha256": state_binding["parent_state_sha256"],
        "parent_event_sha256": state_binding["parent_event_sha256"],
        "business_preimage_sha256": contract["business_preimage_sha256"],
        "output_hashes": expected_hashes,
        "static_review_receipt_sha256": plan["static_review_receipt_sha256"],
        "stage_plan_sha256": contract["stage_plan_sha256"],
        "transaction_id": stage_commit_id,
    }
    _require(receipt == _with_semantic_sha(expected_receipt_base, "receipt_sha256"), "stage prepare receipt rebuild")
    _require(
        contract.get("stage_commit_intent_sha256")
        == semantic_sha256(contract, excluded_fields=("stage_commit_intent_sha256",)),
        "stage commit intent semantic hash",
    )


def _load_stage_contracts(*, attempt_id: str) -> dict[str, dict[str, Any]]:
    contracts: dict[str, dict[str, Any]] = {}
    with os.scandir(CONTROL_ROOT / "transactions") as iterator:
        entries = sorted(iterator, key=lambda item: item.name)
    for entry in entries:
        if STAGE_COMMIT_ID_RE.fullmatch(entry.name) is None:
            continue
        _require(entry.is_dir(follow_symlinks=False) and not entry.is_symlink(), "stage transaction dir")
        contract, _encoded = _read_canonical_json(
            Path(entry.path) / "stage_commit_intent.json"
        )
        _require(isinstance(contract, dict), "stage commit intent object")
        _validate_stage_commit_intent(contract, attempt_id=attempt_id)
        _require(contract["stage_commit_id"] == entry.name, "stage intent path/ID")
        stage_plan, stage_plan_bytes = _read_canonical_json(Path(entry.path) / "stage_plan.json")
        prepare_receipt, prepare_bytes = _read_canonical_json(Path(entry.path) / "prepare_receipt.json")
        _require(stage_plan == contract["stage_plan"], "persisted stage plan drift")
        _require(prepare_receipt == contract["prepare_receipt"], "persisted stage prepare receipt drift")
        _require(bool(stage_plan_bytes) and bool(prepare_bytes), "empty stage authority artifact")
        contracts[entry.name] = contract
    return contracts


def _build_stage_commit_receipt(
    contract: Mapping[str, Any],
    state: Mapping[str, Any],
    event: Mapping[str, Any],
) -> dict[str, Any]:
    output_hashes = {
        item["relative_path"]: item["sha256"]
        for item in contract["output_records"]
    }
    base = {
        "schema_version": "c28f_a4_stage_commit_receipt_v1",
        "status": "FSYNCED_CAS_COMMITTED",
        "goal_id": GOAL_ID,
        "attempt_id": contract["attempt_id"],
        "stage_action": contract["stage_plan"]["action"],
        "stage_commit_id": contract["stage_commit_id"],
        "parent_state_sha256": contract["prepare_receipt"]["parent_state_sha256"],
        "parent_event_sha256": contract["prepare_receipt"]["parent_event_sha256"],
        "business_preimage_sha256": contract["business_preimage_sha256"],
        "business_postimage_sha256": contract["business_postimage_sha256"],
        "output_hashes": dict(sorted(output_hashes.items())),
        "static_review_receipt_sha256": contract["stage_plan"][
            "static_review_receipt_sha256"
        ],
        "transaction_id": contract["stage_commit_id"],
        "state_sha256": state["state_sha256"],
        "event_sha256": event["event_sha256"],
        "prepare_receipt_sha256": contract["prepare_receipt"]["receipt_sha256"],
    }
    return _with_semantic_sha(base, "receipt_sha256")


