def _build_id_mapping_access_receipt(
    registry: Mapping[str, Any],
    state: Mapping[str, Any],
    event: Mapping[str, Any],
) -> dict[str, Any]:
    counters = registry["access_counters"]
    observation = registry["source_observation_receipt"]
    manifest_open_count = observation["manifest_content_open_count"]
    train_source_open_count = observation[
        "protected_source_content_open_count"
    ]
    official_open_count = observation["official_val_content_open_count"]
    content_open_count = (
        manifest_open_count + train_source_open_count + official_open_count
    )
    base = {
        "schema_version": "c28f_protected_id_mapping_access_receipt_v3",
        "status": "FSYNCED_ID_ONLY_ACCESS_COMMITTED",
        "goal_id": GOAL_ID,
        "attempt_id": registry["attempt_id"],
        "authority_permission_id": registry["authority_permission_id"],
        "operation_id": registry["operation_id"],
        "access_transaction_id": registry["transaction_id"],
        "running_state_sha256": registry["running_state_sha256"],
        "running_event_sha256": registry["running_event_sha256"],
        "control_capability_sha256": registry[
            "control_capability_sha256"
        ],
        "descriptor_identity_sha256": registry[
            "descriptor_identity_sha256"
        ],
        "access_intent_sha256": registry["access_intent_sha256"],
        **dict(counters),
        "manifest_content_open_count": manifest_open_count,
        "protected_source_content_open_count": train_source_open_count,
        "official_val_content_open_count": official_open_count,
        "source_observation_receipt_sha256": observation["receipt_sha256"],
        "content_open_count": content_open_count,
        "protected_id_mapping_operation_count": 1,
        "model_forward_count": 0,
        "evaluator_count": 0,
        "unmediated_content_open_count": 0,
        "instrumentation_complete": observation["instrumentation_complete"],
        "eval_token_consumed": False,
        "operation_state_before": "RUNNING",
        "operation_state_after": "ACCESSED_AWAITING_PROJECTION_CAS",
        "access_state_sha256": state["state_sha256"],
        "access_event_sha256": event["event_sha256"],
    }
    return _with_semantic_sha(base, "receipt_sha256")


