def _build_finalization_phase_receipt(
    registry: Mapping[str, Any],
    state: Mapping[str, Any],
    event: Mapping[str, Any],
) -> dict[str, Any]:
    phase = registry["phase"]
    base = {
        "schema_version": (
            "c28f_a4_finalization_prepare_receipt_v2"
            if phase == "PREPARE"
            else "c28f_a4_terminal_receipt_v2"
        ),
        "status": "FSYNCED_PREPARED" if phase == "PREPARE" else "COMMITTED",
        "goal_id": GOAL_ID,
        "attempt_id": registry["attempt_id"],
        "finalization_txn_id": registry["finalization_txn_id"],
        "phase": phase,
        "transaction_id": registry["transaction_id"],
        "pending_core_sha256": registry["pending_core_sha256"],
        "final_artifact_hashes_sha256": registry[
            "final_artifact_hashes_sha256"
        ],
        "closed_authority_sha256": registry["closed_authority_sha256"],
        "snapshot_capability_sha256": registry["snapshot_capability_sha256"],
        "previous_phase_receipt_sha256": registry[
            "previous_phase_receipt_sha256"
        ],
        "state_sha256": state["state_sha256"],
        "event_sha256": event["event_sha256"],
        "observed_authority_sha256": (
            registry["closed_authority_sha256"]
            if phase == "COMMIT"
            else None
        ),
        "observed_terminal_state_sha256": (
            state["state_sha256"] if phase == "COMMIT" else None
        ),
        "observed_terminal_event_sha256": (
            event["event_sha256"] if phase == "COMMIT" else None
        ),
        "lease_release_authorized": phase == "COMMIT",
        "authority_reactivation_allowed": False,
        "business_actions_allowed": False,
    }
    return _with_semantic_sha(base, "receipt_sha256")


def _validate_eval_cursor_chain(
    registry: Mapping[str, Any],
    state: Mapping[str, Any],
    event: Mapping[str, Any],
) -> tuple[set[str], set[str], Optional[dict[str, Any]]]:
    pointer_relative = f"transactions/{registry['transaction_id']}/eval_cursor.json"
    pointer_path = CONTROL_ROOT / pointer_relative
    cursor_dir_relative = f"transactions/{registry['transaction_id']}/cursor_receipts"
    cursor_dir = CONTROL_ROOT / cursor_dir_relative
    if not os.path.lexists(pointer_path):
        _require(not os.path.lexists(cursor_dir), "cursor sidecars exist without committed pointer")
        return set(), set(), None
    pointer, pointer_bytes = _read_canonical_json(pointer_path)
    _require(isinstance(pointer, dict), "eval cursor pointer object")
    _require(pointer_bytes == _canonical_file_bytes(pointer), "eval cursor pointer canonical")
    _require(cursor_dir.is_dir() and not cursor_dir.is_symlink(), "eval cursor sidecar directory")
    with os.scandir(cursor_dir) as iterator:
        entries = sorted(iterator, key=lambda item: item.name)
    _require(entries, "eval cursor sidecars missing")
    expected_files = {pointer_relative}
    previous: Optional[str] = None
    latest: Optional[dict[str, Any]] = None
    for index, entry in enumerate(entries):
        _require(entry.is_file(follow_symlinks=False) and not entry.is_symlink(), "eval cursor sidecar type")
        receipt, _encoded = _read_canonical_json(Path(entry.path))
        _require(isinstance(receipt, dict), "eval cursor receipt object")
        for field in ("cursor_sha256", "chunks_sha256", "artifacts_sha256"):
            _require(
                isinstance(receipt.get(field), str)
                and HEX64.fullmatch(receipt[field]),
                f"eval cursor receipt hash: {field}",
            )
        expected = _build_eval_cursor_receipt(
            registry,
            state,
            event,
            cursor_index=index,
            cursor_sha256=receipt.get("cursor_sha256"),
            chunks_sha256=receipt.get("chunks_sha256"),
            artifacts_sha256=receipt.get("artifacts_sha256"),
            previous_cursor_receipt_sha256=previous,
        )
        _require(receipt == expected, f"eval cursor receipt rebuild at {index}")
        expected_name = f"{index:06d}_{receipt['receipt_sha256']}.json"
        _require(entry.name == expected_name, f"eval cursor sidecar name at {index}")
        expected_files.add(f"{cursor_dir_relative}/{expected_name}")
        previous = receipt["receipt_sha256"]
        latest = receipt
    _require(pointer == latest, "eval cursor pointer is not chain tail")
    return expected_files, {cursor_dir_relative}, latest


def _build_lmdb_batch_receipt(
    registry: Mapping[str, Any],
    state: Mapping[str, Any],
    event: Mapping[str, Any],
    *,
    batch_index: int,
    source_id: str,
    source_identity_sha256: str,
    key_manifest_sha256: str,
    key_set_sha256: str,
    source_manifest_sha256: str,
    batch_sha256: str,
    key_count: int,
    shared_ledger_tail_sha256: str,
    previous_batch_receipt_sha256: Optional[str],
) -> dict[str, Any]:
    base = {
        "schema_version": "c28f_a4_lmdb_batch_persistence_receipt_v1",
        "status": "FSYNCED_BATCH_RECEIPT_COMMITTED",
        "goal_id": GOAL_ID,
        "attempt_id": registry["attempt_id"],
        "run_id": registry["run_id"],
        "token_id": registry["token_id"],
        "eval_id": registry["eval_id"],
        "batch_index": batch_index,
        "source_id": source_id,
        "source_identity_sha256": source_identity_sha256,
        "key_manifest_sha256": key_manifest_sha256,
        "key_set_sha256": key_set_sha256,
        "key_count": key_count,
        "source_manifest_sha256": source_manifest_sha256,
        "batch_sha256": batch_sha256,
        "shared_ledger_tail_sha256": shared_ledger_tail_sha256,
        "previous_batch_receipt_sha256": previous_batch_receipt_sha256,
        "running_state_sha256": state["state_sha256"],
        "running_event_sha256": event["event_sha256"],
    }
    return _with_semantic_sha(base, "receipt_sha256")


def _validate_lmdb_batch_chain(
    registry: Mapping[str, Any],
    state: Mapping[str, Any],
    event: Mapping[str, Any],
) -> tuple[set[str], set[str], list[dict[str, Any]]]:
    relative_dir = f"transactions/{registry['transaction_id']}/lmdb_batch_receipts"
    directory = CONTROL_ROOT / relative_dir
    if not os.path.lexists(directory):
        return set(), set(), []
    _require(directory.is_dir() and not directory.is_symlink(), "LMDB receipt directory")
    with os.scandir(directory) as iterator:
        entries = sorted(iterator, key=lambda item: item.name)
    _require(entries, "empty LMDB receipt directory forbidden")
    expected_files: set[str] = set()
    previous: Optional[str] = None
    receipts: list[dict[str, Any]] = []
    source_ids: set[str] = set()
    for index, entry in enumerate(entries):
        _require(entry.is_file(follow_symlinks=False) and not entry.is_symlink(), "LMDB receipt type")
        receipt, _encoded = _read_canonical_json(Path(entry.path))
        _require(isinstance(receipt, dict), "LMDB receipt object")
        _require(
            isinstance(receipt.get("source_id"), str)
            and bool(receipt["source_id"])
            and receipt["source_id"] not in source_ids,
            f"LMDB receipt unique source at {index}",
        )
        source_ids.add(receipt["source_id"])
        for field in (
            "source_identity_sha256",
            "key_manifest_sha256",
            "key_set_sha256",
            "source_manifest_sha256",
            "batch_sha256",
            "shared_ledger_tail_sha256",
        ):
            _require(
                isinstance(receipt.get(field), str) and HEX64.fullmatch(receipt[field]),
                f"LMDB receipt hash: {field}",
            )
        _require(
            type(receipt.get("key_count")) is int and receipt["key_count"] > 0,
            f"LMDB receipt key count at {index}",
        )
        expected = _build_lmdb_batch_receipt(
            registry,
            state,
            event,
            batch_index=index,
            source_id=receipt["source_id"],
            source_identity_sha256=receipt["source_identity_sha256"],
            key_manifest_sha256=receipt["key_manifest_sha256"],
            key_set_sha256=receipt["key_set_sha256"],
            source_manifest_sha256=receipt["source_manifest_sha256"],
            batch_sha256=receipt["batch_sha256"],
            key_count=receipt["key_count"],
            shared_ledger_tail_sha256=receipt["shared_ledger_tail_sha256"],
            previous_batch_receipt_sha256=previous,
        )
        _require(receipt == expected, f"LMDB receipt rebuild at {index}")
        expected_name = f"{index:06d}_{receipt['receipt_sha256']}.json"
        _require(entry.name == expected_name, f"LMDB receipt name at {index}")
        expected_files.add(f"{relative_dir}/{expected_name}")
        previous = receipt["receipt_sha256"]
        receipts.append(receipt)
    return expected_files, {relative_dir}, receipts


def _build_g2_replay_abort_receipt(
    authority: Mapping[str, Any],
    *,
    preopen_committed: bool,
) -> dict[str, Any]:
    payload = authority["payload"]
    base = {
        "schema_version": "c28f_g2_replay_abort_receipt_v1",
        "status": "ABORTED_FAIL_CLOSED",
        "session_id": payload["session_id"],
        "control_handle_capability_sha256": authority["capability_sha256"],
        "committed_state_sha256": payload["committed_state_sha256"],
        "committed_event_sha256": payload["committed_event_sha256"],
        "phase": (
            "PREOPEN_COMMITTED_CONTENT_OPEN_ABORTED"
            if preopen_committed
            else "AUTHORITY_ISSUED_BEFORE_CONTENT_OPEN"
        ),
        "content_open_attempted": preopen_committed,
        "protected_content": False,
        "reason_code": "ONLINE_RECOVERY_AFTER_FAIL_CLOSED_G2_REPLAY",
        "user_authorization_sha256": bytes_sha256(
            ONLINE_CODE_CHANGE_AUTHORIZATION_TEXT.encode("utf-8")
        ),
    }
    return {**base, "receipt_sha256": semantic_sha256(base)}


def _build_g2_replay_failure_observation(
    payload: Mapping[str, Any],
    observed: Mapping[str, Any],
    *,
    content_paths: Sequence[str],
    expected_paths: Sequence[str],
) -> dict[str, Any]:
    checks = {
        "instrumentation_complete": observed.get("instrumentation_complete")
        is True,
        "sys_profile_restored": observed.get("sys_profile_restored") is True,
        "thread_profile_restored": observed.get("thread_profile_restored")
        is True,
        "regular_content_open_count_is_four": observed.get(
            "regular_content_open_count"
        )
        == 4,
        "write_mutation_event_count_is_zero": observed.get(
            "write_mutation_event_count"
        )
        == 0,
        "data_loader_call_count_is_zero": observed.get(
            "data_loader_call_count"
        )
        == 0,
        "model_forward_call_count_is_zero": observed.get(
            "model_forward_call_count"
        )
        == 0,
        "subprocess_call_count_is_zero": observed.get(
            "subprocess_call_count"
        )
        == 0,
        "preopened_regular_fd_change_count_is_zero": observed.get(
            "preopened_regular_fd_change_count"
        )
        == 0,
        "new_regular_fd_count_is_zero": observed.get(
            "new_regular_fd_count"
        )
        == 0,
        "content_paths_exact": list(content_paths) == list(expected_paths),
    }
    base = {
        "schema_version": "c28f_g2_replay_failure_observation_v1",
        "status": "FAIL_CLOSED_OBSERVER_CLOSURE_MISMATCH",
        "session_id": payload["session_id"],
        "control_handle_capability_sha256": semantic_sha256(payload),
        "protected_content": False,
        "closure_checks": checks,
        "content_paths": list(content_paths),
        "expected_content_paths": list(expected_paths),
        "observer": dict(observed),
    }
    return {**base, "observation_sha256": semantic_sha256(base)}


def _build_g2_parity_failure_observation(
    payload: Mapping[str, Any],
    *,
    control_handle_capability_sha256: str,
    close_receipt: Mapping[str, Any],
    legacy_metrics: Mapping[str, Any],
    current_metrics: Mapping[str, Any],
) -> dict[str, Any]:
    """Seal non-protected aggregate metrics when historical parity fails."""

    from blueprint_e2e_v2.c28f_v5.a4_metrics import (
        C7_LEGACY_VCMR_PARITY_FIELD_MAP,
        compare_vcmr_parity,
    )

    legacy = dict(legacy_metrics)
    current = dict(current_metrics)
    _require(
        bytes_sha256(canonical_json_bytes(legacy))
        == close_receipt.get("legacy_metrics_sha256")
        and bytes_sha256(canonical_json_bytes(current))
        == close_receipt.get("current_metrics_sha256"),
        "G2 parity failure observation metric commitments",
    )
    parity = compare_vcmr_parity(
        legacy,
        current,
        field_map=C7_LEGACY_VCMR_PARITY_FIELD_MAP,
        tolerance=0.000001,
        legacy_unit="percent",
        current_unit="ratio",
    )
    _require(
        parity.get("status") == "FAIL",
        "G2 parity failure observation requires failed parity",
    )
    base = {
        "schema_version": "c28f_g2_parity_failure_observation_v1",
        "status": "FAIL_CLOSED_HISTORICAL_PARITY_MISMATCH",
        "session_id": payload["session_id"],
        "control_handle_capability_sha256": (
            control_handle_capability_sha256
        ),
        "committed_state_sha256": payload["committed_state_sha256"],
        "committed_event_sha256": payload["committed_event_sha256"],
        "close_receipt_sha256": close_receipt["receipt_sha256"],
        "replay_packet_sha256": close_receipt[
            "replay_packet_sha256"
        ],
        "legacy_metrics_sha256": close_receipt["legacy_metrics_sha256"],
        "current_metrics_sha256": close_receipt[
            "current_metrics_sha256"
        ],
        "legacy_metric_unit": "percent",
        "current_metric_unit": "ratio",
        "protected_content": False,
        "legacy_metrics": legacy,
        "current_metrics": current,
        "parity": parity,
    }
    return {**base, "observation_sha256": semantic_sha256(base)}


def _recover_incomplete_g2_replay_sessions(lease: WriterLease) -> None:
    """Persist fail-closed aborts before retrying G2 in a new process."""

    state, _state_bytes, _events, _journal = _current_state_and_events()
    if state.get("next_action") != "G2_METRIC_CONTRACT":
        return
    transactions = CONTROL_ROOT / "transactions"
    with os.scandir(transactions) as iterator:
        entries = sorted(
            (
                entry
                for entry in iterator
                if G2_REPLAY_SESSION_RE.fullmatch(entry.name) is not None
            ),
            key=lambda item: item.name,
        )
    for entry in entries:
        _require(
            entry.is_dir(follow_symlinks=False) and not entry.is_symlink(),
            "G2 recovery session directory type",
        )
        session_root = Path(entry.path)
        if os.path.lexists(session_root / "abort_receipt.json"):
            continue
        authority, _authority_bytes = _read_canonical_json(
            session_root / "session_authority.json"
        )
        _require(
            isinstance(authority, dict)
            and authority.get("record_sha256")
            == semantic_sha256(
                authority,
                excluded_fields=("record_sha256",),
            )
            and authority.get("payload", {}).get("session_id")
            == entry.name,
            "G2 recovery authority",
        )
        atomic_write_immutable(
            session_root / "abort_receipt.json",
            _canonical_file_bytes(
                _build_g2_replay_abort_receipt(
                    authority,
                    preopen_committed=os.path.lexists(
                        session_root / "preopen_receipt.json"
                    ),
                )
            ),
            lease=lease,
        )


def _validate_g2_replay_sessions() -> tuple[set[str], set[str]]:
    transactions = CONTROL_ROOT / "transactions"
    with os.scandir(transactions) as iterator:
        entries = sorted(
            (
                entry
                for entry in iterator
                if G2_REPLAY_SESSION_RE.fullmatch(entry.name) is not None
            ),
            key=lambda item: item.name,
        )
    expected_files: set[str] = set()
    expected_directories: set[str] = set()
    active_session_count = 0
    ordered_names = [
        "session_authority.json",
        "preopen_receipt.json",
        "legacy_metrics_receipt.json",
        "close_receipt.json",
        "parity_receipt.json",
    ]
    for entry in entries:
        _require(
            entry.is_dir(follow_symlinks=False) and not entry.is_symlink(),
            "G2 replay session directory type",
        )
        with os.scandir(entry.path) as iterator:
            names = sorted(item.name for item in iterator)
        observed_names = set(names)
        aborted = "abort_receipt.json" in observed_names
        phase_names = observed_names - {
            "abort_receipt.json",
            "failure_observation.json",
            "parity_failure_observation.json",
        }
        _require(
            bool(names)
            and any(
                phase_names == set(ordered_names[:phase_count])
                for phase_count in range(1, len(ordered_names) + 1)
            ),
            "G2 replay sidecar phase namespace/order",
        )
        active_session_count += int(not aborted)
        prefix = f"transactions/{entry.name}"
        expected_directories.add(prefix)
        authority, _encoded = _read_canonical_json(
            Path(entry.path) / "session_authority.json"
        )
        _require(
            isinstance(authority, dict)
            and set(authority)
            == {
                "schema_version", "status", "capability_sha256", "payload",
                "record_sha256",
            }
            and authority.get("schema_version")
            == "c28f_a4_g2_replay_session_authority_v1"
            and authority.get("status") == "FSYNCED_CONTROLLER_ISSUED"
            and authority.get("record_sha256")
            == semantic_sha256(authority, excluded_fields=("record_sha256",))
            and authority.get("capability_sha256")
            == semantic_sha256(authority.get("payload"))
            and authority.get("payload", {}).get("session_id") == entry.name,
            "G2 replay session authority",
        )
        expected_files.add(f"{prefix}/session_authority.json")
        previous_receipts: dict[str, dict[str, Any]] = {}
        for filename in ordered_names[1:]:
            if filename not in observed_names:
                continue
            receipt, _receipt_bytes = _read_canonical_json(
                Path(entry.path) / filename
            )
            _require(
                isinstance(receipt, dict)
                and receipt.get("receipt_sha256")
                == semantic_sha256(receipt, excluded_fields=("receipt_sha256",))
                and receipt.get("control_handle_capability_sha256")
                == authority["capability_sha256"],
                f"G2 replay sidecar binding: {filename}",
            )
            previous_receipts[filename] = dict(receipt)
            expected_files.add(f"{prefix}/{filename}")
        if "legacy_metrics_receipt.json" in previous_receipts:
            _require(
                previous_receipts["legacy_metrics_receipt.json"].get(
                    "preopen_receipt_sha256"
                )
                == previous_receipts["preopen_receipt.json"]["receipt_sha256"],
                "G2 legacy/preopen chain",
            )
        if "close_receipt.json" in previous_receipts:
            _require(
                previous_receipts["close_receipt.json"].get(
                    "preopen_receipt_sha256"
                )
                == previous_receipts["preopen_receipt.json"]["receipt_sha256"]
                and previous_receipts["close_receipt.json"].get(
                    "legacy_metric_receipt_sha256"
                )
                == previous_receipts["legacy_metrics_receipt.json"][
                    "receipt_sha256"
                ],
                "G2 close receipt chain",
            )
        if aborted:
            abort_receipt, _abort_bytes = _read_canonical_json(
                Path(entry.path) / "abort_receipt.json"
            )
            _require(
                isinstance(abort_receipt, dict)
                and abort_receipt
                == _build_g2_replay_abort_receipt(
                    authority,
                    preopen_committed="preopen_receipt.json" in observed_names,
                ),
                "G2 replay abort receipt",
            )
            expected_files.add(f"{prefix}/abort_receipt.json")
        if "failure_observation.json" in observed_names:
            failure, _failure_bytes = _read_canonical_json(
                Path(entry.path) / "failure_observation.json"
            )
            _require(
                isinstance(failure, dict)
                and failure.get("schema_version")
                == "c28f_g2_replay_failure_observation_v1"
                and failure.get("status")
                == "FAIL_CLOSED_OBSERVER_CLOSURE_MISMATCH"
                and failure.get("session_id") == entry.name
                and failure.get("control_handle_capability_sha256")
                == authority["capability_sha256"]
                and failure.get("protected_content") is False
                and failure.get("observation_sha256")
                == semantic_sha256(
                    failure,
                    excluded_fields=("observation_sha256",),
                )
                and isinstance(failure.get("closure_checks"), dict)
                and not all(failure["closure_checks"].values()),
                "G2 replay failure observation",
            )
            expected_files.add(f"{prefix}/failure_observation.json")
        if "parity_failure_observation.json" in observed_names:
            _require(
                "close_receipt.json" in previous_receipts,
                "G2 parity failure observation requires replay closure",
            )
            failure, _failure_bytes = _read_canonical_json(
                Path(entry.path) / "parity_failure_observation.json"
            )
            _require(
                isinstance(failure, dict)
                and failure
                == _build_g2_parity_failure_observation(
                    authority["payload"],
                    control_handle_capability_sha256=authority[
                        "capability_sha256"
                    ],
                    close_receipt=previous_receipts[
                        "close_receipt.json"
                    ],
                    legacy_metrics=failure.get("legacy_metrics", {}),
                    current_metrics=failure.get("current_metrics", {}),
                ),
                "G2 parity failure observation",
            )
            expected_files.add(
                f"{prefix}/parity_failure_observation.json"
            )
    _require(
        active_session_count <= 1,
        "multiple active G2 replay sessions",
    )
    return expected_files, expected_directories


def _g6_synthetic_cache_roots() -> list[Path]:
    if not os.path.lexists(CACHE_ROOT):
        return []
    roots: list[Path] = []
    with os.scandir(CACHE_ROOT) as iterator:
        attempt_entries = sorted(iterator, key=lambda entry: entry.name)
    for entry in attempt_entries:
        if A4_ATTEMPT_RE.fullmatch(entry.name) is None:
            continue
        _require(
            entry.is_dir(follow_symlinks=False) and not entry.is_symlink(),
            "G6 synthetic cache attempt root type",
        )
        candidate = Path(entry.path) / "g6_synthetic_recovery"
        if not os.path.lexists(candidate):
            continue
        identity = candidate.lstat()
        _require(
            stat.S_ISDIR(identity.st_mode)
            and not stat.S_ISLNK(identity.st_mode),
            "G6 synthetic cache root type",
        )
        roots.append(candidate)
    _require(len(roots) <= 1, "multiple G6 synthetic cache roots")
    return roots


def _validate_g6_synthetic_sessions() -> tuple[set[str], set[str]]:
    synthetic_cache_roots = _g6_synthetic_cache_roots()
    transactions = CONTROL_ROOT / "transactions"
    with os.scandir(transactions) as iterator:
        entries = sorted(
            (
                entry
                for entry in iterator
                if G6_SYNTHETIC_SESSION_RE.fullmatch(entry.name) is not None
            ),
            key=lambda item: item.name,
    )
    _require(len(entries) <= 1, "multiple G6 synthetic sessions")
    _require(
        bool(entries) == bool(synthetic_cache_roots),
        "G6 synthetic session/cache-root prefix closure",
    )
    expected_files: set[str] = set()
    expected_directories: set[str] = set()
    for entry in entries:
        _require(
            entry.is_dir(follow_symlinks=False) and not entry.is_symlink(),
            "G6 synthetic session directory type",
        )
        prefix = "transactions/%s" % entry.name
        expected_directories.add(prefix)
        root_record, _root_bytes = _read_canonical_json(
            Path(entry.path) / "root_handle.json"
        )
        _require(
            isinstance(root_record, dict)
            and root_record.get("schema_version")
            == "c28f_a4_g6_synthetic_root_handle_record_v1"
            and root_record.get("status") == "FSYNCED_CONTROLLER_ISSUED"
            and root_record.get("capability_sha256")
            == semantic_sha256(root_record.get("payload"))
            and root_record.get("record_sha256")
            == semantic_sha256(
                root_record,
                excluded_fields=("record_sha256",),
            )
            and _g6_synthetic_session_id(root_record["payload"])
            == entry.name,
            "G6 synthetic persisted root handle record",
        )
        _require(
            len(synthetic_cache_roots) == 1
            and synthetic_cache_roots[0]
            == Path(root_record["payload"]["parent_root_path"]),
            "G6 synthetic cache root/session authority binding",
        )
        expected_files.add("%s/root_handle.json" % prefix)
        child_names = root_record["payload"].get("child_root_names")
        _require(
            isinstance(child_names, dict) and len(child_names) == 4,
            "G6 synthetic persisted child mapping",
        )
        allowed_names = {"root_handle.json", "bundle_input.json"}
        for child_name in child_names.values():
            allowed_names.update(
                {
                    "consume_%s.json" % child_name,
                    "unstarted_reissue_%s.json" % child_name,
                    "unstarted_resume_consumed_%s.json" % child_name,
                    "rehydrate_%s.json" % child_name,
                    "rehydrate_access_%s.json" % child_name,
                    "evidence_%s.json" % child_name,
                    "crash_receipt_%s.json" % child_name,
                    "executor_v2_intent_%s.json" % child_name,
                    "executor_v2_completion_%s.json" % child_name,
                    "legacy_terminal_migration_intent_%s.json"
                    % child_name,
                }
            )
        with os.scandir(entry.path) as iterator:
            session_entries = sorted(iterator, key=lambda item: item.name)
        _require(
            all(
                item.is_file(follow_symlinks=False) and not item.is_symlink()
                for item in session_entries
            ),
            "G6 synthetic session contains a non-regular object",
        )
        observed_names = {item.name for item in session_entries}
        owner_name_patterns = tuple(
            re.compile(
                r"executor_v2_owner_%s_[0-9]{6}_[0-9a-f]{64}\.json"
                % re.escape(child_name)
            )
            for child_name in child_names.values()
        )
        _require(
            all(
                name in allowed_names
                or any(pattern.fullmatch(name) for pattern in owner_name_patterns)
                for name in observed_names
            )
            and "root_handle.json" in observed_names,
            "G6 synthetic session file namespace",
        )
        receipt_count = 0
        completion_count = 0
        for crash_point, child_name in sorted(child_names.items()):
            consume_name = "consume_%s.json" % child_name
            unstarted_name = "unstarted_reissue_%s.json" % child_name
            unstarted_consumed_name = (
                "unstarted_resume_consumed_%s.json" % child_name
            )
            rehydrate_name = "rehydrate_%s.json" % child_name
            rehydrate_access_name = (
                "rehydrate_access_%s.json" % child_name
            )
            evidence_name = "evidence_%s.json" % child_name
            receipt_name = "crash_receipt_%s.json" % child_name
            executor_intent_name = (
                "executor_v2_intent_%s.json" % child_name
            )
            executor_completion_name = (
                "executor_v2_completion_%s.json" % child_name
            )
            migration_intent_name = (
                "legacy_terminal_migration_intent_%s.json" % child_name
            )
            child_owner_pattern = re.compile(
                r"executor_v2_owner_%s_[0-9]{6}_[0-9a-f]{64}\.json"
                % re.escape(child_name)
            )
            child_owner_names = sorted(
                name
                for name in observed_names
                if child_owner_pattern.fullmatch(name) is not None
            )
            if migration_intent_name in observed_names:
                _require(
                    executor_intent_name not in observed_names
                    and consume_name in observed_names
                    and not child_owner_names,
                    "G6 legacy migration authority namespace collision",
                )
                _require(
                    os.path.lexists(
                        Path(root_record["payload"]["parent_root_path"])
                        / child_name
                    ),
                    "G6 legacy migration lost terminal child",
                )
                parent_fd, child_fd, child_descriptor, _created = (
                    _g6_open_controller_child(
                        root_payload=root_record["payload"],
                        child_name=child_name,
                        child_root_binding_sha256=semantic_sha256(
                            {
                                "synthetic_root_handle_sha256": root_record[
                                    "capability_sha256"
                                ],
                                "crash_point": crash_point,
                                "child_root_name": child_name,
                                "child_root_path": str(
                                    Path(
                                        root_record["payload"][
                                            "parent_root_path"
                                        ]
                                    )
                                    / child_name
                                ),
                                "parent_descriptor_identity_sha256": (
                                    root_record["payload"][
                                        "parent_descriptor_identity_sha256"
                                    ]
                                ),
                                "child_root_contract_sha256": root_record[
                                    "payload"
                                ]["child_root_contract_sha256"],
                            }
                        ),
                        create_if_absent=False,
                    )
                )
                try:
                    observed_bytes = _g6_read_controller_child_bytes(
                        child_fd,
                        expected_device=child_descriptor["device"],
                        expected_mount_id=child_descriptor["mount_id"],
                    )
                finally:
                    os.close(child_fd)
                    os.close(parent_fd)
                expected_bytes = _g6_fixed_expected_material(crash_point)[
                    "expected_artifact_bytes"
                ]
                _require(
                    observed_bytes == expected_bytes,
                    "G6 legacy migration terminal bytes drift",
                )
                actual = _g6_controller_reread_actual_postimage(
                    root_handle_sha256=root_record["capability_sha256"],
                    root_handle_payload=root_record["payload"],
                    crash_point=crash_point,
                    child_root_name=child_name,
                    child_root_binding_sha256=child_descriptor[
                        "child_root_binding_sha256"
                    ],
                )
                migration_record, _migration_bytes = _read_canonical_json(
                    Path(entry.path) / migration_intent_name
                )
                migration_intent = (
                    _validate_g6_legacy_terminal_migration_intent(
                        migration_record,
                        session=Path(entry.path),
                        root_payload=root_record["payload"],
                        root_handle_sha256=root_record["capability_sha256"],
                        actual_postimage=actual,
                    )
                )
                expected_files.add(
                    "%s/%s" % (prefix, migration_intent_name)
                )
                expected_files.update(
                    "%s/%s" % (prefix, name)
                    for name in migration_intent[
                        "legacy_authority_records"
                    ]
                )
                if evidence_name in observed_names:
                    evidence, _evidence_bytes = _read_canonical_json(
                        Path(entry.path) / evidence_name
                    )
                    _require(
                        evidence
                        == _g6_rebuild_fixed_evidence(
                            intent=migration_intent,
                            actual_postimage=actual,
                        ),
                        "G6 legacy migration evidence rebuild",
                    )
                    expected_files.add("%s/%s" % (prefix, evidence_name))
                if receipt_name in observed_names:
                    _require(
                        evidence_name in observed_names,
                        "G6 legacy migration receipt lacks evidence",
                    )
                    receipt, _receipt_bytes = _read_canonical_json(
                        Path(entry.path) / receipt_name
                    )
                    _require(
                        receipt.get("evidence_sha256")
                        == evidence["evidence_sha256"]
                        and receipt.get("actual_postimage") == actual
                        and receipt.get("receipt_sha256")
                        == semantic_sha256(
                            receipt,
                            excluded_fields=("receipt_sha256",),
                        ),
                        "G6 legacy migration receipt rebuild",
                    )
                    receipt_count += 1
                    expected_files.add("%s/%s" % (prefix, receipt_name))
                if executor_completion_name in observed_names:
                    _require(
                        receipt_name in observed_names,
                        "G6 legacy migration completion lacks receipt",
                    )
                    completion, _completion_bytes = _read_canonical_json(
                        Path(entry.path) / executor_completion_name
                    )
                    _validate_g6_v2_completion_record(
                        completion,
                        session=Path(entry.path),
                        intent=migration_intent,
                        root_payload=root_record["payload"],
                        actual_postimage=actual,
                    )
                    completion_count += 1
                    expected_files.add(
                        "%s/%s" % (prefix, executor_completion_name)
                    )
                continue
            if executor_intent_name in observed_names:
                _require(
                    consume_name not in observed_names
                    and unstarted_name not in observed_names
                    and unstarted_consumed_name not in observed_names
                    and rehydrate_name not in observed_names
                    and rehydrate_access_name not in observed_names,
                    "G6 v1/v2 synthetic executor namespace collision",
                )
                intent_record, _executor_intent_bytes = (
                    _read_canonical_json(
                        Path(entry.path) / executor_intent_name
                    )
                )
                intent = _validate_g6_executor_intent(
                    intent_record,
                    root_payload=root_record["payload"],
                    root_handle_sha256=root_record["capability_sha256"],
                )
                _require(
                    intent["crash_point"] == crash_point
                    and intent["child_root_name"] == child_name,
                    "G6 v2 intent child mapping",
                )
                expected_files.add(
                    "%s/%s" % (prefix, executor_intent_name)
                )
                owners = _g6_executor_owner_records(
                    session=Path(entry.path),
                    intent=intent,
                    root_payload=root_record["payload"],
                    root_handle_sha256=root_record["capability_sha256"],
                )
                _require(
                    len(child_owner_names) == len(owners) - 1,
                    "G6 v2 executor owner namespace closure",
                )
                expected_files.update(
                    "%s/%s" % (prefix, name)
                    for name in child_owner_names
                )
                child_path = Path(intent["child_root_path"])
                if os.path.lexists(child_path):
                    parent_fd, child_fd, child_descriptor, _created = (
                        _g6_open_controller_child(
                            root_payload=root_record["payload"],
                            child_name=child_name,
                            child_root_binding_sha256=intent[
                                "child_root_binding_sha256"
                            ],
                            create_if_absent=False,
                        )
                    )
                    try:
                        observed_bytes = _g6_read_controller_child_bytes(
                            child_fd,
                            expected_device=child_descriptor["device"],
                            expected_mount_id=child_descriptor["mount_id"],
                        )
                    finally:
                        os.close(child_fd)
                        os.close(parent_fd)
                else:
                    observed_bytes = {}
                expected_bytes = _g6_fixed_expected_material(crash_point)[
                    "expected_artifact_bytes"
                ]
                _require(
                    observed_bytes == {} or observed_bytes == expected_bytes,
                    "G6 v2 persisted child is partial/nonterminal",
                )
                if evidence_name in observed_names:
                    _require(
                        observed_bytes == expected_bytes,
                        "G6 v2 evidence requires terminal postimage",
                    )
                    actual = _g6_controller_reread_actual_postimage(
                        root_handle_sha256=root_record["capability_sha256"],
                        root_handle_payload=root_record["payload"],
                        crash_point=crash_point,
                        child_root_name=child_name,
                        child_root_binding_sha256=intent[
                            "child_root_binding_sha256"
                        ],
                    )
                    evidence, _evidence_bytes = _read_canonical_json(
                        Path(entry.path) / evidence_name
                    )
                    _require(
                        evidence
                        == _g6_rebuild_fixed_evidence(
                            intent=intent,
                            actual_postimage=actual,
                        ),
                        "G6 v2 persisted evidence rebuild",
                    )
                    expected_files.add(
                        "%s/%s" % (prefix, evidence_name)
                    )
                if receipt_name in observed_names:
                    _require(
                        evidence_name in observed_names,
                        "G6 v2 receipt lacks evidence prefix",
                    )
                    receipt, _receipt_bytes = _read_canonical_json(
                        Path(entry.path) / receipt_name
                    )
                    _require(
                        receipt.get("evidence_sha256")
                        == evidence["evidence_sha256"]
                        and receipt.get("actual_postimage") == actual
                        and receipt.get("receipt_sha256")
                        == semantic_sha256(
                            receipt,
                            excluded_fields=("receipt_sha256",),
                        ),
                        "G6 v2 persisted receipt rebuild",
                    )
                    receipt_count += 1
                    expected_files.add(
                        "%s/%s" % (prefix, receipt_name)
                    )
                if executor_completion_name in observed_names:
                    _require(
                        receipt_name in observed_names,
                        "G6 v2 completion lacks receipt prefix",
                    )
                    completion, _completion_bytes = _read_canonical_json(
                        Path(entry.path) / executor_completion_name
                    )
                    _validate_g6_v2_completion_record(
                        completion,
                        session=Path(entry.path),
                        intent=intent,
                        root_payload=root_record["payload"],
                        actual_postimage=actual,
                    )
                    completion_count += 1
                    expected_files.add(
                        "%s/%s" % (prefix, executor_completion_name)
                    )
                continue
            _require(
                not child_owner_names
                and executor_completion_name not in observed_names,
                "G6 v2 owner/completion without intent",
            )
            if consume_name not in observed_names:
                _require(
                    rehydrate_name not in observed_names
                    and unstarted_name not in observed_names
                    and unstarted_consumed_name not in observed_names
                    and rehydrate_access_name not in observed_names
                    and evidence_name not in observed_names
                    and receipt_name not in observed_names,
                    "G6 evidence without child consumption",
                )
                continue
            consumption, _consume_bytes = _read_canonical_json(
                Path(entry.path) / consume_name
            )
            _require(
                consumption.get("schema_version")
                == "c28f_a4_g6_child_root_consumption_v1"
                and consumption.get("synthetic_root_handle_sha256")
                == root_record["capability_sha256"]
                and consumption.get("crash_point") == crash_point
                and consumption.get("child_root_name") == child_name
                and consumption.get("receipt_sha256")
                == semantic_sha256(
                    consumption,
                    excluded_fields=("receipt_sha256",),
                ),
                "G6 child consumption receipt",
            )
            expected_files.add("%s/%s" % (prefix, consume_name))
            if unstarted_name in observed_names:
                unstarted_record, _unstarted_bytes = _read_canonical_json(
                    Path(entry.path) / unstarted_name
                )
                unstarted = unstarted_record.get("payload")
                child_descriptor = (
                    unstarted.get("child_descriptor")
                    if isinstance(unstarted, dict)
                    else None
                )
                _require(
                    isinstance(unstarted, dict)
                    and set(unstarted)
                    == {
                        "schema_version", "status", "goal_id",
                        "attempt_id", "synthetic_root_handle_sha256",
                        "crash_point", "child_root_name",
                        "child_root_path", "child_root_binding_sha256",
                        "consumption_receipt_sha256",
                        "parent_descriptor_identity_sha256",
                        "child_descriptor",
                        "child_descriptor_identity_sha256",
                        "controller_precreated_empty", "synthetic_only",
                        "one_shot_per_capability", "resume_binding_sha256",
                    }
                    and unstarted.get("schema_version")
                    == (
                        "c28f_a4_g6_synthetic_unstarted_"
                        "resume_capability_v1"
                    )
                    and unstarted.get("status")
                    == (
                        "FSYNCED_CONTROLLER_PRECREATED_EMPTY_"
                        "CHILD_FOR_RESUME"
                    )
                    and unstarted.get("synthetic_root_handle_sha256")
                    == root_record["capability_sha256"]
                    and unstarted.get("crash_point") == crash_point
                    and unstarted.get("child_root_name") == child_name
                    and unstarted.get("child_root_binding_sha256")
                    == consumption["child_root_binding_sha256"]
                    and unstarted.get("consumption_receipt_sha256")
                    == consumption["receipt_sha256"]
                    and isinstance(child_descriptor, dict)
                    and unstarted.get("child_descriptor_identity_sha256")
                    == semantic_sha256(child_descriptor)
                    and child_descriptor.get("mode") == "0o700"
                    and child_descriptor.get("child_root_binding_sha256")
                    == consumption["child_root_binding_sha256"]
                    and unstarted.get("controller_precreated_empty") is True
                    and unstarted.get("synthetic_only") is True
                    and unstarted.get("one_shot_per_capability") is True
                    and unstarted.get("resume_binding_sha256")
                    == semantic_sha256(
                        unstarted,
                        excluded_fields=("resume_binding_sha256",),
                    )
                    and unstarted_record.get("schema_version")
                    == (
                        "c28f_a4_g6_synthetic_unstarted_"
                        "resume_record_v1"
                    )
                    and unstarted_record.get("status")
                    == "FSYNCED_UNSTARTED_REISSUE_CLAIM"
                    and unstarted_record.get("capability_sha256")
                    == semantic_sha256(unstarted)
                    and unstarted_record.get("record_sha256")
                    == semantic_sha256(
                        unstarted_record,
                        excluded_fields=("record_sha256",),
                    ),
                    "G6 persisted unstarted resume claim",
                )
                expected_files.add("%s/%s" % (prefix, unstarted_name))
            if unstarted_consumed_name in observed_names:
                _require(
                    unstarted_name in observed_names,
                    "G6 unstarted consume lacks reissue claim",
                )
                marker, _marker_bytes = _read_canonical_json(
                    Path(entry.path) / unstarted_consumed_name
                )
                _require(
                    isinstance(marker, dict)
                    and set(marker)
                    == {
                        "schema_version", "status",
                        "synthetic_root_handle_sha256", "crash_point",
                        "child_root_name", "child_root_binding_sha256",
                        "resume_capability_sha256",
                        "resume_binding_sha256",
                        "child_descriptor_identity_sha256",
                        "receipt_sha256",
                    }
                    and marker.get("schema_version")
                    == (
                        "c28f_a4_g6_synthetic_unstarted_"
                        "resume_consumption_v1"
                    )
                    and marker.get("status")
                    == "FSYNCED_GLOBAL_ONE_SHOT_RESUME_CONSUMED"
                    and marker.get("synthetic_root_handle_sha256")
                    == root_record["capability_sha256"]
                    and marker.get("crash_point") == crash_point
                    and marker.get("child_root_name") == child_name
                    and marker.get("child_root_binding_sha256")
                    == consumption["child_root_binding_sha256"]
                    and marker.get("resume_capability_sha256")
                    == unstarted_record["capability_sha256"]
                    and marker.get("resume_binding_sha256")
                    == unstarted["resume_binding_sha256"]
                    and marker.get("child_descriptor_identity_sha256")
                    == unstarted["child_descriptor_identity_sha256"]
                    and marker.get("receipt_sha256")
                    == semantic_sha256(
                        marker,
                        excluded_fields=("receipt_sha256",),
                    ),
                    "G6 persisted global unstarted resume consumption",
                )
                expected_files.add(
                    "%s/%s" % (prefix, unstarted_consumed_name)
                )
            if rehydrate_name in observed_names:
                rehydrate_record, _rehydrate_bytes = _read_canonical_json(
                    Path(entry.path) / rehydrate_name
                )
                rehydrate = rehydrate_record.get("payload")
                _require(
                    isinstance(rehydrate, dict)
                    and rehydrate.get("schema_version")
                    == (
                        "c28f_a4_g6_synthetic_postimage_"
                        "rehydrate_capability_v1"
                    )
                    and rehydrate.get("status")
                    == (
                        "CONTROLLER_VERIFIED_SYNTHETIC_"
                        "POSTIMAGE_REHYDRATE"
                    )
                    and rehydrate.get("synthetic_root_handle_sha256")
                    == root_record["capability_sha256"]
                    and rehydrate.get("crash_point") == crash_point
                    and rehydrate.get("child_root_name") == child_name
                    and rehydrate.get("child_root_binding_sha256")
                    == consumption["child_root_binding_sha256"]
                    and rehydrate.get("consumption_receipt_sha256")
                    == consumption["receipt_sha256"]
                    and rehydrate.get("actual_postimage_sha256")
                    == _validate_g6_actual_postimage(
                        rehydrate.get("actual_postimage")
                    )["postimage_sha256"]
                    and rehydrate.get("rehydrate_binding_sha256")
                    == semantic_sha256(
                        rehydrate,
                        excluded_fields=("rehydrate_binding_sha256",),
                    )
                    and rehydrate_record.get("schema_version")
                    == (
                        "c28f_a4_g6_synthetic_postimage_"
                        "rehydrate_record_v1"
                    )
                    and rehydrate_record.get("status")
                    == "FSYNCED_CONTROLLER_ISSUED"
                    and rehydrate_record.get("capability_sha256")
                    == semantic_sha256(rehydrate)
                    and rehydrate_record.get("record_sha256")
                    == semantic_sha256(
                        rehydrate_record,
                        excluded_fields=("record_sha256",),
                    ),
                    "G6 persisted postimage rehydrate record",
                )
                expected_files.add("%s/%s" % (prefix, rehydrate_name))
            if rehydrate_access_name in observed_names:
                _require(
                    rehydrate_name in observed_names,
                    "G6 rehydrate access lacks issued capability",
                )
                access, _access_bytes = _read_canonical_json(
                    Path(entry.path) / rehydrate_access_name
                )
                _require(
                    isinstance(access, dict)
                    and set(access)
                    == {
                        "schema_version", "status",
                        "synthetic_root_handle_sha256", "crash_point",
                        "child_root_binding_sha256",
                        "consumption_receipt_sha256", "actual_postimage",
                        "artifact_bytes_sha256s",
                        "access_receipt_sha256",
                    }
                    and access.get("schema_version")
                    == (
                        "c28f_a4_g6_synthetic_postimage_"
                        "rehydrate_access_v1"
                    )
                    and access.get("status")
                    == (
                        "CONTROLLER_READONLY_SYNTHETIC_"
                        "POSTIMAGE_REHYDRATED"
                    )
                    and access.get("synthetic_root_handle_sha256")
                    == root_record["capability_sha256"]
                    and access.get("crash_point") == crash_point
                    and access.get("child_root_binding_sha256")
                    == consumption["child_root_binding_sha256"]
                    and access.get("consumption_receipt_sha256")
                    == consumption["receipt_sha256"]
                    and access.get("actual_postimage")
                    == rehydrate["actual_postimage"]
                    and access.get("artifact_bytes_sha256s")
                    == {
                        item["name"]: item["sha256"]
                        for item in access["actual_postimage"][
                            "artifact_inventory"
                        ]
                    }
                    and access.get("access_receipt_sha256")
                    == semantic_sha256(
                        access,
                        excluded_fields=("access_receipt_sha256",),
                    ),
                    "G6 persisted postimage rehydrate access",
                )
                expected_files.add(
                    "%s/%s" % (prefix, rehydrate_access_name)
                )
            if evidence_name in observed_names:
                evidence, _evidence_bytes = _read_canonical_json(
                    Path(entry.path) / evidence_name
                )
                _require(
                    evidence.get("schema_version")
                    == "c28f_synthetic_atomic_recovery_evidence_v1"
                    and evidence.get("synthetic_root_handle_sha256")
                    == root_record["capability_sha256"]
                    and evidence.get("crash_point") == crash_point
                    and evidence.get("evidence_sha256")
                    == semantic_sha256(
                        evidence,
                        excluded_fields=("evidence_sha256",),
                    ),
                    "G6 persisted harness evidence",
                )
                expected_files.add("%s/%s" % (prefix, evidence_name))
            if receipt_name in observed_names:
                _require(
                    evidence_name in observed_names,
                    "G6 crash receipt lacks persisted evidence",
                )
                receipt, _receipt_bytes = _read_canonical_json(
                    Path(entry.path) / receipt_name
                )
                _require(
                    receipt.get("schema_version")
                    == "c28f_g6_controlled_synthetic_crash_receipt_v2"
                    and receipt.get("synthetic_root_handle_sha256")
                    == root_record["capability_sha256"]
                    and receipt.get("crash_point") == crash_point
                    and receipt.get("evidence_sha256")
                    == evidence["evidence_sha256"]
                    and receipt.get("receipt_sha256")
                    == semantic_sha256(
                        receipt,
                        excluded_fields=("receipt_sha256",),
                    ),
                    "G6 controlled crash receipt",
                )
                receipt_count += 1
                expected_files.add("%s/%s" % (prefix, receipt_name))
        if "bundle_input.json" in observed_names:
            bundle_record, _bundle_bytes = _read_canonical_json(
                Path(entry.path) / "bundle_input.json"
            )
            _require(
                receipt_count == 4
                and completion_count == 4
                and bundle_record.get("schema_version")
                == "c28f_a4_g6_bundle_input_record_v1"
                and bundle_record.get("status")
                == "FSYNCED_CONTROLLER_ISSUED"
                and bundle_record.get("capability_sha256")
                == semantic_sha256(bundle_record.get("payload"))
                and bundle_record.get("record_sha256")
                == semantic_sha256(
                    bundle_record,
                    excluded_fields=("record_sha256",),
                ),
                "G6 bundle input persisted record",
            )
            expected_files.add("%s/bundle_input.json" % prefix)
    return expected_files, expected_directories


def _validate_g2_power_computation_sessions() -> tuple[set[str], set[str]]:
    transactions = CONTROL_ROOT / "transactions"
    with os.scandir(transactions) as iterator:
        entries = sorted(
            (
                entry
                for entry in iterator
                if G2_POWER_COMPUTATION_RE.fullmatch(entry.name) is not None
            ),
            key=lambda item: item.name,
        )
    _require(len(entries) <= 1, "multiple G2 power computation sessions")
    files: set[str] = set()
    directories: set[str] = set()
    for entry in entries:
        _require(
            entry.is_dir(follow_symlinks=False) and not entry.is_symlink(),
            "G2 power computation session directory",
        )
        with os.scandir(entry.path) as iterator:
            names = sorted(item.name for item in iterator)
        _require(
            names in ([], ["receipt_record.json"]),
            "G2 power computation session namespace",
        )
        prefix = "transactions/%s" % entry.name
        directories.add(prefix)
        if not names:
            continue
        record, _record_bytes = _read_canonical_json(
            Path(entry.path) / "receipt_record.json"
        )
        payload = record.get("payload")
        _require(
            isinstance(payload, dict)
            and payload.get("receipt_sha256")
            == semantic_sha256(payload, excluded_fields=("receipt_sha256",))
            and entry.name
            == "G2-POWER-%s" % payload["receipt_sha256"][:32]
            and record.get("capability_sha256") == semantic_sha256(payload)
            and record.get("payload_file_sha256")
            == bytes_sha256(_canonical_file_bytes(payload))
            and record.get("record_sha256")
            == semantic_sha256(record, excluded_fields=("record_sha256",)),
            "G2 power computation persisted record",
        )
        files.add("%s/receipt_record.json" % prefix)
    return files, directories


def _validate_train_jsonl_index_sessions(
    state: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
) -> tuple[set[str], set[str]]:
    sessions = _all_train_jsonl_index_sessions()
    files: set[str] = set()
    directories: set[str] = set()
    claims_by_session: dict[str, dict[str, Any]] = {}
    aborts_by_session: dict[str, dict[str, Any]] = {}
    allowed_progressions = (
        {"scan_claim.json"},
        {"scan_claim.json", "abort_receipt.json"},
        {"scan_claim.json", "train_jsonl_index.json"},
        {
            "scan_claim.json", "train_jsonl_index.json",
            "bootstrap_receipt.json",
        },
        {
            "scan_claim.json", "train_jsonl_index.json",
            "bootstrap_receipt.json", "transition_intent.json",
        },
        {
            "scan_claim.json", "train_jsonl_index.json",
            "bootstrap_receipt.json", "transition_intent.json",
            "plan.json",
        },
    )
    for session in sessions:
        with os.scandir(session) as iterator:
            names = {entry.name for entry in iterator}
        projection_names = {
            name
            for name in names
            if re.fullmatch(
                r"(?:trusted_query_)?projection_"
                r"TRAIN-PROJECTION-[0-9a-f]{32}\.json",
                name,
            )
            is not None
        }
        projection_claim_names = {
            name
            for name in names
            if re.fullmatch(
                r"projection_claim_TRAIN-PROJECTION-"
                r"[0-9a-f]{32}\.json",
                name,
            )
            is not None
        }
        role_authority_names = {
            name
            for name in names
            if re.fullmatch(
                r"role_authority_F0_[AB]_FORWARD_QUERY_IDENTITY\.json",
                name,
            )
            is not None
        }
        post_forward_role_authority_names = {
            name
            for name in names
            if re.fullmatch(
                r"post_forward_role_authority_F0_[AB]_"
                r"POST_FORWARD_EVAL_STATS\.json",
                name,
            )
            is not None
        }
        role_claim_names = {
            name
            for name in names
            if re.fullmatch(
                r"role_authority_claim_F0_[AB]_"
                r"FORWARD_QUERY_IDENTITY\.json",
                name,
            )
            is not None
        }
        aux_role_authority_names = {
            name
            for name in names
            if re.fullmatch(
                r"aux_role_authority_G4_(?:PROTECTED_ID_MAPPING_ONLY|"
                r"TRAIN_FIT_ROLE_MAPPING)\.json",
                name,
            )
            is not None
        }
        aux_role_claim_names = {
            name
            for name in names
            if re.fullmatch(
                r"aux_role_claim_G4_(?:PROTECTED_ID_MAPPING_ONLY|"
                r"TRAIN_FIT_ROLE_MAPPING)\.json",
                name,
            )
            is not None
        }
        base_names = (
            names
            - projection_names
            - projection_claim_names
            - role_authority_names
            - post_forward_role_authority_names
            - role_claim_names
            - aux_role_authority_names
            - aux_role_claim_names
        )
        _require(
            base_names in allowed_progressions,
            "TRAIN index session progressive namespace",
        )
        _require(
            len(projection_names) <= 8
            and len(projection_claim_names) <= 6
            and len(role_authority_names) <= 2
            and len(post_forward_role_authority_names) <= 2
            and len(role_claim_names) <= 2
            and len(aux_role_authority_names) <= 2
            and len(aux_role_claim_names) <= 2
            and (
                not (
                    projection_names
                    or projection_claim_names
                    or role_authority_names
                    or post_forward_role_authority_names
                    or role_claim_names
                    or aux_role_authority_names
                    or aux_role_claim_names
                )
                or base_names == allowed_progressions[-1]
            )
            and {
                name.removeprefix("role_authority_").removesuffix(".json")
                for name in role_authority_names
            }
            <= {
                name.removeprefix("role_authority_claim_").removesuffix(
                    ".json"
                )
                for name in role_claim_names
            }
            and {
                name.removeprefix("aux_role_authority_").removesuffix(
                    ".json"
                )
                for name in aux_role_authority_names
            }
            <= {
                name.removeprefix("aux_role_claim_").removesuffix(".json")
                for name in aux_role_claim_names
            },
            "TRAIN projection/role authority exact committed namespace",
        )
        claim, _claim_bytes = _read_canonical_json(
            session / "scan_claim.json"
        )
        claim = _validate_train_jsonl_index_scan_claim(claim)
        _require(
            session.name == claim["transaction_id"],
            "TRAIN index session/claim transaction",
        )
        prefix = "transactions/%s" % session.name
        claims_by_session[session.name] = claim
        directories.add(prefix)
        files.add("%s/scan_claim.json" % prefix)
        if "abort_receipt.json" in base_names:
            loaded_abort, _abort_bytes = _read_canonical_json(
                session / "abort_receipt.json"
            )
            abort_receipt = (
                _validate_train_jsonl_index_scan_abort_receipt(
                    loaded_abort,
                    claim=claim,
                )
            )
            aborts_by_session[session.name] = abort_receipt
            files.add("%s/abort_receipt.json" % prefix)
        index: Optional[dict[str, Any]] = None
        receipt: Optional[dict[str, Any]] = None
        if "train_jsonl_index.json" in base_names:
            loaded_index, index_bytes = _read_canonical_json(
                session / "train_jsonl_index.json",
                max_bytes=1024 * 1024 * 1024,
            )
            index = _validate_train_jsonl_descriptor_index(
                loaded_index,
                claim=claim,
            )
            files.add("%s/train_jsonl_index.json" % prefix)
        if "bootstrap_receipt.json" in base_names:
            _require(index is not None, "TRAIN index receipt preimage")
            loaded_receipt, _receipt_bytes = _read_canonical_json(
                session / "bootstrap_receipt.json"
            )
            receipt = _validate_train_jsonl_index_bootstrap_receipt(
                loaded_receipt,
                claim=claim,
                index=index,
                index_file_sha256=bytes_sha256(index_bytes),
            )
            files.add("%s/bootstrap_receipt.json" % prefix)
        if "transition_intent.json" in base_names:
            _require(
                index is not None and receipt is not None,
                "TRAIN index transition preimages",
            )
            envelope, _envelope_bytes = _read_canonical_json(
                session / "transition_intent.json"
            )
            _validate_transition_envelope(
                envelope,
                attempt_id=claim["attempt_id"],
            )
            _require(
                envelope["transaction_id"] == claim["transaction_id"]
                and envelope["action"]
                == "G2_TRAIN_JSONL_INDEX_BOOTSTRAP"
                and envelope["result"]
                == (
                    "FSYNCED_DESCRIPTOR_BOUND_INDEX_COMMITTED_"
                    "NONREPLAYABLE"
                )
                and envelope["registry_name"]
                == "train_jsonl_index_registry.json"
                and envelope["registry_payload"]
                == _build_train_jsonl_index_registry(
                    claim=claim,
                    index=index,
                    receipt=receipt,
                ),
                "TRAIN index transition envelope binding",
            )
            files.add("%s/transition_intent.json" % prefix)
        if "plan.json" in base_names:
            plan, _plan_bytes = _read_canonical_json(session / "plan.json")
            _require(
                isinstance(plan, dict)
                and plan.get("transaction_id") == claim["transaction_id"]
                and plan.get("action")
                == "G2_TRAIN_JSONL_INDEX_BOOTSTRAP"
                and plan.get("plan_sha256")
                == semantic_sha256(plan, excluded_fields=("plan_sha256",)),
                "TRAIN index transaction plan",
            )
            files.add("%s/plan.json" % prefix)
        role_authorities_by_projection_id: dict[
            str, tuple[dict[str, Any], list[int]]
        ] = {}
        base_role_authorities_by_token: dict[
            str, tuple[dict[str, Any], list[int]]
        ] = {}
        for token_id in ("F0_A", "F0_B"):
            role_id = "%s_FORWARD_QUERY_IDENTITY" % token_id
            authority_name = "role_authority_%s.json" % role_id
            claim_name = "role_authority_claim_%s.json" % role_id
            if claim_name not in role_claim_names:
                _require(
                    authority_name not in role_authority_names,
                    "TRAIN role authority without preopen claim",
                )
                continue
            _require(
                index is not None
                and receipt is not None,
                "TRAIN role claim requires committed index preimages",
            )
            loaded_role_claim, _role_claim_bytes = _read_canonical_json(
                session / claim_name
            )
            role_claim = _validate_f0_role_manifest_preopen_claim(
                loaded_role_claim,
                state=state,
                events=events,
                expected_token_id=token_id,
            )
            files.add("%s/%s" % (prefix, claim_name))
            if authority_name not in role_authority_names:
                continue
            authority_record, _authority_bytes = _read_canonical_json(
                session / authority_name
            )
            authority, authority_desc_ids = (
                _validate_f0_query_role_manifest_authority_record(
                    authority_record,
                    preopen_claim=role_claim,
                    state=state,
                    events=events,
                    expected_token_id=token_id,
                )
            )
            projection_seed = {
                "schema_version": "c28f_a4_train_projection_seed_v1",
                "index_binding_sha256": index["index_binding_sha256"],
                "purpose": authority["purpose"],
                "role_id": authority["role_id"],
                "role_manifest_authority_binding_sha256": authority[
                    "authority_binding_sha256"
                ],
                "requested_desc_ids_sha256": authority[
                    "desc_ids_sha256"
                ],
            }
            expected_projection_id = "TRAIN-PROJECTION-%s" % semantic_sha256(
                projection_seed
            )[:32]
            _require(
                expected_projection_id
                not in role_authorities_by_projection_id,
                "TRAIN role authority projection ID collision",
            )
            role_authorities_by_projection_id[expected_projection_id] = (
                authority,
                authority_desc_ids,
            )
            base_role_authorities_by_token[token_id] = (
                authority,
                authority_desc_ids,
            )
            files.add("%s/%s" % (prefix, authority_name))
        for token_id in ("F0_A", "F0_B"):
            role_id = "%s_POST_FORWARD_EVAL_STATS" % token_id
            authority_name = "post_forward_role_authority_%s.json" % role_id
            if authority_name not in post_forward_role_authority_names:
                continue
            _require(
                index is not None
                and receipt is not None
                and token_id in base_role_authorities_by_token,
                "post-forward role authority requires base role/index",
            )
            matching_consumers: list[dict[str, Any]] = []
            with os.scandir(CONTROL_ROOT / "transactions") as iterator:
                derivation_entries = sorted(
                    (
                        entry
                        for entry in iterator
                        if FORWARD_DERIVATION_SESSION_RE.fullmatch(
                            entry.name
                        )
                        is not None
                        and entry.is_dir(follow_symlinks=False)
                        and not entry.is_symlink()
                    ),
                    key=lambda item: item.name,
                )
            for derivation_entry in derivation_entries:
                consumer_record, _consumer_bytes = _read_canonical_json(
                    Path(derivation_entry.path) / "consumer_capability.json"
                )
                consumer_payload = (
                    _validate_forward_derivation_consumer_payload(
                        consumer_record.get("payload")
                    )
                )
                if consumer_payload["token_id"] != token_id:
                    continue
                _require(
                    consumer_record.get("schema_version")
                    == "c28f_a4_forward_derivation_consumer_record_v1"
                    and consumer_record.get("status")
                    == "FSYNCED_CONTROLLER_ISSUED"
                    and consumer_record.get("capability_sha256")
                    == semantic_sha256(consumer_payload)
                    and consumer_record.get("record_sha256")
                    == semantic_sha256(
                        consumer_record,
                        excluded_fields=("record_sha256",),
                    )
                    and derivation_entry.name
                    == _forward_derivation_session_id(consumer_payload),
                    "post-forward role consumer record binding",
                )
                matching_consumers.append(consumer_payload)
            _require(
                len(matching_consumers) == 1,
                "post-forward role unique completed consumer",
            )
            consumer = matching_consumers[0]
            _validate_forward_derivation_completion_lineage(
                consumer,
                events=events,
            )
            loaded_post_authority, _post_authority_bytes = (
                _read_canonical_json(session / authority_name)
            )
            base_authority, base_desc_ids = (
                base_role_authorities_by_token[token_id]
            )
            post_authority = _validate_f0_post_forward_role_authority_record(
                loaded_post_authority,
                base_authority=base_authority,
                desc_ids=base_desc_ids,
                consumer=consumer,
            )
            projection_seed = {
                "schema_version": "c28f_a4_train_projection_seed_v1",
                "index_binding_sha256": index["index_binding_sha256"],
                "purpose": post_authority["purpose"],
                "role_id": post_authority["role_id"],
                "role_manifest_authority_binding_sha256": post_authority[
                    "authority_binding_sha256"
                ],
                "requested_desc_ids_sha256": post_authority[
                    "desc_ids_sha256"
                ],
            }
            expected_projection_id = "TRAIN-PROJECTION-%s" % semantic_sha256(
                projection_seed
            )[:32]
            _require(
                expected_projection_id
                not in role_authorities_by_projection_id,
                "post-forward role authority projection ID collision",
            )
            role_authorities_by_projection_id[expected_projection_id] = (
                post_authority,
                base_desc_ids,
            )
            files.add("%s/%s" % (prefix, authority_name))
        if aux_role_claim_names or aux_role_authority_names:
            _require(
                index is not None and receipt is not None,
                "G4 auxiliary role authority requires committed TRAIN index",
            )
            g1_authority, _g1_authority_file_sha = (
                _read_committed_g1_genesis_registry(
                    "g1_registry_authority.json"
                )
            )
            protected_manifest_contract = (
                _protected_id_mapping_manifest_contract(g1_authority)
            )
            train_probe = g1_authority["metadata_path_probe"]
            _require(
                train_probe.get("path") == str(TRAIN_FIT_MANIFEST),
                "G4 auxiliary train-fit descriptor source",
            )
            aux_source_commitments = {
                "PROTECTED_ID_MAPPING_ONLY": {
                    "schema_version": (
                        "c28f_a4_g4_protected_manifest_commitment_v1"
                    ),
                    "kind": "FROZEN_PROTECTED_DESC_ID_MANIFEST_CONTRACT",
                    "contract_sha256": protected_manifest_contract[
                        "contract_sha256"
                    ],
                    "manifests": [
                        {
                            "absolute_path": manifest["absolute_path"],
                            "content_sha256": manifest["content_sha256"],
                            "descriptor_identity_sha256": manifest[
                                "descriptor_identity_sha256"
                            ],
                        }
                        for manifest in protected_manifest_contract["manifests"]
                    ],
                },
                "TRAIN_FIT_ROLE_MAPPING": {
                    "schema_version": (
                        "c28f_a4_g4_train_fit_manifest_commitment_v1"
                    ),
                    "kind": "FROZEN_G1_TRAIN_FIT_DESCRIPTOR",
                    "absolute_path": str(TRAIN_FIT_MANIFEST),
                    "expected_descriptor_identity": train_probe[
                        "expected_descriptor_identity"
                    ],
                    "expected_descriptor_identity_sha256": train_probe[
                        "expected_descriptor_identity_sha256"
                    ],
                },
            }
            for purpose in (
                "PROTECTED_ID_MAPPING_ONLY",
                "TRAIN_FIT_ROLE_MAPPING",
            ):
                role_id = str(_G4_AUX_ROLE_SPECS[purpose]["role_id"])
                claim_name = "aux_role_claim_%s.json" % role_id
                authority_name = "aux_role_authority_%s.json" % role_id
                if claim_name not in aux_role_claim_names:
                    _require(
                        authority_name not in aux_role_authority_names,
                        "G4 auxiliary authority without preopen claim",
                    )
                    continue
                loaded_aux_claim, _aux_claim_bytes = _read_canonical_json(
                    session / claim_name
                )
                aux_claim = _validate_g4_aux_role_claim(
                    loaded_aux_claim,
                    purpose=purpose,
                    source_commitment=aux_source_commitments[purpose],
                    state=state,
                    events=events,
                )
                files.add("%s/%s" % (prefix, claim_name))
                if authority_name not in aux_role_authority_names:
                    continue
                loaded_aux_authority, _aux_authority_bytes = (
                    _read_canonical_json(
                        session / authority_name,
                        max_bytes=32 * 1024 * 1024,
                    )
                )
                aux_authority, aux_desc_ids = (
                    _validate_g4_aux_role_authority(
                        loaded_aux_authority,
                        claim=aux_claim,
                        state=state,
                        events=events,
                    )
                )
                projection_seed = {
                    "schema_version": "c28f_a4_train_projection_seed_v1",
                    "index_binding_sha256": index[
                        "index_binding_sha256"
                    ],
                    "purpose": aux_authority["purpose"],
                    "role_id": aux_authority["role_id"],
                    "role_manifest_authority_binding_sha256": (
                        aux_authority["authority_binding_sha256"]
                    ),
                    "requested_desc_ids_sha256": aux_authority[
                        "desc_ids_sha256"
                    ],
                }
                expected_projection_id = (
                    "TRAIN-PROJECTION-%s"
                    % semantic_sha256(projection_seed)[:32]
                )
                _require(
                    expected_projection_id
                    not in role_authorities_by_projection_id,
                    "G4 auxiliary role projection ID collision",
                )
                role_authorities_by_projection_id[expected_projection_id] = (
                    aux_authority,
                    aux_desc_ids,
                )
                files.add("%s/%s" % (prefix, authority_name))
        expected_projection_claim_names = {
            "projection_claim_%s.json" % projection_id
            for projection_id in role_authorities_by_projection_id
        }
        _require(
            projection_claim_names <= expected_projection_claim_names,
            "TRAIN projection claim lacks independent role authority",
        )
        projection_preopen_claims: dict[str, dict[str, Any]] = {}
        for projection_id, role_preimage in sorted(
            role_authorities_by_projection_id.items()
        ):
            projection_claim_name = "projection_claim_%s.json" % projection_id
            if projection_claim_name not in projection_claim_names:
                continue
            loaded_projection_claim, _projection_claim_bytes = (
                _read_canonical_json(session / projection_claim_name)
            )
            role_authority, authority_desc_ids = role_preimage
            projection_preopen_claims[projection_id] = (
                _validate_train_projection_preopen_claim(
                    loaded_projection_claim,
                    projection_id=projection_id,
                    role_manifest_authority=role_authority,
                    requested_desc_ids=authority_desc_ids,
                    index=index,
                    state=state,
                    events=events,
                )
            )
            files.add("%s/%s" % (prefix, projection_claim_name))
        projection_records: dict[str, dict[str, Any]] = {}
        for name in sorted(
            item
            for item in projection_names
            if item.startswith("projection_")
        ):
            record, _record_bytes = _read_canonical_json(
                session / name,
                max_bytes=1024 * 1024 * 1024,
            )
            _require(
                isinstance(record, dict),
                "persisted authorized TRAIN projection object",
            )
            projection_id = record.get("projection_id")
            access = record.get("access_receipt")
            role_authority_preimage = role_authorities_by_projection_id.get(
                projection_id
            )
            projection_preopen_claim = projection_preopen_claims.get(
                projection_id
            )
            _require(
                role_authority_preimage is not None
                and projection_preopen_claim is not None
                and record.get("schema_version")
                == "c28f_a4_authorized_train_projection_record_v1"
                and record.get("status")
                == "FSYNCED_AUTHORIZED_PREAD_PROJECTION"
                and isinstance(projection_id, str)
                and re.fullmatch(
                    r"TRAIN-PROJECTION-[0-9a-f]{32}",
                    projection_id,
                )
                is not None
                and name == "projection_%s.json" % projection_id
                and record.get("index_binding_sha256")
                == (None if index is None else index["index_binding_sha256"])
                and isinstance(record.get("records"), list)
                and record.get("records_sha256")
                == bytes_sha256(canonical_json_bytes(record["records"]))
                and isinstance(access, dict)
                and access.get("projection_id") == projection_id
                and access.get("purpose") == record.get("purpose")
                and access.get("role_id") == record.get("role_id")
                and access.get("records_sha256")
                == record["records_sha256"]
                and access.get("physical_content_open_count") == 1
                and isinstance(access.get("observer_summary"), dict)
                and access["observer_summary"].get("summary_sha256")
                == access.get("observer_summary_sha256")
                == semantic_sha256(
                    access["observer_summary"],
                    excluded_fields=("summary_sha256",),
                )
                and access.get("pread_call_count")
                == access.get("requested_desc_id_count")
                == len(record["records"])
                and access.get("full_line_json_decode_count") == 0
                and access.get(
                    "unauthorized_field_semantic_decode_count"
                ) == 0
                and access.get("receipt_sha256")
                == semantic_sha256(
                    access,
                    excluded_fields=("receipt_sha256",),
                )
                and record.get("record_sha256")
                == semantic_sha256(
                    record,
                    excluded_fields=("record_sha256",),
                ),
                "persisted authorized TRAIN projection",
            )
            _require(index is not None, "TRAIN projection committed index")
            role_authority, authority_desc_ids = role_authority_preimage
            projection_records[projection_id] = (
                _validate_authorized_train_projection_record(
                    record,
                    preopen_claim=projection_preopen_claim,
                    role_manifest_authority=role_authority,
                    desc_ids=authority_desc_ids,
                    index=index,
                    control_state=state,
                    control_events=events,
                )
            )
            files.add("%s/%s" % (prefix, name))
        expected_projection_file_names = {
            "projection_%s.json" % projection_id
            for projection_id in role_authorities_by_projection_id
        }
        _require(
            {
                name
                for name in projection_names
                if name.startswith("projection_")
            }
            <= expected_projection_file_names,
            "TRAIN projection filename lacks independent role authority",
        )
        for name in sorted(
            item
            for item in projection_names
            if item.startswith("trusted_query_projection_")
        ):
            capability_record, _capability_bytes = _read_canonical_json(
                session / name,
                max_bytes=1024 * 1024 * 1024,
            )
            projection_id = name[
                len("trusted_query_projection_") : -len(".json")
            ]
            projection_record = projection_records.get(projection_id)
            role_authority_preimage = role_authorities_by_projection_id.get(
                projection_id
            )
            _require(
                projection_record is not None
                and role_authority_preimage is not None
                and index is not None
                and receipt is not None,
                "persisted trusted query projection committed preimages",
            )
            _validate_persisted_trusted_query_projection_record(
                capability_record,
                projection_record=projection_record,
                role_manifest_authority=role_authority_preimage[0],
                index=index,
                index_receipt=receipt,
            )
            files.add("%s/%s" % (prefix, name))
    _require(
        len(aborts_by_session) <= 1,
        "TRAIN index aborted session cardinality",
    )
    active_session_names = sorted(
        set(claims_by_session) - set(aborts_by_session)
    )
    _require(
        len(active_session_names) <= 1,
        "TRAIN index active session cardinality",
    )
    if aborts_by_session:
        aborted_name = next(iter(aborts_by_session))
        aborted_claim = claims_by_session[aborted_name]
        _require(
            aborted_claim["schema_version"]
            == "c28f_a4_train_jsonl_index_scan_claim_v1",
            "TRAIN index retry must abort the original claim",
        )
        if active_session_names:
            retry_claim = claims_by_session[active_session_names[0]]
            _require(
                retry_claim["schema_version"]
                == "c28f_a4_train_jsonl_index_retry_scan_claim_v1"
                and retry_claim["prior_failed_transaction_id"]
                == aborted_claim["transaction_id"]
                and retry_claim["prior_failed_claim_sha256"]
                == aborted_claim["claim_sha256"]
                and retry_claim["prior_abort_receipt_sha256"]
                == aborts_by_session[aborted_name]["receipt_sha256"],
                "TRAIN index retry/abort cross-session lineage",
            )
    elif active_session_names:
        _require(
            claims_by_session[active_session_names[0]]["schema_version"]
            == "c28f_a4_train_jsonl_index_scan_claim_v1",
            "TRAIN index retry claim requires an aborted predecessor",
        )
    return files, directories


def _controller_forward_authority_record_paths() -> list[tuple[str, Path]]:
    records: list[tuple[str, Path]] = []
    transactions = CONTROL_ROOT / "transactions"
    with os.scandir(transactions) as iterator:
        entries = sorted(iterator, key=lambda item: item.name)
    for entry in entries:
        if not entry.is_dir(follow_symlinks=False) or entry.is_symlink():
            continue
        path = Path(entry.path) / "controller_forward_authority.json"
        if os.path.lexists(path):
            records.append((entry.name, path))
    _require(
        len(records) <= 2,
        "controller forward authority persisted record cardinality",
    )
    return records


def _validate_persisted_controller_forward_authority_record(
    value: Any,
    *,
    origin_transaction_id: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    record_fields = {
        "schema_version", "status", "capability_sha256", "payload",
        "active_rehydrate_projection",
        "active_rehydrate_projection_sha256", "record_sha256",
    }
    payload_fields = {
        "schema_version", "status", "goal_id", "attempt_id",
        "authority_id", "stage", "purpose", "token_id",
        "origin_transaction_id", "origin_state_sha256",
        "origin_event_sha256", "forward_manifest_sha256",
        "input_identity_sha256", "authority_binding_sha256",
        "query_identity", "query_text_slice_commitment_sha256",
        "query_identity_source_access_receipt",
        "query_identity_source_access_receipt_sha256",
        "corpus_identity", "query_source_descriptor",
        "query_source_descriptor_identity_sha256",
        "query_source_selected_projection_sha256",
        "query_source_index_binding_sha256",
        "query_source_index_bootstrap_receipt_sha256",
        "query_source_file_sha256", "video_meta_source_descriptor",
        "video_meta_source_file_sha256", "split_source_lineage",
        "feature_source_descriptor_set_sha256",
        "code_source_set_sha256", "metric_schema_sha256",
        "evaluator_schema_sha256", "environment_sha256",
        "source_semantic_minimization", "handle_binding_sha256",
    }
    projection_fields = {
        "schema_version", "status", "manifest", "query_keys",
        "corpus_video_ids", "corpus_durations_sec",
        "authority_binding_material", "authority_binding_sha256",
        "forward_authority_handle_sha256", "forward_manifest_sha256",
        "input_identity_sha256", "encoded_cache_fingerprint",
        "descriptor_only", "source_content_present",
        "active_content_opened", "eval_token_reissued",
        "projection_binding_sha256",
    }
    payload = value.get("payload") if isinstance(value, dict) else None
    projection = (
        value.get("active_rehydrate_projection")
        if isinstance(value, dict)
        else None
    )
    stage_contracts = {
        "F0_A": (
            "G3_F0_A",
            "F0_A_TEACHER_FREE_CALIB_SELECT_FORENSICS",
        ),
        "F0_B": (
            "G5_F0_B",
            "F0_B_ROUTE_DEV_REPLICATION",
        ),
    }
    _require(
        isinstance(value, dict)
        and set(value) == record_fields
        and value["schema_version"]
        == "c28f_a4_controller_forward_authority_record_v1"
        and value["status"] == "FSYNCED_CONTROLLER_BUILT"
        and isinstance(payload, dict)
        and set(payload) == payload_fields
        and payload["schema_version"]
        == "c28f_a4_controller_forward_authority_handle_v1"
        and payload["status"] == "CONTROLLER_BUILT_UNRESERVED"
        and payload["goal_id"] == GOAL_ID
        and isinstance(payload["attempt_id"], str)
        and A4_ATTEMPT_RE.fullmatch(payload["attempt_id"]) is not None
        and payload["token_id"] in stage_contracts
        and (payload["stage"], payload["purpose"])
        == stage_contracts[payload["token_id"]]
        and payload["origin_transaction_id"] == origin_transaction_id
        and payload["handle_binding_sha256"]
        == semantic_sha256(
            payload,
            excluded_fields=("handle_binding_sha256",),
        )
        and value["capability_sha256"] == semantic_sha256(payload)
        and isinstance(projection, dict)
        and set(projection) == projection_fields
        and projection["schema_version"]
        == "c28f_a4_active_forward_authority_rehydrate_projection_v1"
        and projection["status"]
        == "ACTIVE_AUTHORITY_DESCRIPTOR_ONLY_RECOVERY_PROJECTION"
        and projection["descriptor_only"] is True
        and projection["source_content_present"] is False
        and projection["active_content_opened"] is False
        and projection["eval_token_reissued"] is False
        and projection["forward_authority_handle_sha256"]
        == value["capability_sha256"]
        and projection["authority_binding_sha256"]
        == payload["authority_binding_sha256"]
        and projection["forward_manifest_sha256"]
        == payload["forward_manifest_sha256"]
        and projection["input_identity_sha256"]
        == payload["input_identity_sha256"]
        and projection["projection_binding_sha256"]
        == value["active_rehydrate_projection_sha256"]
        == semantic_sha256(
            projection,
            excluded_fields=("projection_binding_sha256",),
        )
        and value["record_sha256"]
        == semantic_sha256(value, excluded_fields=("record_sha256",)),
        "controller forward authority persisted exact record",
    )
    for field_name in (
        "origin_state_sha256", "origin_event_sha256",
        "forward_manifest_sha256", "input_identity_sha256",
        "authority_binding_sha256", "handle_binding_sha256",
    ):
        _require(
            isinstance(payload[field_name], str)
            and HEX64.fullmatch(payload[field_name]) is not None,
            "controller forward authority persisted hash: %s"
            % field_name,
        )
    manifest = projection["manifest"]
    material = projection["authority_binding_material"]
    _require(
        isinstance(manifest, dict)
        and manifest.get("attempt_id") == payload["attempt_id"]
        and manifest.get("stage") == payload["stage"]
        and manifest.get("purpose") == payload["purpose"]
        and manifest.get("declared_semantic_sha256")
        == payload["forward_manifest_sha256"]
        and manifest.get("declared_semantic_sha256")
        == semantic_sha256(
            manifest,
            excluded_fields=("declared_semantic_sha256",),
        )
        and isinstance(payload["query_identity"], dict)
        and manifest.get("query_identity") == payload["query_identity"]
        and isinstance(payload["corpus_identity"], dict)
        and manifest.get("corpus_identity") == payload["corpus_identity"]
        and isinstance(material, dict)
        and semantic_sha256(material) == payload["authority_binding_sha256"]
        and isinstance(projection["query_keys"], list)
        and len(projection["query_keys"])
        == payload["query_identity"].get("query_count")
        and isinstance(projection["corpus_video_ids"], list)
        and isinstance(projection["corpus_durations_sec"], list)
        and len(projection["corpus_video_ids"])
        == len(projection["corpus_durations_sec"])
        == payload["corpus_identity"].get("video_count"),
        "controller forward authority persisted descriptor projection",
    )
    return dict(payload), dict(projection)


def _validate_controller_forward_authority_record_lineage(
    payload: Mapping[str, Any],
    *,
    state: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
) -> None:
    positions = [
        index
        for index, event in enumerate(events)
        if event.get("transaction_id")
        == payload.get("origin_transaction_id")
        and event.get("event_sha256") == payload.get("origin_event_sha256")
        and event.get("expected_next_state_sha256")
        == payload.get("origin_state_sha256")
    ]
    _require(
        len(positions) == 1
        and payload.get("attempt_id") == state.get("attempt_id")
        and bool(events)
        and events[-1].get("expected_next_state_sha256")
        == state.get("state_sha256"),
        "controller forward authority committed origin lineage",
    )
    origin_event = events[positions[0]]
    origin_state, _origin_state_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "state_records"
        / (
            "%06d_%s.json"
            % (origin_event["seq"], payload["origin_state_sha256"])
        )
    )
    expected_action = (
        "G3_F0_A_BASELINE_FORENSICS"
        if payload["token_id"] == "F0_A"
        else "G5_F0_B_EXPOSURE_REPLICATION"
    )
    _require(
        isinstance(origin_state, dict)
        and origin_state.get("attempt_id") == payload["attempt_id"]
        and origin_state.get("transaction_id")
        == payload["origin_transaction_id"]
        and origin_state.get("state_sha256")
        == payload["origin_state_sha256"]
        and origin_state.get("next_action") == expected_action
        and origin_state.get("eval_token_states", {}).get(
            payload["token_id"]
        ) == "UNISSUED",
        "controller forward authority unissued origin state",
    )
    current_token_state = state.get("eval_token_states", {}).get(
        payload["token_id"]
    )
    _require(
        current_token_state
        in {"UNISSUED", "RESERVED", "RUNNING", "COMPLETED"},
        "controller forward authority current token lineage",
    )
    if current_token_state == "UNISSUED":
        intervening = events[positions[0] + 1 :]
        _require(
            state.get("next_action") == expected_action
            and all(
                event.get("action") == "COMMIT_REVIEWED_CODE_CHANGE"
                and event.get("result")
                == (
                    "COMMITTED_USER_AUTHORIZED_ONLINE_EXISTING_FILE_"
                    "POSTIMAGE"
                )
                and isinstance(event.get("transaction_id"), str)
                and CODE_CHANGE_TXN_RE.fullmatch(event["transaction_id"])
                is not None
                for event in intervening
            ),
            "unreserved controller authority may advance through online code only",
        )


def _validate_controller_forward_authority_records_namespace(
    state: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
) -> tuple[set[str], set[str]]:
    files: set[str] = set()
    directories: set[str] = set()
    observed_tokens: set[str] = set()
    for transaction_id, path in _controller_forward_authority_record_paths():
        record, _record_bytes = _read_canonical_json(
            path,
            max_bytes=1024 * 1024 * 1024,
        )
        payload, _projection = (
            _validate_persisted_controller_forward_authority_record(
                record,
                origin_transaction_id=transaction_id,
            )
        )
        _validate_controller_forward_authority_record_lineage(
            payload,
            state=state,
            events=events,
        )
        _require(
            payload["token_id"] not in observed_tokens,
            "duplicate persisted controller authority token",
        )
        observed_tokens.add(payload["token_id"])
        prefix = "transactions/%s" % transaction_id
        directories.add(prefix)
        files.add("%s/controller_forward_authority.json" % prefix)
    return files, directories


def _completed_forward_rehydrate_sessions() -> list[Path]:
    with os.scandir(CONTROL_ROOT / "transactions") as iterator:
        sessions = sorted(
            Path(entry.path)
            for entry in iterator
            if COMPLETED_FORWARD_REHYDRATE_SESSION_RE.fullmatch(entry.name)
            is not None
            and entry.is_dir(follow_symlinks=False)
            and not entry.is_symlink()
        )
    _require(
        len(sessions) <= 2,
        "completed forward rehydrate session cardinality",
    )
    return sessions


def _validate_completed_forward_rehydrate_sessions(
    events: Sequence[Mapping[str, Any]],
) -> tuple[set[str], set[str]]:
    files: set[str] = set()
    directories: set[str] = set()
    observed_runs: set[str] = set()
    for session in _completed_forward_rehydrate_sessions():
        with os.scandir(session) as iterator:
            names = sorted(entry.name for entry in iterator)
        _require(
            names in ([], ["record.json"]),
            "completed forward rehydrate exact session namespace",
        )
        prefix = "transactions/%s" % session.name
        directories.add(prefix)
        if not names:
            continue
        record, _record_bytes = _read_canonical_json(
            session / "record.json"
        )
        payload, _material = _validate_completed_forward_rehydrate_record(
            record,
            session_id=session.name,
            events=events,
        )
        _require(
            payload["run_id"] not in observed_runs,
            "duplicate completed forward rehydrate run",
        )
        observed_runs.add(payload["run_id"])
        files.add("%s/record.json" % prefix)
    return files, directories


def _forward_derivation_session_id(payload: Mapping[str, Any]) -> str:
    binding_sha256 = payload.get("consumer_binding_sha256")
    _require(
        isinstance(binding_sha256, str)
        and HEX64.fullmatch(binding_sha256) is not None,
        "forward derivation consumer binding SHA",
    )
    return "FORWARD-DERIVATION-%s" % binding_sha256[:32]


def _validate_forward_derivation_consumer_payload(
    payload: Any,
) -> dict[str, Any]:
    exact_fields = {
        "schema_version", "goal_id", "attempt_id", "run_id",
        "token_id", "eval_id", "completed_transaction_id",
        "completed_state_sha256", "completed_event_sha256",
        "forward_authority_handle_sha256", "forward_manifest_sha256",
        "input_identity_sha256", "reservation_input_capability_sha256",
        "result_chunk_set_sha256", "result_chunk_count",
        "ordered_ranges", "ordered_ranges_sha256",
        "single_use_per_range", "strict_in_order",
        "consumer_binding_sha256",
    }
    _require(
        isinstance(payload, dict)
        and set(payload) == exact_fields
        and payload["schema_version"]
        == "c28f_a4_forward_derivation_consumer_capability_v1"
        and payload["goal_id"] == GOAL_ID
        and payload["token_id"] in {"F0_A", "F0_B"}
        and isinstance(payload["attempt_id"], str)
        and A4_ATTEMPT_RE.fullmatch(payload["attempt_id"]) is not None
        and isinstance(payload["run_id"], str)
        and SAFE_ENTITY_ID_RE.fullmatch(payload["run_id"]) is not None
        and isinstance(payload["eval_id"], str)
        and SAFE_ENTITY_ID_RE.fullmatch(payload["eval_id"]) is not None
        and isinstance(payload["completed_transaction_id"], str)
        and EVAL_TOKEN_TXN_RE.fullmatch(
            payload["completed_transaction_id"]
        ) is not None
        and payload["completed_transaction_id"].endswith("-COMPLETE")
        and type(payload["result_chunk_count"]) is int
        and 0 < payload["result_chunk_count"] <= 100_000
        and payload["single_use_per_range"] is True
        and payload["strict_in_order"] is True,
        "forward derivation consumer exact identity contract",
    )
    for field_name in (
        "completed_state_sha256", "completed_event_sha256",
        "forward_authority_handle_sha256", "forward_manifest_sha256",
        "input_identity_sha256", "reservation_input_capability_sha256",
        "result_chunk_set_sha256", "ordered_ranges_sha256",
        "consumer_binding_sha256",
    ):
        _require(
            isinstance(payload[field_name], str)
            and HEX64.fullmatch(payload[field_name]) is not None,
            "forward derivation consumer hash: %s" % field_name,
        )
    ordered_ranges = payload["ordered_ranges"]
    range_fields = {
        "range_index", "start_index", "end_index", "artifact_name",
        "artifact_file_sha256", "payload_semantic_sha256",
    }
    _require(
        isinstance(ordered_ranges, list)
        and len(ordered_ranges) == payload["result_chunk_count"],
        "forward derivation ordered range count",
    )
    expected_start = 0
    for range_index, item in enumerate(ordered_ranges):
        _require(
            isinstance(item, dict)
            and set(item) == range_fields
            and item["range_index"] == range_index
            and item["start_index"] == expected_start
            and type(item["end_index"]) is int
            and item["end_index"] > expected_start
            and item["artifact_name"]
            == "queries_%05d_%05d.pt"
            % (item["start_index"], item["end_index"]),
            "forward derivation ordered range %d" % range_index,
        )
        for field_name in (
            "artifact_file_sha256", "payload_semantic_sha256",
        ):
            _require(
                isinstance(item[field_name], str)
                and HEX64.fullmatch(item[field_name]) is not None,
                "forward derivation range hash: %s" % field_name,
            )
        expected_start = item["end_index"]
    _require(
        payload["ordered_ranges_sha256"]
        == bytes_sha256(canonical_json_bytes(ordered_ranges))
        and payload["consumer_binding_sha256"]
        == semantic_sha256(
            payload,
            excluded_fields=("consumer_binding_sha256",),
        ),
        "forward derivation ordered range/binding hash",
    )
    return dict(payload)


def _validate_forward_derivation_completion_lineage(
    payload: Mapping[str, Any],
    *,
    events: Sequence[Mapping[str, Any]],
) -> None:
    transaction_id = str(payload["completed_transaction_id"])
    matches = [
        event
        for event in events
        if event.get("transaction_id") == transaction_id
    ]
    _require(
        len(matches) == 1
        and matches[0].get("action") == "COMPLETE_EVAL_TOKEN"
        and matches[0].get("expected_next_state_sha256")
        == payload["completed_state_sha256"]
        and matches[0].get("event_sha256")
        == payload["completed_event_sha256"],
        "forward derivation completed event lineage",
    )
    receipt, _receipt_bytes = _read_canonical_json(
        CONTROL_ROOT / "transactions" / transaction_id / "phase_receipt.json"
    )
    _require(
        isinstance(receipt, dict)
        and receipt.get("schema_version")
        == "c28f_eval_token_phase_receipt_v1"
        and receipt.get("status") == "FSYNCED_CAS_COMMITTED"
        and receipt.get("phase") == "COMPLETED"
        and receipt.get("goal_id") == GOAL_ID
        and receipt.get("run_id") == payload["run_id"]
        and receipt.get("token_id") == payload["token_id"]
        and receipt.get("eval_id") == payload["eval_id"]
        and receipt.get("transaction_id") == transaction_id
        and receipt.get("state_sha256")
        == payload["completed_state_sha256"]
        and receipt.get("event_sha256")
        == payload["completed_event_sha256"]
        and receipt.get("reservation_input_capability_sha256")
        == payload["reservation_input_capability_sha256"]
        and receipt.get("model_forward_evaluations") == 1
        and receipt.get("receipt_sha256")
        == semantic_sha256(receipt, excluded_fields=("receipt_sha256",)),
        "forward derivation completed phase receipt lineage",
    )
    stem = transaction_id.removesuffix("-COMPLETE")
    reservation_record, _reservation_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "transactions"
        / (stem + "-RESERVE")
        / "reservation_input.json"
    )
    reservation_payload = reservation_record.get("payload")
    _require(
        isinstance(reservation_record, dict)
        and reservation_record.get("schema_version")
        == "c28f_a4_persisted_eval_reservation_input_v1"
        and reservation_record.get("status")
        == "FSYNCED_CONTROLLER_ISSUED_INPUT"
        and reservation_record.get("capability_sha256")
        == payload["reservation_input_capability_sha256"]
        and isinstance(reservation_payload, dict)
        and semantic_sha256(reservation_payload)
        == payload["reservation_input_capability_sha256"]
        and reservation_record.get("record_sha256")
        == semantic_sha256(
            reservation_record,
            excluded_fields=("record_sha256",),
        ),
        "forward derivation reservation input record",
    )
    execution_binding = reservation_payload.get("execution_binding")
    source_lineage = reservation_payload.get("source_lineage")
    _require(
        isinstance(execution_binding, dict)
        and isinstance(source_lineage, dict)
        and reservation_payload.get("attempt_id") == payload["attempt_id"]
        and reservation_payload.get("token_id") == payload["token_id"]
        and reservation_payload.get("eval_id") == payload["eval_id"]
        and execution_binding.get("forward_manifest_sha256")
        == payload["forward_manifest_sha256"]
        and execution_binding.get("input_identity_sha256")
        == payload["input_identity_sha256"]
        and source_lineage.get(
            "controller_forward_authority_handle_sha256"
        ) == payload["forward_authority_handle_sha256"],
        "forward derivation reservation authority lineage",
    )


def _forward_derivation_owner_lineage_sha256(
    receipt: Mapping[str, Any],
) -> str:
    lineage = {
        "schema_version": "c28f_a4_forward_derivation_owner_lineage_v1",
        "materialization_owner_generation": receipt[
            "materialization_owner_generation"
        ],
        "materialization_owner_binding_sha256": receipt[
            "materialization_owner_binding_sha256"
        ],
        "materialization_owner_takeover_chain_sha256": receipt[
            "materialization_owner_takeover_chain_sha256"
        ],
        "commit_owner_generation": receipt["commit_owner_generation"],
        "commit_owner_binding_sha256": receipt[
            "commit_owner_binding_sha256"
        ],
        "commit_owner_takeover_chain_sha256": receipt[
            "commit_owner_takeover_chain_sha256"
        ],
        "commit_owner_binding_chain": receipt[
            "commit_owner_binding_chain"
        ],
        "commit_owner_binding_chain_sha256": receipt[
            "commit_owner_binding_chain_sha256"
        ],
    }
    return semantic_sha256(lineage)


def _read_forward_derivation_range_receipts(
    payload: Mapping[str, Any],
) -> list[dict[str, Any]]:
    session = (
        CONTROL_ROOT
        / "transactions"
        / _forward_derivation_session_id(payload)
    )
    if not os.path.lexists(session):
        return []
    with os.scandir(session) as iterator:
        entries = sorted(
            (
                entry
                for entry in iterator
                if re.fullmatch(
                    r"range_[0-9]{6}_[0-9a-f]{64}\.json",
                    entry.name,
                ) is not None
            ),
            key=lambda item: item.name,
        )
    receipts: list[dict[str, Any]] = []
    previous: Optional[str] = None
    ordered_ranges = payload["ordered_ranges"]
    for range_index, entry in enumerate(entries):
        _require(
            range_index < len(ordered_ranges),
            "forward derivation range receipt overflow before decode",
        )
        _require(
            entry.is_file(follow_symlinks=False) and not entry.is_symlink(),
            "forward derivation range receipt type",
        )
        receipt, _receipt_bytes = _read_canonical_json(Path(entry.path))
        expected_range = ordered_ranges[range_index]
        _require(
            isinstance(receipt, dict)
            and set(receipt)
            == {
                "schema_version", "status", "goal_id", "attempt_id",
                "run_id", "token_id", "eval_id",
                "completed_transaction_id", "consumer_capability_sha256",
                "consumer_binding_sha256", "claim_capability_sha256",
                "claim_binding_sha256",
                "derived_range_postimage_capability_sha256",
                "derived_range_postimage_binding_sha256",
                "materialization_owner_generation",
                "materialization_owner_binding_sha256",
                "materialization_owner_takeover_chain_sha256",
                "commit_owner_generation",
                "commit_owner_binding_sha256",
                "commit_owner_takeover_chain_sha256",
                "commit_owner_binding_chain",
                "commit_owner_binding_chain_sha256",
                "range_index", "start_index",
                "end_index", "artifact_name", "artifact_file_sha256",
                "payload_semantic_sha256", "previous_range_receipt_sha256",
                "previous_cursor_index", "next_cursor_index",
                "all_ranges_consumed", "receipt_sha256",
            }
            and receipt["schema_version"]
            == "c28f_a4_forward_derivation_range_consumption_receipt_v1"
            and receipt["status"] == "FSYNCED_DERIVATION_RANGE_CONSUMED"
            and receipt["goal_id"] == payload["goal_id"]
            and receipt["attempt_id"] == payload["attempt_id"]
            and receipt["run_id"] == payload["run_id"]
            and receipt["token_id"] == payload["token_id"]
            and receipt["eval_id"] == payload["eval_id"]
            and receipt["completed_transaction_id"]
            == payload["completed_transaction_id"]
            and receipt["consumer_capability_sha256"]
            == semantic_sha256(payload)
            and receipt["consumer_binding_sha256"]
            == payload["consumer_binding_sha256"]
            and all(
                isinstance(receipt.get(field_name), str)
                and HEX64.fullmatch(receipt[field_name]) is not None
                for field_name in (
                    "claim_capability_sha256", "claim_binding_sha256",
                    "derived_range_postimage_capability_sha256",
                    "derived_range_postimage_binding_sha256",
                    "materialization_owner_binding_sha256",
                    "materialization_owner_takeover_chain_sha256",
                    "commit_owner_binding_sha256",
                    "commit_owner_takeover_chain_sha256",
                    "commit_owner_binding_chain_sha256",
                )
            )
            and type(receipt["materialization_owner_generation"]) is int
            and receipt["materialization_owner_generation"] >= 0
            and type(receipt["commit_owner_generation"]) is int
            and receipt["commit_owner_generation"]
            >= receipt["materialization_owner_generation"]
            and isinstance(receipt["commit_owner_binding_chain"], list)
            and all(
                receipt.get(field_name) == expected_range[field_name]
                for field_name in (
                    "range_index", "start_index", "end_index",
                    "artifact_name", "artifact_file_sha256",
                    "payload_semantic_sha256",
                )
            )
            and receipt["previous_range_receipt_sha256"] == previous
            and receipt["previous_cursor_index"] == range_index
            and receipt["next_cursor_index"] == range_index + 1
            and receipt["all_ranges_consumed"]
            is (range_index + 1 == len(ordered_ranges))
            and receipt["receipt_sha256"]
            == semantic_sha256(receipt, excluded_fields=("receipt_sha256",))
            and entry.name
            == "range_%06d_%s.json"
            % (range_index, receipt["receipt_sha256"]),
            "forward derivation range receipt chain at %d" % range_index,
        )
        owners = _forward_derivation_delivery_owner_records(
            payload,
            range_index=range_index,
        )
        materialization_generation = receipt[
            "materialization_owner_generation"
        ]
        commit_generation = receipt["commit_owner_generation"]
        commit_chain = [
            owner["owner_binding_sha256"]
            for owner in owners[: commit_generation + 1]
        ]
        _require(
            commit_generation < len(owners)
            and owners[materialization_generation][
                "owner_binding_sha256"
            ] == receipt["materialization_owner_binding_sha256"]
            and owners[materialization_generation][
                "takeover_chain_sha256"
            ] == receipt["materialization_owner_takeover_chain_sha256"]
            and owners[commit_generation]["owner_binding_sha256"]
            == receipt["commit_owner_binding_sha256"]
            and owners[commit_generation]["takeover_chain_sha256"]
            == receipt["commit_owner_takeover_chain_sha256"]
            == bytes_sha256(canonical_json_bytes(commit_chain[:-1]))
            and receipt["commit_owner_binding_chain"] == commit_chain
            and receipt["commit_owner_binding_chain_sha256"]
            == bytes_sha256(canonical_json_bytes(commit_chain))
            and receipt[
                "materialization_owner_takeover_chain_sha256"
            ]
            == bytes_sha256(
                canonical_json_bytes(
                    commit_chain[:materialization_generation]
                )
            )
            and (
                materialization_generation == commit_generation
                or receipt["materialization_owner_binding_sha256"]
                in {
                    owner["previous_owner_binding_sha256"]
                    for owner in owners[
                        materialization_generation + 1 :
                        commit_generation + 1
                    ]
                }
            ),
            "forward derivation range receipt delivery owner at %d"
            % range_index,
        )
        previous = receipt["receipt_sha256"]
        receipts.append(dict(receipt))
    _require(
        len(receipts) <= len(ordered_ranges),
        "forward derivation range receipt overflow",
    )
    return receipts


def _validate_forward_derivation_sessions(
    events: Sequence[Mapping[str, Any]],
) -> tuple[set[str], set[str]]:
    transactions = CONTROL_ROOT / "transactions"
    with os.scandir(transactions) as iterator:
        entries = sorted(
            (
                entry
                for entry in iterator
                if FORWARD_DERIVATION_SESSION_RE.fullmatch(entry.name)
                is not None
            ),
            key=lambda item: item.name,
        )
    _require(len(entries) <= 2, "forward derivation session cardinality")
    files: set[str] = set()
    directories: set[str] = set()
    observed_run_ids: set[str] = set()
    observed_token_ids: set[str] = set()
    for entry in entries:
        _require(
            entry.is_dir(follow_symlinks=False) and not entry.is_symlink(),
            "forward derivation session directory",
        )
        record, _record_bytes = _read_canonical_json(
            Path(entry.path) / "consumer_capability.json"
        )
        payload = _validate_forward_derivation_consumer_payload(
            record.get("payload")
        )
        validation_receipt = (
            _validate_completed_forward_validation_receipt_shape(
                record.get("completed_forward_validation_receipt")
            )
        )
        _require(
            set(record)
            == {
                "schema_version", "status", "capability_sha256",
                "completed_forward_validation_receipt",
                "completed_forward_validation_receipt_sha256",
                "payload", "record_sha256",
            }
            and record["schema_version"]
            == "c28f_a4_forward_derivation_consumer_record_v1"
            and record["status"] == "FSYNCED_CONTROLLER_ISSUED"
            and record["capability_sha256"] == semantic_sha256(payload)
            and record["completed_forward_validation_receipt_sha256"]
            == validation_receipt["validation_receipt_sha256"]
            and validation_receipt["run_id"] == payload["run_id"]
            and validation_receipt["token_id"] == payload["token_id"]
            and validation_receipt["eval_id"] == payload["eval_id"]
            and validation_receipt["forward_manifest_sha256"]
            == payload["forward_manifest_sha256"]
            and validation_receipt["input_identity_sha256"]
            == payload["input_identity_sha256"]
            and validation_receipt["result_chunk_set_sha256"]
            == payload["result_chunk_set_sha256"]
            and validation_receipt["ordered_ranges"]
            == payload["ordered_ranges"]
            and record["record_sha256"]
            == semantic_sha256(record, excluded_fields=("record_sha256",))
            and _forward_derivation_session_id(payload) == entry.name
            and payload["run_id"] not in observed_run_ids
            and payload["token_id"] not in observed_token_ids,
            "forward derivation persisted consumer record",
        )
        observed_run_ids.add(payload["run_id"])
        observed_token_ids.add(payload["token_id"])
        _validate_forward_derivation_completion_lineage(
            payload,
            events=events,
        )
        receipts = _read_forward_derivation_range_receipts(payload)
        with os.scandir(entry.path) as iterator:
            claim_entries = sorted(
                (
                    item
                    for item in iterator
                    if re.fullmatch(
                        r"claim_[0-9]{6}_[0-9a-f]{64}\.json",
                        item.name,
                    ) is not None
                ),
                key=lambda item: item.name,
            )
        _require(
            len(claim_entries) in {len(receipts), len(receipts) + 1}
            and len(claim_entries) <= payload["result_chunk_count"],
            "forward derivation claim/commit phase cardinality",
        )
        with os.scandir(entry.path) as iterator:
            owner_entries = sorted(
                (
                    item
                    for item in iterator
                    if re.fullmatch(
                        r"delivery_owner_[0-9]{6}_[0-9]{6}_"
                        r"[0-9a-f]{64}\.json",
                        item.name,
                    )
                    is not None
                ),
                key=lambda item: item.name,
            )
        owner_range_indices = sorted(
            {
                int(item.name.split("_", 3)[2])
                for item in owner_entries
            }
        )
        committed_or_claimed_owner_ranges = list(
            range(len(claim_entries))
        )
        pending_owner_ranges = list(range(len(claim_entries) + 1))
        _require(
            owner_range_indices == committed_or_claimed_owner_ranges
            or (
                len(claim_entries) == len(receipts)
                and len(claim_entries) < payload["result_chunk_count"]
                and owner_range_indices == pending_owner_ranges
            ),
            "forward derivation owner/claim phase cardinality",
        )
        owner_records_by_range: dict[int, list[dict[str, Any]]] = {}
        owner_names: list[str] = []
        for owner_range_index in owner_range_indices:
            owners = _forward_derivation_delivery_owner_records(
                payload,
                range_index=owner_range_index,
            )
            _require(
                1 <= len(owners)
                <= FORWARD_DERIVATION_MAX_OWNER_GENERATIONS,
                "forward derivation owner chain cardinality",
            )
            owner_records_by_range[owner_range_index] = owners
            owner_names.extend(
                "delivery_owner_%06d_%06d_%s.json"
                % (
                    owner_range_index,
                    generation,
                    owner["owner_binding_sha256"],
                )
                for generation, owner in enumerate(owners)
            )
        _require(
            sorted(item.name for item in owner_entries)
            == sorted(owner_names),
            "forward derivation exact delivery owner namespace",
        )
        claim_records: list[dict[str, Any]] = []
        for range_index, claim_entry in enumerate(claim_entries):
            _require(
                claim_entry.is_file(follow_symlinks=False)
                and not claim_entry.is_symlink(),
                "forward derivation claim record type",
            )
            claim_record, _claim_bytes = _read_canonical_json(
                Path(claim_entry.path)
            )
            claim = claim_record.get("payload")
            expected_range = payload["ordered_ranges"][range_index]
            previous_receipt_sha256 = (
                None
                if range_index == 0
                else receipts[range_index - 1]["receipt_sha256"]
            )
            _require(
                isinstance(claim, dict)
                and set(claim)
                == {
                    "schema_version", "status", "goal_id", "attempt_id",
                    "run_id", "token_id", "eval_id",
                    "completed_transaction_id",
                    "consumer_capability_sha256",
                    "consumer_binding_sha256", "result_chunk_set_sha256",
                    "range_index", "start_index", "end_index",
                    "artifact_name", "artifact_file_sha256",
                    "payload_semantic_sha256",
                    "previous_range_receipt_sha256",
                    "previous_cursor_index", "claim_binding_sha256",
                }
                and claim["schema_version"]
                == "c28f_a4_forward_derivation_range_claim_capability_v1"
                and claim["status"]
                == "FSYNCED_DERIVATION_RANGE_CLAIMED"
                and all(
                    claim.get(field_name) == payload[field_name]
                    for field_name in (
                        "goal_id", "attempt_id", "run_id", "token_id",
                        "eval_id", "completed_transaction_id",
                        "consumer_binding_sha256",
                        "result_chunk_set_sha256",
                    )
                )
                and claim["consumer_capability_sha256"]
                == semantic_sha256(payload)
                and all(
                    claim.get(field_name) == expected_range[field_name]
                    for field_name in (
                        "range_index", "start_index", "end_index",
                        "artifact_name", "artifact_file_sha256",
                        "payload_semantic_sha256",
                    )
                )
                and claim["previous_range_receipt_sha256"]
                == previous_receipt_sha256
                and claim["previous_cursor_index"] == range_index
                and claim["claim_binding_sha256"]
                == semantic_sha256(
                    claim,
                    excluded_fields=("claim_binding_sha256",),
                )
                and set(claim_record)
                == {
                    "schema_version", "status", "capability_sha256",
                    "payload", "record_sha256",
                }
                and claim_record["schema_version"]
                == "c28f_a4_forward_derivation_range_claim_record_v1"
                and claim_record["status"]
                == "FSYNCED_CONTROLLER_CLAIMED"
                and claim_record["capability_sha256"]
                == semantic_sha256(claim)
                and claim_record["record_sha256"]
                == semantic_sha256(
                    claim_record,
                    excluded_fields=("record_sha256",),
                )
                and claim_entry.name
                == "claim_%06d_%s.json"
                % (range_index, claim["claim_binding_sha256"]),
                "forward derivation claim chain at %d" % range_index,
            )
            claim_records.append(dict(claim_record))
        with os.scandir(entry.path) as iterator:
            postimage_entries = sorted(
                (
                    item
                    for item in iterator
                    if re.fullmatch(
                        r"postimage_[0-9]{6}_[0-9a-f]{64}\.json",
                        item.name,
                    ) is not None
                ),
                key=lambda item: item.name,
            )
        _require(
            len(receipts) <= len(postimage_entries) <= len(claim_records)
            and len(postimage_entries) <= payload["result_chunk_count"],
            "forward derivation postimage phase cardinality",
        )
        postimage_records: list[dict[str, Any]] = []
        pre_gt_names: list[str] = []
        nms_names: list[str] = []
        for range_index, postimage_entry in enumerate(postimage_entries):
            _require(
                postimage_entry.is_file(follow_symlinks=False)
                and not postimage_entry.is_symlink(),
                "forward derivation postimage record type",
            )
            postimage_record, _postimage_record_bytes = (
                _read_canonical_json(Path(postimage_entry.path))
            )
            postimage = postimage_record.get("payload")
            claim_record = claim_records[range_index]
            claim = claim_record["payload"]
            _require(
                isinstance(postimage, dict)
                and set(postimage)
                == {
                    "schema_version", "status", "goal_id", "attempt_id",
                    "run_id", "token_id", "eval_id",
                    "completed_transaction_id",
                    "consumer_capability_sha256",
                    "consumer_binding_sha256", "claim_capability_sha256",
                    "claim_binding_sha256", "range_index", "start_index",
                    "end_index", "source_artifact_name",
                    "source_artifact_file_sha256",
                    "source_payload_semantic_sha256",
                    "materialization_owner_generation",
                    "materialization_owner_binding_sha256",
                    "materialization_owner_takeover_chain_sha256",
                    "controller_projection_sha256", "pre_gt_artifact_name",
                    "pre_gt_artifact_file_sha256", "pre_gt_payload_sha256",
                    "derived_nms_artifact_name",
                    "derived_nms_artifact_file_sha256",
                    "derived_nms_payload_sha256",
                    "postimage_binding_sha256",
                }
                and postimage["schema_version"]
                == "c28f_a4_forward_derived_range_postimage_capability_v1"
                and postimage["status"]
                == "FSYNCED_CONTROLLER_DERIVED_RANGE_POSTIMAGE"
                and all(
                    postimage.get(field_name) == claim[field_name]
                    for field_name in (
                        "goal_id", "attempt_id", "run_id", "token_id",
                        "eval_id", "completed_transaction_id",
                        "consumer_capability_sha256",
                        "consumer_binding_sha256", "range_index",
                        "start_index", "end_index",
                    )
                )
                and postimage["claim_capability_sha256"]
                == claim_record["capability_sha256"]
                and postimage["claim_binding_sha256"]
                == claim["claim_binding_sha256"]
                and postimage["source_artifact_name"]
                == claim["artifact_name"]
                and postimage["source_artifact_file_sha256"]
                == claim["artifact_file_sha256"]
                and postimage["source_payload_semantic_sha256"]
                == claim["payload_semantic_sha256"]
                and type(
                    postimage["materialization_owner_generation"]
                ) is int
                and 0
                <= postimage["materialization_owner_generation"]
                < len(owner_records_by_range[range_index])
                and owner_records_by_range[range_index][
                    postimage["materialization_owner_generation"]
                ]["owner_binding_sha256"]
                == postimage["materialization_owner_binding_sha256"]
                and owner_records_by_range[range_index][
                    postimage["materialization_owner_generation"]
                ]["takeover_chain_sha256"]
                == postimage[
                    "materialization_owner_takeover_chain_sha256"
                ]
                and postimage["postimage_binding_sha256"]
                == semantic_sha256(
                    postimage,
                    excluded_fields=("postimage_binding_sha256",),
                )
                and postimage_record.get("schema_version")
                == "c28f_a4_forward_derived_range_postimage_record_v1"
                and postimage_record.get("status")
                == "FSYNCED_CONTROLLER_DERIVED"
                and postimage_record.get("capability_sha256")
                == semantic_sha256(postimage)
                and postimage_record.get("record_sha256")
                == semantic_sha256(
                    postimage_record,
                    excluded_fields=("record_sha256",),
                )
                and postimage_entry.name
                == "postimage_%06d_%s.json"
                % (range_index, postimage["postimage_binding_sha256"]),
                "forward derivation postimage chain at %d" % range_index,
            )
            pre_gt_name = postimage["pre_gt_artifact_name"]
            nms_name = postimage["derived_nms_artifact_name"]
            _require(
                pre_gt_name
                == "pre_gt_%06d_%s.json"
                % (range_index, postimage["pre_gt_payload_sha256"])
                and nms_name
                == "derived_nms_%06d_%s.json"
                % (range_index, postimage["derived_nms_payload_sha256"]),
                "forward derivation postimage artifact names",
            )
            pre_gt, pre_gt_bytes = _read_canonical_json(
                Path(entry.path) / pre_gt_name,
                max_bytes=1024 * 1024 * 1024,
            )
            nms, nms_bytes = _read_canonical_json(
                Path(entry.path) / nms_name,
                max_bytes=1024 * 1024 * 1024,
            )
            _require(
                isinstance(pre_gt, dict)
                and pre_gt.get("payload_sha256")
                == postimage["pre_gt_payload_sha256"]
                == semantic_sha256(
                    pre_gt,
                    excluded_fields=("payload_sha256",),
                )
                and bytes_sha256(pre_gt_bytes)
                == postimage["pre_gt_artifact_file_sha256"]
                and all(
                    pre_gt.get(field_name) == postimage[field_name]
                    for field_name in (
                        "materialization_owner_generation",
                        "materialization_owner_binding_sha256",
                        "materialization_owner_takeover_chain_sha256",
                    )
                )
                and isinstance(nms, dict)
                and nms.get("payload_sha256")
                == postimage["derived_nms_payload_sha256"]
                == semantic_sha256(
                    nms,
                    excluded_fields=("payload_sha256",),
                )
                and bytes_sha256(nms_bytes)
                == postimage["derived_nms_artifact_file_sha256"]
                and all(
                    nms.get(field_name) == postimage[field_name]
                    for field_name in (
                        "materialization_owner_generation",
                        "materialization_owner_binding_sha256",
                        "materialization_owner_takeover_chain_sha256",
                    )
                ),
                "forward derivation persisted range artifacts",
            )
            if range_index < len(receipts):
                receipt = receipts[range_index]
                _require(
                    receipt["claim_capability_sha256"]
                    == claim_record["capability_sha256"]
                    and receipt["claim_binding_sha256"]
                    == claim["claim_binding_sha256"]
                    and receipt[
                        "derived_range_postimage_capability_sha256"
                    ] == postimage_record["capability_sha256"]
                    and receipt[
                        "derived_range_postimage_binding_sha256"
                    ] == postimage["postimage_binding_sha256"]
                    and all(
                        receipt[field_name] == postimage[field_name]
                        for field_name in (
                            "materialization_owner_generation",
                            "materialization_owner_binding_sha256",
                            "materialization_owner_takeover_chain_sha256",
                        )
                    ),
                    "forward derivation commit/postimage lineage",
                )
            postimage_records.append(dict(postimage_record))
            pre_gt_names.append(pre_gt_name)
            nms_names.append(nms_name)
        with os.scandir(entry.path) as iterator:
            observed_names = sorted(item.name for item in iterator)
        expected_names = ["consumer_capability.json"] + owner_names + [
            "range_%06d_%s.json"
            % (index, receipt["receipt_sha256"])
            for index, receipt in enumerate(receipts)
        ] + [
            "claim_%06d_%s.json"
            % (index, record["payload"]["claim_binding_sha256"])
            for index, record in enumerate(claim_records)
        ] + [
            "postimage_%06d_%s.json"
            % (index, record["payload"]["postimage_binding_sha256"])
            for index, record in enumerate(postimage_records)
        ] + pre_gt_names + nms_names
        _require(
            observed_names == sorted(expected_names),
            "forward derivation session exact namespace",
        )
        prefix = "transactions/%s" % entry.name
        directories.add(prefix)
        files.add("%s/consumer_capability.json" % prefix)
        files.update("%s/%s" % (prefix, name) for name in owner_names)
        files.update(
            "%s/range_%06d_%s.json"
            % (prefix, index, receipt["receipt_sha256"])
            for index, receipt in enumerate(receipts)
        )
        files.update(
            "%s/claim_%06d_%s.json"
            % (
                prefix,
                index,
                record["payload"]["claim_binding_sha256"],
            )
            for index, record in enumerate(claim_records)
        )
        files.update(
            "%s/postimage_%06d_%s.json"
            % (
                prefix,
                index,
                record["payload"]["postimage_binding_sha256"],
            )
            for index, record in enumerate(postimage_records)
        )
        files.update("%s/%s" % (prefix, name) for name in pre_gt_names)
        files.update("%s/%s" % (prefix, name) for name in nms_names)
    return files, directories


def _validate_completed_eval_derivation_artifacts(
    events: Sequence[Mapping[str, Any]],
) -> set[str]:
    """Admit only a deterministic fsynced prefix in each COMPLETE txn.

    The artifacts are controller-derived after the eval-token CAS, so they do
    not create another control transition.  Prefix admission makes a crash
    recoverable while the final joint receipt remains the sole complete marker.
    """

    ordered_names = (
        "gt_access_receipt.json",
        "cursor_artifact_index.json",
        "raw_forward_artifact_index.json",
        "derived_nms_artifact_index.json",
        "joint_derivation_receipt.json",
    )
    files: set[str] = set()
    for event in events:
        if event.get("action") != "COMPLETE_EVAL_TOKEN":
            continue
        transaction_id = str(event["transaction_id"])
        transaction_dir = CONTROL_ROOT / "transactions" / transaction_id
        present = tuple(
            name for name in ordered_names
            if os.path.lexists(transaction_dir / name)
        )
        _require(
            present == ordered_names[:len(present)],
            "completed eval derivation artifacts are not an exact prefix",
        )
        if not present:
            continue
        phase_receipt, _phase_bytes = _read_canonical_json(
            transaction_dir / "phase_receipt.json"
        )
        identity = {
            "goal_id": GOAL_ID,
            "attempt_id": event.get("attempt_id"),
            "run_id": phase_receipt.get("run_id"),
            "token_id": phase_receipt.get("token_id"),
            "eval_id": phase_receipt.get("eval_id"),
            "completed_transaction_id": transaction_id,
        }
        if "gt_access_receipt.json" in present:
            gt_receipt, _gt_bytes = _read_canonical_json(
                transaction_dir / "gt_access_receipt.json"
            )
            _require(
                isinstance(gt_receipt, dict)
                and set(gt_receipt)
                == {
                    "schema_version", "status", "goal_id", "attempt_id",
                    "run_id", "token_id", "eval_id",
                    "completed_transaction_id", "purpose", "role_id",
                    "role_manifest_authority_binding_sha256",
                    "projection_id", "projection_record_sha256",
                    "projection_records_sha256", "gt_record_count",
                    "index_binding_sha256",
                    "source_descriptor_identity_sha256",
                    "source_file_sha256", "projection_access_receipt",
                    "projection_access_receipt_sha256",
                    "physical_content_open_count",
                    "decoded_field_counts", "protected_semantic_decode_count",
                    "receipt_sha256",
                }
                and gt_receipt.get("schema_version")
                == "c28f_a4_post_forward_gt_access_receipt_v1"
                and gt_receipt.get("status")
                == "FSYNCED_EXACT_AUTHORIZED_POST_FORWARD_GT_ACCESS"
                and all(
                    gt_receipt.get(field_name) == expected
                    for field_name, expected in identity.items()
                )
                and gt_receipt.get("purpose") == "POST_FORWARD_EVAL_STATS"
                and gt_receipt.get("physical_content_open_count") == 1
                and gt_receipt.get("protected_semantic_decode_count") == 0
                and isinstance(
                    gt_receipt.get("projection_access_receipt"), dict
                )
                and gt_receipt.get("projection_access_receipt_sha256")
                == gt_receipt["projection_access_receipt"].get(
                    "receipt_sha256"
                )
                and gt_receipt.get("receipt_sha256")
                == semantic_sha256(
                    gt_receipt,
                    excluded_fields=("receipt_sha256",),
                ),
                "completed eval GT access receipt prefix",
            )
        if "cursor_artifact_index.json" in present:
            cursor_index, _cursor_bytes = _read_canonical_json(
                transaction_dir / "cursor_artifact_index.json"
            )
            _require(
                isinstance(cursor_index, dict)
                and set(cursor_index)
                == {
                    "schema_version", "status", "goal_id", "attempt_id",
                    "run_id", "token_id", "eval_id",
                    "completed_transaction_id", "cursor_receipt_sha256",
                    "result_chunk_count", "artifact_index",
                    "artifact_index_sha256", "index_sha256",
                }
                and cursor_index.get("schema_version")
                == "c28f_a4_cursor_artifact_index_v1"
                and cursor_index.get("status")
                == "FSYNCED_EXACT_COMPLETED_CURSOR_ARTIFACT_INDEX"
                and all(
                    cursor_index.get(field_name) == expected
                    for field_name, expected in identity.items()
                )
                and isinstance(cursor_index.get("artifact_index"), list)
                and cursor_index.get("artifact_index_sha256")
                == bytes_sha256(
                    canonical_json_bytes(cursor_index["artifact_index"])
                )
                and cursor_index.get("index_sha256")
                == semantic_sha256(
                    cursor_index,
                    excluded_fields=("index_sha256",),
                ),
                "completed eval cursor artifact index prefix",
            )
        if "raw_forward_artifact_index.json" in present:
            raw_index, _raw_bytes = _read_canonical_json(
                transaction_dir / "raw_forward_artifact_index.json",
                max_bytes=1024 * 1024 * 1024,
            )
            _require(
                isinstance(raw_index, dict)
                and raw_index.get("schema_version")
                == "c28f_a4_raw_forward_artifact_index_v2"
                and raw_index.get("status")
                == "FSYNCED_BOUNDED_TWO_PHASE_RAW_FORWARD_INDEX"
                and all(
                    raw_index.get(field_name) == expected
                    for field_name, expected in identity.items()
                    if field_name in raw_index
                )
                and raw_index.get("index_sha256")
                == semantic_sha256(
                    raw_index,
                    excluded_fields=("index_sha256",),
                ),
                "completed eval raw artifact index prefix",
            )
        if "derived_nms_artifact_index.json" in present:
            nms_index, _nms_bytes = _read_canonical_json(
                transaction_dir / "derived_nms_artifact_index.json",
                max_bytes=1024 * 1024 * 1024,
            )
            _require(
                isinstance(nms_index, dict)
                and nms_index.get("schema_version")
                == "c28f_a4_derived_nms_artifact_index_v2"
                and nms_index.get("status")
                == "FSYNCED_FROZEN_NMS_INDEX"
                and all(
                    nms_index.get(field_name) == expected
                    for field_name, expected in identity.items()
                    if field_name in nms_index
                )
                and nms_index.get("index_sha256")
                == semantic_sha256(
                    nms_index,
                    excluded_fields=("index_sha256",),
                ),
                "completed eval NMS artifact index prefix",
            )
        if "joint_derivation_receipt.json" in present:
            joint, _joint_bytes = _read_canonical_json(
                transaction_dir / "joint_derivation_receipt.json"
            )
            _require(
                isinstance(joint, dict)
                and joint.get("schema_version")
                == "c28f_a4_completed_eval_joint_derivation_receipt_v1"
                and joint.get("status")
                == "FSYNCED_CONTROLLER_DERIVED_SAFE_STATS"
                and all(
                    joint.get(field_name) == expected
                    for field_name, expected in identity.items()
                )
                and joint.get("receipt_sha256")
                == semantic_sha256(
                    joint,
                    excluded_fields=("receipt_sha256",),
                ),
                "completed eval joint derivation receipt prefix",
            )
        prefix = "transactions/%s" % transaction_id
        files.update("%s/%s" % (prefix, name) for name in present)
    return files


def _validate_dynamic_control_chain(
    intent: Mapping[str, Any],
    prepared: Mapping[str, Any],
    contracts: Mapping[str, Mapping[str, Any]],
) -> tuple[dict[str, Any], list[dict[str, Any]], dict[str, bytes], set[str], set[str]]:
    journal, _journal_record = read_regular_bytes(
        CONTROL_ROOT / "GOAL_EVENTS.jsonl", require_nlink_one=True
    )
    events = _validate_semantic_journal(
        journal,
        hash_field="event_sha256",
        previous_field="prev_event_sha256",
    )
    _require(events and events[0] == prepared["event"], "dynamic chain lost GENESIS anchor")
    stage_contracts = _load_stage_contracts(attempt_id=str(intent["attempt_id"]))
    state_records: list[dict[str, Any]] = []
    expected_files, expected_directories = _a4_expected_namespace(intent, prepared)
    mutation_journal, _record = read_regular_bytes(
        CONTROL_ROOT / "ledgers/mutation_ledger.jsonl", require_nlink_one=True
    )
    mutation_entries = _validate_semantic_journal(
        mutation_journal,
        hash_field="entry_sha256",
        previous_field="previous_entry_sha256",
        expected_kind="mutation",
    )
    _require(len(mutation_entries) == len(events), "mutation ledger/event cardinality")
    _require(
        mutation_entries[0] == prepared["ledgers"]["mutation"],
        "mutation ledger lost GENESIS anchor",
    )
    mutation_lines = mutation_journal[:-1].split(b"\n")
    latest_code_registry: Optional[bytes] = None
    latest_enveloped_registries: dict[str, bytes] = {}
    used_code_ids: set[str] = set()
    phases_by_code: dict[str, list[str]] = {}
    used_stage_ids: set[str] = set()
    eval_phase_chains: dict[tuple[str, str], list[str]] = {}
    eval_last_registry_sha: dict[tuple[str, str], str] = {}
    eval_last_receipt_sha: dict[tuple[str, str], str] = {}
    eval_last_registry_payload: dict[tuple[str, str], dict[str, Any]] = {}
    eval_cursor_tails: dict[tuple[str, str], Optional[dict[str, Any]]] = {}
    id_mapping_phases: dict[str, list[str]] = {}
    id_mapping_last_registry_sha: dict[str, str] = {}
    id_mapping_last_receipt_sha: dict[str, str] = {}
    id_mapping_last_registry_payload: dict[str, dict[str, Any]] = {}
    finalization_phases: dict[str, list[str]] = {}
    finalization_last_receipt: dict[str, str] = {}
    previous_state: Optional[dict[str, Any]] = None
    for seq, event in enumerate(events):
        transition_envelope: Optional[dict[str, Any]] = None
        event_bytes = canonical_json_bytes(event) + b"\n"
        event_sidecar_name = f"event_records/{seq:06d}_{event['event_sha256']}.jsonl"
        event_sidecar, _record = read_regular_bytes(CONTROL_ROOT / event_sidecar_name, require_nlink_one=True)
        _require(event_sidecar == event_bytes, f"event sidecar mismatch at {seq}")
        expected_files.add(event_sidecar_name)
        state_name = f"state_records/{seq:06d}_{event['expected_next_state_sha256']}.json"
        state, state_bytes = _read_canonical_json(CONTROL_ROOT / state_name)
        _require(isinstance(state, dict), f"state object at {seq}")
        _require(
            state.get("state_sha256") == semantic_sha256(state, excluded_fields=("state_sha256",)),
            f"state semantic hash at {seq}",
        )
        _require(state["state_sha256"] == event["expected_next_state_sha256"], f"event/state hash at {seq}")
        _require(state.get("transition_seq") == seq and state.get("next_action") == event["next_action"], f"state fields at {seq}")
        _require(state.get("attempt_id") == intent["attempt_id"], f"state attempt at {seq}")
        _require(state.get("transaction_id") == event["transaction_id"], f"state transaction at {seq}")
        _require(
            state.get("expected_goal_delta_sha256") == event["expected_goal_delta_sha256"],
            f"state business hash at {seq}",
        )
        expected_files.add(state_name)
        state_records.append(state)
        transaction_id = event["transaction_id"]
        if seq == 0:
            _require(state == prepared["state"] and state_bytes == prepared["state_bytes"], "GENESIS state anchor")
            _require(A4_GENESIS_TXN_RE.fullmatch(transaction_id) is not None, "GENESIS transaction ID")
            plan_expected = prepared["plan"]
            plan_bytes_expected = prepared["plan_bytes"]
        elif CODE_CHANGE_TXN_RE.fullmatch(transaction_id) is not None:
            action = event.get("action")
            expected_suffix = "-PREPARE" if action == "PREPARE_REVIEWED_CODE_CHANGE" else "-COMMIT"
            _require(
                action in {"PREPARE_REVIEWED_CODE_CHANGE", "COMMIT_REVIEWED_CODE_CHANGE"}
                and transaction_id.endswith(expected_suffix),
                f"code transaction action/ID at {seq}",
            )
            code_change_id = transaction_id.rsplit("-", 1)[0]
            _require(code_change_id in contracts, f"missing code intent at {seq}")
            contract = contracts[code_change_id]
            is_online_direct = (
                contract.get("schema_version")
                == "c28f_user_authorized_online_code_change_v1"
            )
            used_code_ids.add(code_change_id)
            phases = phases_by_code.setdefault(code_change_id, [])
            phases.append(action)
            _require(
                phases in (
                    ["PREPARE_REVIEWED_CODE_CHANGE"],
                    ["PREPARE_REVIEWED_CODE_CHANGE", "COMMIT_REVIEWED_CODE_CHANGE"],
                    *(
                        (["COMMIT_REVIEWED_CODE_CHANGE"],)
                        if is_online_direct
                        else ()
                    ),
                ),
                f"invalid code-change phase order at {seq}",
            )
            _require(event["input_hashes"].get("parent_state") == previous_state["state_sha256"], f"event parent state at {seq}")  # type: ignore[index]
            _require(
                event["input_hashes"].get("code_change_intent")
                == contract["code_change_intent_sha256"],
                f"event/code intent binding at {seq}",
            )
            if action == "PREPARE_REVIEWED_CODE_CHANGE":
                _require(contract["parent_state_sha256"] == previous_state["state_sha256"], "prepare contract parent state")  # type: ignore[index]
                _require(contract["parent_event_sha256"] == events[seq - 1]["event_sha256"], "prepare contract parent event")
                _require(
                    contract["business_preimage_sha256"]
                    == previous_state["expected_goal_delta_sha256"],
                    "prepare contract business parent",
                )  # type: ignore[index]
                _require(state.get("status") == "CODE_CHANGE_PREPARED", "prepare state status")
                _require(state.get("pending_code_change", {}).get("code_change_id") == code_change_id, "prepare pending ID")
                _require(event["expected_goal_delta_sha256"] == contract["business_preimage_sha256"], "prepare business preimage")
                expected_pending: Optional[dict[str, Any]] = {
                    "code_change_id": code_change_id,
                    "prepare_transaction_id": transaction_id,
                    "code_change_intent_sha256": contract["code_change_intent_sha256"],
                    "business_postimage_sha256": contract["business_postimage_sha256"],
                    "resume_action": contract["resume_action"],
                }
                expected_status = "CODE_CHANGE_PREPARED"
                expected_next_action = "COMMIT_REVIEWED_CODE_CHANGE"
                expected_result = "PRECOMMITTED_REVIEWED_POSTIMAGE_AWAITING_APPLY_PATCH"
            else:
                committed_status = (
                    str(contract.get("resume_status", "PREFLIGHT_OK"))
                    if is_online_direct
                    else "PREFLIGHT_OK"
                )
                _require(
                    state.get("status") == committed_status
                    and state.get("pending_code_change") is None,
                    "commit state status",
                )
                _require(event["expected_goal_delta_sha256"] == contract["business_postimage_sha256"], "commit business postimage")
                if is_online_direct:
                    _require(
                        contract["parent_state_sha256"]
                        == previous_state["state_sha256"]  # type: ignore[index]
                        and contract["parent_event_sha256"]
                        == events[seq - 1]["event_sha256"]
                        and contract["business_preimage_sha256"]
                        == previous_state["expected_goal_delta_sha256"],  # type: ignore[index]
                        "online commit parent binding",
                    )
                else:
                    previous_pending = previous_state.get("pending_code_change")  # type: ignore[union-attr]
                    _require(
                        isinstance(previous_pending, dict)
                        and previous_pending.get("code_change_id") == code_change_id,
                        "commit does not follow its prepared state",
                    )
                expected_pending = None
                expected_status = (
                    str(contract.get("resume_status", "PREFLIGHT_OK"))
                    if is_online_direct
                    else "PREFLIGHT_OK"
                )
                expected_next_action = contract["resume_action"]
                expected_result = (
                    "COMMITTED_USER_AUTHORIZED_ONLINE_EXISTING_FILE_POSTIMAGE"
                    if is_online_direct
                    else "COMMITTED_EXACT_STATIC_REVIEWED_POSTIMAGE"
                )
            _require(event.get("result") == expected_result, f"code event result at {seq}")
            expected_state_base = dict(previous_state)  # type: ignore[arg-type]
            expected_state_base.pop("state_sha256", None)
            expected_state_base.update(
                {
                    "transaction_id": transaction_id,
                    "transition_seq": seq,
                    "status": expected_status,
                    "next_action": expected_next_action,
                    "next_action_is_unique": True,
                    "expected_goal_delta_sha256": event["expected_goal_delta_sha256"],
                    "pending_code_change": expected_pending,
                    "updated_at": f"control-seq:{seq}",
                }
            )
            _require(
                state == _with_semantic_sha(expected_state_base, "state_sha256"),
                f"state differs from deterministic transition at {seq}",
            )
            plan_expected = None
            plan_bytes_expected = None
        else:
            _require(
                STAGE_COMMIT_ID_RE.fullmatch(transaction_id) is not None
                or TRAIN_JSONL_INDEX_TXN_RE.fullmatch(transaction_id)
                is not None
                or EVAL_TOKEN_TXN_RE.fullmatch(transaction_id) is not None
                or ID_MAPPING_TXN_RE.fullmatch(transaction_id) is not None
                or FINALIZATION_TXN_RE.fullmatch(transaction_id) is not None,
                f"unsupported transition transaction ID at {seq}",
            )
            envelope_name = f"transactions/{transaction_id}/transition_intent.json"
            loaded_envelope, _envelope_bytes = _read_canonical_json(
                CONTROL_ROOT / envelope_name
            )
            _require(isinstance(loaded_envelope, dict), f"transition envelope at {seq}")
            transition_envelope = loaded_envelope
            _validate_transition_envelope(
                transition_envelope,
                attempt_id=str(intent["attempt_id"]),
            )
            if STAGE_COMMIT_ID_RE.fullmatch(transaction_id) is not None:
                _require(transaction_id in stage_contracts, f"missing stage intent at {seq}")
                stage_contract = stage_contracts[transaction_id]
                used_stage_ids.add(transaction_id)
                _require(
                    transition_envelope["action"] == stage_contract["stage_plan"]["action"]
                    and transition_envelope["expected_business_sha256"]
                    == stage_contract["business_postimage_sha256"]
                    and transition_envelope["input_bindings"].get("stage_commit_intent")
                    == stage_contract["stage_commit_intent_sha256"]
                    and transition_envelope["input_bindings"].get("stage_prepare_receipt")
                    == stage_contract["prepare_receipt"]["receipt_sha256"],
                    f"stage envelope binding at {seq}",
                )
            elif TRAIN_JSONL_INDEX_TXN_RE.fullmatch(transaction_id) is not None:
                session = CONTROL_ROOT / "transactions" / transaction_id
                claim, index, bootstrap_receipt = (
                    _load_train_jsonl_index_session(session)
                )
                index_registry = transition_envelope["registry_payload"]
                _validate_train_jsonl_index_registry(
                    index_registry,
                    claim=claim,
                    index=index,
                    receipt=bootstrap_receipt,
                )
                _require(
                    transition_envelope["action"]
                    == "G2_TRAIN_JSONL_INDEX_BOOTSTRAP"
                    and transition_envelope["result"]
                    == (
                        "FSYNCED_DESCRIPTOR_BOUND_INDEX_COMMITTED_"
                        "NONREPLAYABLE"
                    )
                    and transition_envelope["registry_name"]
                    == "train_jsonl_index_registry.json"
                    and transition_envelope["parent_state_sha256"]
                    == previous_state["state_sha256"]
                    and previous_state.get("status")
                    == "METRIC_CONTRACT_OK"
                    and previous_state.get("next_action")
                    == "G2_TRAIN_JSONL_INDEX_BOOTSTRAP"
                    and state.get("status") == "METRIC_CONTRACT_OK"
                    and state.get("next_action")
                    == "G3_F0_A_BASELINE_FORENSICS"
                    and state.get("train_jsonl_index_state") == "READY"
                    and state.get("train_jsonl_index_binding_sha256")
                    == index["index_binding_sha256"]
                    and state.get("train_jsonl_index_receipt_sha256")
                    == bootstrap_receipt["receipt_sha256"]
                    and state.get("train_jsonl_index_transaction_id")
                    == transaction_id
                    and state.get(
                        "authorized_mixed_container_index_open_count"
                    )
                    == _train_jsonl_index_total_authorized_open_count(claim)
                    and state.get(
                        "authorized_train_desc_selection_key_decode_count"
                    ) == index["line_count"]
                    and state.get(
                        "unauthorized_protected_payload_decode_count"
                    ) == 0
                    and transition_envelope["safety_counts"]
                    == {
                        "protected_content_opens": (
                            _train_jsonl_index_total_authorized_open_count(
                                claim
                            )
                        ),
                        "model_forward_evaluations": 0,
                        "real_data_optimizer_updates": 0,
                    },
                    f"TRAIN index committed transition at {seq}",
                )
            elif EVAL_TOKEN_TXN_RE.fullmatch(transaction_id) is not None:
                eval_registry = transition_envelope["registry_payload"]
                eval_fields = {
                    "schema_version", "goal_id", "attempt_id", "transaction_id",
                    "token_id", "eval_id", "run_id", "authority_id", "purpose", "token_state",
                    "cas_intent", "cas_intent_sha256", "authorization_sha256",
                    "budget_preimage_sha256", "budget_postimage_sha256",
                    "execution_binding", "execution_binding_sha256", "resume_status",
                    "resume_action", "previous_registry_sha256",
                    "previous_phase_receipt_sha256", "model_forward_evaluations",
                    "completion", "reservation_input_capability_sha256",
                }
                _require(
                    eval_registry.get("schema_version")
                    == "c28f_a4_eval_token_registry_v1"
                    and set(eval_registry) == eval_fields,
                    f"eval registry schema at {seq}",
                )
                _require(
                    isinstance(
                        eval_registry["reservation_input_capability_sha256"],
                        str,
                    )
                    and HEX64.fullmatch(
                        eval_registry["reservation_input_capability_sha256"]
                    ),
                    f"eval reservation capability hash at {seq}",
                )
                token_id = eval_registry["token_id"]
                eval_id = eval_registry["eval_id"]
                key = (token_id, eval_id)
                phase = eval_registry["token_state"]
                expected_suffix = {
                    "RESERVED": "-RESERVE",
                    "RUNNING": "-RUNNING",
                    "COMPLETED": "-COMPLETE",
                }.get(phase)
                _require(expected_suffix is not None and transaction_id.endswith(expected_suffix), f"eval phase/ID at {seq}")
                phases = eval_phase_chains.setdefault(key, [])
                phases.append(phase)
                _require(
                    phases in (["RESERVED"], ["RESERVED", "RUNNING"], ["RESERVED", "RUNNING", "COMPLETED"]),
                    f"eval token phase order at {seq}",
                )
                _require(
                    eval_registry["goal_id"] == GOAL_ID
                    and eval_registry["attempt_id"] == intent["attempt_id"]
                    and eval_registry["transaction_id"] == transaction_id
                    and state["eval_token_states"].get(token_id) == phase,
                    f"eval registry owner/state at {seq}",
                )
                cas_intent = eval_registry["cas_intent"]
                _validate_eval_cas_intent(cas_intent)
                _validate_eval_execution_binding(eval_registry["execution_binding"])
                _require(
                    isinstance(cas_intent, dict)
                    and cas_intent.get("intent_sha256")
                    == semantic_sha256(cas_intent, excluded_fields=("intent_sha256",))
                    == eval_registry["cas_intent_sha256"],
                    f"eval CAS intent at {seq}",
                )
                _require(
                    eval_registry["execution_binding_sha256"]
                    == semantic_sha256(eval_registry["execution_binding"]),
                    f"eval execution binding at {seq}",
                )
                expected_stem = _eval_transaction_stem(
                    cas_intent,
                    eval_registry["execution_binding"],
                )
                _require(
                    eval_registry["run_id"] == expected_stem
                    and transaction_id == expected_stem + expected_suffix,
                    f"eval deterministic run/transaction ID at {seq}",
                )
                previous_token_state = previous_state["eval_token_states"].get(token_id)  # type: ignore[index]
                expected_previous_state = {
                    "RESERVED": "UNISSUED",
                    "RUNNING": "RESERVED",
                    "COMPLETED": "RUNNING",
                }[phase]
                _require(previous_token_state == expected_previous_state, f"eval token CAS preimage at {seq}")
                _require(
                    eval_registry["authorization_sha256"]
                    == transition_envelope["input_bindings"].get("authorization")
                    and eval_registry["cas_intent_sha256"]
                    == transition_envelope["input_bindings"].get("cas_intent")
                    and eval_registry["execution_binding_sha256"]
                    == transition_envelope["input_bindings"].get("execution_binding")
                    and eval_registry["budget_preimage_sha256"]
                    == transition_envelope["input_bindings"].get("budget_preimage")
                    and eval_registry["budget_postimage_sha256"]
                    == transition_envelope["input_bindings"].get("budget_postimage")
                    and eval_registry["reservation_input_capability_sha256"]
                    == transition_envelope["input_bindings"].get(
                        "reservation_input_capability"
                    ),
                    f"eval envelope input closure at {seq}",
                )
                _require(
                    eval_registry["previous_registry_sha256"]
                    == eval_last_registry_sha.get(key)
                    and eval_registry["previous_phase_receipt_sha256"]
                    == eval_last_receipt_sha.get(key),
                    f"eval registry predecessor at {seq}",
                )
                if phase == "RESERVED":
                    _require(
                        eval_registry["resume_status"] == previous_state["status"]  # type: ignore[index]
                        and eval_registry["resume_action"] == previous_state["next_action"],  # type: ignore[index]
                        f"eval resume binding at {seq}",
                    )
                    reservation_name = (
                        f"transactions/{transaction_id}/reservation_input.json"
                    )
                    reservation_record, _reservation_bytes = _read_canonical_json(
                        CONTROL_ROOT / reservation_name
                    )
                    _require(
                        isinstance(reservation_record, dict)
                        and set(reservation_record)
                        == {
                            "schema_version", "status", "goal_id",
                            "capability_sha256", "payload", "record_sha256",
                        }
                        and reservation_record.get("schema_version")
                        == "c28f_a4_persisted_eval_reservation_input_v1"
                        and reservation_record.get("status")
                        == "FSYNCED_CONTROLLER_ISSUED_INPUT"
                        and reservation_record.get("goal_id") == GOAL_ID
                        and reservation_record.get("record_sha256")
                        == semantic_sha256(
                            reservation_record,
                            excluded_fields=("record_sha256",),
                        )
                        and reservation_record.get("capability_sha256")
                        == eval_registry[
                            "reservation_input_capability_sha256"
                        ],
                        f"eval reservation input record at {seq}",
                    )
                    rebuilt_reservation = _build_eval_reservation_input_record(
                        reservation_record["payload"],
                        reservation_record["capability_sha256"],
                    )
                    _require(
                        rebuilt_reservation == reservation_record
                        and reservation_record["payload"]["cas_intent"]
                        == eval_registry["cas_intent"]
                        and reservation_record["payload"]["execution_binding"]
                        == eval_registry["execution_binding"]
                        and reservation_record["payload"]["authorization_sha256"]
                        == eval_registry["authorization_sha256"]
                        and reservation_record["payload"]["committed_state_sha256"]
                        == previous_state["state_sha256"]  # type: ignore[index]
                        and reservation_record["payload"]["committed_event_sha256"]
                        == events[seq - 1]["event_sha256"],
                        f"eval reservation input full rebuild at {seq}",
                    )
                    expected_files.add(reservation_name)
                else:
                    prior_registry = eval_last_registry_payload[key]
                    immutable_eval_fields = {
                        "token_id", "eval_id", "run_id", "authority_id", "purpose", "cas_intent",
                        "cas_intent_sha256", "authorization_sha256",
                        "budget_preimage_sha256", "budget_postimage_sha256",
                        "execution_binding", "execution_binding_sha256", "resume_status",
                        "resume_action", "reservation_input_capability_sha256",
                    }
                    _require(
                        all(
                            eval_registry[field] == prior_registry[field]
                            for field in immutable_eval_fields
                        ),
                        f"eval immutable binding drift at {seq}",
                    )
                expected_action = {
                    "RESERVED": "RESERVE_EVAL_TOKEN",
                    "RUNNING": "MARK_EVAL_RUNNING",
                    "COMPLETED": "COMPLETE_EVAL_TOKEN",
                }[phase]
                _require(
                    event["action"] == expected_action
                    and event["result"] == f"FSYNCED_EVAL_TOKEN_{phase}",
                    f"eval event action/result at {seq}",
                )
                if phase in {"RESERVED", "RUNNING"}:
                    _require(
                        eval_registry["model_forward_evaluations"] == 0
                        and eval_registry["completion"] is None
                        and transition_envelope["safety_counts"]["model_forward_evaluations"] == 0,
                        f"premature eval forward evidence at {seq}",
                    )
                else:
                    completion = eval_registry["completion"]
                    _require(
                        isinstance(completion, dict)
                        and completion.get("model_forward_evaluations") == 1
                        and eval_cursor_tails.get(key) is not None
                        and completion.get("cursor_sha256")
                        == eval_cursor_tails[key]["cursor_sha256"]  # type: ignore[index]
                        and completion.get("chunks_sha256")
                        == eval_cursor_tails[key]["chunks_sha256"]  # type: ignore[index]
                        and completion.get("artifacts_sha256")
                        == eval_cursor_tails[key]["artifacts_sha256"]  # type: ignore[index]
                        and eval_registry["model_forward_evaluations"] == 1
                        and transition_envelope["safety_counts"]["model_forward_evaluations"] == 1,
                        f"eval completion evidence at {seq}",
                    )
                receipt_name = (
                    f"transactions/{transaction_id}/cas_receipt.json"
                    if phase == "RESERVED"
                    else f"transactions/{transaction_id}/phase_receipt.json"
                )
                phase_receipt, _receipt_bytes = _read_canonical_json(
                    CONTROL_ROOT / receipt_name
                )
                expected_phase_receipt = _build_eval_phase_receipt(
                    eval_registry,
                    state,
                    event,
                )
                _require(phase_receipt == expected_phase_receipt, f"eval phase receipt at {seq}")
                expected_files.add(receipt_name)
                if phase == "RUNNING":
                    consumption_name = (
                        f"transactions/{transaction_id}/forward_capability_consumption.json"
                    )
                    if os.path.lexists(CONTROL_ROOT / consumption_name):
                        consumption, _consumption_bytes = _read_canonical_json(
                            CONTROL_ROOT / consumption_name
                        )
                        _require(isinstance(consumption, dict), "forward consumption receipt")
                        _require(
                            consumption.get("authority_binding_sha256")
                            == eval_registry["execution_binding"][
                                "authority_binding_sha256"
                            ]
                            and isinstance(consumption.get("consumer_nonce_sha256"), str)
                            and HEX64.fullmatch(consumption["consumer_nonce_sha256"]),
                            "forward consumption binding",
                        )
                        _require(
                            consumption
                            == _build_forward_consumption_receipt(
                                eval_registry,
                                state,
                                event,
                                authority_binding_sha256=consumption[
                                    "authority_binding_sha256"
                                ],
                                consumer_nonce_sha256=consumption[
                                    "consumer_nonce_sha256"
                                ],
                            ),
                            "forward consumption receipt full rebuild",
                        )
                        expected_files.add(consumption_name)
                    cursor_files, cursor_directories, latest_cursor = (
                        _validate_eval_cursor_chain(eval_registry, state, event)
                    )
                    expected_files.update(cursor_files)
                    expected_directories.update(cursor_directories)
                    lmdb_files, lmdb_directories, _lmdb_receipts = (
                        _validate_lmdb_batch_chain(eval_registry, state, event)
                    )
                    expected_files.update(lmdb_files)
                    expected_directories.update(lmdb_directories)
                    eval_cursor_tails[key] = latest_cursor
                eval_last_registry_sha[key] = bytes_sha256(
                    _canonical_file_bytes(eval_registry)
                )
                eval_last_receipt_sha[key] = expected_phase_receipt["receipt_sha256"]
                eval_last_registry_payload[key] = dict(eval_registry)
            elif ID_MAPPING_TXN_RE.fullmatch(transaction_id) is not None:
                mapping_registry = transition_envelope["registry_payload"]
                mapping_fields = {
                    "schema_version", "goal_id", "attempt_id",
                    "authority_permission_id", "operation_id", "transaction_id",
                    "phase", "parent_state_sha256", "parent_event_sha256",
                    "running_state_sha256", "running_event_sha256",
                    "descriptor_record", "descriptor_identity_sha256",
                    "protected_manifest_contract", "access_intent_sha256",
                    "authority_source_file_sha256", "previous_registry_sha256",
                    "previous_phase_receipt_sha256",
                    "control_capability_sha256", "access_counters",
                    "source_observation_receipt", "result_seal_sha256",
                    "projection_manifest_sha256",
                    "minimal_projection_preimage_sha256",
                    "eval_token_consumed",
                }
                _require(
                    isinstance(mapping_registry, dict)
                    and set(mapping_registry) == mapping_fields
                    and mapping_registry.get("schema_version")
                    == "c28f_a4_protected_id_mapping_registry_v1"
                    and mapping_registry.get("goal_id") == GOAL_ID
                    and mapping_registry.get("attempt_id") == intent["attempt_id"]
                    and mapping_registry.get("transaction_id") == transaction_id
                    and mapping_registry.get("authority_permission_id")
                    == "AUTH_PROTECTED_ID_MAPPING_ONLY"
                    and mapping_registry.get("eval_token_consumed") is False,
                    f"protected ID mapping registry at {seq}",
                )
                operation_id = mapping_registry["operation_id"]
                phase = mapping_registry["phase"]
                expected_suffix = {
                    "RUNNING": "-RUNNING",
                    "ACCESS": "-ACCESS",
                    "COMPLETE": "-COMPLETE",
                }.get(phase)
                _require(
                    isinstance(operation_id, str)
                    and transaction_id == operation_id + expected_suffix
                    if expected_suffix is not None
                    else False,
                    f"protected ID mapping phase/transaction at {seq}",
                )
                phases = id_mapping_phases.setdefault(operation_id, [])
                phases.append(phase)
                _require(
                    phases
                    in (
                        ["RUNNING"],
                        ["RUNNING", "ACCESS"],
                        ["RUNNING", "ACCESS", "COMPLETE"],
                    ),
                    f"protected ID mapping phase order at {seq}",
                )
                descriptor = mapping_registry["descriptor_record"]
                manifest_contract = mapping_registry[
                    "protected_manifest_contract"
                ]
                _require(
                    isinstance(descriptor, dict)
                    and semantic_sha256(descriptor)
                    == mapping_registry["descriptor_identity_sha256"]
                    and isinstance(manifest_contract, dict)
                    and manifest_contract.get("contract_sha256")
                    == semantic_sha256(
                        manifest_contract,
                        excluded_fields=("contract_sha256",),
                    )
                    and manifest_contract.get("union_sha256")
                    == PROTECTED_ID_MAPPING_UNION_SHA256
                    and manifest_contract.get("union_count")
                    == PROTECTED_ID_MAPPING_UNION_COUNT,
                    f"protected ID mapping source/manifest binding at {seq}",
                )
                _require(
                    mapping_registry["previous_registry_sha256"]
                    == id_mapping_last_registry_sha.get(operation_id)
                    and mapping_registry["previous_phase_receipt_sha256"]
                    == id_mapping_last_receipt_sha.get(operation_id),
                    f"protected ID mapping predecessor at {seq}",
                )
                if phase != "RUNNING":
                    prior = id_mapping_last_registry_payload[operation_id]
                    immutable_fields = {
                        "goal_id", "attempt_id", "authority_permission_id",
                        "operation_id", "parent_state_sha256",
                        "parent_event_sha256", "descriptor_record",
                        "descriptor_identity_sha256",
                        "protected_manifest_contract", "access_intent_sha256",
                        "authority_source_file_sha256", "eval_token_consumed",
                    }
                    _require(
                        all(
                            mapping_registry[field] == prior[field]
                            for field in immutable_fields
                        ),
                        f"protected ID mapping immutable binding at {seq}",
                    )
                if phase == "RUNNING":
                    _require(
                        mapping_registry["running_state_sha256"] is None
                        and mapping_registry["running_event_sha256"] is None
                        and mapping_registry["control_capability_sha256"] is None
                        and mapping_registry["access_counters"] is None
                        and mapping_registry["source_observation_receipt"] is None
                        and mapping_registry["result_seal_sha256"] is None
                        and mapping_registry["projection_manifest_sha256"] is None
                        and mapping_registry[
                            "minimal_projection_preimage_sha256"
                        ]
                        is None
                        and event["action"]
                        == "BEGIN_PROTECTED_ID_MAPPING_OPERATION"
                        and event["result"] == "FSYNCED_ID_MAPPING_RUNNING"
                        and state["status"] == "ID_MAPPING_RUNNING",
                        f"protected ID mapping RUNNING state at {seq}",
                    )
                    receipt_name = (
                        f"transactions/{transaction_id}/phase_receipt.json"
                    )
                    receipt, _receipt_bytes = _read_canonical_json(
                        CONTROL_ROOT / receipt_name
                    )
                    expected_receipt = _build_id_mapping_phase_receipt(
                        mapping_registry,
                        state,
                        event,
                    )
                    preimage_name = (
                        f"transactions/{transaction_id}/"
                        "minimal_projection_batch_preimage.json"
                    )
                    if os.path.lexists(CONTROL_ROOT / preimage_name):
                        preimage, _preimage_bytes = _read_canonical_json(
                            CONTROL_ROOT / preimage_name,
                            max_bytes=1024 * 1024 * 1024,
                        )
                        validated_preimage = (
                            _validate_g4_minimal_projection_preimage(
                                preimage
                            )
                        )
                        _require(
                            validated_preimage["operation_id"]
                            == operation_id
                            and validated_preimage[
                                "running_transaction_id"
                            ]
                            == transaction_id
                            and validated_preimage[
                                "running_state_sha256"
                            ]
                            == state["state_sha256"]
                            and validated_preimage[
                                "running_event_sha256"
                            ]
                            == event["event_sha256"]
                            and validated_preimage[
                                "protected_manifest_contract_sha256"
                            ]
                            == manifest_contract["contract_sha256"],
                            f"protected ID mapping preimage at {seq}",
                        )
                        expected_files.add(preimage_name)
                elif phase == "ACCESS":
                    observation = mapping_registry[
                        "source_observation_receipt"
                    ]
                    _require(
                        isinstance(mapping_registry["running_state_sha256"], str)
                        and HEX64.fullmatch(
                            mapping_registry["running_state_sha256"]
                        )
                        and isinstance(mapping_registry["running_event_sha256"], str)
                        and HEX64.fullmatch(
                            mapping_registry["running_event_sha256"]
                        )
                        and isinstance(
                            mapping_registry["control_capability_sha256"], str
                        )
                        and HEX64.fullmatch(
                            mapping_registry["control_capability_sha256"]
                        )
                        and isinstance(mapping_registry["access_counters"], dict)
                        and isinstance(observation, dict)
                        and observation.get("receipt_sha256")
                        == semantic_sha256(
                            observation,
                            excluded_fields=("receipt_sha256",),
                        )
                        and mapping_registry["result_seal_sha256"] is None
                        and mapping_registry["projection_manifest_sha256"] is None
                        and isinstance(
                            mapping_registry[
                                "minimal_projection_preimage_sha256"
                            ],
                            str,
                        )
                        and HEX64.fullmatch(
                            mapping_registry[
                                "minimal_projection_preimage_sha256"
                            ]
                        )
                        and event["action"]
                        == "COMMIT_PROTECTED_ID_MAPPING_ACCESS"
                        and event["result"]
                        == "FSYNCED_ID_ONLY_ACCESS_COMMITTED"
                        and state["status"] == "ID_MAPPING_ACCESS_COMMITTED",
                        f"protected ID mapping ACCESS state at {seq}",
                    )
                    preimage_name = (
                        f"transactions/{operation_id}-RUNNING/"
                        "minimal_projection_batch_preimage.json"
                    )
                    preimage, _preimage_bytes = _read_canonical_json(
                        CONTROL_ROOT / preimage_name,
                        max_bytes=1024 * 1024 * 1024,
                    )
                    validated_preimage = (
                        _validate_g4_minimal_projection_preimage(preimage)
                    )
                    _require(
                        validated_preimage[
                            "running_capability_sha256"
                        ]
                        == mapping_registry[
                            "control_capability_sha256"
                        ]
                        and validated_preimage["preimage_sha256"]
                        == mapping_registry[
                            "minimal_projection_preimage_sha256"
                        ]
                        and validated_preimage[
                            "source_observation_receipt"
                        ]
                        == observation
                        and validated_preimage["access_counters"]
                        == mapping_registry["access_counters"],
                        f"protected ID mapping ACCESS/preimage at {seq}",
                    )
                    expected_files.add(preimage_name)
                    receipt_name = (
                        f"transactions/{transaction_id}/access_receipt.json"
                    )
                    receipt, _receipt_bytes = _read_canonical_json(
                        CONTROL_ROOT / receipt_name
                    )
                    expected_receipt = _build_id_mapping_access_receipt(
                        mapping_registry,
                        state,
                        event,
                    )
                else:
                    _require(
                        isinstance(mapping_registry["result_seal_sha256"], str)
                        and HEX64.fullmatch(
                            mapping_registry["result_seal_sha256"]
                        )
                        and isinstance(
                            mapping_registry["projection_manifest_sha256"], str
                        )
                        and HEX64.fullmatch(
                            mapping_registry["projection_manifest_sha256"]
                        )
                        and isinstance(
                            mapping_registry[
                                "minimal_projection_preimage_sha256"
                            ],
                            str,
                        )
                        and mapping_registry[
                            "minimal_projection_preimage_sha256"
                        ]
                        == prior["minimal_projection_preimage_sha256"]
                        and event["action"]
                        == "COMPLETE_PROTECTED_ID_MAPPING_OPERATION"
                        and event["result"]
                        == "FSYNCED_ID_MAPPING_COMPLETE"
                        and state["status"] == "ID_MAPPING_COMPLETE",
                        f"protected ID mapping COMPLETE state at {seq}",
                    )
                    receipt_name = (
                        f"transactions/{transaction_id}/phase_receipt.json"
                    )
                    receipt, _receipt_bytes = _read_canonical_json(
                        CONTROL_ROOT / receipt_name
                    )
                    expected_receipt = _build_id_mapping_phase_receipt(
                        mapping_registry,
                        state,
                        event,
                    )
                _require(
                    receipt == expected_receipt,
                    f"protected ID mapping phase receipt at {seq}",
                )
                expected_files.add(receipt_name)
                if phase == "ACCESS":
                    seal_name = (
                        f"transactions/{transaction_id}/result_seal_receipt.json"
                    )
                    if os.path.lexists(CONTROL_ROOT / seal_name):
                        seal_receipt, _seal_bytes = _read_canonical_json(
                            CONTROL_ROOT / seal_name
                        )
                        _require(
                            isinstance(seal_receipt, dict)
                            and set(seal_receipt)
                            == {
                                "schema_version", "status", "goal_id",
                                "attempt_id", "operation_id",
                                "access_transaction_id", "access_state_sha256",
                                "access_event_sha256",
                                "running_capability_sha256",
                                "batch_capability_sha256",
                                "access_receipt_sha256",
                                "batch_binding_sha256",
                                "protected_manifest_contract_sha256",
                                "expected_desc_ids_sha256", "records_sha256",
                                "scanner_contract_sha256",
                                "source_observation_receipt_sha256",
                                "result_payload_sha256", "result_seal_sha256",
                                "receipt_sha256",
                            }
                            and seal_receipt.get("schema_version")
                            == (
                                "c28f_a4_g4_projection_result_seal_receipt_v1"
                            )
                            and seal_receipt.get("status")
                            == "FSYNCED_CONTROLLER_RESULT_SEAL"
                            and seal_receipt.get("operation_id") == operation_id
                            and seal_receipt.get("access_transaction_id")
                            == transaction_id
                            and seal_receipt.get("access_state_sha256")
                            == state["state_sha256"]
                            and seal_receipt.get("access_event_sha256")
                            == event["event_sha256"]
                            and seal_receipt.get("running_capability_sha256")
                            == mapping_registry["control_capability_sha256"]
                            and seal_receipt.get("access_receipt_sha256")
                            == expected_receipt["receipt_sha256"]
                            and all(
                                isinstance(seal_receipt.get(field), str)
                                and HEX64.fullmatch(seal_receipt[field])
                                for field in (
                                    "batch_binding_sha256",
                                    "protected_manifest_contract_sha256",
                                    "expected_desc_ids_sha256",
                                    "records_sha256",
                                    "scanner_contract_sha256",
                                    "source_observation_receipt_sha256",
                                )
                            )
                            and seal_receipt.get("result_seal_sha256")
                            == semantic_sha256(
                                {
                                    "schema_version": (
                                        "c28f_a4_g4_projection_result_seal_v2"
                                    ),
                                    "control_capability_sha256": seal_receipt[
                                        "running_capability_sha256"
                                    ],
                                    "batch_capability_sha256": seal_receipt[
                                        "batch_capability_sha256"
                                    ],
                                    "access_receipt_sha256": seal_receipt[
                                        "access_receipt_sha256"
                                    ],
                                    "result_payload_sha256": seal_receipt[
                                        "result_payload_sha256"
                                    ],
                                }
                            )
                            and seal_receipt.get("receipt_sha256")
                            == semantic_sha256(
                                seal_receipt,
                                excluded_fields=("receipt_sha256",),
                            ),
                            f"protected ID mapping result seal at {seq}",
                        )
                        expected_files.add(seal_name)
                id_mapping_last_registry_sha[operation_id] = bytes_sha256(
                    _canonical_file_bytes(mapping_registry)
                )
                id_mapping_last_receipt_sha[operation_id] = expected_receipt[
                    "receipt_sha256"
                ]
                id_mapping_last_registry_payload[operation_id] = dict(
                    mapping_registry
                )
            else:
                final_registry = transition_envelope["registry_payload"]
                final_fields = {
                    "schema_version", "goal_id", "attempt_id", "transaction_id",
                    "finalization_txn_id", "phase", "pending_core_sha256",
                    "final_artifact_hashes_sha256", "closed_authority",
                    "closed_authority_sha256", "snapshot_capability_sha256",
                    "previous_phase_receipt_sha256",
                    "lease_release_authorized",
                }
                _require(
                    isinstance(final_registry, dict)
                    and final_registry.get("schema_version")
                    == "c28f_a4_finalization_registry_v2"
                    and set(final_registry) == final_fields
                    and final_registry.get("transaction_id") == transaction_id,
                    f"finalization registry at {seq}",
                )
                phase = final_registry.get("phase")
                expected_suffix = "-PREPARE" if phase == "PREPARE" else "-COMMIT"
                _require(
                    phase in {"PREPARE", "COMMIT"}
                    and transaction_id.endswith(expected_suffix),
                    f"finalization phase at {seq}",
                )
                finalization_id = final_registry["finalization_txn_id"]
                _require(
                    transaction_id == "%s-%s" % (
                        finalization_id,
                        "PREPARE" if phase == "PREPARE" else "COMMIT",
                    ),
                    f"finalization transaction/base identity at {seq}",
                )
                phases = finalization_phases.setdefault(finalization_id, [])
                phases.append(phase)
                _require(
                    phases in (["PREPARE"], ["PREPARE", "COMMIT"]),
                    f"finalization phase order at {seq}",
                )
                _require(
                    final_registry["previous_phase_receipt_sha256"]
                    == finalization_last_receipt.get(finalization_id)
                    and final_registry["lease_release_authorized"] is False,
                    f"finalization receipt predecessor/release at {seq}",
                )
                closed_authority = final_registry["closed_authority"]
                _require(
                    isinstance(closed_authority, dict)
                    and closed_authority.get("authority_sha256")
                    == semantic_sha256(
                        closed_authority,
                        excluded_fields=("authority_sha256",),
                    )
                    == final_registry["closed_authority_sha256"],
                    f"finalization closed authority at {seq}",
                )
                pending_record, _pending_record_bytes = _read_canonical_json(
                    CONTROL_ROOT / "PENDING_FINALIZATION.json"
                )
                final_intent = pending_record.get("pending_intent")
                _require(
                    isinstance(final_intent, dict)
                    and final_intent.get("pending_intent_sha256")
                    == semantic_sha256(
                        final_intent,
                        excluded_fields=("pending_intent_sha256",),
                    )
                    == pending_record.get("pending_intent_sha256")
                    and final_intent.get("finalization_txn_id")
                    == finalization_id
                    and final_intent.get("pending_core_sha256")
                    == final_registry.get("pending_core_sha256")
                    and final_intent.get("final_artifact_hashes_sha256")
                    == final_registry.get("final_artifact_hashes_sha256")
                    and final_intent.get(
                        "expected_closed_authority_sha256"
                    )
                    == final_registry.get("closed_authority_sha256")
                    and pending_record.get("record_sha256")
                    == semantic_sha256(
                        pending_record,
                        excluded_fields=("record_sha256",),
                    ),
                    f"finalization intent at {seq}",
                )
                expected_state_field = (
                    "expected_pending_state_sha256"
                    if phase == "PREPARE"
                    else "expected_terminal_state_sha256"
                )
                expected_event_field = (
                    "expected_pending_event_sha256"
                    if phase == "PREPARE"
                    else "expected_terminal_event_sha256"
                )
                _require(
                    final_intent.get(expected_state_field)
                    == state["state_sha256"]
                    and final_intent.get(expected_event_field)
                    == event["event_sha256"],
                    f"finalization intent expected state/event at {seq}",
                )
                final_intent_name = f"transactions/{transaction_id}/finalization_intent.json"
                persisted_intent, _persisted_bytes = _read_canonical_json(
                    CONTROL_ROOT / final_intent_name
                )
                _require(persisted_intent == final_intent, f"finalization persisted intent at {seq}")
                receipt_name = (
                    f"transactions/{transaction_id}/prepare_receipt.json"
                    if phase == "PREPARE"
                    else f"transactions/{transaction_id}/terminal_receipt.json"
                )
                final_receipt, _receipt_bytes = _read_canonical_json(
                    CONTROL_ROOT / receipt_name
                )
                _require(
                    isinstance(final_receipt, dict)
                    and final_receipt
                    == _build_finalization_phase_receipt(
                        final_registry,
                        state,
                        event,
                    ),
                    f"finalization receipt at {seq}",
                )
                finalization_last_receipt[finalization_id] = final_receipt[
                    "receipt_sha256"
                ]
                expected_files.update(
                    {
                        final_intent_name,
                        receipt_name,
                        "PENDING_FINALIZATION.json",
                    }
                )
            _require(
                transition_envelope["transaction_id"] == transaction_id
                and transition_envelope["parent_state_sha256"] == previous_state["state_sha256"]
                and transition_envelope["parent_event_sha256"] == events[seq - 1]["event_sha256"],
                f"transition envelope parent at {seq}",
            )
            _require(
                event["action"] == transition_envelope["action"]
                and event["result"] == transition_envelope["result"]
                and event["input_hashes"].get("transition_intent")
                == transition_envelope["transition_intent_sha256"]
                and event["input_hashes"].get("parent_state") == previous_state["state_sha256"],
                f"transition envelope event binding at {seq}",
            )
            _require(
                event["expected_goal_delta_sha256"]
                == transition_envelope["expected_business_sha256"],
                f"transition envelope business at {seq}",
            )
            for name, digest in transition_envelope["input_bindings"].items():
                _require(event["input_hashes"].get(name) == digest, f"envelope input binding {name} at {seq}")
            expected_state_base = dict(previous_state)
            expected_state_base.pop("state_sha256", None)
            expected_state_base.update(dict(transition_envelope["state_updates"]))
            expected_state_base.update(
                {
                    "transaction_id": transaction_id,
                    "transition_seq": seq,
                    "next_action_is_unique": True,
                    "expected_goal_delta_sha256": transition_envelope[
                        "expected_business_sha256"
                    ],
                    "updated_at": f"control-seq:{seq}",
                }
            )
            _require(
                state == _with_semantic_sha(expected_state_base, "state_sha256"),
                f"enveloped state differs from deterministic transition at {seq}",
            )
            expected_files.add(envelope_name)
            plan_expected = None
            plan_bytes_expected = None
        plan_name = f"transactions/{transaction_id}/plan.json"
        plan, plan_bytes = _read_canonical_json(CONTROL_ROOT / plan_name)
        _require(isinstance(plan, dict), f"plan object at {seq}")
        _require(plan.get("plan_sha256") == semantic_sha256(plan, excluded_fields=("plan_sha256",)), f"plan semantic at {seq}")
        _require(plan.get("seq") == seq and plan.get("transaction_id") == transaction_id, f"plan identity at {seq}")
        _require(plan.get("schema_version") == "c28f_append_only_transaction_plan_v1", f"plan schema at {seq}")
        _require(plan.get("goal_id") == GOAL_ID and plan.get("attempt_id") == intent["attempt_id"], f"plan owner at {seq}")
        _require(plan.get("action") == event["action"], f"plan action at {seq}")
        _require(plan.get("expected_state_sha256") == state["state_sha256"], f"plan state at {seq}")
        _require(plan.get("state_pointer_is_last_commit_marker") is True, f"plan commit marker at {seq}")
        _require(bytes_sha256(plan_bytes) == event["input_hashes"]["transaction_plan_file"], f"event/plan binding at {seq}")
        if plan_expected is not None:
            _require(plan == plan_expected and plan_bytes == plan_bytes_expected, "GENESIS plan anchor")
        else:
            _require(plan.get("parent_state_sha256") == previous_state["state_sha256"], f"plan parent state at {seq}")  # type: ignore[index]
            _require(plan.get("parent_event_sha256") == events[seq - 1]["event_sha256"], f"plan parent event at {seq}")
            _require(
                plan.get("expected_business_postimage_sha256")
                == event["expected_goal_delta_sha256"],
                f"plan business hash at {seq}",
            )
            if transition_envelope is None:
                _require(
                    plan.get("code_change_intent_sha256")
                    == contracts[transaction_id.rsplit("-", 1)[0]]["code_change_intent_sha256"],
                    f"plan/code intent binding at {seq}",
                )
                _require("transition_intent_sha256" not in plan, f"code plan envelope field at {seq}")
            else:
                _require(
                    plan.get("transition_intent_sha256")
                    == transition_envelope["transition_intent_sha256"],
                    f"plan/transition intent binding at {seq}",
                )
                _require("code_change_intent_sha256" not in plan, f"envelope plan code field at {seq}")
            declared_outputs = {
                **plan.get("registry_output_hashes", {}),
                **plan.get("ledger_output_hashes", {}),
            }
            _require(declared_outputs == event["output_hashes"], f"plan/event outputs at {seq}")
            if transition_envelope is not None:
                envelope_registry_name = str(transition_envelope["registry_name"])
                envelope_registry_bytes = _canonical_file_bytes(
                    transition_envelope["registry_payload"]
                )
                mutation_prefix = b"\n".join(mutation_lines[: seq + 1]) + b"\n"
                expected_plan_base = {
                    "schema_version": "c28f_append_only_transaction_plan_v1",
                    "goal_id": GOAL_ID,
                    "attempt_id": intent["attempt_id"],
                    "transaction_id": transaction_id,
                    "seq": seq,
                    "action": transition_envelope["action"],
                    "parent_state_sha256": previous_state["state_sha256"],  # type: ignore[index]
                    "parent_event_sha256": events[seq - 1]["event_sha256"],
                    "expected_state_sha256": state["state_sha256"],
                    "expected_business_postimage_sha256": transition_envelope[
                        "expected_business_sha256"
                    ],
                    "registry_output_hashes": {
                        envelope_registry_name: bytes_sha256(envelope_registry_bytes)
                    },
                    "ledger_output_hashes": {
                        "ledgers/mutation_ledger.jsonl": bytes_sha256(mutation_prefix)
                    },
                    "transition_intent_sha256": transition_envelope[
                        "transition_intent_sha256"
                    ],
                    "state_pointer_is_last_commit_marker": True,
                }
                expected_enveloped_plan = _with_semantic_sha(
                    expected_plan_base,
                    "plan_sha256",
                )
                _require(plan == expected_enveloped_plan, f"enveloped plan full rebuild at {seq}")
                expected_event_base = {
                    "schema_version": "c28f_goal_event_v2",
                    "seq": seq,
                    "goal_id": GOAL_ID,
                    "attempt_id": intent["attempt_id"],
                    "transaction_id": transaction_id,
                    "action": transition_envelope["action"],
                    "result": transition_envelope["result"],
                    "prev_event_sha256": events[seq - 1]["event_sha256"],
                    "expected_next_state_sha256": state["state_sha256"],
                    "expected_goal_delta_sha256": transition_envelope[
                        "expected_business_sha256"
                    ],
                    "next_action": state["next_action"],
                    "input_hashes": {
                        "parent_state": previous_state["state_sha256"],  # type: ignore[index]
                        "transaction_plan_file": bytes_sha256(plan_bytes),
                        "transition_intent": transition_envelope[
                            "transition_intent_sha256"
                        ],
                        **dict(transition_envelope["input_bindings"]),
                    },
                    "output_hashes": {
                        envelope_registry_name: bytes_sha256(envelope_registry_bytes),
                        "ledgers/mutation_ledger.jsonl": bytes_sha256(mutation_prefix),
                    },
                    "safety_counts": dict(transition_envelope["safety_counts"]),
                }
                _require(
                    event == _with_semantic_sha(expected_event_base, "event_sha256"),
                    f"enveloped event full rebuild at {seq}",
                )
        expected_files.add(plan_name)
        expected_directories.add(f"transactions/{transaction_id}")
        mutation_entry = mutation_entries[seq]
        _require(
            mutation_entry["action"] == event["action"]
            and mutation_entry["transaction_id"] == transaction_id,
            f"mutation/event binding at {seq}",
        )
        mutation_sidecar_name = (
            f"ledger_records/mutation/{seq:06d}_{mutation_entry['entry_sha256']}.jsonl"
        )
        mutation_sidecar, _record = read_regular_bytes(
            CONTROL_ROOT / mutation_sidecar_name,
            require_nlink_one=True,
        )
        _require(mutation_sidecar == mutation_lines[seq] + b"\n", f"mutation sidecar at {seq}")
        expected_files.add(mutation_sidecar_name)
        if seq > 0:
            prefix = b"\n".join(mutation_lines[: seq + 1]) + b"\n"
            _require(
                event["output_hashes"].get("ledgers/mutation_ledger.jsonl")
                == bytes_sha256(prefix),
                f"mutation prefix hash at {seq}",
            )
            current_registry_name = (
                "code_change_registry.json"
                if transition_envelope is None
                else str(transition_envelope["registry_name"])
            )
            registry_sha = event["output_hashes"].get(current_registry_name)
            _require(isinstance(registry_sha, str) and HEX64.fullmatch(registry_sha), f"registry hash at {seq}")
            registry_sidecar_name = (
                f"registry_records/{seq:06d}_{current_registry_name[:-5]}_{registry_sha}.json"
            )
            registry_bytes, _record = read_regular_bytes(
                CONTROL_ROOT / registry_sidecar_name,
                require_nlink_one=True,
            )
            _require(bytes_sha256(registry_bytes) == registry_sha, f"registry sidecar at {seq}")
            registry_payload = json.loads(registry_bytes.decode("utf-8", "strict"))
            _require(registry_bytes == _canonical_file_bytes(registry_payload), f"registry canonical at {seq}")
            if transition_envelope is None:
                _require(registry_payload.get("transaction_id") == transaction_id, f"code registry transaction at {seq}")
                code_change_id = transaction_id.rsplit("-", 1)[0]
                contract = contracts[code_change_id]
                is_online_direct = (
                    contract.get("schema_version")
                    == "c28f_user_authorized_online_code_change_v1"
                )
                if event["action"] == "PREPARE_REVIEWED_CODE_CHANGE":
                    expected_mutation_facts = {
                        "phase": "PREPARE",
                        "code_change_intent_sha256": contract["code_change_intent_sha256"],
                        "business_preimage_sha256": contract["business_preimage_sha256"],
                        "business_postimage_sha256": contract["business_postimage_sha256"],
                        "apply_patch_executed": False,
                    }
                elif is_online_direct:
                    expected_mutation_facts = {
                        "phase": "DIRECT_ONLINE_COMMIT",
                        "code_change_intent_sha256": contract["code_change_intent_sha256"],
                        "business_preimage_sha256": contract["business_preimage_sha256"],
                        "business_postimage_sha256": contract["business_postimage_sha256"],
                        "installed_file_count": len(contract["files"]),
                        "code_executed_or_imported_before_commit": True,
                        "review_policy": ONLINE_CODE_CHANGE_REVIEW_POLICY,
                        "user_authorization_sha256": contract["user_authorization"][
                            "text_sha256"
                        ],
                    }
                else:
                    expected_mutation_facts = {
                        "phase": "COMMIT",
                        "code_change_intent_sha256": contract["code_change_intent_sha256"],
                        "business_postimage_sha256": contract["business_postimage_sha256"],
                        "installed_file_count": len(contract["files"]),
                        "code_executed_or_imported_before_commit": False,
                    }
                expected_registry = {
                    "schema_version": "c28f_code_change_registry_v1",
                    "goal_id": GOAL_ID,
                    "attempt_id": intent["attempt_id"],
                    "transaction_id": transaction_id,
                    "code_change_id": code_change_id,
                    "status": (
                        "PREPARED_AWAITING_EXACT_APPLY_PATCH_POSTIMAGE"
                        if event["action"] == "PREPARE_REVIEWED_CODE_CHANGE"
                        else (
                            "COMMITTED_USER_AUTHORIZED_ONLINE_EXISTING_FILE_POSTIMAGE"
                            if is_online_direct
                            else "COMMITTED_EXACT_REVIEWED_POSTIMAGE"
                        )
                    ),
                    "code_change_intent_sha256": contract["code_change_intent_sha256"],
                    "business_preimage_sha256": contract["business_preimage_sha256"],
                    "business_postimage_sha256": contract["business_postimage_sha256"],
                    "resume_action": contract["resume_action"],
                    (
                        "code_executed_or_imported"
                        if event["action"] == "PREPARE_REVIEWED_CODE_CHANGE"
                        else "code_executed_or_imported_before_commit"
                    ): is_online_direct,
                }
                if is_online_direct:
                    expected_registry.update(
                        {
                            "review_policy": ONLINE_CODE_CHANGE_REVIEW_POLICY,
                            "user_authorization_sha256": contract[
                                "user_authorization"
                            ]["text_sha256"],
                        }
                    )
                latest_code_registry = registry_bytes
            else:
                expected_mutation_facts = transition_envelope["mutation_facts"]
                expected_registry = transition_envelope["registry_payload"]
                latest_enveloped_registries[current_registry_name] = registry_bytes
            _require(mutation_entry.get("facts") == expected_mutation_facts, f"mutation facts at {seq}")
            _require(registry_payload == expected_registry, f"code registry payload at {seq}")
            expected_files.add(registry_sidecar_name)
        previous_state = state
    _require(set(contracts) == used_code_ids, "orphan or unreferenced code-change intent")
    for code_change_id in sorted(contracts):
        expected_files.add(f"transactions/{code_change_id}/reviewed_code_change_intent.json")
        expected_directories.add(f"transactions/{code_change_id}")
    uncommitted_stage_ids = set(stage_contracts) - used_stage_ids
    _require(len(uncommitted_stage_ids) <= 1, "multiple uncommitted stage PREPARE intents")
    for stage_commit_id, stage_contract in sorted(stage_contracts.items()):
        stage_prefix = f"transactions/{stage_commit_id}"
        expected_directories.add(stage_prefix)
        expected_files.update(
            {
                f"{stage_prefix}/stage_commit_intent.json",
                f"{stage_prefix}/stage_plan.json",
                f"{stage_prefix}/prepare_receipt.json",
            }
        )
        if stage_commit_id not in used_stage_ids:
            _require(
                stage_contract["prepare_receipt"]["parent_state_sha256"]
                == state_records[-1]["state_sha256"]
                and stage_contract["prepare_receipt"]["parent_event_sha256"]
                == events[-1]["event_sha256"],
                "uncommitted stage PREPARE is not bound to the current tail",
            )
            continue
        commit_name = f"{stage_prefix}/commit_receipt.json"
        commit_receipt, _commit_bytes = _read_canonical_json(CONTROL_ROOT / commit_name)
        _require(isinstance(commit_receipt, dict), "stage commit receipt object")
        event = next(item for item in events if item["transaction_id"] == stage_commit_id)
        state = state_records[int(event["seq"])]
        _require(
            commit_receipt == _build_stage_commit_receipt(stage_contract, state, event),
            "stage commit receipt full rebuild",
        )
        expected_files.add(commit_name)
    if latest_code_registry is not None:
        current_registry, _record = read_regular_bytes(
            CONTROL_ROOT / "code_change_registry.json", require_nlink_one=True
        )
        _require(current_registry == latest_code_registry, "current code registry pointer")
        expected_files.add("code_change_registry.json")
    for registry_name, expected_bytes in sorted(latest_enveloped_registries.items()):
        current_registry, _record = read_regular_bytes(
            CONTROL_ROOT / registry_name,
            require_nlink_one=True,
        )
        _require(current_registry == expected_bytes, f"current enveloped registry pointer: {registry_name}")
        expected_files.add(registry_name)
    g2_replay_files, g2_replay_directories = _validate_g2_replay_sessions()
    expected_files.update(g2_replay_files)
    expected_directories.update(g2_replay_directories)
    g6_files, g6_directories = _validate_g6_synthetic_sessions()
    expected_files.update(g6_files)
    expected_directories.update(g6_directories)
    g2_power_files, g2_power_directories = (
        _validate_g2_power_computation_sessions()
    )
    expected_files.update(g2_power_files)
    expected_directories.update(g2_power_directories)
    train_index_files, train_index_directories = (
        _validate_train_jsonl_index_sessions(state_records[-1], events)
    )
    expected_files.update(train_index_files)
    expected_directories.update(train_index_directories)
    authority_files, authority_directories = (
        _validate_controller_forward_authority_records_namespace(
            state_records[-1],
            events,
        )
    )
    expected_files.update(authority_files)
    expected_directories.update(authority_directories)
    rehydrate_files, rehydrate_directories = (
        _validate_completed_forward_rehydrate_sessions(events)
    )
    expected_files.update(rehydrate_files)
    expected_directories.update(rehydrate_directories)
    derivation_files, derivation_directories = (
        _validate_forward_derivation_sessions(events)
    )
    expected_files.update(derivation_files)
    expected_directories.update(derivation_directories)
    expected_files.update(
        _validate_completed_eval_derivation_artifacts(events)
    )
    finalization_snapshot_path = CONTROL_ROOT / "finalization_snapshot.json"
    finalization_snapshot_required = (
        state_records[-1].get("stage") == "G7"
        and state_records[-1].get("status")
        in {
            "FINAL_ARTIFACTS_READY",
            "PENDING_FINALIZATION",
            "FINALIZATION_RECOVERY",
            "TERMINAL_COMMITTED_LEASE_PENDING",
            "F0_F1_WINDOW_COMPLETE_STOPPED",
        }
    )
    _require(
        os.path.lexists(finalization_snapshot_path)
        or not finalization_snapshot_required,
        "G7 prepared/terminal state lost persisted finalization snapshot",
    )
    if os.path.lexists(finalization_snapshot_path):
        finalization_snapshot_record, _snapshot_record_bytes = (
            _read_canonical_json(finalization_snapshot_path)
        )
        _validate_finalization_snapshot_record(
            finalization_snapshot_record,
            events=events,
        )
        expected_files.add("finalization_snapshot.json")
    current_state, current_state_bytes = _read_canonical_json(CONTROL_ROOT / "GOAL_STATE.json")
    _require(current_state == state_records[-1], "current state pointer is not chain tail")
    tail_state_bytes, _record = read_regular_bytes(
        CONTROL_ROOT / f"state_records/{len(events)-1:06d}_{current_state['state_sha256']}.json",
        require_nlink_one=True,
    )
    _require(current_state_bytes == tail_state_bytes, "current state pointer bytes")
    continuation, _record = read_regular_bytes(CONTROL_ROOT / "CONTINUATION.md", require_nlink_one=True)
    _require(continuation == _a4_continuation(current_state, events[-1]), "dynamic continuation pointer")
    return current_state, events, {"event_journal": journal, "mutation_journal": mutation_journal}, expected_files, expected_directories


def verify_a4_state(
    bootstrap_lease: BootstrapLease,
    *,
    active_lease: Optional[WriterLease] = None,
) -> dict[str, Any]:
    """Dynamically verify GENESIS and every committed append-only transition."""

    _assert_a4_import_bytecode_absent()
    bootstrap_lease.assert_active_capability()
    supersession = _validate_supersession_receipt(bootstrap_lease)
    manual_fd: Optional[int] = None
    try:
        if active_lease is None:
            manual_fd, live_lock = _acquire_fixed_writer(CONTROL_ROOT / "single_writer.lock")
        else:
            active_lease.assert_active_capability()
            live_lock = _writer_lock_identity(active_lease.fd, CONTROL_ROOT / "single_writer.lock")  # type: ignore[arg-type]
        intent, _intent_bytes = _validate_a4_intent_file()
        binding = intent["writer_lease"]
        for field in ("device", "inode", "mode", "nlink", "header_sha256"):
            _require(live_lock[field] == binding[field], f"A4 writer binding mismatch: {field}")
        _validate_a4_heartbeat(intent, active_lease=active_lease)
        prepared = _prepare_a4_genesis(intent)
        _assert_a4_roundtrip(intent, prepared)
        contracts = _load_code_change_contracts(attempt_id=intent["attempt_id"])
        current_state, events, _journals, expected_files, expected_directories = (
            _validate_dynamic_control_chain(intent, prepared, contracts)
        )
        current_business = _a4_business_inventory(
            forbidden_identities=_protected_identities_from_a3()
        )
        stage_contracts = _load_stage_contracts(attempt_id=str(intent["attempt_id"]))
        code_change_order = list(
            dict.fromkeys(
                str(event["transaction_id"]).rsplit("-", 1)[0]
                for event in events
                if CODE_CHANGE_TXN_RE.fullmatch(
                    str(event.get("transaction_id"))
                )
                is not None
            )
        )
        reconstructed_bootstrap = _reconstruct_bootstrap_inventory(
            current_business,
            contracts,
            stage_contracts,
            code_change_order,
        )
        _require(
            reconstructed_bootstrap == intent["bootstrap_business_inventory"],
            "dynamic business chain does not reconstruct GENESIS inventory",
        )
        _rebuild_and_validate_a4_intent(
            intent,
            supersession=supersession,
            writer_binding=binding,
            expected_bootstrap_inventory=reconstructed_bootstrap,
        )
        business_phase = "COMMITTED"
        if current_business["business_delta_sha256"] != current_state["expected_goal_delta_sha256"]:
            pending = current_state.get("pending_code_change")
            _require(
                current_state.get("status") == "CODE_CHANGE_PREPARED"
                and isinstance(pending, dict)
                and pending.get("code_change_id") in contracts
                and current_business["business_delta_sha256"]
                == contracts[pending["code_change_id"]]["business_postimage_sha256"],
                "current business is neither committed preimage nor exact prepared postimage",
            )
            business_phase = "PREPARED_POSTIMAGE_INSTALLED"
        for name, expected in prepared["registry_bytes"].items():
            current, _record = read_regular_bytes(CONTROL_ROOT / name, require_nlink_one=True)
            if name == "authority_ledger.json" and current != expected:
                active_authority = json.loads(
                    expected.decode("utf-8", "strict")
                )
                _active, closed_authority = (
                    _finalization_authority_snapshots(
                        source=active_authority,
                        source_file_sha256=bytes_sha256(expected),
                        attempt_id=str(current_state["attempt_id"]),
                        mapping_token_state="COMPLETED_NONREPLAYABLE",
                    )
                )
                _require(
                    current == _canonical_file_bytes(closed_authority)
                    and current_state.get("stage") == "G7"
                    and current_state.get("status")
                    in {
                        "PENDING_FINALIZATION",
                        "FINALIZATION_RECOVERY",
                        "TERMINAL_COMMITTED_LEASE_PENDING",
                        "F0_F1_WINDOW_COMPLETE_STOPPED",
                    },
                    "G7 closed authority pointer drift",
                )
            else:
                _require(
                    current == expected,
                    f"GENESIS registry pointer drift: {name}",
                )
                _require(
                    not (
                        name == "authority_ledger.json"
                        and current_state.get("status")
                        in {
                            "TERMINAL_COMMITTED_LEASE_PENDING",
                            "F0_F1_WINDOW_COMPLETE_STOPPED",
                        }
                    ),
                    "terminal state retained active authority pointer",
                )
            digest = bytes_sha256(expected)
            sidecar, _record = read_regular_bytes(
                CONTROL_ROOT / f"registry_records/000000_{name[:-5]}_{digest}.json",
                require_nlink_one=True,
            )
            _require(sidecar == expected, f"GENESIS registry sidecar drift: {name}")
        artifact_root, _record = read_regular_bytes(
            CONTROL_ROOT / "artifact_manifest.root.sha256", max_bytes=128, require_nlink_one=True
        )
        _require(artifact_root == prepared["artifact_root_bytes"], "artifact root drift")
        artifact_sidecar_name = (
            "registry_records/000000_artifact_manifest_root_"
            f"{bytes_sha256(artifact_root)}.sha256"
        )
        artifact_sidecar, _record = read_regular_bytes(
            CONTROL_ROOT / artifact_sidecar_name, require_nlink_one=True
        )
        _require(artifact_sidecar == artifact_root, "artifact root sidecar drift")
        for ledger in ("access", "evaluation"):
            journal, _record = read_regular_bytes(
                CONTROL_ROOT / f"ledgers/{ledger}_ledger.jsonl", require_nlink_one=True
            )
            _require(journal == prepared["ledger_bytes"][ledger], f"{ledger} ledger drift")
            entry = prepared["ledgers"][ledger]
            sidecar, _record = read_regular_bytes(
                CONTROL_ROOT / f"ledger_records/{ledger}/000000_{entry['entry_sha256']}.jsonl",
                require_nlink_one=True,
            )
            _require(sidecar == journal, f"{ledger} sidecar drift")
        directories, files, _tree_sha = _walk_tree(
            CONTROL_ROOT, opaque_directories={"inbox"}
        )
        _require({item["path"] for item in files} == expected_files, "dynamic authoritative file namespace")
        _require(set(directories) == expected_directories, "dynamic authoritative directory namespace")
        inbox_file_count = _opaque_inbox_file_count()
        bootstrap_lease.assert_active_capability()
        if active_lease is not None:
            active_lease.assert_active_capability()
        return {
            "status": current_state["status"],
            "stage": current_state["stage"],
            "attempt_id": current_state["attempt_id"],
            "next_action": current_state["next_action"],
            "next_action_is_unique": current_state["next_action_is_unique"],
            "state_sha256": current_state["state_sha256"],
            "event_sha256": events[-1]["event_sha256"],
            "event_count": len(events),
            "business_delta_sha256": current_business["business_delta_sha256"],
            "business_phase": business_phase,
            "a3_disposition": supersession["payload"]["disposition"],
            "untrusted_inbox_file_count": inbox_file_count,
            "model_forward_evaluations": int(
                current_state.get("model_forward_evaluations", 0)
            ),
            "protected_content_opens_current_attempt": 0,
            "authorized_mixed_container_index_open_count": int(
                current_state.get(
                    "authorized_mixed_container_index_open_count",
                    0,
                )
            ),
            "authorized_train_desc_selection_key_decode_count": int(
                current_state.get(
                    "authorized_train_desc_selection_key_decode_count",
                    0,
                )
            ),
            "unauthorized_protected_payload_decode_count": int(
                current_state.get(
                    "unauthorized_protected_payload_decode_count",
                    0,
                )
            ),
            "real_data_optimizer_updates": 0,
        }
    finally:
        if manual_fd is not None:
            _release_fixed_writer(manual_fd)


def recover_then_verify_a4_state(
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Recover the authoritative tail under one writer, then verify it.

    This is the sole public recovery gate for the canonical runner.  It does
    not select or execute an action; the runner must compare the requested
    action with the unique ``next_action`` returned after recovery.
    """

    bootstrap_lease.assert_active_capability()
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "RECOVER_THEN_VERIFY_CURRENT_ACTION",
    ) as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        _recover_incomplete_g2_replay_sessions(lease)
        verified = verify_a4_state(
            bootstrap_lease,
            active_lease=lease,
        )
        _require(
            verified.get("next_action_is_unique") is True,
            "recovered state does not expose one unique next action",
        )
        return verified


def _recover_supersession_receipt(bootstrap_lease: BootstrapLease) -> dict[str, Any]:
    bootstrap_lease.assert_active_capability()
    _require(not CONTROL_ROOT.exists(), "receipt recovery requires absent live control root")
    old_writer_fd, _identity = _acquire_fixed_writer(A3_SUPERSEDED_CONTROL / "single_writer.lock")
    try:
        closure = verify_a3_valid_nonextensible_closure(
            A3_SUPERSEDED_CONTROL,
            held_writer_fd=old_writer_fd,
        )
        reviewed_exception = verify_reviewed_drift_exception(
            closure,
            a3_root=A3_SUPERSEDED_CONTROL,
        )
        receipt = _build_supersession_receipt(closure, reviewed_exception)
        bootstrap_lease.assert_active_capability()
        _writer_lock_identity(old_writer_fd, A3_SUPERSEDED_CONTROL / "single_writer.lock")
        _install_capability_file(A3_SUPERSESSION_RECEIPT, _canonical_file_bytes(receipt))
        fsync_directory(REPORT_ROOT)
        fsync_directory(A3_SUPERSEDED_PARENT)
        bootstrap_lease.assert_active_capability()
        _writer_lock_identity(old_writer_fd, A3_SUPERSEDED_CONTROL / "single_writer.lock")
        payload, encoded, receipt_record = _read_bound_canonical_json(
            A3_SUPERSEDED_PARENT,
            "SUPERSESSION_RECEIPT.json",
            max_bytes=4 * 1024 * 1024,
            forbidden_identities=_protected_identities_from_a3(A3_SUPERSEDED_CONTROL),
        )
        _require(payload == receipt, "recovered supersession receipt mismatch")
        carry_forward = _read_a3_carry_forward_locked()
        return {
            "closure": closure,
            "payload": payload,
            "file_sha256": receipt_record["sha256"],
            "size_bytes": len(encoded),
            "carry_forward": carry_forward,
        }
    finally:
        _release_fixed_writer(old_writer_fd)


def initialize_a4(
    producer_argv: Sequence[str],
    producer_raw_argv: Sequence[str],
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Seal A3 if needed, recoverably install A4, and stop before G1."""

    bootstrap_lease.assert_active_capability()
    _validate_producer_argv(producer_argv, producer_raw_argv)
    if CONTROL_ROOT.is_dir() and (CONTROL_ROOT / "g0_bootstrap_intent.json").is_file():
        _require(not A3_SUPERSEDED_CONTROL.exists(), "both live and superseded A3 roots exist")
        supersession = seal_a3_as_valid_nonextensible(bootstrap_lease)
    else:
        _require(A3_SUPERSEDED_CONTROL.is_dir(), "A3 parent is neither live nor superseded")
        if A3_SUPERSESSION_RECEIPT.is_file():
            supersession = _validate_supersession_receipt(bootstrap_lease)
        else:
            _require(not CONTROL_ROOT.exists(), "cannot recover A3 receipt beside a live A4 root")
            supersession = _recover_supersession_receipt(bootstrap_lease)
    bootstrap_lease.assert_active_capability()
    if (
        (CONTROL_ROOT / "a4_bootstrap_intent.json").is_file()
        and (CONTROL_ROOT / "GOAL_STATE.json").is_file()
    ):
        return verify_a4_state(bootstrap_lease)
    lock_path = CONTROL_ROOT / "single_writer.lock"
    heartbeat_path = CONTROL_ROOT / "single_writer.heartbeat.json"
    with WriterLease(
        lock_path,
        heartbeat_path,
        GOAL_ID,
        "G0_A4_EXTENSIBLE_CONTROL_GENESIS",
    ) as lease:
        lease.heartbeat("bind_a4_authorities_and_business_postimage")
        intent = _write_or_load_a4_intent(
            producer_argv,
            producer_raw_argv,
            lease,
            supersession,
        )
        lease.heartbeat("precommit_g1_pristine_write_roots")
        g1_write_root_postimage = _precommit_g1_write_roots(
            intent,
            lease,
            bootstrap_lease,
        )
        current_business = _a4_business_inventory(
            forbidden_identities=_protected_identities_from_a3()
        )
        _require(current_business == intent["bootstrap_business_inventory"], "A4 pre-GENESIS drift")
        prepared = _prepare_a4_genesis(intent)
        _require(
            prepared["plan"]["g1_write_root_directory_postimage"]
            == g1_write_root_postimage,
            "G1 write-root precommit/GENESIS plan drift",
        )
        _assert_a4_roundtrip(intent, prepared)
        lease.heartbeat("install_a4_genesis")
        _install_a4_genesis(intent, prepared, lease, bootstrap_lease)
        lease.heartbeat("verify_a4_genesis")
        return verify_a4_state(bootstrap_lease, active_lease=lease)


def _current_state_and_events() -> tuple[dict[str, Any], bytes, list[dict[str, Any]], bytes]:
    state, state_bytes = _read_canonical_json(CONTROL_ROOT / "GOAL_STATE.json")
    _require(isinstance(state, dict), "current state object required")
    _require(
        state.get("state_sha256") == semantic_sha256(state, excluded_fields=("state_sha256",)),
        "current state semantic hash",
    )
    journal, _record = read_regular_bytes(CONTROL_ROOT / "GOAL_EVENTS.jsonl", require_nlink_one=True)
    events = _validate_semantic_journal(
        journal,
        hash_field="event_sha256",
        previous_field="prev_event_sha256",
    )
    _require(bool(events), "event chain cannot be empty")
    _require(events[-1]["expected_next_state_sha256"] == state["state_sha256"], "event/state tail")
    _require(events[-1]["seq"] == state["transition_seq"], "event/state sequence")
    _require(state.get("next_action_is_unique") is True, "current action must be unique")
    return state, state_bytes, events, journal


def _safe_inbox_file(relative: str) -> Path:
    _require(isinstance(relative, str) and relative == Path(relative).as_posix(), "inbox path canonical")
    candidate = CONTROL_ROOT / "inbox" / relative
    _require(
        Path(relative).parts
        and ".." not in Path(relative).parts
        and "." not in Path(relative).parts
        and not Path(relative).is_absolute(),
        "unsafe inbox path",
    )
    _require(_path_is_within(CONTROL_ROOT / "inbox", candidate), "inbox escape")
    return candidate


def _safe_code_destination(relative: str) -> Path:
    _require(isinstance(relative, str) and relative == Path(relative).as_posix(), "destination canonical")
    _require(".." not in Path(relative).parts and not Path(relative).is_absolute(), "unsafe destination")
    candidate = REPO_ROOT / relative
    allowed = _path_is_within(CODE_ROOT, candidate) or _path_is_within(TEST_ROOT, candidate)
    allowed = allowed or candidate == ENTRYPOINT
    _require(allowed, f"reviewed code destination outside code/test domain: {relative}")
    _require(not _path_is_within(CONTROL_ROOT, candidate), "live control cannot be code destination")
    _assert_safe_path_chain(candidate.parent)
    return candidate


def _inventory_from_entries(entries: Sequence[Mapping[str, Any]]) -> dict[str, Any]:
    ordered = sorted((dict(item) for item in entries), key=lambda item: item["path"])
    _require(len({item["path"] for item in ordered}) == len(ordered), "duplicate inventory path")
    domain = {"schema": "regular-file-content-v2", "entries": ordered}
    return {**domain, "business_delta_sha256": bytes_sha256(canonical_json_bytes(domain))}


def _validate_code_change_review_receipt(
    payload: Any,
    expected_files: Mapping[str, str],
) -> None:
    _require(isinstance(payload, dict), "code-change review receipt object required")
    _require(payload.get("schema_version") == "c28f_reviewed_code_change_receipt_v1", "code review schema")
    _require(payload.get("status") == "STATIC_GO", "code review status")
    _require(payload.get("constraints") == REQUIRED_REVIEW_CONSTRAINTS, "code review constraints")
    _require(payload.get("reviewed_files") == dict(sorted(expected_files.items())), "code review file set")
    author = payload.get("author_task")
    _require(isinstance(author, str) and author.startswith("/root/"), "code review author task")
    reviewed_files_sha256 = bytes_sha256(canonical_json_bytes(dict(sorted(expected_files.items()))))
    _require(payload.get("reviewed_files_sha256") == reviewed_files_sha256, "code review file-map hash")
    receipt_subject = dict(payload)
    receipt_subject.pop("receipt_reviewers", None)
    receipt_subject.pop("receipt_review_subject_sha256", None)
    receipt_review_subject_sha256 = semantic_sha256(receipt_subject)
    _require(
        payload.get("receipt_review_subject_sha256")
        == receipt_review_subject_sha256,
        "code receipt-review subject hash mismatch",
    )
    static_tasks = _validate_review_party(
        payload.get("reviewers"),
        verdict="STATIC_GO",
        label="code reviewers",
        reviewed_files_sha256=reviewed_files_sha256,
    )
    receipt_tasks = _validate_review_party(
        payload.get("receipt_reviewers"),
        verdict="RECEIPT_GO",
        label="code receipt reviewers",
        reviewed_files_sha256=reviewed_files_sha256,
        receipt_review_subject_sha256=receipt_review_subject_sha256,
    )
    _require(author not in static_tasks | receipt_tasks, "code author is a reviewer")
    _require(static_tasks.isdisjoint(receipt_tasks), "code reviewer roles overlap")


def _load_code_change_manifest(manifest_name: str) -> dict[str, Any]:
    _require(MANIFEST_NAME_RE.fullmatch(manifest_name) is not None, "manifest name format")
    _safe_inbox_file(manifest_name)
    manifest, _manifest_bytes, _manifest_record = _read_bound_canonical_json(
        CONTROL_ROOT,
        f"inbox/{manifest_name}",
        max_bytes=4 * 1024 * 1024,
        forbidden_identities=_protected_identities_from_a3(),
    )
    _require(isinstance(manifest, dict), "code-change manifest object required")
    _require(
        manifest.get("schema_version") == "c28f_reviewed_code_change_postimage_v1",
        "code-change manifest schema",
    )
    _require(manifest.get("goal_id") == GOAL_ID, "code-change manifest Goal")
    _require(
        manifest.get("manifest_sha256")
        == semantic_sha256(manifest, excluded_fields=("manifest_sha256",)),
        "code-change manifest semantic hash",
    )
    _require("manifest_file_sha256" not in manifest, "self-referential manifest file hash is forbidden")
    return manifest


def _prepare_code_change_contract(
    manifest_name: str,
    state: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, bytes], dict[str, Any]]:
    manifest = _load_code_change_manifest(manifest_name)
    _require(manifest.get("parent_attempt_id") == state["attempt_id"], "code-change parent attempt")
    _require(manifest.get("parent_state_sha256") == state["state_sha256"], "code-change parent state")
    _require(manifest.get("prepare_action") == state["next_action"], "code-change prepare action")
    _require(manifest.get("commit_action") == "COMMIT_REVIEWED_CODE_CHANGE", "code-change commit action")
    resume_action = manifest.get("resume_action")
    _require(isinstance(resume_action, str) and bool(resume_action), "code-change resume action")
    _require(
        resume_action == manifest["prepare_action"],
        "reviewed code installation must resume the same unique stage action",
    )
    files = manifest.get("files")
    _require(
        isinstance(files, list) and 1 <= len(files) <= MAX_CODE_CHANGE_FILES,
        "code-change file count exceeds cap",
    )
    declared_total = 0
    for item in files:
        _require(isinstance(item, dict), "code-change file record")
        declared_size = item.get("size_bytes")
        _require(
            type(declared_size) is int and 0 < declared_size <= MAX_CODE_CHANGE_FILE_BYTES,
            "code-change per-file byte cap",
        )
        declared_total += declared_size
    _require(declared_total <= MAX_CODE_CHANGE_TOTAL_BYTES, "code-change total byte cap")
    current = _a4_business_inventory(
        forbidden_identities=_protected_identities_from_a3()
    )
    _require(current["business_delta_sha256"] == state["expected_goal_delta_sha256"], "prepare preimage drift")
    records = {item["path"]: dict(item) for item in current["entries"]}
    blobs: dict[str, bytes] = {}
    reviewed_hashes: dict[str, str] = {}
    used_blobs: set[str] = set()
    normalized_files: list[dict[str, Any]] = []
    for item in files:
        _require(isinstance(item, dict), "code-change file record")
        destination = item.get("destination")
        blob_name = item.get("blob")
        _require(isinstance(destination, str) and isinstance(blob_name, str), "code-change paths")
        _safe_code_destination(destination)
        _safe_inbox_file(blob_name)
        _require(blob_name not in used_blobs, "duplicate code-change blob")
        used_blobs.add(blob_name)
        blob, record = _read_bound_regular(
            CONTROL_ROOT,
            f"inbox/{blob_name}",
            max_bytes=MAX_CODE_CHANGE_FILE_BYTES,
            forbidden_identities=_protected_identities_from_a3(),
        )
        _require(record["sha256"] == item.get("sha256"), f"code-change blob hash: {destination}")
        _require(len(blob) == item.get("size_bytes"), f"code-change blob size: {destination}")
        _require(destination not in reviewed_hashes, f"duplicate code-change destination: {destination}")
        operation = item.get("operation")
        _require(
            operation == "ADD",
            f"v1 code-change protocol permits versioned ADD only: {destination}",
        )
        existing = records.get(destination)
        _require(existing is None, f"ADD destination exists: {destination}")
        _require(item.get("expected_preimage_sha256") is None, f"ADD preimage must be null: {destination}")
        records[destination] = {
            "path": destination,
            "type": "regular_file",
            "size_bytes": len(blob),
            "sha256": record["sha256"],
        }
        reviewed_hashes[destination] = record["sha256"]
        blobs[destination] = blob
        normalized_files.append(
            {
                "destination": destination,
                "blob": blob_name,
                "operation": operation,
                "expected_preimage_sha256": item.get("expected_preimage_sha256"),
                "sha256": record["sha256"],
                "size_bytes": len(blob),
            }
        )
    postimage = _inventory_from_entries(list(records.values()))
    _require(
        manifest.get("expected_postimage_business_delta_sha256")
        == postimage["business_delta_sha256"],
        "declared code-change postimage mismatch",
    )
    receipt_name = manifest.get("static_review_receipt_blob")
    _require(isinstance(receipt_name, str), "code-change receipt blob missing")
    _safe_inbox_file(receipt_name)
    review_payload, review_bytes, _review_record = _read_bound_canonical_json(
        CONTROL_ROOT,
        f"inbox/{receipt_name}",
        max_bytes=4 * 1024 * 1024,
        forbidden_identities=_protected_identities_from_a3(),
    )
    _validate_code_change_review_receipt(review_payload, reviewed_hashes)
    _require(
        bytes_sha256(review_bytes) == manifest.get("static_review_receipt_sha256"),
        "code-change review receipt hash",
    )
    contract_base = {
        "schema_version": "c28f_reviewed_code_change_intent_v1",
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "parent_state_sha256": state["state_sha256"],
        "parent_event_sha256": None,
        "prepare_action": manifest["prepare_action"],
        "commit_action": "COMMIT_REVIEWED_CODE_CHANGE",
        "resume_action": resume_action,
        "manifest_name": manifest_name,
        "manifest_sha256": manifest["manifest_sha256"],
        "static_review_receipt_sha256": manifest["static_review_receipt_sha256"],
        "static_review_receipt": review_payload,
        "business_preimage_sha256": current["business_delta_sha256"],
        "business_postimage_sha256": postimage["business_delta_sha256"],
        "files": sorted(normalized_files, key=lambda item: item["destination"]),
        "application_method": "apply_patch installs exact reviewed postimages only after PREPARE commit",
        "code_executed_or_imported_before_commit": False,
    }
    contract = _with_semantic_sha(contract_base, "code_change_intent_sha256")
    transaction_seed = bytes_sha256(canonical_json_bytes(contract))
    contract["code_change_id"] = f"CODE-CHANGE-{transaction_seed[:32]}"
    contract["code_change_intent_sha256"] = semantic_sha256(
        contract,
        excluded_fields=("code_change_intent_sha256",),
    )
    _require(CODE_CHANGE_ID_RE.fullmatch(contract["code_change_id"]) is not None, "code-change ID")
    return contract, blobs, postimage


def _append_mutation_evidence(
    *,
    lease: WriterLease,
    seq: int,
    action: str,
    transaction_id: str,
    attempt_id: str,
    facts: Mapping[str, Any],
) -> tuple[dict[str, Any], bytes]:
    path = CONTROL_ROOT / "ledgers" / "mutation_ledger.jsonl"
    old, old_record = read_regular_bytes(path, require_nlink_one=True)
    records = _validate_semantic_journal(
        old,
        hash_field="entry_sha256",
        previous_field="previous_entry_sha256",
        expected_kind="mutation",
    )
    _require(len(records) in {seq, seq + 1}, "mutation ledger/event sequence mismatch")
    previous_sha = records[seq - 1]["entry_sha256"] if seq else None
    entry = _ledger_entry(
        ledger="mutation",
        action=action,
        attempt_id=attempt_id,
        transaction_id=transaction_id,
        facts=facts,
        seq=seq,
        previous_sha256=previous_sha,
    )
    encoded = canonical_json_bytes(entry) + b"\n"
    if len(records) == seq + 1:
        _require(records[-1] == entry and old.endswith(encoded), "mutation ledger recovery mismatch")
        sidecar, _sidecar_record = read_regular_bytes(
            CONTROL_ROOT / "ledger_records" / "mutation" / f"{seq:06d}_{entry['entry_sha256']}.jsonl",
            require_nlink_one=True,
        )
        _require(sidecar == encoded, "mutation ledger recovery sidecar mismatch")
        return entry, old
    new = old + encoded
    atomic_write_immutable(
        CONTROL_ROOT / "ledger_records" / "mutation" / f"{seq:06d}_{entry['entry_sha256']}.jsonl",
        encoded,
        lease=lease,
    )
    atomic_write_bytes(
        path,
        new,
        lease=lease,
        expected_preimage_sha256=old_record["sha256"],
    )
    return entry, new


def _validate_transition_envelope(
    envelope: Mapping[str, Any],
    *,
    attempt_id: str,
) -> None:
    required = {
        "schema_version",
        "goal_id",
        "attempt_id",
        "transaction_id",
        "action",
        "result",
        "parent_state_sha256",
        "parent_event_sha256",
        "expected_business_sha256",
        "state_updates",
        "registry_name",
        "registry_payload",
        "mutation_facts",
        "input_bindings",
        "safety_counts",
        "transition_intent_sha256",
    }
    _require(set(envelope) == required, "transition envelope field set")
    _require(envelope.get("schema_version") == "c28f_a4_control_transition_intent_v1", "transition envelope schema")
    _require(envelope.get("goal_id") == GOAL_ID and envelope.get("attempt_id") == attempt_id, "transition envelope owner")
    transaction_id = envelope.get("transaction_id")
    _require(
        isinstance(transaction_id, str)
        and (
            STAGE_COMMIT_ID_RE.fullmatch(transaction_id) is not None
            or TRAIN_JSONL_INDEX_TXN_RE.fullmatch(transaction_id) is not None
            or EVAL_TOKEN_TXN_RE.fullmatch(transaction_id) is not None
            or ID_MAPPING_TXN_RE.fullmatch(transaction_id) is not None
            or FINALIZATION_TXN_RE.fullmatch(transaction_id) is not None
        ),
        "transition envelope transaction ID",
    )
    for field in ("parent_state_sha256", "parent_event_sha256", "expected_business_sha256"):
        _require(isinstance(envelope.get(field), str) and HEX64.fullmatch(envelope[field]), f"transition envelope {field}")
    _require(isinstance(envelope.get("action"), str) and envelope["action"], "transition envelope action")
    _require(isinstance(envelope.get("result"), str) and envelope["result"], "transition envelope result")
    state_updates = envelope.get("state_updates")
    _require(isinstance(state_updates, dict) and state_updates, "transition envelope state updates")
    forbidden_updates = {
        "schema_version",
        "goal_id",
        "attempt_id",
        "transaction_id",
        "transition_seq",
        "expected_goal_delta_sha256",
        "updated_at",
        "state_sha256",
    }
    _require(set(state_updates).isdisjoint(forbidden_updates), "transition envelope reserved state field")
    registry_name = envelope.get("registry_name")
    _require(
        isinstance(registry_name, str)
        and re.fullmatch(r"[a-z][a-z0-9_]{0,63}\.json", registry_name) is not None,
        "transition envelope registry name",
    )
    _require(isinstance(envelope.get("registry_payload"), dict), "transition envelope registry payload")
    _require(isinstance(envelope.get("mutation_facts"), dict), "transition envelope mutation facts")
    _require(isinstance(envelope.get("input_bindings"), dict), "transition envelope input bindings")
    _require(
        envelope.get("safety_counts", {}).keys()
        == {
            "protected_content_opens",
            "model_forward_evaluations",
            "real_data_optimizer_updates",
        }
        and all(type(value) is int and value >= 0 for value in envelope["safety_counts"].values()),
        "transition envelope safety counts",
    )
    _require(
        envelope.get("transition_intent_sha256")
        == semantic_sha256(envelope, excluded_fields=("transition_intent_sha256",)),
        "transition envelope semantic hash",
    )


def _project_enveloped_control_transition(
    *,
    state: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    envelope: Mapping[str, Any],
    mutation_journal: bytes,
) -> dict[str, Any]:
    """Purely project the exact CAS postimage used by the writer."""

    _validate_transition_envelope(
        envelope,
        attempt_id=str(state["attempt_id"]),
    )
    _require(
        envelope["parent_state_sha256"] == state["state_sha256"]
        and envelope["parent_event_sha256"] == events[-1]["event_sha256"],
        "projected envelope parent",
    )
    transaction_id = str(envelope["transaction_id"])
    seq = len(events)
    _require(
        seq == int(state["transition_seq"]) + 1,
        "projected envelope sequence",
    )
    mutation_records = _validate_semantic_journal(
        mutation_journal,
        hash_field="entry_sha256",
        previous_field="previous_entry_sha256",
        expected_kind="mutation",
    )
    _require(
        len(mutation_records) in {seq, seq + 1},
        "projected mutation/event sequence",
    )
    previous_sha = mutation_records[seq - 1]["entry_sha256"] if seq else None
    mutation_entry = _ledger_entry(
        ledger="mutation",
        action=str(envelope["action"]),
        attempt_id=str(state["attempt_id"]),
        transaction_id=transaction_id,
        facts=dict(envelope["mutation_facts"]),
        seq=seq,
        previous_sha256=previous_sha,
    )
    mutation_line = canonical_json_bytes(mutation_entry) + b"\n"
    if len(mutation_records) == seq:
        projected_mutation_journal = mutation_journal + mutation_line
    else:
        _require(
            mutation_records[-1] == mutation_entry
            and mutation_journal.endswith(mutation_line),
            "projected mutation recovery entry",
        )
        projected_mutation_journal = mutation_journal
    registry_name = str(envelope["registry_name"])
    registry_bytes = _canonical_file_bytes(envelope["registry_payload"])
    state_base = dict(state)
    state_base.pop("state_sha256", None)
    state_base.update(dict(envelope["state_updates"]))
    state_base.update(
        {
            "transaction_id": transaction_id,
            "transition_seq": seq,
            "next_action_is_unique": True,
            "expected_goal_delta_sha256": envelope[
                "expected_business_sha256"
            ],
            "updated_at": f"control-seq:{seq}",
        }
    )
    next_state = _with_semantic_sha(state_base, "state_sha256")
    next_state_bytes = _canonical_file_bytes(next_state)
    plan_base = {
        "schema_version": "c28f_append_only_transaction_plan_v1",
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "seq": seq,
        "action": envelope["action"],
        "parent_state_sha256": state["state_sha256"],
        "parent_event_sha256": events[-1]["event_sha256"],
        "expected_state_sha256": next_state["state_sha256"],
        "expected_business_postimage_sha256": envelope[
            "expected_business_sha256"
        ],
        "registry_output_hashes": {
            registry_name: bytes_sha256(registry_bytes)
        },
        "ledger_output_hashes": {
            "ledgers/mutation_ledger.jsonl": bytes_sha256(
                projected_mutation_journal
            )
        },
        "transition_intent_sha256": envelope[
            "transition_intent_sha256"
        ],
        "state_pointer_is_last_commit_marker": True,
    }
    plan = _with_semantic_sha(plan_base, "plan_sha256")
    plan_bytes = _canonical_file_bytes(plan)
    event_base = {
        "schema_version": "c28f_goal_event_v2",
        "seq": seq,
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "action": envelope["action"],
        "result": envelope["result"],
        "prev_event_sha256": events[-1]["event_sha256"],
        "expected_next_state_sha256": next_state["state_sha256"],
        "expected_goal_delta_sha256": envelope[
            "expected_business_sha256"
        ],
        "next_action": next_state["next_action"],
        "input_hashes": {
            "parent_state": state["state_sha256"],
            "transaction_plan_file": bytes_sha256(plan_bytes),
            "transition_intent": envelope["transition_intent_sha256"],
            **dict(envelope["input_bindings"]),
        },
        "output_hashes": {
            registry_name: bytes_sha256(registry_bytes),
            "ledgers/mutation_ledger.jsonl": bytes_sha256(
                projected_mutation_journal
            ),
        },
        "safety_counts": dict(envelope["safety_counts"]),
    }
    event = _with_semantic_sha(event_base, "event_sha256")
    return {
        "state": next_state,
        "state_bytes": next_state_bytes,
        "event": event,
        "event_bytes": canonical_json_bytes(event) + b"\n",
        "plan": plan,
        "plan_bytes": plan_bytes,
        "registry_name": registry_name,
        "registry_bytes": registry_bytes,
        "mutation_entry": mutation_entry,
        "mutation_journal": projected_mutation_journal,
    }


def _commit_enveloped_control_transition(
    *,
    lease: WriterLease,
    bootstrap_lease: BootstrapLease,
    state: Mapping[str, Any],
    state_bytes: bytes,
    events: Sequence[Mapping[str, Any]],
    event_journal: bytes,
    envelope: Mapping[str, Any],
) -> dict[str, Any]:
    """Commit one immutable transition envelope with GOAL_STATE as the last marker."""

    _validate_transition_envelope(envelope, attempt_id=str(state["attempt_id"]))
    _require(envelope["parent_state_sha256"] == state["state_sha256"], "envelope parent state")
    _require(envelope["parent_event_sha256"] == events[-1]["event_sha256"], "envelope parent event")
    transaction_id = str(envelope["transaction_id"])
    seq = len(events)
    _require(seq == int(state["transition_seq"]) + 1, "envelope transition sequence")
    registry_name = str(envelope["registry_name"])
    registry_payload = dict(envelope["registry_payload"])
    registry_bytes = _canonical_file_bytes(registry_payload)
    registry_path = CONTROL_ROOT / registry_name
    if os.path.lexists(registry_path):
        _old_registry, old_registry_record = read_regular_bytes(
            registry_path,
            require_nlink_one=True,
        )
        registry_precondition: dict[str, Any] = {
            "expected_preimage_sha256": old_registry_record["sha256"]
        }
    else:
        registry_precondition = {"precondition": "MUST_BE_ABSENT"}
    mutation_entry, mutation_journal = _append_mutation_evidence(
        lease=lease,
        seq=seq,
        action=str(envelope["action"]),
        transaction_id=transaction_id,
        attempt_id=str(state["attempt_id"]),
        facts=dict(envelope["mutation_facts"]),
    )
    state_base = dict(state)
    state_base.pop("state_sha256", None)
    state_base.update(dict(envelope["state_updates"]))
    state_base.update(
        {
            "transaction_id": transaction_id,
            "transition_seq": seq,
            "next_action_is_unique": True,
            "expected_goal_delta_sha256": envelope["expected_business_sha256"],
            "updated_at": f"control-seq:{seq}",
        }
    )
    next_state = _with_semantic_sha(state_base, "state_sha256")
    next_state_bytes = _canonical_file_bytes(next_state)
    plan_base = {
        "schema_version": "c28f_append_only_transaction_plan_v1",
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "seq": seq,
        "action": envelope["action"],
        "parent_state_sha256": state["state_sha256"],
        "parent_event_sha256": events[-1]["event_sha256"],
        "expected_state_sha256": next_state["state_sha256"],
        "expected_business_postimage_sha256": envelope["expected_business_sha256"],
        "registry_output_hashes": {registry_name: bytes_sha256(registry_bytes)},
        "ledger_output_hashes": {
            "ledgers/mutation_ledger.jsonl": bytes_sha256(mutation_journal)
        },
        "transition_intent_sha256": envelope["transition_intent_sha256"],
        "state_pointer_is_last_commit_marker": True,
    }
    plan = _with_semantic_sha(plan_base, "plan_sha256")
    plan_bytes = _canonical_file_bytes(plan)
    event_base = {
        "schema_version": "c28f_goal_event_v2",
        "seq": seq,
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "action": envelope["action"],
        "result": envelope["result"],
        "prev_event_sha256": events[-1]["event_sha256"],
        "expected_next_state_sha256": next_state["state_sha256"],
        "expected_goal_delta_sha256": envelope["expected_business_sha256"],
        "next_action": next_state["next_action"],
        "input_hashes": {
            "parent_state": state["state_sha256"],
            "transaction_plan_file": bytes_sha256(plan_bytes),
            "transition_intent": envelope["transition_intent_sha256"],
            **dict(envelope["input_bindings"]),
        },
        "output_hashes": {
            registry_name: bytes_sha256(registry_bytes),
            "ledgers/mutation_ledger.jsonl": bytes_sha256(mutation_journal),
        },
        "safety_counts": dict(envelope["safety_counts"]),
    }
    event = _with_semantic_sha(event_base, "event_sha256")
    event_bytes = canonical_json_bytes(event) + b"\n"
    projection = _project_enveloped_control_transition(
        state=state,
        events=events,
        envelope=envelope,
        mutation_journal=mutation_journal,
    )
    _require(
        projection["state"] == next_state
        and projection["state_bytes"] == next_state_bytes
        and projection["event"] == event
        and projection["event_bytes"] == event_bytes
        and projection["plan"] == plan
        and projection["plan_bytes"] == plan_bytes
        and projection["registry_name"] == registry_name
        and projection["registry_bytes"] == registry_bytes
        and projection["mutation_entry"] == mutation_entry
        and projection["mutation_journal"] == mutation_journal,
        "writer CAS differs from precommit transition projection",
    )
    atomic_write_immutable(
        CONTROL_ROOT / "transactions" / transaction_id / "plan.json",
        plan_bytes,
        lease=lease,
    )
    registry_digest = bytes_sha256(registry_bytes)
    atomic_write_immutable(
        CONTROL_ROOT
        / "registry_records"
        / f"{seq:06d}_{registry_name[:-5]}_{registry_digest}.json",
        registry_bytes,
        lease=lease,
    )
    atomic_write_bytes(registry_path, registry_bytes, lease=lease, **registry_precondition)
    atomic_write_immutable(
        CONTROL_ROOT / "state_records" / f"{seq:06d}_{next_state['state_sha256']}.json",
        next_state_bytes,
        lease=lease,
    )
    atomic_write_immutable(
        CONTROL_ROOT / "event_records" / f"{seq:06d}_{event['event_sha256']}.jsonl",
        event_bytes,
        lease=lease,
    )
    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    atomic_write_bytes(
        CONTROL_ROOT / "GOAL_EVENTS.jsonl",
        event_journal + event_bytes,
        lease=lease,
        expected_preimage_sha256=bytes_sha256(event_journal),
    )
    old_continuation, continuation_record = read_regular_bytes(
        CONTROL_ROOT / "CONTINUATION.md",
        require_nlink_one=True,
    )
    _require(bool(old_continuation), "current continuation cannot be empty")
    atomic_write_bytes(
        CONTROL_ROOT / "CONTINUATION.md",
        _a4_continuation(next_state, event),
        lease=lease,
        expected_preimage_sha256=continuation_record["sha256"],
    )
    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    atomic_write_bytes(
        CONTROL_ROOT / "GOAL_STATE.json",
        next_state_bytes,
        lease=lease,
        expected_preimage_sha256=bytes_sha256(state_bytes),
    )
    return {
        "state": next_state,
        "event": event,
        "mutation_entry": mutation_entry,
        "plan": plan,
        "registry_bytes": registry_bytes,
    }


def _recover_enveloped_state_pointer(
    *,
    lease: WriterLease,
    bootstrap_lease: BootstrapLease,
    state: Mapping[str, Any],
    state_bytes: bytes,
    events: Sequence[Mapping[str, Any]],
    pending: Mapping[str, Any],
) -> None:
    """Rebuild a stage/eval transition completely before advancing GOAL_STATE."""

    transaction_id = str(pending["transaction_id"])
    envelope, envelope_bytes = _read_canonical_json(
        CONTROL_ROOT / "transactions" / transaction_id / "transition_intent.json"
    )
    _require(isinstance(envelope, dict), "pending transition envelope object")
    _validate_transition_envelope(envelope, attempt_id=str(state["attempt_id"]))
    _require(envelope["transaction_id"] == transaction_id, "pending envelope transaction")
    _require(envelope["parent_state_sha256"] == state["state_sha256"], "pending envelope parent state")
    _require(envelope["parent_event_sha256"] == events[-2]["event_sha256"], "pending envelope parent event")
    _require(bytes_sha256(envelope_bytes) != "", "pending envelope file hash")
    seq = int(pending["seq"])
    mutation_journal, _record = read_regular_bytes(
        CONTROL_ROOT / "ledgers/mutation_ledger.jsonl",
        require_nlink_one=True,
    )
    mutation_records = _validate_semantic_journal(
        mutation_journal,
        hash_field="entry_sha256",
        previous_field="previous_entry_sha256",
        expected_kind="mutation",
    )
    _require(len(mutation_records) == len(events), "pending envelope mutation cardinality")
    mutation_entry = mutation_records[-1]
    _require(
        mutation_entry["transaction_id"] == transaction_id
        and mutation_entry["action"] == envelope["action"]
        and mutation_entry["facts"] == envelope["mutation_facts"],
        "pending envelope mutation binding",
    )
    mutation_line = canonical_json_bytes(mutation_entry) + b"\n"
    mutation_sidecar, _record = read_regular_bytes(
        CONTROL_ROOT
        / "ledger_records"
        / "mutation"
        / f"{seq:06d}_{mutation_entry['entry_sha256']}.jsonl",
        require_nlink_one=True,
    )
    _require(mutation_sidecar == mutation_line, "pending envelope mutation sidecar")
    registry_name = str(envelope["registry_name"])
    registry_bytes = _canonical_file_bytes(envelope["registry_payload"])
    registry_sha = bytes_sha256(registry_bytes)
    current_registry, _record = read_regular_bytes(
        CONTROL_ROOT / registry_name,
        require_nlink_one=True,
    )
    _require(current_registry == registry_bytes, "pending envelope registry pointer")
    registry_sidecar, _record = read_regular_bytes(
        CONTROL_ROOT
        / "registry_records"
        / f"{seq:06d}_{registry_name[:-5]}_{registry_sha}.json",
        require_nlink_one=True,
    )
    _require(registry_sidecar == registry_bytes, "pending envelope registry sidecar")
    expected_state_base = dict(state)
    expected_state_base.pop("state_sha256", None)
    expected_state_base.update(dict(envelope["state_updates"]))
    expected_state_base.update(
        {
            "transaction_id": transaction_id,
            "transition_seq": seq,
            "next_action_is_unique": True,
            "expected_goal_delta_sha256": envelope["expected_business_sha256"],
            "updated_at": f"control-seq:{seq}",
        }
    )
    next_state = _with_semantic_sha(expected_state_base, "state_sha256")
    next_state_bytes = _canonical_file_bytes(next_state)
    stored_state, stored_state_bytes = _read_canonical_json(
        CONTROL_ROOT / "state_records" / f"{seq:06d}_{next_state['state_sha256']}.json"
    )
    _require(stored_state == next_state and stored_state_bytes == next_state_bytes, "pending envelope state")
    plan_base = {
        "schema_version": "c28f_append_only_transaction_plan_v1",
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "seq": seq,
        "action": envelope["action"],
        "parent_state_sha256": state["state_sha256"],
        "parent_event_sha256": events[-2]["event_sha256"],
        "expected_state_sha256": next_state["state_sha256"],
        "expected_business_postimage_sha256": envelope["expected_business_sha256"],
        "registry_output_hashes": {registry_name: registry_sha},
        "ledger_output_hashes": {
            "ledgers/mutation_ledger.jsonl": bytes_sha256(mutation_journal)
        },
        "transition_intent_sha256": envelope["transition_intent_sha256"],
        "state_pointer_is_last_commit_marker": True,
    }
    expected_plan = _with_semantic_sha(plan_base, "plan_sha256")
    expected_plan_bytes = _canonical_file_bytes(expected_plan)
    plan, plan_bytes = _read_canonical_json(
        CONTROL_ROOT / "transactions" / transaction_id / "plan.json"
    )
    _require(plan == expected_plan and plan_bytes == expected_plan_bytes, "pending envelope plan")
    event_base = {
        "schema_version": "c28f_goal_event_v2",
        "seq": seq,
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "action": envelope["action"],
        "result": envelope["result"],
        "prev_event_sha256": events[-2]["event_sha256"],
        "expected_next_state_sha256": next_state["state_sha256"],
        "expected_goal_delta_sha256": envelope["expected_business_sha256"],
        "next_action": next_state["next_action"],
        "input_hashes": {
            "parent_state": state["state_sha256"],
            "transaction_plan_file": bytes_sha256(expected_plan_bytes),
            "transition_intent": envelope["transition_intent_sha256"],
            **dict(envelope["input_bindings"]),
        },
        "output_hashes": {
            registry_name: registry_sha,
            "ledgers/mutation_ledger.jsonl": bytes_sha256(mutation_journal),
        },
        "safety_counts": dict(envelope["safety_counts"]),
    }
    expected_event = _with_semantic_sha(event_base, "event_sha256")
    _require(dict(pending) == expected_event, "pending envelope event full rebuild")
    event_sidecar, _record = read_regular_bytes(
        CONTROL_ROOT / "event_records" / f"{seq:06d}_{expected_event['event_sha256']}.jsonl",
        require_nlink_one=True,
    )
    _require(event_sidecar == canonical_json_bytes(expected_event) + b"\n", "pending envelope event sidecar")
    current_business = _a4_business_inventory(
        forbidden_identities=_protected_identities_from_a3()
    )
    _require(
        current_business["business_delta_sha256"] == envelope["expected_business_sha256"],
        "pending envelope business postimage",
    )
    current_continuation, continuation_record = read_regular_bytes(
        CONTROL_ROOT / "CONTINUATION.md",
        require_nlink_one=True,
    )
    continuation = _a4_continuation(next_state, expected_event)
    if current_continuation != continuation:
        _assert_dual_live_capability(bootstrap_lease, lease)
        atomic_write_bytes(
            CONTROL_ROOT / "CONTINUATION.md",
            continuation,
            lease=lease,
            expected_preimage_sha256=continuation_record["sha256"],
        )
    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    atomic_write_bytes(
        CONTROL_ROOT / "GOAL_STATE.json",
        next_state_bytes,
        lease=lease,
        expected_preimage_sha256=bytes_sha256(state_bytes),
    )
    if STAGE_COMMIT_ID_RE.fullmatch(transaction_id) is not None:
        stage_contract, _encoded = _read_canonical_json(
            CONTROL_ROOT / "transactions" / transaction_id / "stage_commit_intent.json"
        )
        _require(isinstance(stage_contract, dict), "recovery stage contract")
        _validate_stage_commit_intent(
            stage_contract,
            attempt_id=str(next_state["attempt_id"]),
        )
        atomic_write_immutable(
            CONTROL_ROOT / "transactions" / transaction_id / "commit_receipt.json",
            _canonical_file_bytes(
                _build_stage_commit_receipt(stage_contract, next_state, expected_event)
            ),
            lease=lease,
        )
    elif TRAIN_JSONL_INDEX_TXN_RE.fullmatch(transaction_id) is not None:
        claim, index, receipt = _load_train_jsonl_index_session(
            CONTROL_ROOT / "transactions" / transaction_id
        )
        _validate_train_jsonl_index_registry(
            envelope["registry_payload"],
            claim=claim,
            index=index,
            receipt=receipt,
        )
    elif EVAL_TOKEN_TXN_RE.fullmatch(transaction_id) is not None:
        eval_registry = envelope["registry_payload"]
        eval_receipt = _build_eval_phase_receipt(
            eval_registry,
            next_state,
            expected_event,
        )
        receipt_name = (
            "cas_receipt.json"
            if eval_registry["token_state"] == "RESERVED"
            else "phase_receipt.json"
        )
        atomic_write_immutable(
            CONTROL_ROOT / "transactions" / transaction_id / receipt_name,
            _canonical_file_bytes(eval_receipt),
            lease=lease,
        )
    elif ID_MAPPING_TXN_RE.fullmatch(transaction_id) is not None:
        mapping_registry = envelope["registry_payload"]
        if mapping_registry["phase"] == "ACCESS":
            mapping_receipt = _build_id_mapping_access_receipt(
                mapping_registry,
                next_state,
                expected_event,
            )
            receipt_name = "access_receipt.json"
        else:
            mapping_receipt = _build_id_mapping_phase_receipt(
                mapping_registry,
                next_state,
                expected_event,
            )
            receipt_name = "phase_receipt.json"
        atomic_write_immutable(
            CONTROL_ROOT / "transactions" / transaction_id / receipt_name,
            _canonical_file_bytes(mapping_receipt),
            lease=lease,
        )
    elif FINALIZATION_TXN_RE.fullmatch(transaction_id) is not None:
        final_registry = envelope["registry_payload"]
        final_receipt = _build_finalization_phase_receipt(
            final_registry,
            next_state,
            expected_event,
        )
        receipt_name = (
            "prepare_receipt.json"
            if final_registry["phase"] == "PREPARE"
            else "terminal_receipt.json"
        )
        atomic_write_immutable(
            CONTROL_ROOT / "transactions" / transaction_id / receipt_name,
            _canonical_file_bytes(final_receipt),
            lease=lease,
        )
    verify_a4_state(bootstrap_lease, active_lease=lease)


def _recover_pending_state_pointer(
    lease: WriterLease,
    bootstrap_lease: BootstrapLease,
) -> None:
    """Finish the last fsynced event when a crash preceded the state commit marker."""

    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    state, state_bytes = _read_canonical_json(CONTROL_ROOT / "GOAL_STATE.json")
    _require(
        state.get("state_sha256") == semantic_sha256(state, excluded_fields=("state_sha256",)),
        "recovery parent state semantic hash",
    )
    journal, _record = read_regular_bytes(CONTROL_ROOT / "GOAL_EVENTS.jsonl", require_nlink_one=True)
    events = _validate_semantic_journal(
        journal,
        hash_field="event_sha256",
        previous_field="prev_event_sha256",
    )
    committed_count = int(state["transition_seq"]) + 1
    _require(len(events) in {committed_count, committed_count + 1}, "unrecoverable event/state distance")
    if len(events) == committed_count:
        _require(events[-1]["expected_next_state_sha256"] == state["state_sha256"], "state/event tail")
        current_transaction_id = str(events[-1]["transaction_id"])
        if any(
            pattern.fullmatch(current_transaction_id) is not None
            for pattern in (
                STAGE_COMMIT_ID_RE,
                EVAL_TOKEN_TXN_RE,
                ID_MAPPING_TXN_RE,
                FINALIZATION_TXN_RE,
            )
        ):
            envelope, _envelope_bytes = _read_canonical_json(
                CONTROL_ROOT
                / "transactions"
                / current_transaction_id
                / "transition_intent.json"
            )
            _require(
                isinstance(envelope, dict)
                and envelope.get("transaction_id")
                == current_transaction_id,
                "current enveloped receipt recovery envelope",
            )
            if STAGE_COMMIT_ID_RE.fullmatch(current_transaction_id):
                stage_contract, _stage_contract_bytes = _read_canonical_json(
                    CONTROL_ROOT
                    / "transactions"
                    / current_transaction_id
                    / "stage_commit_intent.json"
                )
                _validate_stage_commit_intent(
                    stage_contract,
                    attempt_id=str(state["attempt_id"]),
                )
                tail_receipt = _build_stage_commit_receipt(
                    stage_contract,
                    state,
                    events[-1],
                )
                receipt_name = "commit_receipt.json"
            elif EVAL_TOKEN_TXN_RE.fullmatch(current_transaction_id):
                eval_registry = envelope.get("registry_payload")
                _require(
                    isinstance(eval_registry, dict)
                    and eval_registry.get("transaction_id")
                    == current_transaction_id,
                    "current eval receipt recovery registry",
                )
                tail_receipt = _build_eval_phase_receipt(
                    eval_registry,
                    state,
                    events[-1],
                )
                receipt_name = (
                    "cas_receipt.json"
                    if eval_registry.get("token_state") == "RESERVED"
                    else "phase_receipt.json"
                )
            elif ID_MAPPING_TXN_RE.fullmatch(current_transaction_id):
                mapping_registry = envelope.get("registry_payload")
                _require(
                    isinstance(mapping_registry, dict)
                    and mapping_registry.get("transaction_id")
                    == current_transaction_id,
                    "current G4 receipt recovery registry",
                )
                if mapping_registry.get("phase") == "ACCESS":
                    tail_receipt = _build_id_mapping_access_receipt(
                        mapping_registry,
                        state,
                        events[-1],
                    )
                    receipt_name = "access_receipt.json"
                else:
                    tail_receipt = _build_id_mapping_phase_receipt(
                        mapping_registry,
                        state,
                        events[-1],
                    )
                    receipt_name = "phase_receipt.json"
            else:
                final_registry = envelope.get("registry_payload")
                _require(
                    isinstance(final_registry, dict)
                    and final_registry.get("transaction_id")
                    == current_transaction_id,
                    "current finalization receipt recovery registry",
                )
                tail_receipt = _build_finalization_phase_receipt(
                    final_registry,
                    state,
                    events[-1],
                )
                receipt_name = (
                    "prepare_receipt.json"
                    if final_registry.get("phase") == "PREPARE"
                    else "terminal_receipt.json"
                )
            atomic_write_immutable(
                CONTROL_ROOT
                / "transactions"
                / current_transaction_id
                / receipt_name,
                _canonical_file_bytes(tail_receipt),
                lease=lease,
            )
        return
    pending = events[-1]
    _require(
        pending.get("input_hashes", {}).get("parent_state") == state["state_sha256"],
        "pending event parent state mismatch",
    )
    seq = pending["seq"]
    event_sidecar, _event_record = read_regular_bytes(
        CONTROL_ROOT / "event_records" / f"{seq:06d}_{pending['event_sha256']}.jsonl",
        require_nlink_one=True,
    )
    _require(event_sidecar == canonical_json_bytes(pending) + b"\n", "pending event sidecar")
    transaction_id = pending["transaction_id"]
    if (
        isinstance(transaction_id, str)
        and (
                STAGE_COMMIT_ID_RE.fullmatch(transaction_id) is not None
                or TRAIN_JSONL_INDEX_TXN_RE.fullmatch(transaction_id)
                is not None
                or EVAL_TOKEN_TXN_RE.fullmatch(transaction_id) is not None
            or ID_MAPPING_TXN_RE.fullmatch(transaction_id) is not None
            or FINALIZATION_TXN_RE.fullmatch(transaction_id) is not None
        )
    ):
        _recover_enveloped_state_pointer(
            lease=lease,
            bootstrap_lease=bootstrap_lease,
            state=state,
            state_bytes=state_bytes,
            events=events,
            pending=pending,
        )
        return
    _require(CODE_CHANGE_TXN_RE.fullmatch(transaction_id) is not None, "pending transaction ID")
    plan, plan_bytes = _read_canonical_json(
        CONTROL_ROOT / "transactions" / transaction_id / "plan.json"
    )
    _require(
        bytes_sha256(plan_bytes) == pending["input_hashes"]["transaction_plan_file"],
        "pending transaction plan binding",
    )
    _require(
        plan.get("plan_sha256") == semantic_sha256(plan, excluded_fields=("plan_sha256",))
        and plan.get("transaction_id") == transaction_id
        and plan.get("seq") == seq
        and plan.get("action") == pending["action"]
        and plan.get("parent_state_sha256") == state["state_sha256"]
        and plan.get("parent_event_sha256") == events[-2]["event_sha256"]
        and plan.get("expected_state_sha256") == pending["expected_next_state_sha256"],
        "pending transaction plan semantics",
    )
    for relative, expected_sha in pending.get("output_hashes", {}).items():
        _require(
            relative in {"code_change_registry.json", "ledgers/mutation_ledger.jsonl"},
            f"unexpected pending output: {relative}",
        )
        output, output_record = read_regular_bytes(CONTROL_ROOT / relative, require_nlink_one=True)
        _require(bool(output) and output_record["sha256"] == expected_sha, f"pending output: {relative}")
        if relative == "code_change_registry.json":
            sidecar, _sidecar_record = read_regular_bytes(
                CONTROL_ROOT
                / "registry_records"
                / f"{seq:06d}_code_change_registry_{expected_sha}.json",
                require_nlink_one=True,
            )
            _require(sidecar == output, "pending code registry sidecar")
        else:
            mutation_records = _validate_semantic_journal(
                output,
                hash_field="entry_sha256",
                previous_field="previous_entry_sha256",
                expected_kind="mutation",
            )
            _require(len(mutation_records) == len(events), "pending mutation ledger length")
            mutation_sidecar, _sidecar_record = read_regular_bytes(
                CONTROL_ROOT
                / "ledger_records"
                / "mutation"
                / f"{seq:06d}_{mutation_records[-1]['entry_sha256']}.jsonl",
                require_nlink_one=True,
            )
            _require(
                mutation_sidecar == canonical_json_bytes(mutation_records[-1]) + b"\n",
                "pending mutation sidecar",
            )
    next_state, next_state_bytes = _read_canonical_json(
        CONTROL_ROOT / "state_records" / f"{seq:06d}_{pending['expected_next_state_sha256']}.json"
    )
    _require(
        next_state.get("state_sha256") == pending["expected_next_state_sha256"]
        and next_state.get("state_sha256")
        == semantic_sha256(next_state, excluded_fields=("state_sha256",)),
        "pending state identity",
    )
    _require(next_state.get("transition_seq") == seq, "pending state sequence")
    _require(next_state.get("next_action") == pending["next_action"], "pending next action")
    code_change_id = transaction_id.rsplit("-", 1)[0]
    contract, _contract_bytes = _read_canonical_json(
        CONTROL_ROOT / "transactions" / code_change_id / "reviewed_code_change_intent.json"
    )
    _require(isinstance(contract, dict), "pending code intent object")
    _validate_code_change_contract_payload(contract, attempt_id=state["attempt_id"])
    _require(contract["code_change_id"] == code_change_id, "pending code intent ID")
    _require(
        pending["input_hashes"].get("code_change_intent")
        == contract["code_change_intent_sha256"]
        == plan.get("code_change_intent_sha256"),
        "pending code intent bindings",
    )
    action = pending["action"]
    _require(
        action in {"PREPARE_REVIEWED_CODE_CHANGE", "COMMIT_REVIEWED_CODE_CHANGE"},
        "pending action",
    )
    if action == "PREPARE_REVIEWED_CODE_CHANGE":
        expected_pending: Optional[dict[str, Any]] = {
            "code_change_id": code_change_id,
            "prepare_transaction_id": transaction_id,
            "code_change_intent_sha256": contract["code_change_intent_sha256"],
            "business_postimage_sha256": contract["business_postimage_sha256"],
            "resume_action": contract["resume_action"],
        }
        expected_status = "CODE_CHANGE_PREPARED"
        expected_next = "COMMIT_REVIEWED_CODE_CHANGE"
        expected_business = contract["business_preimage_sha256"]
    else:
        expected_pending = None
        expected_status = (
            str(contract.get("resume_status", "PREFLIGHT_OK"))
            if contract.get("schema_version")
            == "c28f_user_authorized_online_code_change_v1"
            else "PREFLIGHT_OK"
        )
        expected_next = contract["resume_action"]
        expected_business = contract["business_postimage_sha256"]
    expected_state_base = dict(state)
    expected_state_base.pop("state_sha256", None)
    expected_state_base.update(
        {
            "transaction_id": transaction_id,
            "transition_seq": seq,
            "status": expected_status,
            "next_action": expected_next,
            "next_action_is_unique": True,
            "expected_goal_delta_sha256": expected_business,
            "pending_code_change": expected_pending,
            "updated_at": f"control-seq:{seq}",
        }
    )
    _require(
        next_state == _with_semantic_sha(expected_state_base, "state_sha256"),
        "pending state differs from deterministic rebuild",
    )
    _require(
        plan.get("expected_business_postimage_sha256") == expected_business
        and pending["expected_goal_delta_sha256"] == expected_business,
        "pending business declaration",
    )
    current_business = _a4_business_inventory(
        forbidden_identities=_protected_identities_from_a3()
    )
    _require(
        current_business["business_delta_sha256"] == expected_business,
        "pending recovery business postimage mismatch",
    )
    continuation = _a4_continuation(next_state, pending)
    current_continuation, continuation_record = read_regular_bytes(
        CONTROL_ROOT / "CONTINUATION.md", require_nlink_one=True
    )
    if current_continuation != continuation:
        _assert_dual_live_capability(bootstrap_lease, lease)
        atomic_write_bytes(
            CONTROL_ROOT / "CONTINUATION.md",
            continuation,
            lease=lease,
            expected_preimage_sha256=continuation_record["sha256"],
        )
    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    atomic_write_bytes(
        CONTROL_ROOT / "GOAL_STATE.json",
        next_state_bytes,
        lease=lease,
        expected_preimage_sha256=bytes_sha256(state_bytes),
    )
    verify_a4_state(bootstrap_lease, active_lease=lease)


def _commit_code_control_transition(
    *,
    lease: WriterLease,
    bootstrap_lease: BootstrapLease,
    state: Mapping[str, Any],
    state_bytes: bytes,
    events: Sequence[Mapping[str, Any]],
    event_journal: bytes,
    transaction_id: str,
    action: str,
    result: str,
    next_action: str,
    status: str,
    expected_business_sha256: str,
    pending_code_change: Optional[Mapping[str, Any]],
    registry_payload: Mapping[str, Any],
    mutation_facts: Mapping[str, Any],
) -> dict[str, Any]:
    seq = len(events)
    registry_bytes = _canonical_file_bytes(registry_payload)
    registry_name = "code_change_registry.json"
    registry_path = CONTROL_ROOT / registry_name
    if registry_path.exists():
        _old_registry, old_registry_record = read_regular_bytes(registry_path, require_nlink_one=True)
        registry_precondition: dict[str, Any] = {
            "expected_preimage_sha256": old_registry_record["sha256"]
        }
    else:
        registry_precondition = {"precondition": "MUST_BE_ABSENT"}
    mutation_entry, mutation_journal = _append_mutation_evidence(
        lease=lease,
        seq=seq,
        action=action,
        transaction_id=transaction_id,
        attempt_id=state["attempt_id"],
        facts=mutation_facts,
    )
    state_base = dict(state)
    state_base.pop("state_sha256", None)
    state_base.update(
        {
            "transaction_id": transaction_id,
            "transition_seq": seq,
            "status": status,
            "next_action": next_action,
            "next_action_is_unique": True,
            "expected_goal_delta_sha256": expected_business_sha256,
            "pending_code_change": dict(pending_code_change) if pending_code_change else None,
            "updated_at": f"control-seq:{seq}",
        }
    )
    next_state = _with_semantic_sha(state_base, "state_sha256")
    next_state_bytes = _canonical_file_bytes(next_state)
    plan_base = {
        "schema_version": "c28f_append_only_transaction_plan_v1",
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "seq": seq,
        "action": action,
        "parent_state_sha256": state["state_sha256"],
        "parent_event_sha256": events[-1]["event_sha256"],
        "expected_state_sha256": next_state["state_sha256"],
        "expected_business_postimage_sha256": expected_business_sha256,
        "registry_output_hashes": {registry_name: bytes_sha256(registry_bytes)},
        "ledger_output_hashes": {
            "ledgers/mutation_ledger.jsonl": bytes_sha256(mutation_journal)
        },
        "code_change_intent_sha256": registry_payload["code_change_intent_sha256"],
        "state_pointer_is_last_commit_marker": True,
    }
    plan = _with_semantic_sha(plan_base, "plan_sha256")
    plan_bytes = _canonical_file_bytes(plan)
    event_base = {
        "schema_version": "c28f_goal_event_v2",
        "seq": seq,
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "action": action,
        "result": result,
        "prev_event_sha256": events[-1]["event_sha256"],
        "expected_next_state_sha256": next_state["state_sha256"],
        "expected_goal_delta_sha256": expected_business_sha256,
        "next_action": next_action,
        "input_hashes": {
            "parent_state": state["state_sha256"],
            "transaction_plan_file": bytes_sha256(plan_bytes),
            "code_change_intent": registry_payload["code_change_intent_sha256"],
        },
        "output_hashes": {
            registry_name: bytes_sha256(registry_bytes),
            "ledgers/mutation_ledger.jsonl": bytes_sha256(mutation_journal),
        },
        "safety_counts": {
            "protected_content_opens": 0,
            "model_forward_evaluations": 0,
            "real_data_optimizer_updates": 0,
        },
    }
    event = _with_semantic_sha(event_base, "event_sha256")
    event_bytes = canonical_json_bytes(event) + b"\n"
    atomic_write_immutable(
        CONTROL_ROOT / "transactions" / transaction_id / "plan.json",
        plan_bytes,
        lease=lease,
    )
    atomic_write_immutable(
        CONTROL_ROOT / "registry_records" / f"{seq:06d}_code_change_registry_{bytes_sha256(registry_bytes)}.json",
        registry_bytes,
        lease=lease,
    )
    atomic_write_bytes(registry_path, registry_bytes, lease=lease, **registry_precondition)
    atomic_write_immutable(
        CONTROL_ROOT / "state_records" / f"{seq:06d}_{next_state['state_sha256']}.json",
        next_state_bytes,
        lease=lease,
    )
    atomic_write_immutable(
        CONTROL_ROOT / "event_records" / f"{seq:06d}_{event['event_sha256']}.jsonl",
        event_bytes,
        lease=lease,
    )
    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    _old_event_record = bytes_sha256(event_journal)
    atomic_write_bytes(
        CONTROL_ROOT / "GOAL_EVENTS.jsonl",
        event_journal + event_bytes,
        lease=lease,
        expected_preimage_sha256=_old_event_record,
    )
    continuation = _a4_continuation(next_state, event)
    old_continuation, continuation_record = read_regular_bytes(
        CONTROL_ROOT / "CONTINUATION.md", require_nlink_one=True
    )
    _require(bool(old_continuation), "current continuation cannot be empty")
    atomic_write_bytes(
        CONTROL_ROOT / "CONTINUATION.md",
        continuation,
        lease=lease,
        expected_preimage_sha256=continuation_record["sha256"],
    )
    _assert_dual_live_capability(bootstrap_lease, lease)
    _validate_supersession_receipt(bootstrap_lease)
    atomic_write_bytes(
        CONTROL_ROOT / "GOAL_STATE.json",
        next_state_bytes,
        lease=lease,
        expected_preimage_sha256=bytes_sha256(state_bytes),
    )
    return {
        "state": next_state,
        "event": event,
        "mutation_entry": mutation_entry,
        "plan": plan,
    }


def commit_user_authorized_online_code_change(
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Commit the user's already-installed online replacements without PREPARE."""

    bootstrap_lease.assert_active_capability()
    lock_path = CONTROL_ROOT / "single_writer.lock"
    heartbeat_path = CONTROL_ROOT / "single_writer.heartbeat.json"
    with WriterLease(
        lock_path,
        heartbeat_path,
        GOAL_ID,
        ONLINE_CODE_CHANGE_ACTION,
    ) as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        _recover_incomplete_g2_replay_sessions(lease)
        state, state_bytes, events, event_journal = _current_state_and_events()
        current = _a4_business_inventory(
            forbidden_identities=_protected_identities_from_a3()
        )
        if (
            events[-1].get("action") == "COMMIT_REVIEWED_CODE_CHANGE"
            and current["business_delta_sha256"]
            == state.get("expected_goal_delta_sha256")
        ):
            code_change_id = str(events[-1]["transaction_id"]).rsplit("-", 1)[0]
            contract, _encoded = _read_canonical_json(
                CONTROL_ROOT
                / "transactions"
                / code_change_id
                / "reviewed_code_change_intent.json"
            )
            _require(
                isinstance(contract, dict)
                and contract.get("schema_version")
                == "c28f_user_authorized_online_code_change_v1",
                "last commit is not the online code change",
            )
            verified = verify_a4_state(bootstrap_lease, active_lease=lease)
            return {
                "status": verified["status"],
                "next_action": verified["next_action"],
                "state_sha256": verified["state_sha256"],
                "event_sha256": events[-1]["event_sha256"],
                "transaction_id": events[-1]["transaction_id"],
                "business_delta_sha256": verified[
                    "expected_goal_delta_sha256"
                ],
                "code_executed_or_imported_before_commit": True,
                "review_policy": ONLINE_CODE_CHANGE_REVIEW_POLICY,
            }
        _require(
            state.get("status") != "CODE_CHANGE_PREPARED"
            and isinstance(state.get("next_action"), str)
            and bool(state["next_action"])
            and state.get("pending_code_change") is None,
            "online code change requires a stable nonterminal tail",
        )
        if state.get("active_eval") is not None:
            active_registry, _active_registry_bytes = _read_eval_registry()
            _assert_pre_forward_active_eval_online_maintenance(
                state=state,
                events=events,
                registry=active_registry,
            )
        intent, _intent_bytes = _validate_a4_intent_file()
        genesis_inventory = intent["bootstrap_business_inventory"]
        contracts = _load_code_change_contracts(
            attempt_id=str(state["attempt_id"])
        )
        stage_contracts = _load_stage_contracts(
            attempt_id=str(state["attempt_id"])
        )
        committed_records = {
            item["path"]: dict(item)
            for item in genesis_inventory["entries"]
        }
        applied_ids: set[str] = set()
        for event in events[1:]:
            transaction_id = str(event["transaction_id"])
            if CODE_CHANGE_TXN_RE.fullmatch(transaction_id) is not None:
                code_change_id = transaction_id.rsplit("-", 1)[0]
                if code_change_id in applied_ids:
                    continue
                contract = contracts[code_change_id]
                for item in contract["files"]:
                    destination = item["destination"]
                    if item["operation"] == "ADD":
                        _require(
                            destination not in committed_records,
                            f"replayed ADD destination exists: {destination}",
                        )
                    else:
                        installed = committed_records.get(destination)
                        _require(
                            installed is not None
                            and installed["sha256"]
                            == item["expected_preimage_sha256"]
                            and installed["size_bytes"]
                            == item["expected_preimage_size_bytes"],
                            f"replayed replacement preimage: {destination}",
                        )
                    committed_records[destination] = {
                        "path": destination,
                        "type": "regular_file",
                        "size_bytes": item["size_bytes"],
                        "sha256": item["sha256"],
                    }
                applied_ids.add(code_change_id)
                continue
            if STAGE_COMMIT_ID_RE.fullmatch(transaction_id) is not None:
                stage_contract = stage_contracts[transaction_id]
                for item in stage_contract["output_records"]:
                    destination = item["destination"]
                    _require(
                        destination not in committed_records,
                        f"replayed stage destination exists: {destination}",
                    )
                    committed_records[destination] = {
                        "path": destination,
                        "type": "regular_file",
                        "size_bytes": item["size_bytes"],
                        "sha256": item["sha256"],
                    }
        baseline = _inventory_from_entries(list(committed_records.values()))
        _require(
            baseline["business_delta_sha256"]
            == state["expected_goal_delta_sha256"],
            "online code change committed business preimage",
        )
        _require(
            current["business_delta_sha256"]
            != baseline["business_delta_sha256"],
            "online code change has no installed delta",
        )
        baseline_records = {
            item["path"]: dict(item) for item in baseline["entries"]
        }
        current_records = {
            item["path"]: dict(item) for item in current["entries"]
        }
        _require(
            set(current_records) == set(baseline_records),
            "online code change permits existing-file replacement only",
        )
        changed: list[dict[str, Any]] = []
        for destination in sorted(current_records):
            before = baseline_records[destination]
            after = current_records[destination]
            if before == after:
                continue
            _require(
                destination in A4_REQUIRED_REVIEWED_FILES
                or destination
                == A4_REVIEW_RECEIPT.relative_to(REPO_ROOT).as_posix(),
                f"online code change outside reviewed code/test domain: {destination}",
            )
            _safe_code_destination(destination)
            changed.append(
                {
                    "destination": destination,
                    "operation": "REPLACE_EXISTING",
                    "expected_preimage_sha256": before["sha256"],
                    "expected_preimage_size_bytes": before["size_bytes"],
                    "sha256": after["sha256"],
                    "size_bytes": after["size_bytes"],
                }
            )
        _require(
            1 <= len(changed) <= MAX_CODE_CHANGE_FILES,
            "online code change file count",
        )
        validate_a4_static_review_receipt()
        contract_base = {
            "schema_version": "c28f_user_authorized_online_code_change_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "parent_state_sha256": state["state_sha256"],
            "parent_event_sha256": events[-1]["event_sha256"],
            "commit_action": "COMMIT_REVIEWED_CODE_CHANGE",
            "resume_action": state["next_action"],
            "resume_status": state["status"],
            "user_authorization": {
                "text": ONLINE_CODE_CHANGE_AUTHORIZATION_TEXT,
                "text_sha256": bytes_sha256(
                    ONLINE_CODE_CHANGE_AUTHORIZATION_TEXT.encode("utf-8")
                ),
            },
            "review_policy": ONLINE_CODE_CHANGE_REVIEW_POLICY,
            "business_preimage_sha256": baseline[
                "business_delta_sha256"
            ],
            "business_postimage_sha256": current[
                "business_delta_sha256"
            ],
            "files": changed,
            "application_method": (
                "direct online replacement of existing regular files"
            ),
            "code_executed_or_imported_before_commit": True,
        }
        identity_seed = dict(contract_base)
        code_change_id = (
            "CODE-CHANGE-"
            + bytes_sha256(canonical_json_bytes(identity_seed))[:32]
        )
        contract = {
            **contract_base,
            "code_change_id": code_change_id,
        }
        contract["code_change_intent_sha256"] = semantic_sha256(
            contract,
            excluded_fields=("code_change_intent_sha256",),
        )
        _validate_code_change_contract_payload(
            contract,
            attempt_id=str(state["attempt_id"]),
        )
        transaction_id = f"{code_change_id}-COMMIT"
        _require(
            CODE_CHANGE_TXN_RE.fullmatch(transaction_id) is not None,
            "online code transaction ID",
        )
        atomic_write_immutable(
            CONTROL_ROOT
            / "transactions"
            / code_change_id
            / "reviewed_code_change_intent.json",
            _canonical_file_bytes(contract),
            lease=lease,
        )
        authorization_sha256 = contract["user_authorization"]["text_sha256"]
        registry = {
            "schema_version": "c28f_code_change_registry_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "transaction_id": transaction_id,
            "code_change_id": code_change_id,
            "status": (
                "COMMITTED_USER_AUTHORIZED_ONLINE_EXISTING_FILE_POSTIMAGE"
            ),
            "code_change_intent_sha256": contract[
                "code_change_intent_sha256"
            ],
            "business_preimage_sha256": contract[
                "business_preimage_sha256"
            ],
            "business_postimage_sha256": contract[
                "business_postimage_sha256"
            ],
            "resume_action": contract["resume_action"],
            "code_executed_or_imported_before_commit": True,
            "review_policy": ONLINE_CODE_CHANGE_REVIEW_POLICY,
            "user_authorization_sha256": authorization_sha256,
        }
        transition = _commit_code_control_transition(
            lease=lease,
            bootstrap_lease=bootstrap_lease,
            state=state,
            state_bytes=state_bytes,
            events=events,
            event_journal=event_journal,
            transaction_id=transaction_id,
            action="COMMIT_REVIEWED_CODE_CHANGE",
            result=(
                "COMMITTED_USER_AUTHORIZED_ONLINE_EXISTING_FILE_POSTIMAGE"
            ),
            next_action=str(contract["resume_action"]),
            status=str(contract["resume_status"]),
            expected_business_sha256=str(
                contract["business_postimage_sha256"]
            ),
            pending_code_change=None,
            registry_payload=registry,
            mutation_facts={
                "phase": "DIRECT_ONLINE_COMMIT",
                "code_change_intent_sha256": contract[
                    "code_change_intent_sha256"
                ],
                "business_preimage_sha256": contract[
                    "business_preimage_sha256"
                ],
                "business_postimage_sha256": contract[
                    "business_postimage_sha256"
                ],
                "installed_file_count": len(changed),
                "code_executed_or_imported_before_commit": True,
                "review_policy": ONLINE_CODE_CHANGE_REVIEW_POLICY,
                "user_authorization_sha256": authorization_sha256,
            },
        )
        verified = verify_a4_state(bootstrap_lease, active_lease=lease)
        _require(
            verified["state_sha256"]
            == transition["state"]["state_sha256"],
            "online code commit verification",
        )
        return {
            "status": verified["status"],
            "next_action": verified["next_action"],
            "state_sha256": verified["state_sha256"],
            "event_sha256": transition["event"]["event_sha256"],
            "transaction_id": transaction_id,
            "code_change_id": code_change_id,
            "business_delta_sha256": current["business_delta_sha256"],
            "changed_files": [item["destination"] for item in changed],
            "code_executed_or_imported_before_commit": True,
            "review_policy": ONLINE_CODE_CHANGE_REVIEW_POLICY,
        }


def prepare_reviewed_code_change(
    manifest_name: str,
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """PREPARE_REVIEWED_CODE_CHANGE: fsync exact postimage authority before apply_patch."""

    bootstrap_lease.assert_active_capability()
    lock_path = CONTROL_ROOT / "single_writer.lock"
    heartbeat_path = CONTROL_ROOT / "single_writer.heartbeat.json"
    with WriterLease(lock_path, heartbeat_path, GOAL_ID, "PREPARE_REVIEWED_CODE_CHANGE") as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        state, state_bytes, events, event_journal = _current_state_and_events()
        if state.get("status") == "CODE_CHANGE_PREPARED":
            pending = state.get("pending_code_change")
            _require(isinstance(pending, dict), "prepared code change lacks pending identity")
            existing, _encoded = _read_canonical_json(
                CONTROL_ROOT
                / "transactions"
                / pending["code_change_id"]
                / "reviewed_code_change_intent.json"
            )
            _require(existing.get("manifest_name") == manifest_name, "different code change already prepared")
            _validate_code_change_contract_payload(existing, attempt_id=state["attempt_id"])
            verified = verify_a4_state(bootstrap_lease, active_lease=lease)
            _require(
                verified["state_sha256"] == state["state_sha256"],
                "idempotent PREPARE state verification",
            )
            return {
                "status": state["status"],
                "next_action": state["next_action"],
                "state_sha256": state["state_sha256"],
                "event_sha256": events[-1]["event_sha256"],
                "transaction_id": pending["prepare_transaction_id"],
                "code_change_id": pending["code_change_id"],
                "expected_business_postimage_sha256": pending["business_postimage_sha256"],
                "authorized_installation_method": "apply_patch exact postimages, then COMMIT_REVIEWED_CODE_CHANGE",
            }
        contract, _blobs, postimage = _prepare_code_change_contract(manifest_name, state)
        contract["parent_event_sha256"] = events[-1]["event_sha256"]
        contract["code_change_intent_sha256"] = semantic_sha256(
            contract, excluded_fields=("code_change_intent_sha256",)
        )
        code_change_id = contract["code_change_id"]
        transaction_id = f"{code_change_id}-PREPARE"
        _require(CODE_CHANGE_TXN_RE.fullmatch(transaction_id) is not None, "prepare transaction ID")
        code_intent_path = (
            CONTROL_ROOT / "transactions" / code_change_id / "reviewed_code_change_intent.json"
        )
        if not os.path.lexists(code_intent_path):
            verified = verify_a4_state(bootstrap_lease, active_lease=lease)
            _require(verified["state_sha256"] == state["state_sha256"], "PREPARE parent verification")
        contract_bytes = _canonical_file_bytes(contract)
        atomic_write_immutable(
            code_intent_path,
            contract_bytes,
            lease=lease,
        )
        registry = {
            "schema_version": "c28f_code_change_registry_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "transaction_id": transaction_id,
            "code_change_id": code_change_id,
            "status": "PREPARED_AWAITING_EXACT_APPLY_PATCH_POSTIMAGE",
            "code_change_intent_sha256": contract["code_change_intent_sha256"],
            "business_preimage_sha256": contract["business_preimage_sha256"],
            "business_postimage_sha256": contract["business_postimage_sha256"],
            "resume_action": contract["resume_action"],
            "code_executed_or_imported": False,
        }
        pending = {
            "code_change_id": code_change_id,
            "prepare_transaction_id": transaction_id,
            "code_change_intent_sha256": contract["code_change_intent_sha256"],
            "business_postimage_sha256": postimage["business_delta_sha256"],
            "resume_action": contract["resume_action"],
        }
        transition = _commit_code_control_transition(
            lease=lease,
            bootstrap_lease=bootstrap_lease,
            state=state,
            state_bytes=state_bytes,
            events=events,
            event_journal=event_journal,
            transaction_id=transaction_id,
            action="PREPARE_REVIEWED_CODE_CHANGE",
            result="PRECOMMITTED_REVIEWED_POSTIMAGE_AWAITING_APPLY_PATCH",
            next_action="COMMIT_REVIEWED_CODE_CHANGE",
            status="CODE_CHANGE_PREPARED",
            expected_business_sha256=contract["business_preimage_sha256"],
            pending_code_change=pending,
            registry_payload=registry,
            mutation_facts={
                "phase": "PREPARE",
                "code_change_intent_sha256": contract["code_change_intent_sha256"],
                "business_preimage_sha256": contract["business_preimage_sha256"],
                "business_postimage_sha256": contract["business_postimage_sha256"],
                "apply_patch_executed": False,
            },
        )
        verified = verify_a4_state(bootstrap_lease, active_lease=lease)
        _require(verified["state_sha256"] == transition["state"]["state_sha256"], "PREPARE commit verification")
        return {
            "status": transition["state"]["status"],
            "next_action": transition["state"]["next_action"],
            "state_sha256": transition["state"]["state_sha256"],
            "event_sha256": transition["event"]["event_sha256"],
            "transaction_id": transaction_id,
            "code_change_id": code_change_id,
            "expected_business_postimage_sha256": contract["business_postimage_sha256"],
            "authorized_installation_method": "apply_patch exact postimages, then COMMIT_REVIEWED_CODE_CHANGE",
        }


def commit_reviewed_code_change(bootstrap_lease: BootstrapLease) -> dict[str, Any]:
    """COMMIT_REVIEWED_CODE_CHANGE: verify installed bytes, then commit state/event."""

    bootstrap_lease.assert_active_capability()
    lock_path = CONTROL_ROOT / "single_writer.lock"
    heartbeat_path = CONTROL_ROOT / "single_writer.heartbeat.json"
    with WriterLease(lock_path, heartbeat_path, GOAL_ID, "COMMIT_REVIEWED_CODE_CHANGE") as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        state, state_bytes, events, event_journal = _current_state_and_events()
        if (
            state.get("status") == "PREFLIGHT_OK"
            and events[-1].get("action") == "COMMIT_REVIEWED_CODE_CHANGE"
        ):
            verified = verify_a4_state(bootstrap_lease, active_lease=lease)
            _require(verified["state_sha256"] == state["state_sha256"], "idempotent COMMIT verification")
            return {
                "status": state["status"],
                "next_action": state["next_action"],
                "state_sha256": state["state_sha256"],
                "event_sha256": events[-1]["event_sha256"],
                "transaction_id": events[-1]["transaction_id"],
                "business_delta_sha256": state["expected_goal_delta_sha256"],
                "code_executed_or_imported_before_commit": False,
            }
        _require(state["status"] == "CODE_CHANGE_PREPARED", "code change is not PREPARED")
        _require(state["next_action"] == "COMMIT_REVIEWED_CODE_CHANGE", "commit action is not current")
        pending = state.get("pending_code_change")
        _require(isinstance(pending, dict), "pending code change missing")
        code_change_id = pending["code_change_id"]
        _require(CODE_CHANGE_ID_RE.fullmatch(code_change_id) is not None, "pending code-change ID")
        transaction_id = f"{code_change_id}-COMMIT"
        if not (CONTROL_ROOT / "transactions" / transaction_id).exists():
            verified = verify_a4_state(bootstrap_lease, active_lease=lease)
            _require(verified["state_sha256"] == state["state_sha256"], "COMMIT parent verification")
        contract, contract_bytes = _read_canonical_json(
            CONTROL_ROOT / "transactions" / code_change_id / "reviewed_code_change_intent.json"
        )
        _require(isinstance(contract, dict), "code change intent object required")
        _require(
            contract.get("code_change_intent_sha256")
            == semantic_sha256(contract, excluded_fields=("code_change_intent_sha256",)),
            "code change intent semantic hash",
        )
        _require(
            contract["code_change_intent_sha256"] == pending["code_change_intent_sha256"],
            "pending code change identity drift",
        )
        _require(contract.get("code_change_id") == code_change_id, "pending code-change contract ID")
        _require(bool(contract_bytes), "code change intent cannot be empty")
        for item in contract["files"]:
            destination = _safe_code_destination(item["destination"])
            installed, record = read_regular_bytes(destination, require_nlink_one=True)
            _require(record["sha256"] == item["sha256"], f"installed code hash: {destination}")
            _require(len(installed) == item["size_bytes"], f"installed code size: {destination}")
        postimage = _a4_business_inventory(
            forbidden_identities=_protected_identities_from_a3()
        )
        _require(
            postimage["business_delta_sha256"] == contract["business_postimage_sha256"],
            "installed business postimage mismatch",
        )
        registry = {
            "schema_version": "c28f_code_change_registry_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "transaction_id": transaction_id,
            "code_change_id": code_change_id,
            "status": "COMMITTED_EXACT_REVIEWED_POSTIMAGE",
            "code_change_intent_sha256": contract["code_change_intent_sha256"],
            "business_preimage_sha256": contract["business_preimage_sha256"],
            "business_postimage_sha256": contract["business_postimage_sha256"],
            "resume_action": contract["resume_action"],
            "code_executed_or_imported_before_commit": False,
        }
        transition = _commit_code_control_transition(
            lease=lease,
            bootstrap_lease=bootstrap_lease,
            state=state,
            state_bytes=state_bytes,
            events=events,
            event_journal=event_journal,
            transaction_id=transaction_id,
            action="COMMIT_REVIEWED_CODE_CHANGE",
            result="COMMITTED_EXACT_STATIC_REVIEWED_POSTIMAGE",
            next_action=contract["resume_action"],
            status="PREFLIGHT_OK",
            expected_business_sha256=contract["business_postimage_sha256"],
            pending_code_change=None,
            registry_payload=registry,
            mutation_facts={
                "phase": "COMMIT",
                "code_change_intent_sha256": contract["code_change_intent_sha256"],
                "business_postimage_sha256": contract["business_postimage_sha256"],
                "installed_file_count": len(contract["files"]),
                "code_executed_or_imported_before_commit": False,
            },
        )
        verified = verify_a4_state(bootstrap_lease, active_lease=lease)
        _require(verified["state_sha256"] == transition["state"]["state_sha256"], "COMMIT verification")
        return {
            "status": transition["state"]["status"],
            "next_action": transition["state"]["next_action"],
            "state_sha256": transition["state"]["state_sha256"],
            "event_sha256": transition["event"]["event_sha256"],
            "transaction_id": transaction_id,
            "business_delta_sha256": postimage["business_delta_sha256"],
            "code_executed_or_imported_before_commit": False,
        }


def _stage_commit_id(plan: Mapping[str, Any], output_bytes: Mapping[str, bytes]) -> str:
    output_hashes = {
        name: bytes_sha256(data)
        for name, data in sorted(output_bytes.items())
    }
    seed = bytes_sha256(
        canonical_json_bytes(
            {
                "stage_plan_sha256": plan.get("stage_plan_sha256"),
                "output_hashes": output_hashes,
            }
        )
    )
    return f"STAGE-COMMIT-{seed[:32]}"


def _validate_stage_bundle_input(
    *,
    plan: Mapping[str, Any],
    output_bytes: Mapping[str, bytes],
    intent: Mapping[str, Any],
    state: Mapping[str, Any],
    parent_event: Mapping[str, Any],
) -> tuple[str, list[dict[str, Any]]]:
    plan_fields = {
        "schema_version", "goal_id", "attempt_id", "action", "action_is_unique",
        "state_binding", "static_review_receipt_sha256", "business_preimage_sha256",
        "isolated_output_root_id", "output_policy", "input_hashes", "output_index",
        "next_state_contract", "declared_safety_counts", "commit_eligible",
        "stage_plan_sha256",
    }
    _require(isinstance(plan, dict) and set(plan) == plan_fields, "stage plan field set")
    _require(plan.get("schema_version") == "c28f_a4_stage_plan_v1", "stage plan schema")
    _require(
        plan.get("stage_plan_sha256")
        == semantic_sha256(plan, excluded_fields=("stage_plan_sha256",)),
        "stage plan semantic hash",
    )
    _require(plan.get("goal_id") == GOAL_ID and plan.get("attempt_id") == intent["attempt_id"], "stage plan owner")
    _require(plan.get("action") == state["next_action"] and plan.get("action_is_unique") is True, "stage action is not current")
    _require(plan.get("commit_eligible") is True, "stage plan is not commit eligible")
    _require(
        plan.get("static_review_receipt_sha256") == intent["static_review_receipt"]["sha256"],
        "stage plan review receipt binding",
    )
    binding = plan.get("state_binding")
    _require(isinstance(binding, dict), "stage state binding")
    _require(
        binding.get("state_binding_sha256")
        == semantic_sha256(binding, excluded_fields=("state_binding_sha256",)),
        "stage state binding semantic hash",
    )
    required_binding = {
        "goal_id": GOAL_ID,
        "attempt_id": intent["attempt_id"],
        "transition_seq": int(state["transition_seq"]) + 1,
        "current_action": state["next_action"],
        "current_status": state["status"],
        "parent_state_sha256": state["state_sha256"],
        "parent_event_sha256": parent_event["event_sha256"],
        "business_preimage_sha256": state["expected_goal_delta_sha256"],
        "static_review_receipt_sha256": intent["static_review_receipt"]["sha256"],
        "train_jsonl_index_state": state.get(
            "train_jsonl_index_state",
            "ABSENT",
        ),
        "train_jsonl_index_binding_sha256": state.get(
            "train_jsonl_index_binding_sha256"
        ),
        "train_jsonl_index_receipt_sha256": state.get(
            "train_jsonl_index_receipt_sha256"
        ),
        "train_jsonl_index_transaction_id": state.get(
            "train_jsonl_index_transaction_id"
        ),
    }
    _require(
        all(binding.get(field) == value for field, value in required_binding.items()),
        "stage state binding differs from current tail",
    )
    _require(plan.get("business_preimage_sha256") == state["expected_goal_delta_sha256"], "stage business preimage")
    safety_fields = {
        "protected_content_opens",
        "protected_id_mapping_content_opens",
        "historical_write_bytes",
        "model_forward_evaluations",
        "real_data_optimizer_updates",
    }
    declared_safety = plan.get("declared_safety_counts")
    _require(
        isinstance(declared_safety, dict)
        and set(declared_safety) == safety_fields
        and all(
            type(value) is int and value >= 0
            for value in declared_safety.values()
        ),
        "stage declared safety exact nonnegative fields",
    )
    expected_safety = dict.fromkeys(safety_fields, 0)
    if plan["action"] in {
        "G3_F0_A_BASELINE_FORENSICS",
        "G5_F0_B_EXPOSURE_REPLICATION",
    }:
        expected_safety["model_forward_evaluations"] = 1
    elif plan["action"] == "G4_PROTECTED_ID_MAPPING_PROJECTION":
        expected_safety["protected_id_mapping_content_opens"] = 5
    _require(
        declared_safety == expected_safety,
        "stage declared safety differs from fixed action allowance",
    )
    if plan["action"] == "G4_PROTECTED_ID_MAPPING_PROJECTION":
        mapping_registry, _mapping_registry_bytes = _read_canonical_json(
            CONTROL_ROOT / "protected_id_mapping_registry.json"
        )
        _require(
            isinstance(mapping_registry, dict)
            and mapping_registry.get("phase") == "ACCESS"
            and mapping_registry.get("transaction_id")
            == state["transaction_id"],
            "G4 projection stage requires current ACCESS registry",
        )
        access_receipt, _access_receipt_bytes = _read_canonical_json(
            CONTROL_ROOT
            / "transactions"
            / mapping_registry["transaction_id"]
            / "access_receipt.json"
        )
        observation = mapping_registry.get("source_observation_receipt")
        _require(
            isinstance(access_receipt, dict)
            and isinstance(observation, dict)
            and access_receipt.get("content_open_count") == 5
            and access_receipt.get("manifest_content_open_count") == 3
            and access_receipt.get("protected_source_content_open_count") == 2
            and access_receipt.get("official_val_content_open_count") == 0
            and access_receipt.get("source_observation_receipt_sha256")
            == observation.get("receipt_sha256")
            and access_receipt.get("instrumentation_complete") is True
            and access_receipt.get("unmediated_content_open_count") == 0
            and plan.get("input_hashes", {}).get(
                "projection_access_receipt"
            )
            == access_receipt.get("receipt_sha256")
            and plan.get("input_hashes", {}).get(
                "projection_source_observation"
            )
            == observation.get("receipt_sha256"),
            "G4 projection declared safety/access observation closure",
        )
    output_index = plan.get("output_index")
    _require(
        isinstance(output_index, dict)
        and isinstance(output_bytes, Mapping)
        and set(output_index) == set(output_bytes)
        and 1 <= len(output_index) <= MAX_STAGE_OUTPUT_FILES,
        "stage output index/bytes closure",
    )
    expected_root = REPORT_ROOT / str(intent["attempt_id"]) / "stage_outputs"
    _require(binding.get("isolated_output_root_path") == str(expected_root), "stage isolated output root path")
    _require(binding.get("isolated_output_root_id") == plan.get("isolated_output_root_id"), "stage output root ID")
    records: list[dict[str, Any]] = []
    total = 0
    for relative, data in sorted(output_bytes.items()):
        _require(
            isinstance(relative, str)
            and relative == Path(relative).as_posix()
            and Path(relative).parts
            and Path(relative).parts[0] in {"f0_forensics", "f1_protocol"}
            and ".." not in Path(relative).parts
            and "." not in Path(relative).parts,
            "stage output relative path",
        )
        _require(isinstance(data, bytes) and 0 < len(data) <= MAX_STAGE_OUTPUT_FILE_BYTES, "stage output bytes")
        digest = bytes_sha256(data)
        _require(output_index[relative] == {"sha256": digest, "size_bytes": len(data)}, "stage output index record")
        total += len(data)
        records.append(
            {
                "relative_path": relative,
                "destination": (expected_root / relative).relative_to(REPO_ROOT).as_posix(),
                "sha256": digest,
                "size_bytes": len(data),
            }
        )
    _require(total <= MAX_STAGE_OUTPUT_TOTAL_BYTES, "stage output total bytes")
    return _stage_commit_id(plan, output_bytes), records


def _validated_stage_bundle_payload(
    bundle: Any,
) -> tuple[dict[str, Any], dict[str, bytes]]:
    from blueprint_e2e_v2.c28f_v5.a4_stages import validate_stage_bundle

    validated = validate_stage_bundle(bundle)
    _require(validated.commit_eligible is True, "stage bundle is not commit eligible")
    plan = dict(validated.plan)
    output_bytes = dict(validated.output_bytes)
    _require(
        all(isinstance(path, str) and isinstance(data, bytes) for path, data in output_bytes.items()),
        "stage bundle exact bytes",
    )
    return plan, output_bytes


def issue_current_stage_context(
    *,
    bootstrap_lease: BootstrapLease,
) -> Any:
    """Issue the exact current committed tail as the sole StageContext."""

    from blueprint_e2e_v2.c28f_v5.a4_stages import StageContext

    g1_handle: Optional[A4G1ControlHandle] = None
    state_probe, _probe_bytes, _probe_events, _probe_journal = (
        _current_state_and_events()
    )
    if state_probe.get("next_action") == "G1_FAIL_CLOSED_GUARD":
        g1_handle = issue_g1_control_handle(
            bootstrap_lease=bootstrap_lease
        )
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_CURRENT_STAGE_CONTEXT",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        intent, _intent_bytes = _validate_a4_intent_file()
        authority, _authority_file_sha = _read_committed_g1_genesis_registry(
            "g1_registry_authority.json"
        )
        snapshot, _snapshot_file_sha = _read_committed_g1_genesis_registry(
            "g1_global_ledger_snapshot.json"
        )
        if g1_handle is not None:
            g1_binding = validate_g1_control_handle(g1_handle)
            _require(
                state["next_action"] == "G1_FAIL_CLOSED_GUARD"
                and g1_binding["committed_state_sha256"]
                == state["state_sha256"]
                and g1_binding["committed_event_sha256"]
                == events[-1]["event_sha256"],
                "G1 StageContext/handle current-tail race",
            )
            control_anchor_receipt_sha256 = g1_handle.capability_sha256
        else:
            control_anchor_receipt_sha256 = events[-1]["event_sha256"]
        output_root = REPORT_ROOT / str(state["attempt_id"]) / "stage_outputs"
        _require(
            output_root.is_dir()
            and not output_root.is_symlink(),
            "StageContext isolated output root",
        )
        context = StageContext(
            goal_id=GOAL_ID,
            attempt_id=str(state["attempt_id"]),
            transition_seq=int(state["transition_seq"]) + 1,
            current_action=str(state["next_action"]),
            current_status=str(state["status"]),
            parent_state_sha256=str(state["state_sha256"]),
            parent_event_sha256=str(events[-1]["event_sha256"]),
            business_preimage_sha256=str(
                state["expected_goal_delta_sha256"]
            ),
            static_review_receipt_sha256=str(
                intent["static_review_receipt"]["sha256"]
            ),
            isolated_output_root_id="g1-write-output",
            isolated_output_root_path=str(output_root),
            expected_negative_suite_sha256=G1_NEGATIVE_SUITE_SHA256,
            control_transaction_id=str(state["transaction_id"]),
            committed_control_state_sha256=str(state["state_sha256"]),
            committed_control_event_sha256=str(
                events[-1]["event_sha256"]
            ),
            frozen_g1_registry_authority_sha256=str(
                authority["authority_sha256"]
            ),
            frozen_global_ledger_snapshot_sha256=str(
                snapshot["snapshot_sha256"]
            ),
            control_anchor_receipt_sha256=control_anchor_receipt_sha256,
            train_jsonl_index_state=str(
                state.get("train_jsonl_index_state", "ABSENT")
            ),
            train_jsonl_index_binding_sha256=(
                None
                if state.get("train_jsonl_index_binding_sha256") is None
                else str(state["train_jsonl_index_binding_sha256"])
            ),
            train_jsonl_index_receipt_sha256=(
                None
                if state.get("train_jsonl_index_receipt_sha256") is None
                else str(state["train_jsonl_index_receipt_sha256"])
            ),
            train_jsonl_index_transaction_id=(
                None
                if state.get("train_jsonl_index_transaction_id") is None
                else str(state["train_jsonl_index_transaction_id"])
            ),
        )
        context.validate(str(state["next_action"]), str(state["status"]))
        return context


def current_forward_action_snapshot(
    *,
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Return the minimal current token state needed by the reviewed runner."""

    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_CURRENT_FORWARD_ACTION_SNAPSHOT",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        base = {
            "schema_version": "c28f_a4_current_forward_action_snapshot_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "status": state["status"],
            "next_action": state["next_action"],
            "state_sha256": state["state_sha256"],
            "event_sha256": events[-1]["event_sha256"],
            "eval_token_states": dict(state["eval_token_states"]),
            "active_eval": (
                None
                if state.get("active_eval") is None
                else dict(state["active_eval"])
            ),
        }
        return {**base, "snapshot_sha256": semantic_sha256(base)}


def prepare_stage_commit(
    *,
    bundle: Any,
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Fsync an exact stage postimage intent before any output directory or byte write."""

    plan, output_bytes = _validated_stage_bundle_payload(bundle)
    bootstrap_lease.assert_active_capability()
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "PREPARE_STAGE_COMMIT",
    ) as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        intent, _intent_bytes = _validate_a4_intent_file()
        stage_commit_id, output_records = _validate_stage_bundle_input(
            plan=plan,
            output_bytes=output_bytes,
            intent=intent,
            state=state,
            parent_event=events[-1],
        )
        stage_dir = CONTROL_ROOT / "transactions" / stage_commit_id
        contract_path = stage_dir / "stage_commit_intent.json"
        if os.path.lexists(contract_path):
            existing, _encoded = _read_canonical_json(contract_path)
            _require(isinstance(existing, dict), "existing stage intent object")
            _validate_stage_commit_intent(existing, attempt_id=str(intent["attempt_id"]))
            _require(existing["stage_plan"] == dict(plan), "idempotent stage plan drift")
            expected_hashes = {item["relative_path"]: item["sha256"] for item in output_records}
            _require(
                existing["prepare_receipt"]["output_hashes"] == dict(sorted(expected_hashes.items())),
                "idempotent stage output drift",
            )
            atomic_write_immutable(
                stage_dir / "stage_plan.json",
                _canonical_file_bytes(plan),
                lease=lease,
            )
            atomic_write_immutable(
                stage_dir / "prepare_receipt.json",
                _canonical_file_bytes(existing["prepare_receipt"]),
                lease=lease,
            )
            observed = _a4_business_inventory(
                forbidden_identities=_protected_identities_from_a3()
            )
            observed_records = {item["path"]: dict(item) for item in observed["entries"]}
            for item in existing["output_records"]:
                installed = observed_records.get(item["destination"])
                if installed is not None:
                    _require(
                        installed["sha256"] == item["sha256"]
                        and installed["size_bytes"] == item["size_bytes"],
                        f"idempotent stage partial output drift: {item['destination']}",
                    )
                    observed_records.pop(item["destination"])
            _require(
                _inventory_from_entries(list(observed_records.values()))[
                    "business_delta_sha256"
                ]
                == existing["business_preimage_sha256"],
                "idempotent stage PREPARE preimage reconstruction",
            )
            if observed["business_delta_sha256"] == existing["business_preimage_sha256"]:
                verify_a4_state(bootstrap_lease, active_lease=lease)
            return dict(existing["prepare_receipt"])
        if os.path.lexists(stage_dir):
            _require(stage_dir.is_dir() and not stage_dir.is_symlink(), "partial stage PREPARE dir")
            with os.scandir(stage_dir) as iterator:
                partial_names = {entry.name for entry in iterator}
            _require(
                partial_names.issubset(
                    {"stage_plan.json", "stage_commit_intent.json", "prepare_receipt.json"}
                ),
                "partial stage PREPARE namespace pollution",
            )
            if "stage_plan.json" in partial_names:
                partial_plan, _partial_bytes = _read_canonical_json(stage_dir / "stage_plan.json")
                _require(partial_plan == dict(plan), "partial stage PREPARE plan drift")
        else:
            verify_a4_state(bootstrap_lease, active_lease=lease)
        current = _a4_business_inventory(
            forbidden_identities=_protected_identities_from_a3()
        )
        _require(current["business_delta_sha256"] == state["expected_goal_delta_sha256"], "stage PREPARE business preimage")
        by_path = {item["path"]: dict(item) for item in current["entries"]}
        for item in output_records:
            _require(item["destination"] not in by_path, f"stage output already exists: {item['destination']}")
            by_path[item["destination"]] = {
                "path": item["destination"],
                "type": "regular_file",
                "size_bytes": item["size_bytes"],
                "sha256": item["sha256"],
            }
        postimage = _inventory_from_entries(list(by_path.values()))
        output_hashes = {
            item["relative_path"]: item["sha256"] for item in output_records
        }
        prepare_base = {
            "schema_version": "c28f_a4_stage_prepare_receipt_v1",
            "status": "FSYNCED_PREPARED_AWAITING_OUTPUT_CAS",
            "goal_id": GOAL_ID,
            "attempt_id": intent["attempt_id"],
            "stage_action": plan["action"],
            "stage_commit_id": stage_commit_id,
            "parent_state_sha256": state["state_sha256"],
            "parent_event_sha256": events[-1]["event_sha256"],
            "business_preimage_sha256": current["business_delta_sha256"],
            "output_hashes": dict(sorted(output_hashes.items())),
            "static_review_receipt_sha256": plan["static_review_receipt_sha256"],
            "stage_plan_sha256": plan["stage_plan_sha256"],
            "transaction_id": stage_commit_id,
        }
        prepare_receipt = _with_semantic_sha(prepare_base, "receipt_sha256")
        contract_base = {
            "schema_version": "c28f_a4_stage_commit_intent_v1",
            "goal_id": GOAL_ID,
            "attempt_id": intent["attempt_id"],
            "stage_commit_id": stage_commit_id,
            "stage_plan": dict(plan),
            "stage_plan_sha256": plan["stage_plan_sha256"],
            "output_root": {
                "root_id": plan["isolated_output_root_id"],
                "absolute_path": plan["state_binding"]["isolated_output_root_path"],
            },
            "output_records": output_records,
            "business_preimage_sha256": current["business_delta_sha256"],
            "business_postimage_sha256": postimage["business_delta_sha256"],
            "prepare_receipt": prepare_receipt,
        }
        contract = _with_semantic_sha(contract_base, "stage_commit_intent_sha256")
        _validate_stage_commit_intent(contract, attempt_id=str(intent["attempt_id"]))
        _assert_dual_live_capability(bootstrap_lease, lease)
        _validate_supersession_receipt(bootstrap_lease)
        atomic_write_immutable(stage_dir / "stage_plan.json", _canonical_file_bytes(plan), lease=lease)
        atomic_write_immutable(contract_path, _canonical_file_bytes(contract), lease=lease)
        atomic_write_immutable(stage_dir / "prepare_receipt.json", _canonical_file_bytes(prepare_receipt), lease=lease)
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return prepare_receipt


def commit_stage_outputs(
    *,
    stage_commit_id: str,
    bundle: Any,
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """CAS-install a prepared stage bundle and commit its state/event chain."""

    _require(STAGE_COMMIT_ID_RE.fullmatch(stage_commit_id) is not None, "stage commit ID format")
    plan, output_bytes = _validated_stage_bundle_payload(bundle)
    bootstrap_lease.assert_active_capability()
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "COMMIT_STAGE_OUTPUTS",
    ) as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        state, state_bytes, events, event_journal = _current_state_and_events()
        intent, _intent_bytes = _validate_a4_intent_file()
        derived_id, output_records = _validate_stage_bundle_input(
            plan=plan,
            output_bytes=output_bytes,
            intent=intent,
            state=(
                state
                if state["transaction_id"] != stage_commit_id
                else _read_canonical_json(
                    CONTROL_ROOT
                    / "state_records"
                    / f"{int(state['transition_seq']) - 1:06d}_{events[-2]['expected_next_state_sha256']}.json"
                )[0]
            ),
            parent_event=(events[-1] if state["transaction_id"] != stage_commit_id else events[-2]),
        )
        _require(derived_id == stage_commit_id, "stage commit ID differs from bundle")
        stage_dir = CONTROL_ROOT / "transactions" / stage_commit_id
        contract, _encoded = _read_canonical_json(stage_dir / "stage_commit_intent.json")
        _require(isinstance(contract, dict), "stage intent object")
        _validate_stage_commit_intent(contract, attempt_id=str(intent["attempt_id"]))
        _require(contract["stage_plan"] == dict(plan), "stage commit plan drift")
        commit_path = stage_dir / "commit_receipt.json"
        if os.path.lexists(commit_path):
            receipt, _receipt_bytes = _read_canonical_json(commit_path)
            verified = verify_a4_state(bootstrap_lease, active_lease=lease)
            _require(verified["event_sha256"] == receipt["event_sha256"], "idempotent stage commit event")
            return dict(receipt)
        if (
            state.get("transaction_id") == stage_commit_id
            and events[-1].get("transaction_id") == stage_commit_id
        ):
            receipt = _build_stage_commit_receipt(contract, state, events[-1])
            atomic_write_immutable(
                commit_path,
                _canonical_file_bytes(receipt),
                lease=lease,
            )
            verify_a4_state(bootstrap_lease, active_lease=lease)
            return receipt
        _require(state["state_sha256"] == contract["prepare_receipt"]["parent_state_sha256"], "stage parent state changed")
        current = _a4_business_inventory(
            forbidden_identities=_protected_identities_from_a3()
        )
        current_by_path = {item["path"]: dict(item) for item in current["entries"]}
        reconstructed = dict(current_by_path)
        for item in output_records:
            installed = reconstructed.get(item["destination"])
            if installed is not None:
                _require(
                    installed["sha256"] == item["sha256"]
                    and installed["size_bytes"] == item["size_bytes"],
                    f"partial stage output drift: {item['destination']}",
                )
                reconstructed.pop(item["destination"])
        _require(
            _inventory_from_entries(list(reconstructed.values()))["business_delta_sha256"]
            == contract["business_preimage_sha256"],
            "stage output CAS preimage reconstruction",
        )
        _assert_dual_live_capability(bootstrap_lease, lease)
        _validate_supersession_receipt(bootstrap_lease)
        output_root = Path(contract["output_root"]["absolute_path"])
        ensure_directory(output_root)
        _assert_safe_path_chain(output_root)
        for item in output_records:
            destination = REPO_ROOT / item["destination"]
            ensure_directory(destination.parent)
            atomic_write_immutable(
                destination,
                output_bytes[item["relative_path"]],
                lease=lease,
            )
        postimage = _a4_business_inventory(
            forbidden_identities=_protected_identities_from_a3()
        )
        _require(postimage["business_delta_sha256"] == contract["business_postimage_sha256"], "stage output postimage")
        next_contract = plan["next_state_contract"]
        _require(
            next_contract.get("next_state_contract_sha256")
            == semantic_sha256(next_contract, excluded_fields=("next_state_contract_sha256",)),
            "stage next-state contract semantic hash",
        )
        _require(next_contract.get("transition_seq") == len(events), "stage next-state sequence")
        registry_payload = {
            "schema_version": "c28f_a4_stage_commit_registry_v1",
            "goal_id": GOAL_ID,
            "attempt_id": intent["attempt_id"],
            "stage_commit_id": stage_commit_id,
            "stage_action": plan["action"],
            "stage_plan_sha256": plan["stage_plan_sha256"],
            "prepare_receipt_sha256": contract["prepare_receipt"]["receipt_sha256"],
            "business_preimage_sha256": contract["business_preimage_sha256"],
            "business_postimage_sha256": contract["business_postimage_sha256"],
            "output_hashes": contract["prepare_receipt"]["output_hashes"],
            "status": "COMMITTED_EXACT_STAGE_POSTIMAGE",
        }
        envelope_base = {
            "schema_version": "c28f_a4_control_transition_intent_v1",
            "goal_id": GOAL_ID,
            "attempt_id": intent["attempt_id"],
            "transaction_id": stage_commit_id,
            "action": plan["action"],
            "result": "COMMITTED_EXACT_STAGE_POSTIMAGE",
            "parent_state_sha256": state["state_sha256"],
            "parent_event_sha256": events[-1]["event_sha256"],
            "expected_business_sha256": contract["business_postimage_sha256"],
            "state_updates": {
                "stage": next_contract["stage"],
                "status": next_contract["status"],
                "next_action": next_contract["next_action"],
                "pending_stage_commit": None,
            },
            "registry_name": "stage_commit_registry.json",
            "registry_payload": registry_payload,
            "mutation_facts": {
                "stage_commit_id": stage_commit_id,
                "stage_plan_sha256": plan["stage_plan_sha256"],
                "prepare_receipt_sha256": contract["prepare_receipt"]["receipt_sha256"],
                "business_postimage_sha256": contract["business_postimage_sha256"],
                "installed_file_count": len(output_records),
            },
            "input_bindings": {
                "stage_commit_intent": contract["stage_commit_intent_sha256"],
                "stage_prepare_receipt": contract["prepare_receipt"]["receipt_sha256"],
                "stage_plan": plan["stage_plan_sha256"],
                "static_review_receipt": plan["static_review_receipt_sha256"],
            },
            "safety_counts": {
                "protected_content_opens": 0,
                "model_forward_evaluations": 0,
                "real_data_optimizer_updates": 0,
            },
        }
        envelope = _with_semantic_sha(envelope_base, "transition_intent_sha256")
        atomic_write_immutable(
            stage_dir / "transition_intent.json",
            _canonical_file_bytes(envelope),
            lease=lease,
        )
        transition = _commit_enveloped_control_transition(
            lease=lease,
            bootstrap_lease=bootstrap_lease,
            state=state,
            state_bytes=state_bytes,
            events=events,
            event_journal=event_journal,
            envelope=envelope,
        )
        receipt = _build_stage_commit_receipt(
            contract,
            transition["state"],
            transition["event"],
        )
        atomic_write_immutable(commit_path, _canonical_file_bytes(receipt), lease=lease)
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return receipt


class A4ControlStageAdapter:
    """Lease-capturing implementation of the a4_stages two-phase protocol."""

    def __init__(self, bootstrap_lease: BootstrapLease) -> None:
        self._bootstrap_lease = bootstrap_lease

    def prepare_stage_commit(
        self,
        *,
        bundle: Any,
    ) -> Mapping[str, Any]:
        return prepare_stage_commit(
            bundle=bundle,
            bootstrap_lease=self._bootstrap_lease,
        )

    def commit_stage_outputs(
        self,
        *,
        stage_commit_id: str,
        bundle: Any,
    ) -> Mapping[str, Any]:
        return commit_stage_outputs(
            stage_commit_id=stage_commit_id,
            bundle=bundle,
            bootstrap_lease=self._bootstrap_lease,
        )


EVAL_EXECUTION_BINDING_FIELDS = {
    "checkpoint_sha256",
    "split_manifest_sha256",
    "corpus_manifest_sha256",
    "evaluator_sha256",
    "cursor_contract_sha256",
    "chunks_contract_sha256",
    "artifacts_contract_sha256",
    "authority_binding_sha256",
    "forward_manifest_sha256",
    "input_identity_sha256",
}


def _validate_eval_cas_intent(cas_intent: Mapping[str, Any]) -> None:
    fields = {
        "schema_version", "token_id", "eval_id", "goal_id", "authority_id",
        "purpose", "expected_budget_preimage_sha256",
        "proposed_budget_postimage_sha256", "token_state_before",
        "token_state_after", "intent_sha256",
    }
    _require(set(cas_intent) == fields, "eval CAS intent fields")
    _require(cas_intent.get("schema_version") == "c28f_eval_token_cas_intent_v1", "eval CAS intent schema")
    _require(cas_intent.get("goal_id") == GOAL_ID, "eval CAS intent Goal")
    _require(
        cas_intent.get("token_id") in {"F0_A", "F0_B"}
        and isinstance(cas_intent.get("eval_id"), str)
        and bool(cas_intent["eval_id"])
        and isinstance(cas_intent.get("authority_id"), str)
        and bool(cas_intent["authority_id"])
        and isinstance(cas_intent.get("purpose"), str)
        and bool(cas_intent["purpose"]),
        "eval CAS intent identity",
    )
    _require(
        cas_intent.get("token_state_before") == "UNISSUED"
        and cas_intent.get("token_state_after") == "RESERVED",
        "eval CAS state transition",
    )
    for field in (
        "expected_budget_preimage_sha256",
        "proposed_budget_postimage_sha256",
        "intent_sha256",
    ):
        _require(isinstance(cas_intent.get(field), str) and HEX64.fullmatch(cas_intent[field]), f"eval CAS {field}")
    _require(
        cas_intent["intent_sha256"]
        == semantic_sha256(cas_intent, excluded_fields=("intent_sha256",)),
        "eval CAS intent semantic hash",
    )


def _validate_eval_execution_binding(binding: Mapping[str, Any]) -> None:
    _require(set(binding) == EVAL_EXECUTION_BINDING_FIELDS, "eval execution binding fields")
    for field, digest in binding.items():
        _require(isinstance(digest, str) and HEX64.fullmatch(digest), f"eval execution binding: {field}")


def _eval_transaction_stem(
    cas_intent: Mapping[str, Any],
    execution_binding: Mapping[str, Any],
) -> str:
    seed = bytes_sha256(
        canonical_json_bytes(
            {
                "cas_intent_sha256": cas_intent["intent_sha256"],
                "execution_binding_sha256": semantic_sha256(execution_binding),
            }
        )
    )
    return f"EVAL-TOKEN-{seed[:32]}"


def _read_eval_registry() -> tuple[dict[str, Any], bytes]:
    payload, encoded = _read_canonical_json(CONTROL_ROOT / "eval_token_registry.json")
    _require(isinstance(payload, dict), "eval token registry object")
    return payload, encoded


def _build_eval_reservation_input_record(
    payload: Mapping[str, Any],
    capability_sha256: str,
) -> dict[str, Any]:
    _require(
        capability_sha256 == semantic_sha256(payload),
        "eval reservation capability/payload hash",
    )
    handle = _register_opaque_capability(
        A4EvalReservationInputHandle(
            _OPAQUE_CONTROL_ISSUER_SEAL,
            payload,
        )
    )
    validate_eval_reservation_input_handle(handle)
    base = {
        "schema_version": "c28f_a4_persisted_eval_reservation_input_v1",
        "status": "FSYNCED_CONTROLLER_ISSUED_INPUT",
        "goal_id": GOAL_ID,
        "capability_sha256": capability_sha256,
        "payload": dict(payload),
    }
    return {**base, "record_sha256": semantic_sha256(base)}


def _read_or_install_eval_receipt(
    registry: Mapping[str, Any],
    state: Mapping[str, Any],
    event: Mapping[str, Any],
    lease: WriterLease,
) -> dict[str, Any]:
    expected = _build_eval_phase_receipt(registry, state, event)
    receipt_name = (
        "cas_receipt.json"
        if registry["token_state"] == "RESERVED"
        else "phase_receipt.json"
    )
    path = CONTROL_ROOT / "transactions" / registry["transaction_id"] / receipt_name
    if os.path.lexists(path):
        observed, _encoded = _read_canonical_json(path)
        _require(observed == expected, "persisted eval phase receipt drift")
    else:
        atomic_write_immutable(path, _canonical_file_bytes(expected), lease=lease)
    return expected


def _commit_eval_phase(
    *,
    phase: str,
    state: Mapping[str, Any],
    state_bytes: bytes,
    events: Sequence[Mapping[str, Any]],
    event_journal: bytes,
    registry_payload: Mapping[str, Any],
    state_updates: Mapping[str, Any],
    lease: WriterLease,
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    transaction_id = str(registry_payload["transaction_id"])
    action = {
        "RESERVED": "RESERVE_EVAL_TOKEN",
        "RUNNING": "MARK_EVAL_RUNNING",
        "COMPLETED": "COMPLETE_EVAL_TOKEN",
    }[phase]
    envelope_base = {
        "schema_version": "c28f_a4_control_transition_intent_v1",
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "transaction_id": transaction_id,
        "action": action,
        "result": f"FSYNCED_EVAL_TOKEN_{phase}",
        "parent_state_sha256": state["state_sha256"],
        "parent_event_sha256": events[-1]["event_sha256"],
        "expected_business_sha256": state["expected_goal_delta_sha256"],
        "state_updates": dict(state_updates),
        "registry_name": "eval_token_registry.json",
        "registry_payload": dict(registry_payload),
        "mutation_facts": {
            "token_id": registry_payload["token_id"],
            "eval_id": registry_payload["eval_id"],
            "token_state": phase,
            "cas_intent_sha256": registry_payload["cas_intent_sha256"],
            "execution_binding_sha256": registry_payload[
                "execution_binding_sha256"
            ],
            "model_forward_evaluations": registry_payload[
                "model_forward_evaluations"
            ],
        },
        "input_bindings": {
            "cas_intent": registry_payload["cas_intent_sha256"],
            "authorization": registry_payload["authorization_sha256"],
            "execution_binding": registry_payload["execution_binding_sha256"],
            "budget_preimage": registry_payload["budget_preimage_sha256"],
            "budget_postimage": registry_payload["budget_postimage_sha256"],
            "reservation_input_capability": registry_payload[
                "reservation_input_capability_sha256"
            ],
        },
        "safety_counts": {
            "protected_content_opens": 0,
            "model_forward_evaluations": registry_payload[
                "model_forward_evaluations"
            ],
            "real_data_optimizer_updates": 0,
        },
    }
    envelope = _with_semantic_sha(envelope_base, "transition_intent_sha256")
    transaction_dir = CONTROL_ROOT / "transactions" / transaction_id
    atomic_write_immutable(
        transaction_dir / "transition_intent.json",
        _canonical_file_bytes(envelope),
        lease=lease,
    )
    transition = _commit_enveloped_control_transition(
        lease=lease,
        bootstrap_lease=bootstrap_lease,
        state=state,
        state_bytes=state_bytes,
        events=events,
        event_journal=event_journal,
        envelope=envelope,
    )
    receipt = _build_eval_phase_receipt(
        registry_payload,
        transition["state"],
        transition["event"],
    )
    receipt_name = "cas_receipt.json" if phase == "RESERVED" else "phase_receipt.json"
    atomic_write_immutable(
        transaction_dir / receipt_name,
        _canonical_file_bytes(receipt),
        lease=lease,
    )
    verify_a4_state(bootstrap_lease, active_lease=lease)
    return receipt


def reserve_eval_token(
    *,
    reservation_input_handle: "A4EvalReservationInputHandle",
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Persist the UNISSUED -> RESERVED CAS before any model-forward capability."""

    reservation = validate_eval_reservation_input_handle(
        reservation_input_handle
    )
    cas_intent = dict(reservation["cas_intent"])
    authorization_sha256 = str(reservation["authorization_sha256"])
    execution_binding = dict(reservation["execution_binding"])
    reservation_record = _build_eval_reservation_input_record(
        reservation,
        reservation_input_handle.capability_sha256,
    )
    _validate_eval_cas_intent(cas_intent)
    _validate_eval_execution_binding(execution_binding)
    _require(HEX64.fullmatch(authorization_sha256) is not None, "eval authorization hash")
    bootstrap_lease.assert_active_capability()
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "RESERVE_EVAL_TOKEN",
    ) as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        state, state_bytes, events, event_journal = _current_state_and_events()
        _require(
            reservation["committed_transaction_id"] == state["transaction_id"]
            and reservation["committed_state_sha256"] == state["state_sha256"]
            and reservation["committed_event_sha256"]
            == events[-1]["event_sha256"]
            and reservation["attempt_id"] == state["attempt_id"],
            "eval reservation input is not the current committed tail",
        )
        token_id = str(cas_intent["token_id"])
        eval_id = str(cas_intent["eval_id"])
        if state["eval_token_states"].get(token_id) == "RESERVED":
            registry, _registry_bytes = _read_eval_registry()
            _require(
                registry["eval_id"] == eval_id
                and registry["cas_intent_sha256"] == cas_intent["intent_sha256"]
                and registry["reservation_input_capability_sha256"]
                == reservation_input_handle.capability_sha256,
                "eval token already reserved for a different evaluation",
            )
            receipt = _read_or_install_eval_receipt(registry, state, events[-1], lease)
            verify_a4_state(bootstrap_lease, active_lease=lease)
            return receipt
        _require(state["eval_token_states"].get(token_id) == "UNISSUED", "eval token replay")
        if os.path.lexists(CONTROL_ROOT / "eval_token_registry.json"):
            recovery_registry, _registry_bytes = _read_eval_registry()
            if (
                recovery_registry["token_state"] == "RESERVED"
                and recovery_registry["token_id"] == token_id
                and recovery_registry["eval_id"] == eval_id
            ):
                _require(
                    recovery_registry["cas_intent_sha256"] == cas_intent["intent_sha256"],
                    "partial eval reservation registry drift",
                )
                _require(
                    recovery_registry["reservation_input_capability_sha256"]
                    == reservation_input_handle.capability_sha256,
                    "partial eval reservation input capability drift",
                )
                recovery_states = dict(state["eval_token_states"])
                recovery_states[token_id] = "RESERVED"
                atomic_write_immutable(
                    CONTROL_ROOT
                    / "transactions"
                    / recovery_registry["transaction_id"]
                    / "reservation_input.json",
                    _canonical_file_bytes(reservation_record),
                    lease=lease,
                )
                return _commit_eval_phase(
                    phase="RESERVED",
                    state=state,
                    state_bytes=state_bytes,
                    events=events,
                    event_journal=event_journal,
                    registry_payload=recovery_registry,
                    state_updates={
                        "status": "EVAL_TOKEN_RESERVED",
                        "next_action": "MARK_EVAL_RUNNING",
                        "eval_token_states": recovery_states,
                        "active_eval": {
                            "token_id": token_id,
                            "eval_id": eval_id,
                            "transaction_stem": recovery_registry["transaction_id"].removesuffix("-RESERVE"),
                            "execution_binding_sha256": recovery_registry[
                                "execution_binding_sha256"
                            ],
                        },
                    },
                    lease=lease,
                    bootstrap_lease=bootstrap_lease,
                )
        verify_a4_state(bootstrap_lease, active_lease=lease)
        stem = _eval_transaction_stem(cas_intent, execution_binding)
        transaction_id = f"{stem}-RESERVE"
        _assert_dual_live_capability(bootstrap_lease, lease)
        atomic_write_immutable(
            CONTROL_ROOT
            / "transactions"
            / transaction_id
            / "reservation_input.json",
            _canonical_file_bytes(reservation_record),
            lease=lease,
        )
        registry_payload = {
            "schema_version": "c28f_a4_eval_token_registry_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "transaction_id": transaction_id,
            "token_id": token_id,
            "eval_id": eval_id,
            "run_id": stem,
            "authority_id": cas_intent["authority_id"],
            "purpose": cas_intent["purpose"],
            "token_state": "RESERVED",
            "cas_intent": dict(cas_intent),
            "cas_intent_sha256": cas_intent["intent_sha256"],
            "authorization_sha256": authorization_sha256,
            "budget_preimage_sha256": cas_intent[
                "expected_budget_preimage_sha256"
            ],
            "budget_postimage_sha256": cas_intent[
                "proposed_budget_postimage_sha256"
            ],
            "execution_binding": dict(execution_binding),
            "execution_binding_sha256": semantic_sha256(execution_binding),
            "resume_status": state["status"],
            "resume_action": state["next_action"],
            "previous_registry_sha256": None,
            "previous_phase_receipt_sha256": None,
            "model_forward_evaluations": 0,
            "completion": None,
            "reservation_input_capability_sha256": (
                reservation_input_handle.capability_sha256
            ),
        }
        token_states = dict(state["eval_token_states"])
        token_states[token_id] = "RESERVED"
        return _commit_eval_phase(
            phase="RESERVED",
            state=state,
            state_bytes=state_bytes,
            events=events,
            event_journal=event_journal,
            registry_payload=registry_payload,
            state_updates={
                "status": "EVAL_TOKEN_RESERVED",
                "next_action": "MARK_EVAL_RUNNING",
                "eval_token_states": token_states,
                "active_eval": {
                    "token_id": token_id,
                    "eval_id": eval_id,
                    "transaction_stem": stem,
                    "execution_binding_sha256": semantic_sha256(execution_binding),
                },
            },
            lease=lease,
            bootstrap_lease=bootstrap_lease,
        )


def mark_eval_running(
    *,
    reserved_capability: "A4EvalReservedCapability",
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Persist RESERVED -> RUNNING; a forward remains forbidden before this commit."""

    reserved = validate_eval_reserved_capability(reserved_capability)
    bootstrap_lease.assert_active_capability()
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "MARK_EVAL_RUNNING",
    ) as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        state, state_bytes, events, event_journal = _current_state_and_events()
        registry, registry_bytes = _read_eval_registry()
        immutable_expected = {
            "goal_id": reserved["goal_id"],
            "attempt_id": reserved["attempt_id"],
            "run_id": reserved["run_id"],
            "token_id": reserved["token_id"],
            "eval_id": reserved["eval_id"],
            "execution_binding_sha256": reserved[
                "execution_binding_sha256"
            ],
            "reservation_input_capability_sha256": reserved[
                "reservation_input_capability_sha256"
            ],
        }
        _require(
            all(registry.get(field) == value for field, value in immutable_expected.items()),
            "RESERVED capability/eval registry binding",
        )
        if registry["token_state"] == "RUNNING":
            _require(
                any(
                    event.get("event_sha256")
                    == reserved["reserved_event_sha256"]
                    and event.get("expected_next_state_sha256")
                    == reserved["reserved_state_sha256"]
                    and event.get("transaction_id")
                    == reserved["transaction_id"]
                    for event in events
                ),
                "RUNNING recovery lost RESERVED capability anchor",
            )
            if state["eval_token_states"].get(registry["token_id"]) == "RUNNING":
                receipt = _read_or_install_eval_receipt(registry, state, events[-1], lease)
                verify_a4_state(bootstrap_lease, active_lease=lease)
                return receipt
            _require(
                state["eval_token_states"].get(registry["token_id"]) == "RESERVED",
                "partial RUNNING state preimage",
            )
            recovery_states = dict(state["eval_token_states"])
            recovery_states[registry["token_id"]] = "RUNNING"
            return _commit_eval_phase(
                phase="RUNNING",
                state=state,
                state_bytes=state_bytes,
                events=events,
                event_journal=event_journal,
                registry_payload=registry,
                state_updates={
                    "status": "RUNNING",
                    "next_action": "COMPLETE_EVAL_TOKEN",
                    "eval_token_states": recovery_states,
                    "active_eval": state["active_eval"],
                },
                lease=lease,
                bootstrap_lease=bootstrap_lease,
            )
        _require(
            registry["token_state"] == "RESERVED"
            and state["eval_token_states"].get(registry["token_id"]) == "RESERVED",
            "eval token is not RESERVED",
        )
        _require(
            registry["transaction_id"] == reserved["transaction_id"]
            and state["state_sha256"] == reserved["reserved_state_sha256"]
            and events[-1]["event_sha256"] == reserved["reserved_event_sha256"]
            and bytes_sha256(registry_bytes) == reserved["eval_registry_sha256"],
            "RESERVED capability is not the current exact CAS tail",
        )
        previous_receipt, _encoded = _read_canonical_json(
            CONTROL_ROOT / "transactions" / registry["transaction_id"] / "cas_receipt.json"
        )
        stem = registry["transaction_id"].removesuffix("-RESERVE")
        transaction_id = f"{stem}-RUNNING"
        next_registry = dict(registry)
        next_registry.update(
            {
                "transaction_id": transaction_id,
                "token_state": "RUNNING",
                "previous_registry_sha256": bytes_sha256(registry_bytes),
                "previous_phase_receipt_sha256": previous_receipt["receipt_sha256"],
            }
        )
        token_states = dict(state["eval_token_states"])
        token_states[registry["token_id"]] = "RUNNING"
        return _commit_eval_phase(
            phase="RUNNING",
            state=state,
            state_bytes=state_bytes,
            events=events,
            event_journal=event_journal,
            registry_payload=next_registry,
            state_updates={
                "status": "RUNNING",
                "next_action": "COMPLETE_EVAL_TOKEN",
                "eval_token_states": token_states,
                "active_eval": state["active_eval"],
            },
            lease=lease,
            bootstrap_lease=bootstrap_lease,
        )


def commit_eval_cursor(
    *,
    running_capability: "A4EvalRunningCapability",
    cursor_index: int,
    cursor_sha256: str,
    chunks_sha256: str,
    artifacts_sha256: str,
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Persist one monotonic chunk cursor CAS while the eval token is RUNNING."""

    _require(type(cursor_index) is int and cursor_index >= 0, "eval cursor index")
    running = validate_eval_running_capability(running_capability)
    for digest in (cursor_sha256, chunks_sha256, artifacts_sha256):
        _require(HEX64.fullmatch(digest) is not None, "eval cursor binding hash")
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "COMMIT_EVAL_CURSOR",
    ) as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        state, events, registry = _assert_current_running_capability_locked(
            running_capability
        )
        _require(
            registry["eval_id"] == running["eval_id"]
            and registry["token_state"] == "RUNNING"
            and state["status"] == "RUNNING"
            and events[-1]["action"] == "MARK_EVAL_RUNNING",
            "cursor CAS requires the current RUNNING state/event",
        )
        consumption_path = (
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "forward_capability_consumption.json"
        )
        _require(consumption_path.is_file(), "cursor CAS requires consumed forward capability")
        pointer_path = (
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "eval_cursor.json"
        )
        cursor_dir = pointer_path.parent / "cursor_receipts"
        previous: Optional[str] = None
        pointer_precondition: dict[str, Any]
        if os.path.lexists(pointer_path):
            _cursor_files, _cursor_dirs, latest = _validate_eval_cursor_chain(
                registry,
                state,
                events[-1],
            )
            _require(latest is not None, "cursor pointer lacks tail")
            _require(cursor_index == int(latest["cursor_index"]) + 1, "cursor index is not monotonic")
            previous = str(latest["receipt_sha256"])
            _pointer_bytes, pointer_record = read_regular_bytes(
                pointer_path,
                require_nlink_one=True,
            )
            pointer_precondition = {
                "expected_preimage_sha256": pointer_record["sha256"]
            }
            verify_a4_state(bootstrap_lease, active_lease=lease)
        else:
            _require(cursor_index == 0, "first cursor index must be zero")
            pointer_precondition = {"precondition": "MUST_BE_ABSENT"}
        receipt = _build_eval_cursor_receipt(
            registry,
            state,
            events[-1],
            cursor_index=cursor_index,
            cursor_sha256=cursor_sha256,
            chunks_sha256=chunks_sha256,
            artifacts_sha256=artifacts_sha256,
            previous_cursor_receipt_sha256=previous,
        )
        sidecar = cursor_dir / f"{cursor_index:06d}_{receipt['receipt_sha256']}.json"
        if os.path.lexists(cursor_dir) and not os.path.lexists(pointer_path):
            _require(cursor_dir.is_dir() and not cursor_dir.is_symlink(), "partial cursor directory")
            with os.scandir(cursor_dir) as iterator:
                partial = sorted(entry.name for entry in iterator)
            _require(
                partial in ([], [sidecar.name]),
                "partial cursor CAS namespace differs from deterministic recovery",
            )
            if partial:
                existing, _encoded = _read_canonical_json(sidecar)
                _require(existing == receipt, "partial cursor sidecar drift")
        elif not os.path.lexists(pointer_path):
            verify_a4_state(bootstrap_lease, active_lease=lease)
        atomic_write_immutable(sidecar, _canonical_file_bytes(receipt), lease=lease)
        _assert_dual_live_capability(bootstrap_lease, lease)
        _validate_supersession_receipt(bootstrap_lease)
        atomic_write_bytes(
            pointer_path,
            _canonical_file_bytes(receipt),
            lease=lease,
            **pointer_precondition,
        )
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return receipt


def complete_eval_token(
    *,
    cursor_capability: "A4EvalCursorCapability",
    bootstrap_lease: BootstrapLease,
) -> dict[str, Any]:
    """Persist RUNNING -> COMPLETED with exact cursor/chunk/artifact bindings."""

    cursor = validate_eval_cursor_capability(cursor_capability)
    running_anchor = dict(cursor["running_anchor"])
    completion = {
        "cursor_sha256": cursor["cursor_sha256"],
        "chunks_sha256": cursor["chunks_sha256"],
        "artifacts_sha256": cursor["artifacts_sha256"],
        "model_forward_evaluations": 1,
    }
    bootstrap_lease.assert_active_capability()
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "COMPLETE_EVAL_TOKEN",
    ) as lease:
        _recover_pending_state_pointer(lease, bootstrap_lease)
        state, state_bytes, events, event_journal = _current_state_and_events()
        registry, registry_bytes = _read_eval_registry()
        _require(
            registry["eval_id"] == running_anchor["eval_id"]
            and registry["token_id"] == running_anchor["token_id"]
            and registry["run_id"] == running_anchor["run_id"]
            and registry["execution_binding_sha256"]
            == running_anchor["execution_binding_sha256"]
            and registry["reservation_input_capability_sha256"]
            == running_anchor["reservation_input_capability_sha256"],
            "completion cursor/RUNNING lineage",
        )
        if registry["token_state"] == "COMPLETED":
            _require(registry["completion"] == dict(completion), "idempotent completion drift")
            historical_cursor, _historical_bytes = _read_canonical_json(
                CONTROL_ROOT
                / "transactions"
                / running_anchor["transaction_id"]
                / "eval_cursor.json"
            )
            _require(
                isinstance(historical_cursor, dict)
                and historical_cursor.get("receipt_sha256")
                == cursor["cursor_receipt_sha256"]
                and historical_cursor.get("cursor_index")
                == cursor["cursor_index"]
                and historical_cursor.get("cursor_sha256")
                == cursor["cursor_sha256"]
                and historical_cursor.get("chunks_sha256")
                == cursor["chunks_sha256"]
                and historical_cursor.get("artifacts_sha256")
                == cursor["artifacts_sha256"],
                "idempotent completion historical cursor drift",
            )
            _consume_registered_capability_once(
                cursor_capability,
                operation="COMPLETE_EVAL_TOKEN",
            )
            if state["eval_token_states"].get(registry["token_id"]) == "COMPLETED":
                receipt = _read_or_install_eval_receipt(registry, state, events[-1], lease)
                verify_a4_state(bootstrap_lease, active_lease=lease)
                return receipt
            _require(
                state["eval_token_states"].get(registry["token_id"]) == "RUNNING",
                "partial COMPLETED state preimage",
            )
            running_events = [
                event
                for event in events
                if event.get("transaction_id")
                == running_anchor["transaction_id"]
                and event.get("action") == "MARK_EVAL_RUNNING"
                and event.get("result") == "FSYNCED_EVAL_TOKEN_RUNNING"
            ]
            _require(
                len(running_events) == 1,
                "partial completion immutable RUNNING event",
            )
            running_event = running_events[0]
            running_registry_sha = running_event["output_hashes"].get(
                "eval_token_registry.json"
            )
            _require(
                isinstance(running_registry_sha, str)
                and HEX64.fullmatch(running_registry_sha),
                "partial completion RUNNING registry hash",
            )
            running_registry_bytes, _record = read_regular_bytes(
                CONTROL_ROOT
                / "registry_records"
                / (
                    f"{int(running_event['seq']):06d}_eval_token_registry_"
                    f"{running_registry_sha}.json"
                ),
                require_nlink_one=True,
            )
            running_registry = json.loads(running_registry_bytes.decode("utf-8", "strict"))
            _require(
                running_registry_bytes == _canonical_file_bytes(running_registry),
                "partial completion RUNNING registry canonical",
            )
            running_state, running_event, _running_position = (
                _active_eval_running_anchor(
                    state=state,
                    events=events,
                    registry=running_registry,
                )
            )
            _require(
                registry.get("previous_registry_sha256")
                == running_registry_sha
                == bytes_sha256(running_registry_bytes)
                and running_state["state_sha256"]
                == running_anchor["running_state_sha256"]
                and running_event["event_sha256"]
                == running_anchor["running_event_sha256"],
                "partial completion immutable RUNNING lineage",
            )
            _cursor_files, _cursor_dirs, latest_cursor = _validate_eval_cursor_chain(
                running_registry,
                running_state,
                running_event,
            )
            _require(
                latest_cursor is not None
                and latest_cursor["cursor_sha256"] == completion["cursor_sha256"]
                and latest_cursor["chunks_sha256"] == completion["chunks_sha256"]
                and latest_cursor["artifacts_sha256"] == completion["artifacts_sha256"],
                "partial completion cursor tail",
            )
            recovery_states = dict(state["eval_token_states"])
            recovery_states[registry["token_id"]] = "COMPLETED"
            return _commit_eval_phase(
                phase="COMPLETED",
                state=state,
                state_bytes=state_bytes,
                events=events,
                event_journal=event_journal,
                registry_payload=registry,
                state_updates={
                    "status": registry["resume_status"],
                    "next_action": registry["resume_action"],
                    "eval_token_states": recovery_states,
                    "active_eval": None,
                    "model_forward_evaluations": int(
                        state.get("model_forward_evaluations", 0)
                    )
                    + 1,
                },
                lease=lease,
                bootstrap_lease=bootstrap_lease,
            )
        _require(
            registry["token_state"] == "RUNNING"
            and state["eval_token_states"].get(registry["token_id"]) == "RUNNING",
            "eval token is not RUNNING",
        )
        running_state, running_event, _running_position = (
            _active_eval_running_anchor(
                state=state,
                events=events,
                registry=registry,
            )
        )
        _cursor_files, _cursor_dirs, latest_cursor = _validate_eval_cursor_chain(
            registry, running_state, running_event,
        )
        _require(
            latest_cursor is not None
            and latest_cursor["receipt_sha256"]
            == cursor["cursor_receipt_sha256"]
            and running_state["state_sha256"]
            == running_anchor["running_state_sha256"]
            and running_event["event_sha256"]
            == running_anchor["running_event_sha256"]
            and latest_cursor["cursor_sha256"] == completion["cursor_sha256"]
            and latest_cursor["chunks_sha256"] == completion["chunks_sha256"]
            and latest_cursor["artifacts_sha256"] == completion["artifacts_sha256"],
            "completion differs from committed cursor tail",
        )
        previous_receipt, _encoded = _read_canonical_json(
            CONTROL_ROOT / "transactions" / registry["transaction_id"] / "phase_receipt.json"
        )
        stem = registry["transaction_id"].removesuffix("-RUNNING")
        transaction_id = f"{stem}-COMPLETE"
        next_registry = dict(registry)
        next_registry.update(
            {
                "transaction_id": transaction_id,
                "token_state": "COMPLETED",
                "previous_registry_sha256": bytes_sha256(registry_bytes),
                "previous_phase_receipt_sha256": previous_receipt["receipt_sha256"],
                "model_forward_evaluations": 1,
                "completion": dict(completion),
            }
        )
        token_states = dict(state["eval_token_states"])
        token_states[registry["token_id"]] = "COMPLETED"
        _consume_registered_capability_once(
            cursor_capability,
            operation="COMPLETE_EVAL_TOKEN",
        )
        return _commit_eval_phase(
            phase="COMPLETED",
            state=state,
            state_bytes=state_bytes,
            events=events,
            event_journal=event_journal,
            registry_payload=next_registry,
            state_updates={
                "status": registry["resume_status"],
                "next_action": registry["resume_action"],
                "eval_token_states": token_states,
                "active_eval": None,
                "model_forward_evaluations": int(
                    state.get("model_forward_evaluations", 0)
                )
                + 1,
            },
            lease=lease,
            bootstrap_lease=bootstrap_lease,
        )


def assert_running_state_event_committed(
    *,
    bootstrap_lease: BootstrapLease,
    eval_id: Optional[str] = None,
) -> str:
    """Return the stable RUNNING event SHA only after full persisted-chain verification."""

    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ASSERT_EVAL_RUNNING_COMMIT",
    ) as lease:
        verified = verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        registry, _registry_bytes = _read_eval_registry()
        running_state, running_event, _running_position = (
            _active_eval_running_anchor(
                state=state,
                events=events,
                registry=registry,
            )
        )
        _require(
            (eval_id is None or registry["eval_id"] == eval_id)
            and verified["state_sha256"] == state["state_sha256"],
            "RUNNING state/event is not the committed active chain",
        )
        consumption_path = (
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "forward_capability_consumption.json"
        )
        _require(consumption_path.is_file(), "forward capability has not been fsynced as consumed")
        consumption, _encoded = _read_canonical_json(consumption_path)
        _require(
            consumption
            == _build_forward_consumption_receipt(
                registry,
                running_state,
                running_event,
                authority_binding_sha256=consumption.get(
                    "authority_binding_sha256"
                ),
                consumer_nonce_sha256=consumption.get(
                    "consumer_nonce_sha256"
                ),
            ),
            "forward consumption does not bind RUNNING event",
        )
        return str(running_event["event_sha256"])


def _active_eval_running_anchor(
    *,
    state: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    registry: Mapping[str, Any],
) -> tuple[dict[str, Any], dict[str, Any], int]:
    """Resolve the immutable RUNNING anchor across online code-only tails."""

    matches = [
        (index, dict(event))
        for index, event in enumerate(events)
        if event.get("transaction_id") == registry.get("transaction_id")
        and event.get("action") == "MARK_EVAL_RUNNING"
        and event.get("result") == "FSYNCED_EVAL_TOKEN_RUNNING"
    ]
    active_eval = state.get("active_eval")
    _require(
        len(matches) == 1
        and isinstance(active_eval, dict)
        and state.get("status") == "RUNNING"
        and state.get("next_action") == "COMPLETE_EVAL_TOKEN"
        and registry.get("token_state") == "RUNNING"
        and registry.get("completion") is None
        and registry.get("model_forward_evaluations") == 0
        and state.get("eval_token_states", {}).get(registry.get("token_id"))
        == "RUNNING"
        and active_eval.get("token_id") == registry.get("token_id")
        and active_eval.get("eval_id") == registry.get("eval_id")
        and active_eval.get("transaction_stem") == registry.get("run_id")
        and active_eval.get("execution_binding_sha256")
        == registry.get("execution_binding_sha256")
        and bool(events)
        and events[-1].get("expected_next_state_sha256")
        == state.get("state_sha256"),
        "active eval RUNNING control identity",
    )
    position, running_event = matches[0]
    running_state, _running_state_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "state_records"
        / (
            "%06d_%s.json"
            % (position, running_event["expected_next_state_sha256"])
        )
    )
    _require(
        isinstance(running_state, dict)
        and running_state.get("transaction_id")
        == registry.get("transaction_id")
        and running_state.get("state_sha256")
        == running_event["expected_next_state_sha256"]
        and running_state.get("status") == "RUNNING"
        and running_state.get("next_action") == "COMPLETE_EVAL_TOKEN"
        and running_state.get("eval_token_states", {}).get(
            registry.get("token_id")
        ) == "RUNNING",
        "active eval immutable RUNNING state/event anchor",
    )
    intervening = events[position + 1 :]
    _require(
        all(
            event.get("action") == "COMMIT_REVIEWED_CODE_CHANGE"
            and event.get("result")
            == "COMMITTED_USER_AUTHORIZED_ONLINE_EXISTING_FILE_POSTIMAGE"
            and isinstance(event.get("transaction_id"), str)
            and CODE_CHANGE_TXN_RE.fullmatch(event["transaction_id"])
            is not None
            for event in intervening
        ),
        "active eval RUNNING anchor may advance through online code only",
    )
    return dict(running_state), running_event, position


def _assert_pre_forward_active_eval_online_maintenance(
    *,
    state: Mapping[str, Any],
    events: Sequence[Mapping[str, Any]],
    registry: Mapping[str, Any],
) -> None:
    """Permit maintenance only before any model-forward evidence exists."""

    running_state, running_event, _running_position = _active_eval_running_anchor(
        state=state,
        events=events,
        registry=registry,
    )
    transaction_dir = (
        CONTROL_ROOT / "transactions" / str(registry["transaction_id"])
    )
    reservation_record, _reservation_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "transactions"
        / (str(registry["run_id"]) + "-RESERVE")
        / "reservation_input.json"
    )
    reservation = reservation_record.get("payload")
    source_lineage = (
        reservation.get("source_lineage")
        if isinstance(reservation, dict)
        else None
    )
    origin_transaction_id = (
        source_lineage.get(
            "controller_forward_authority_origin_transaction_id"
        )
        if isinstance(source_lineage, dict)
        else None
    )
    _require(
        isinstance(origin_transaction_id, str)
        and CODE_CHANGE_TXN_RE.fullmatch(origin_transaction_id) is not None,
        "active eval online maintenance authority origin transaction",
    )
    authority_record, _authority_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "transactions"
        / origin_transaction_id
        / "controller_forward_authority.json",
        max_bytes=1024 * 1024 * 1024,
    )
    authority_payload, projection = (
        _validate_persisted_controller_forward_authority_record(
            authority_record,
            origin_transaction_id=origin_transaction_id,
        )
    )
    material = (
        projection.get("authority_binding_material")
        if isinstance(projection, dict)
        else None
    )
    output_root = material.get("output_root") if isinstance(material, dict) else None
    _require(
        isinstance(reservation, dict)
        and isinstance(source_lineage, dict)
        and reservation_record.get("capability_sha256")
        == registry.get("reservation_input_capability_sha256")
        == semantic_sha256(reservation)
        and reservation.get("token_id") == registry.get("token_id")
        and reservation.get("eval_id") == registry.get("eval_id")
        and reservation.get("execution_binding")
        == registry.get("execution_binding")
        and source_lineage.get(
            "controller_forward_authority_handle_sha256"
        )
        == authority_record.get("capability_sha256")
        == projection.get("forward_authority_handle_sha256")
        and authority_payload.get("attempt_id") == state.get("attempt_id")
        and authority_payload.get("token_id") == registry.get("token_id")
        and authority_payload.get("authority_binding_sha256")
        == registry.get("execution_binding", {}).get(
            "authority_binding_sha256"
        )
        and isinstance(output_root, dict)
        and isinstance(output_root.get("path"), str)
        and reservation.get("stage") in {"G3_F0_A", "G5_F0_B"},
        "active eval online maintenance persisted run descriptor",
    )
    run_root = (
        Path(output_root["path"])
        / str(reservation["stage"])
        / str(state["attempt_id"])
        / str(registry["run_id"])
    )
    consumption_path = transaction_dir / "forward_capability_consumption.json"
    if not os.path.lexists(consumption_path):
        _require(
            not os.path.lexists(run_root)
            and all(
                not os.path.lexists(path)
                for path in (
                    transaction_dir / "eval_cursor.json",
                    transaction_dir / "cursor_receipts",
                    transaction_dir / "lmdb_batch_receipts",
                )
            ),
            "active eval online maintenance requires pristine unconsumed runtime",
        )
        return
    consumption, _consumption_bytes = _read_canonical_json(consumption_path)
    _require(
        isinstance(consumption, dict)
        and consumption
        == _build_forward_consumption_receipt(
            registry,
            running_state,
            running_event,
            authority_binding_sha256=consumption.get(
                "authority_binding_sha256"
            ),
            consumer_nonce_sha256=consumption.get("consumer_nonce_sha256"),
        )
        and consumption.get("authority_binding_sha256")
        == registry["execution_binding"]["authority_binding_sha256"],
        "active eval online maintenance consumed capability binding",
    )
    _assert_safe_path_chain(run_root)
    _require(
        run_root.is_dir() and not run_root.is_symlink(),
        "active eval online maintenance initial run root",
    )
    empty_rows_sha256 = bytes_sha256(canonical_json_bytes([]))
    snapshot_name = f"observations_00000000_{empty_rows_sha256}.json"
    with os.scandir(run_root) as iterator:
        run_entries = {entry.name: entry for entry in iterator}
    initial_run_names = {
        "forward_run_receipt.json",
        snapshot_name,
        "query_chunks",
    }
    failed_pre_forward_names = initial_run_names | {
        "forward_observations.json",
        "heartbeat.json",
    }
    _require(
        frozenset(run_entries)
        in {frozenset(initial_run_names), frozenset(failed_pre_forward_names)}
        and run_entries["forward_run_receipt.json"].is_file(
            follow_symlinks=False
        )
        and not run_entries["forward_run_receipt.json"].is_symlink()
        and run_entries[snapshot_name].is_file(follow_symlinks=False)
        and not run_entries[snapshot_name].is_symlink()
        and run_entries["query_chunks"].is_dir(follow_symlinks=False)
        and not run_entries["query_chunks"].is_symlink(),
        "active eval online maintenance exact initial run namespace",
    )
    has_failed_pre_forward_evidence = (
        set(run_entries) == failed_pre_forward_names
    )
    if has_failed_pre_forward_evidence:
        _require(
            run_entries["forward_observations.json"].is_file(
                follow_symlinks=False
            )
            and not run_entries["forward_observations.json"].is_symlink()
            and run_entries["heartbeat.json"].is_file(
                follow_symlinks=False
            )
            and not run_entries["heartbeat.json"].is_symlink(),
            "active eval online maintenance failure evidence file types",
        )
    with os.scandir(run_root / "query_chunks") as iterator:
        query_chunk_names = [entry.name for entry in iterator]
    _require(
        query_chunk_names == [],
        "active eval online maintenance requires empty query chunks",
    )
    run_receipt, _run_receipt_bytes, _run_receipt_record = (
        _read_canonical_json_without_newline(
            run_root / "forward_run_receipt.json"
        )
    )
    exact_run_fields = {
        "schema_version", "status", "goal_id", "authority_id", "run_id",
        "stage", "purpose", "token_id", "eval_id",
        "forward_manifest_sha256", "input_identity_sha256",
        "query_identity_sha256", "query_types_sha256", "query_rows_sha256",
        "authority_binding_sha256", "token_snapshot_sha256",
        "gpu0_identity_sha256", "running_capability_sha256",
        "reservation_input_capability_sha256",
        "controller_authority_binding_sha256", "query_count",
        "next_query_index", "result_chunks", "encoded_cache_receipt_sha256",
        "encoded_cache_fingerprint", "observation_event_count",
        "observation_ledger_sha256", "teacher_candidate_count",
        "teacher_forward_count", "gt_support_count", "gt_append_count",
        "optimizer_update_count", "receipt_sha256",
    }
    query_identity = authority_payload["query_identity"]
    manifest = projection["manifest"]
    _require(
        isinstance(run_receipt, dict)
        and set(run_receipt) == exact_run_fields
        and run_receipt.get("schema_version")
        == "c28f_v5_a4_forward_run_receipt_v1"
        and run_receipt.get("receipt_sha256")
        == semantic_sha256(
            run_receipt,
            excluded_fields=("receipt_sha256",),
        )
        and run_receipt.get("status") == "RUNNING"
        and run_receipt.get("goal_id") == GOAL_ID
        and run_receipt.get("authority_id") == registry["authority_id"]
        and run_receipt.get("run_id") == registry["run_id"]
        and run_receipt.get("stage") == reservation["stage"]
        and run_receipt.get("purpose") == registry["purpose"]
        and run_receipt.get("token_id") == registry["token_id"]
        and run_receipt.get("eval_id") == registry["eval_id"]
        and run_receipt.get("forward_manifest_sha256")
        == registry["execution_binding"]["forward_manifest_sha256"]
        and run_receipt.get("input_identity_sha256")
        == registry["execution_binding"]["input_identity_sha256"]
        and run_receipt.get("authority_binding_sha256")
        == registry["execution_binding"]["authority_binding_sha256"]
        and run_receipt.get("query_identity_sha256")
        == semantic_sha256(query_identity)
        and run_receipt.get("query_types_sha256")
        == query_identity["query_types_sha256"]
        and run_receipt.get("query_rows_sha256")
        == query_identity["query_rows_sha256"]
        and run_receipt.get("query_count") == query_identity["query_count"]
        and run_receipt.get("token_snapshot_sha256")
        == bytes_sha256(_canonical_file_bytes(registry))
        and run_receipt.get("gpu0_identity_sha256")
        == manifest["gpu0_identity"]["semantic_sha256"]
        and run_receipt.get("reservation_input_capability_sha256")
        == registry["reservation_input_capability_sha256"]
        and isinstance(run_receipt.get("running_capability_sha256"), str)
        and HEX64.fullmatch(run_receipt["running_capability_sha256"])
        is not None
        and isinstance(
            run_receipt.get("controller_authority_binding_sha256"), str
        )
        and HEX64.fullmatch(
            run_receipt["controller_authority_binding_sha256"]
        )
        is not None
        and run_receipt.get("next_query_index") == 0
        and run_receipt.get("result_chunks") == []
        and run_receipt.get("encoded_cache_receipt_sha256") is None
        and run_receipt.get("encoded_cache_fingerprint") is None
        and run_receipt.get("observation_event_count") == 0
        and run_receipt.get("observation_ledger_sha256")
        == empty_rows_sha256
        and all(
            run_receipt.get(field) == 0
            for field in (
                "teacher_candidate_count", "teacher_forward_count",
                "gt_support_count", "gt_append_count", "optimizer_update_count",
            )
        ),
        "active eval online maintenance exact initial run receipt",
    )
    snapshot, snapshot_bytes, _snapshot_record = (
        _read_canonical_json_without_newline(run_root / snapshot_name)
    )
    _require(
        isinstance(snapshot, dict)
        and set(snapshot)
        == {
            "schema_version", "run_id", "capability_id", "event_count",
            "rows_sha256", "rows", "snapshot_sha256",
        }
        and snapshot.get("schema_version")
        == "c28f_v5_a4_forward_observation_snapshot_v1"
        and snapshot.get("run_id") == registry["run_id"]
        and isinstance(snapshot.get("capability_id"), str)
        and HEX64.fullmatch(snapshot["capability_id"]) is not None
        and snapshot.get("event_count") == 0
        and snapshot.get("rows_sha256") == empty_rows_sha256
        and snapshot.get("rows") == []
        and snapshot.get("snapshot_sha256")
        == semantic_sha256(
            snapshot,
            excluded_fields=("snapshot_sha256",),
        ),
        "active eval online maintenance empty observation snapshot",
    )
    if has_failed_pre_forward_evidence:
        heartbeat, _heartbeat_bytes, _heartbeat_record = (
            _read_canonical_json_without_newline(run_root / "heartbeat.json")
        )
        _require(
            isinstance(heartbeat, dict)
            and set(heartbeat)
            == {
                "schema_version", "phase", "cursor", "token_id", "eval_id",
                "run_id", "run_receipt_sha256", "heartbeat_sha256",
            }
            and heartbeat.get("schema_version")
            == "c28f_v5_a4_forward_heartbeat_v1"
            and heartbeat.get("phase") == "RUNNING"
            and heartbeat.get("cursor") == 0
            and heartbeat.get("token_id") == registry["token_id"]
            and heartbeat.get("eval_id") == registry["eval_id"]
            and heartbeat.get("run_id") == registry["run_id"]
            and heartbeat.get("run_receipt_sha256")
            == run_receipt["receipt_sha256"]
            and heartbeat.get("heartbeat_sha256")
            == semantic_sha256(
                heartbeat,
                excluded_fields=("heartbeat_sha256",),
            ),
            "active eval online maintenance cursor-zero heartbeat",
        )
        failure_ledger, _failure_ledger_bytes, _failure_ledger_record = (
            _read_canonical_json_without_newline(
                run_root / "forward_observations.json"
            )
        )
        failure_rows = (
            failure_ledger.get("rows")
            if isinstance(failure_ledger, dict)
            else None
        )
        expected_failure_events = [
            "GPU0_PHYSICAL_BINDING_VERIFIED",
            "CHECKPOINT_MODEL_LOADED",
            "LMDB_ENV_OPENED",
            "LMDB_SNAPSHOT_TRANSACTION_OPENED",
            "LMDB_ENV_OPENED",
            "LMDB_SNAPSHOT_TRANSACTION_OPENED",
            "LMDB_VALUE_READ",
            "LMDB_VALUE_DECODED",
            "LMDB_VALUE_READ",
        ]
        _require(
            isinstance(failure_ledger, dict)
            and set(failure_ledger)
            == {
                "schema_version", "run_id", "capability_id", "event_count",
                "rows", "ledger_sha256",
            }
            and failure_ledger.get("schema_version")
            == "c28f_v5_a4_forward_observation_ledger_v1"
            and failure_ledger.get("run_id") == registry["run_id"]
            and failure_ledger.get("capability_id")
            == snapshot["capability_id"]
            and failure_ledger.get("event_count") == 9
            and isinstance(failure_rows, list)
            and len(failure_rows) == 9
            and all(isinstance(row, dict) for row in failure_rows)
            and [row.get("event_type") for row in failure_rows]
            == expected_failure_events
            and failure_ledger.get("ledger_sha256")
            == semantic_sha256(
                failure_ledger,
                excluded_fields=("ledger_sha256",),
            ),
            "active eval online maintenance exact pre-forward failure ledger",
        )
        previous_failure_event: Optional[str] = None
        exact_failure_row_fields = {
            "schema_version", "run_id", "token_id", "eval_id", "seq",
            "event_type", "counters", "details", "previous_event_sha256",
            "event_sha256",
        }
        exact_failure_counter_fields = {
            "content_open_count", "content_bytes_read",
            "lmdb_transaction_open_count", "model_forward_count",
        }
        for offset, row in enumerate(failure_rows, start=1):
            counters = row.get("counters") if isinstance(row, dict) else None
            _require(
                isinstance(row, dict)
                and set(row) == exact_failure_row_fields
                and row.get("schema_version")
                == "c28f_v5_a4_forward_observation_v1"
                and row.get("run_id") == registry["run_id"]
                and row.get("token_id") == registry["token_id"]
                and row.get("eval_id") == registry["eval_id"]
                and row.get("seq") == offset
                and row.get("previous_event_sha256")
                == previous_failure_event
                and isinstance(counters, dict)
                and set(counters) == exact_failure_counter_fields
                and all(
                    type(value) is int and value >= 0
                    for value in counters.values()
                )
                and counters["model_forward_count"] == 0
                and isinstance(row.get("details"), dict)
                and row.get("event_sha256")
                == semantic_sha256(
                    row,
                    excluded_fields=("event_sha256",),
                ),
                "active eval online maintenance pre-forward failure row",
            )
            previous_failure_event = row["event_sha256"]
    _cursor_files, _cursor_directories, latest_cursor = (
        _validate_eval_cursor_chain(
            registry,
            running_state,
            running_event,
        )
    )
    expected_artifacts_sha256 = bytes_sha256(
        canonical_json_bytes(
            [
                {
                    "artifact_name": "forward_observation_ledger",
                    "artifact_sha256": bytes_sha256(snapshot_bytes),
                    "semantic_sha256": empty_rows_sha256,
                }
            ]
        )
    )
    _require(
        latest_cursor is None
        or (
            latest_cursor.get("cursor_index") == 0
            and latest_cursor.get("cursor_sha256")
            == run_receipt["receipt_sha256"]
            and latest_cursor.get("chunks_sha256") == empty_rows_sha256
            and latest_cursor.get("artifacts_sha256")
            == expected_artifacts_sha256
        ),
        "active eval online maintenance requires exact empty cursor zero",
    )
    _lmdb_files, _lmdb_directories, lmdb_receipts = (
        _validate_lmdb_batch_chain(
            registry,
            running_state,
            running_event,
        )
    )
    _require(
        len(lmdb_receipts) <= 2
        and {receipt["source_id"] for receipt in lmdb_receipts}
        <= {"visual_lmdb", "subtitle_lmdb"},
        "active eval online maintenance permits only video cache LMDB batches",
    )
    cache_root = material.get("cache_root")
    cache_fingerprint = projection.get("encoded_cache_fingerprint")
    cache_path = (
        Path(cache_root["path"])
        / "encoded_corpus"
        / cache_fingerprint
        if isinstance(cache_root, dict)
        and isinstance(cache_root.get("path"), str)
        and isinstance(cache_fingerprint, str)
        else None
    )
    _require(
        isinstance(cache_root, dict)
        and isinstance(cache_root.get("path"), str)
        and isinstance(cache_fingerprint, str)
        and HEX64.fullmatch(cache_fingerprint) is not None
        and isinstance(cache_path, Path),
        "active eval online maintenance encoded cache descriptor",
    )
    if os.path.lexists(cache_path):
        _assert_safe_path_chain(cache_path)
        _require(
            cache_path.is_dir() and not cache_path.is_symlink(),
            "active eval online maintenance encoded cache directory",
        )
        with os.scandir(cache_path) as iterator:
            cache_names = [entry.name for entry in iterator]
        _require(
            cache_names == [],
            "active eval online maintenance requires empty encoded cache",
        )


def assert_fsynced_control_chain(
    *,
    bootstrap_lease: BootstrapLease,
    authority_binding_sha256: str,
    forward_manifest_sha256: str,
    input_identity_sha256: str,
    checkpoint_sha256: str,
    split_manifest_sha256: str,
    corpus_manifest_sha256: str,
    evaluator_sha256: str,
    goal_id: str,
    authority_id: str,
    stage: str,
    purpose: str,
    attempt_id: str,
) -> str:
    """Bind a forward request to the current fsynced RUNNING control chain."""

    for digest in (
        authority_binding_sha256,
        forward_manifest_sha256,
        input_identity_sha256,
        checkpoint_sha256,
        split_manifest_sha256,
        corpus_manifest_sha256,
        evaluator_sha256,
    ):
        _require(HEX64.fullmatch(digest) is not None, "forward control binding hash")
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ASSERT_FSYNCED_FORWARD_CONTROL_CHAIN",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        registry, registry_bytes = _read_eval_registry()
        running_state, running_event, _running_position = (
            _active_eval_running_anchor(
                state=state,
                events=events,
                registry=registry,
            )
        )
        binding = registry["execution_binding"]
        expected_stage = {
            "F0_A": "G3_F0_A",
            "F0_B": "G5_F0_B",
        }.get(registry.get("token_id"))
        _require(
            goal_id == GOAL_ID
            and attempt_id == state["attempt_id"]
            and authority_id == registry["authority_id"]
            and purpose == registry["purpose"]
            and stage == expected_stage
            and binding["authority_binding_sha256"] == authority_binding_sha256
            and binding["forward_manifest_sha256"] == forward_manifest_sha256
            and binding["input_identity_sha256"] == input_identity_sha256,
            "forward request differs from persisted RUNNING authority",
        )
        _require(
            binding["checkpoint_sha256"] == checkpoint_sha256
            and binding["split_manifest_sha256"] == split_manifest_sha256
            and binding["corpus_manifest_sha256"] == corpus_manifest_sha256
            and binding["evaluator_sha256"] == evaluator_sha256,
            "forward request differs from persisted RUNNING authority",
        )
        return semantic_sha256(
            {
                "state_sha256": running_state["state_sha256"],
                "event_sha256": running_event["event_sha256"],
                "eval_registry_file_sha256": bytes_sha256(registry_bytes),
                "execution_binding_sha256": registry["execution_binding_sha256"],
            }
        )


def consume_forward_capability_once(
    *,
    bootstrap_lease: BootstrapLease,
    authority_binding_sha256: str,
    consumer_nonce_sha256: str,
) -> str:
    """Persist exactly one consumer nonce against the committed RUNNING state/event."""

    _require(HEX64.fullmatch(authority_binding_sha256) is not None, "forward authority binding")
    _require(HEX64.fullmatch(consumer_nonce_sha256) is not None, "forward consumer nonce")
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "CONSUME_FORWARD_CAPABILITY_ONCE",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        registry, _registry_bytes = _read_eval_registry()
        running_state, running_event, _running_position = (
            _active_eval_running_anchor(
                state=state,
                events=events,
                registry=registry,
            )
        )
        _require(
            registry["execution_binding"]["authority_binding_sha256"]
            == authority_binding_sha256,
            "forward capability is not a matching RUNNING capability",
        )
        receipt = _build_forward_consumption_receipt(
            registry,
            running_state,
            running_event,
            authority_binding_sha256=authority_binding_sha256,
            consumer_nonce_sha256=consumer_nonce_sha256,
        )
        path = (
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "forward_capability_consumption.json"
        )
        if os.path.lexists(path):
            existing, _encoded = _read_canonical_json(path)
            _require(
                existing == receipt,
                "forward capability already consumed with a different nonce or RUNNING anchor",
            )
            return str(existing["receipt_sha256"])
        _assert_dual_live_capability(bootstrap_lease, lease)
        atomic_write_immutable(path, _canonical_file_bytes(receipt), lease=lease)
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return str(receipt["receipt_sha256"])


def _validate_lmdb_batch_request(
    *,
    source_id: str,
    source_identity_sha256: str,
    key_manifest_sha256: str,
    key_set_sha256: str,
    source_manifest_sha256: str,
    batch_sha256: str,
    key_count: int,
    shared_ledger_tail_sha256: str,
) -> dict[str, Any]:
    _require(
        isinstance(source_id, str)
        and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}", source_id)
        is not None,
        "LMDB source ID",
    )
    hashes = {
        "source_identity_sha256": source_identity_sha256,
        "key_manifest_sha256": key_manifest_sha256,
        "key_set_sha256": key_set_sha256,
        "source_manifest_sha256": source_manifest_sha256,
        "batch_sha256": batch_sha256,
        "shared_ledger_tail_sha256": shared_ledger_tail_sha256,
    }
    _require(
        all(isinstance(value, str) and HEX64.fullmatch(value) for value in hashes.values()),
        "LMDB batch request hashes",
    )
    _require(type(key_count) is int and 0 < key_count <= 100_000_000, "LMDB key count")
    return {
        "source_id": source_id,
        **hashes,
        "key_count": key_count,
    }


def _assert_current_running_capability_locked(
    running_capability: "A4EvalRunningCapability",
) -> tuple[dict[str, Any], list[dict[str, Any]], dict[str, Any]]:
    running = validate_eval_running_capability(running_capability)
    state, _state_bytes, events, _journal = _current_state_and_events()
    registry, registry_bytes = _read_eval_registry()
    running_state, running_event, running_position = (
        _active_eval_running_anchor(
            state=state,
            events=events,
            registry=registry,
        )
    )
    expected = {
        "goal_id": GOAL_ID,
        "attempt_id": state["attempt_id"],
        "run_id": registry["run_id"],
        "token_id": registry["token_id"],
        "eval_id": registry["eval_id"],
        "transaction_id": registry["transaction_id"],
        "running_state_sha256": running_state["state_sha256"],
        "running_event_sha256": running_event["event_sha256"],
        "eval_registry_sha256": bytes_sha256(registry_bytes),
        "execution_binding_sha256": registry["execution_binding_sha256"],
    }
    _require(
        all(running.get(field) == value for field, value in expected.items()),
        "LMDB RUNNING capability is not the current control tail",
    )
    consumption_path = (
        CONTROL_ROOT
        / "transactions"
        / registry["transaction_id"]
        / "forward_capability_consumption.json"
    )
    consumption, _encoded = _read_canonical_json(consumption_path)
    _require(isinstance(consumption, dict), "LMDB forward consumption receipt")
    rebuilt_consumption = _build_forward_consumption_receipt(
        registry,
        running_state,
        running_event,
        authority_binding_sha256=consumption.get("authority_binding_sha256"),
        consumer_nonce_sha256=consumption.get("consumer_nonce_sha256"),
    )
    _require(
        consumption == rebuilt_consumption
        and consumption["authority_binding_sha256"]
        == registry["execution_binding"]["authority_binding_sha256"],
        "LMDB forward consumption receipt drift",
    )
    return running_state, events[: running_position + 1], registry


def commit_lmdb_batch(
    *,
    bootstrap_lease: BootstrapLease,
    running_capability: "A4EvalRunningCapability",
    source_id: str,
    source_identity_sha256: str,
    key_manifest_sha256: str,
    key_set_sha256: str,
    source_manifest_sha256: str,
    batch_sha256: str,
    key_count: int,
    shared_ledger_tail_sha256: str,
) -> "A4LmdbBatchControlReceipt":
    """Persist one exact full-key authorization batch per LMDB source."""

    request = _validate_lmdb_batch_request(
        source_id=source_id,
        source_identity_sha256=source_identity_sha256,
        key_manifest_sha256=key_manifest_sha256,
        key_set_sha256=key_set_sha256,
        source_manifest_sha256=source_manifest_sha256,
        batch_sha256=batch_sha256,
        key_count=key_count,
        shared_ledger_tail_sha256=shared_ledger_tail_sha256,
    )
    validate_eval_running_capability(running_capability)
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "COMMIT_LMDB_EXACT_KEY_BATCH",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, events, registry = _assert_current_running_capability_locked(
            running_capability
        )
        _files, _directories, receipts = _validate_lmdb_batch_chain(
            registry,
            state,
            events[-1],
        )
        matches = [item for item in receipts if item["source_id"] == source_id]
        if matches:
            _require(len(matches) == 1, "LMDB source receipt cardinality")
            existing = matches[0]
            _require(
                all(existing.get(field) == value for field, value in request.items()),
                "LMDB source batch replay differs from persisted exact batch",
            )
            return _issue_a4_lmdb_batch_control_receipt(
                running_capability=running_capability,
                persisted_receipt=existing,
            )
        previous = receipts[-1]["receipt_sha256"] if receipts else None
        receipt = _build_lmdb_batch_receipt(
            registry,
            state,
            events[-1],
            batch_index=len(receipts),
            previous_batch_receipt_sha256=previous,
            **request,
        )
        receipt_path = (
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "lmdb_batch_receipts"
            / f"{len(receipts):06d}_{receipt['receipt_sha256']}.json"
        )
        _assert_dual_live_capability(bootstrap_lease, lease)
        _validate_supersession_receipt(bootstrap_lease)
        atomic_write_immutable(
            receipt_path,
            _canonical_file_bytes(receipt),
            lease=lease,
        )
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return _issue_a4_lmdb_batch_control_receipt(
            running_capability=running_capability,
            persisted_receipt=receipt,
        )


def assert_lmdb_batch_receipt_persisted(
    *,
    bootstrap_lease: BootstrapLease,
    running_capability: "A4EvalRunningCapability",
    source_id: str,
    receipt_sha256: str,
) -> str:
    _require(
        isinstance(source_id, str)
        and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}", source_id)
        is not None,
        "LMDB persisted source ID",
    )
    _require(
        isinstance(receipt_sha256, str) and HEX64.fullmatch(receipt_sha256),
        "LMDB persisted receipt SHA",
    )
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ASSERT_LMDB_BATCH_RECEIPT_PERSISTED",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, events, registry = _assert_current_running_capability_locked(
            running_capability
        )
        _files, _directories, receipts = _validate_lmdb_batch_chain(
            registry,
            state,
            events[-1],
        )
        matches = [
            item
            for item in receipts
            if item["source_id"] == source_id
            and item["receipt_sha256"] == receipt_sha256
        ]
        _require(len(matches) == 1, "LMDB persisted receipt is absent or ambiguous")
        return str(matches[0]["receipt_sha256"])


def load_lmdb_batch_control_receipt(
    *,
    bootstrap_lease: BootstrapLease,
    running_capability: "A4EvalRunningCapability",
    source_id: str,
) -> "A4LmdbBatchControlReceipt":
    """Reissue one opaque receipt only from the exact fsynced RUNNING sidecar chain."""

    _require(
        isinstance(source_id, str)
        and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.:-]{0,127}", source_id)
        is not None,
        "LMDB persisted source ID",
    )
    validate_eval_running_capability(running_capability)
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "LOAD_LMDB_BATCH_CONTROL_RECEIPT",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, events, registry = _assert_current_running_capability_locked(
            running_capability
        )
        _files, _directories, receipts = _validate_lmdb_batch_chain(
            registry,
            state,
            events[-1],
        )
        matches = [
            receipt for receipt in receipts if receipt["source_id"] == source_id
        ]
        _require(matches, "LMDB persisted source receipt absent")
        _require(
            len(matches) == 1,
            "LMDB persisted source receipt ambiguous",
        )
        capability = _issue_a4_lmdb_batch_control_receipt(
            running_capability=running_capability,
            persisted_receipt=matches[0],
        )
        validate_lmdb_batch_control_receipt(capability)
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return capability


class A4EvalForwardControlAdapter:
    """The eval-CAS subset of the forward trust-root protocol."""

    def __init__(self, bootstrap_lease: BootstrapLease) -> None:
        self._bootstrap_lease = bootstrap_lease
        self._issued_running_capability: Optional[A4EvalRunningCapability] = None

    def assert_fsynced_control_chain(self, **values: Any) -> str:
        return assert_fsynced_control_chain(
            bootstrap_lease=self._bootstrap_lease,
            **values,
        )

    def validate_controller_forward_authority(
        self,
        *,
        authority: Any,
    ) -> dict[str, Any]:
        return validate_controller_forward_authority(authority=authority)

    def consume_forward_capability_once(
        self,
        *,
        authority_binding_sha256: str,
        consumer_nonce_sha256: str,
    ) -> str:
        return consume_forward_capability_once(
            bootstrap_lease=self._bootstrap_lease,
            authority_binding_sha256=authority_binding_sha256,
            consumer_nonce_sha256=consumer_nonce_sha256,
        )

    def assert_running_state_event_committed(self) -> str:
        return assert_running_state_event_committed(
            bootstrap_lease=self._bootstrap_lease,
        )

    def committed_token_id(self) -> str:
        registry, _encoded = _read_eval_registry()
        return str(registry["token_id"])

    def committed_eval_id(self) -> str:
        registry, _encoded = _read_eval_registry()
        return str(registry["eval_id"])

    def committed_token_snapshot_sha256(self) -> str:
        registry, encoded = _read_eval_registry()
        _require(registry["token_state"] == "RUNNING", "token snapshot is not RUNNING")
        return bytes_sha256(encoded)

    def committed_run_id(self) -> str:
        registry, _encoded = _read_eval_registry()
        _require(registry["token_state"] == "RUNNING", "run ID is not RUNNING")
        return str(registry["run_id"])

    def issue_eval_running_capability(self) -> "A4EvalRunningCapability":
        capability = issue_eval_running_capability(
            bootstrap_lease=self._bootstrap_lease,
        )
        if self._issued_running_capability is not None:
            _require(
                self._issued_running_capability.capability_sha256
                == capability.capability_sha256,
                "forward adapter RUNNING capability reissue drift",
            )
        self._issued_running_capability = capability
        return capability

    def bind_completed_historical_running_capability(
        self,
        capability: "A4EvalRunningCapability",
    ) -> None:
        """Bind an opaque historical proof for completed-only validation."""

        payload = validate_eval_running_capability(capability)
        _require(
            isinstance(payload.get("run_id"), str)
            and bool(payload["run_id"]),
            "completed historical RUNNING proof identity",
        )
        if self._issued_running_capability is not None:
            _require(
                self._issued_running_capability.capability_sha256
                == capability.capability_sha256,
                "historical RUNNING proof rebind drift",
            )
        self._issued_running_capability = capability

    def _running_capability(self) -> "A4EvalRunningCapability":
        _require(
            type(self._issued_running_capability) is A4EvalRunningCapability,
            "forward adapter has not issued its RUNNING capability",
        )
        return self._issued_running_capability

    def commit_lmdb_batch(
        self,
        *,
        source_id: str,
        source_identity_sha256: str,
        key_manifest_sha256: str,
        key_set_sha256: str,
        source_manifest_sha256: str,
        batch_sha256: str,
        key_count: int,
        shared_ledger_tail_sha256: str,
    ) -> "A4LmdbBatchControlReceipt":
        return commit_lmdb_batch(
            bootstrap_lease=self._bootstrap_lease,
            running_capability=self._running_capability(),
            source_id=source_id,
            source_identity_sha256=source_identity_sha256,
            key_manifest_sha256=key_manifest_sha256,
            key_set_sha256=key_set_sha256,
            source_manifest_sha256=source_manifest_sha256,
            batch_sha256=batch_sha256,
            key_count=key_count,
            shared_ledger_tail_sha256=shared_ledger_tail_sha256,
        )

    def commit_lmdb_batch_receipt(self, **values: Any) -> str:
        capability = self.commit_lmdb_batch(**values)
        receipt = validate_lmdb_batch_control_receipt(capability)
        return str(receipt["persisted_receipt_sha256"])

    def assert_lmdb_batch_receipt_persisted(
        self,
        *,
        source_id: str,
        receipt_sha256: str,
    ) -> str:
        return assert_lmdb_batch_receipt_persisted(
            bootstrap_lease=self._bootstrap_lease,
            running_capability=self._running_capability(),
            source_id=source_id,
            receipt_sha256=receipt_sha256,
        )

    def issue_persisted_lmdb_batch_control_receipt(
        self,
        *,
        source_id: str,
    ) -> "A4LmdbBatchControlReceipt":
        return load_lmdb_batch_control_receipt(
            bootstrap_lease=self._bootstrap_lease,
            running_capability=self._running_capability(),
            source_id=source_id,
        )

    def commit_eval_cursor(
        self,
        *,
        cursor_index: int,
        cursor_sha256: str,
        chunks_sha256: str,
        artifacts_sha256: str,
    ) -> Mapping[str, Any]:
        return commit_eval_cursor(
            running_capability=self._running_capability(),
            cursor_index=cursor_index,
            cursor_sha256=cursor_sha256,
            chunks_sha256=chunks_sha256,
            artifacts_sha256=artifacts_sha256,
            bootstrap_lease=self._bootstrap_lease,
        )

    def issue_eval_cursor_capability(
        self,
        *,
        running_capability: "A4EvalRunningCapability",
    ) -> "A4EvalCursorCapability":
        return issue_eval_cursor_capability(
            bootstrap_lease=self._bootstrap_lease,
            running_capability=running_capability,
        )

    def complete_eval_token(
        self,
        *,
        cursor_capability: "A4EvalCursorCapability",
    ) -> Mapping[str, Any]:
        return complete_eval_token(
            cursor_capability=cursor_capability,
            bootstrap_lease=self._bootstrap_lease,
        )

    def persist_completed_forward_rehydrate_material(
        self,
        *,
        completed_result_verification_projection: Mapping[str, Any],
        input_capability_material: Mapping[str, Any],
        run_root: Mapping[str, Any],
        chunk_root: Mapping[str, Any],
        completed_forward_validation_receipt: Mapping[str, Any],
    ) -> Mapping[str, Any]:
        """Persist completed-only safe material using the original RUNNING cap."""

        return persist_completed_forward_rehydrate_material(
            bootstrap_lease=self._bootstrap_lease,
            running_capability=self._running_capability(),
            completed_result_verification_projection=(
                completed_result_verification_projection
            ),
            input_capability_material=input_capability_material,
            run_root=run_root,
            chunk_root=chunk_root,
            completed_forward_validation_receipt=(
                completed_forward_validation_receipt
            ),
        )


_OPAQUE_CONTROL_ISSUER_SEAL = object()
_THREAD_PROFILE_HOOK_UNAVAILABLE = object()
_OPAQUE_CONTROL_ISSUANCE_LOCK = threading.RLock()
_OPAQUE_CONTROL_ISSUANCE_REGISTRY: dict[int, dict[str, Any]] = {}


def _thread_profile_hook() -> Any:
    """Read the threading profile hook on Python 3.9 and newer runtimes."""

    getter = getattr(threading, "getprofile", None)
    if callable(getter):
        return getter()
    return getattr(threading, "_profile_hook", _THREAD_PROFILE_HOOK_UNAVAILABLE)


class _A4OpaqueControlCapability:
    __slots__ = ("_payload", "_capability_sha256", "_issuer_seal", "_frozen")

    def __init__(self, issuer_seal: object, payload: Mapping[str, Any]) -> None:
        if issuer_seal is not _OPAQUE_CONTROL_ISSUER_SEAL:
            raise A4ControlError("opaque control capability is controller-issued only")
        copied = json.loads(canonical_json_bytes(dict(payload)).decode("utf-8", "strict"))
        object.__setattr__(self, "_payload", copied)
        object.__setattr__(self, "_capability_sha256", semantic_sha256(copied))
        object.__setattr__(self, "_issuer_seal", issuer_seal)
        object.__setattr__(self, "_frozen", True)

    def __setattr__(self, name: str, value: Any) -> None:
        if getattr(self, "_frozen", False):
            raise A4ControlError("opaque control capability is immutable")
        object.__setattr__(self, name, value)

    @property
    def capability_sha256(self) -> str:
        return str(self._capability_sha256)

    def binding(self) -> dict[str, Any]:
        return json.loads(canonical_json_bytes(self._payload).decode("utf-8", "strict"))


def _register_opaque_capability(
    value: _A4OpaqueControlCapability,
) -> _A4OpaqueControlCapability:
    """Record controller ownership outside the caller-mutable capability object."""

    _require(
        isinstance(value, _A4OpaqueControlCapability),
        "opaque capability registration type",
    )
    identity = id(value)
    with _OPAQUE_CONTROL_ISSUANCE_LOCK:
        _require(
            identity not in _OPAQUE_CONTROL_ISSUANCE_REGISTRY,
            "opaque capability identity already registered",
        )
        _OPAQUE_CONTROL_ISSUANCE_REGISTRY[identity] = {
            "object": value,
            "exact_type": type(value),
            "capability_sha256": value.capability_sha256,
            "state": "ACTIVE",
            "consume_operation": None,
        }
    return value


def _consume_registered_capability_once(
    value: _A4OpaqueControlCapability,
    *,
    operation: str,
) -> None:
    _require(
        isinstance(operation, str)
        and re.fullmatch(r"[A-Z][A-Z0-9_]{2,127}", operation) is not None,
        "opaque capability consume operation",
    )
    identity = id(value)
    with _OPAQUE_CONTROL_ISSUANCE_LOCK:
        record = _OPAQUE_CONTROL_ISSUANCE_REGISTRY.get(identity)
        _require(
            isinstance(record, dict)
            and record.get("object") is value
            and record.get("exact_type") is type(value)
            and record.get("capability_sha256") == value.capability_sha256
            and record.get("state") == "ACTIVE",
            "opaque capability is unissued, altered, or already consumed",
        )
        record["state"] = "CONSUMED"
        record["consume_operation"] = operation


class _A4G1ProcessObserver:
    """Irremovable process audit hook with controller-owned activation scopes."""

    __slots__ = (
        "_installed",
        "_active_scope",
        "_events",
        "_lock",
        "_activation_thread_id",
        "_activation_thread_ids",
        "_profile_callback",
        "_profile_thread_ids",
        "_preopen_regular_fds",
    )

    def __init__(self) -> None:
        self._installed = False
        self._active_scope: Optional[str] = None
        self._events: list[dict[str, Any]] = []
        self._lock = threading.RLock()
        self._activation_thread_id: Optional[int] = None
        self._activation_thread_ids: tuple[int, ...] = ()
        self._profile_callback = self._profile
        self._profile_thread_ids: set[int] = set()
        self._preopen_regular_fds: dict[int, dict[str, Any]] = {}

    @staticmethod
    def _regular_fd_snapshot() -> dict[int, dict[str, Any]]:
        snapshot: dict[int, dict[str, Any]] = {}
        with os.scandir("/proc/self/fd") as iterator:
            names = [entry.name for entry in iterator]
        for name in names:
            if not name.isdigit():
                continue
            fd = int(name)
            try:
                observed = os.fstat(fd)
                if not stat.S_ISREG(observed.st_mode):
                    continue
                flags = int(fcntl.fcntl(fd, fcntl.F_GETFL))
                offset = int(os.lseek(fd, 0, os.SEEK_CUR))
                target = os.readlink(f"/proc/self/fd/{fd}")
            except (OSError, ValueError):
                continue
            snapshot[fd] = {
                "device": int(observed.st_dev),
                "inode": int(observed.st_ino),
                "flags": flags,
                "offset": offset,
                "size_bytes": int(observed.st_size),
                "target": target,
            }
        return snapshot

    @staticmethod
    def _authorized_preopen_fd(fd: int, record: Mapping[str, Any]) -> bool:
        if fd in {0, 1, 2}:
            return False
        target = os.path.realpath(str(record["target"]))
        authorized_target = target in {
            os.path.realpath(str(BOOTSTRAP_LOCK)),
            os.path.realpath(str(CONTROL_ROOT / "single_writer.lock")),
        }
        access_mode = int(record["flags"]) & os.O_ACCMODE
        unsafe_status_flags = int(record["flags"]) & (
            os.O_APPEND | os.O_NONBLOCK
        )
        return (
            authorized_target
            and access_mode == os.O_RDWR
            and unsafe_status_flags == 0
            and int(record["offset"]) == int(record["size_bytes"])
        )

    def _profile(self, frame: Any, event: str, _arg: Any) -> None:
        if self._active_scope is None:
            return
        with self._lock:
            if self._active_scope is not None:
                self._profile_thread_ids.add(threading.get_ident())
        if event != "call":
            return
        code = frame.f_code
        function_name = str(code.co_name)
        filename = str(code.co_filename).replace("\\", "/").casefold()
        owner = frame.f_locals.get("self")
        owner_name = type(owner).__name__ if owner is not None else ""
        observed_event: Optional[str] = None
        if function_name in {"forward", "_call_impl", "_wrapped_call_impl"}:
            observed_event = "c28f.model_forward_call"
        elif (
            owner_name in {"DataLoader", "_BaseDataLoaderIter"}
            or "torch/utils/data" in filename
        ) and function_name in {"__iter__", "__next__", "_next_data"}:
            observed_event = "c28f.data_loader_call"
        if observed_event is not None:
            with self._lock:
                if self._active_scope is not None:
                    self._events.append(
                        {
                            "event": observed_event,
                            "path": filename,
                            "write_requested": False,
                            "metadata_only": False,
                            "allowed_proc_metadata": False,
                            "regular_content_open": False,
                            "thread_id": threading.get_ident(),
                        }
                    )

    @staticmethod
    def _path_text(value: Any) -> Optional[str]:
        if isinstance(value, bytes):
            return os.fsdecode(value)
        if isinstance(value, (str, Path)):
            return os.fspath(value)
        return None

    @staticmethod
    def _allowed_proc_metadata(path: str, flags: int) -> bool:
        normalized = os.path.normpath(path)
        allowed = {
            "/proc/self/stat",
            "/proc/self/status",
            "/proc/self/mountinfo",
        }
        return (
            normalized in allowed
            or re.fullmatch(r"/proc/self/fdinfo/[0-9]+", normalized)
            is not None
        ) and not bool(flags & (os.O_WRONLY | os.O_RDWR | os.O_CREAT | os.O_TRUNC))

    def _audit(self, event: str, args: tuple[Any, ...]) -> None:
        with self._lock:
            if self._active_scope is None:
                return
            record: Optional[dict[str, Any]] = None
            if event == "open" and args:
                path = self._path_text(args[0])
                if path is None:
                    return
                mode = args[1] if len(args) > 1 else None
                raw_flags = args[2] if len(args) > 2 else 0
                flags = raw_flags if type(raw_flags) is int else 0
                write_requested = bool(
                    flags
                    & (
                        os.O_WRONLY
                        | os.O_RDWR
                        | os.O_CREAT
                        | os.O_TRUNC
                        | os.O_APPEND
                    )
                ) or (
                    isinstance(mode, str)
                    and any(marker in mode for marker in ("w", "a", "x", "+"))
                )
                o_path = _linux_o_path_flag()
                metadata_only = bool(flags & o_path)
                directory_only = bool(flags & int(getattr(os, "O_DIRECTORY", 0)))
                if not directory_only and not metadata_only:
                    try:
                        directory_only = stat.S_ISDIR(os.lstat(path).st_mode)
                    except (FileNotFoundError, NotADirectoryError, OSError):
                        directory_only = False
                allowed_proc = self._allowed_proc_metadata(path, flags)
                recorded_path = path
                if (
                    re.fullmatch(r"/proc/self/fd/[0-9]+", path)
                    is not None
                ):
                    recorded_path = os.path.realpath(path)
                record = {
                    "event": "open",
                    "path": recorded_path,
                    "write_requested": write_requested,
                    "metadata_only": metadata_only or directory_only,
                    "allowed_proc_metadata": allowed_proc,
                    "regular_content_open": not (
                        metadata_only or directory_only or allowed_proc
                    ),
                    "thread_id": threading.get_ident(),
                }
            elif event in {
                "os.rename",
                "os.replace",
                "os.remove",
                "os.unlink",
                "os.rmdir",
                "os.mkdir",
                "os.symlink",
                "os.link",
            }:
                record = {
                    "event": event,
                    "path": self._path_text(args[0]) if args else None,
                    "write_requested": True,
                    "metadata_only": False,
                    "allowed_proc_metadata": False,
                    "regular_content_open": False,
                    "thread_id": threading.get_ident(),
                }
            elif event in {
                "c28f.data_loader_call",
                "c28f.model_forward_call",
                "subprocess.Popen",
            }:
                record = {
                    "event": event,
                    "path": None,
                    "write_requested": False,
                    "metadata_only": False,
                    "allowed_proc_metadata": False,
                    "regular_content_open": False,
                    "thread_id": threading.get_ident(),
                }
            if record is not None:
                self._events.append(record)

    def start(self, scope_id: str) -> None:
        with self._lock:
            _require(self._active_scope is None, "G1 process observer already active")
            if not self._installed:
                sys.addaudithook(self._audit)
                self._installed = True
            thread_profile_before = _thread_profile_hook()
            _require(
                sys.getprofile() is None
                and thread_profile_before is not _THREAD_PROFILE_HOOK_UNAVAILABLE
                and thread_profile_before is None,
                "G1 cannot prove instrumentation with a preexisting profiler",
            )
            active_threads = tuple(threading.enumerate())
            current_thread = threading.current_thread()
            current_ident = threading.get_ident()
            _require(
                len(active_threads) == 1
                and active_threads[0] is current_thread
                and current_thread.is_alive()
                and current_thread.ident == current_ident,
                "G1 cannot prove instrumentation with preexisting threads",
            )
            preopen = self._regular_fd_snapshot()
            unknown = [
                fd
                for fd, record in preopen.items()
                if not self._authorized_preopen_fd(fd, record)
            ]
            _require(
                not unknown,
                "G1 unknown pre-open regular file descriptor",
            )
            self._preopen_regular_fds = preopen
            self._active_scope = scope_id
            self._events = []
            self._activation_thread_id = current_ident
            self._activation_thread_ids = (current_ident,)
            self._profile_thread_ids = set()
            try:
                sys.setprofile(self._profile_callback)
                threading.setprofile(self._profile_callback)
                _require(
                    sys.getprofile() is self._profile_callback
                    and _thread_profile_hook() is self._profile_callback,
                    "G1 process profiler activation incomplete",
                )
            except BaseException as activation_error:
                activation_restore_errors: list[str] = []
                try:
                    sys.setprofile(None)
                except BaseException as exc:
                    activation_restore_errors.append(
                        "sys:%s" % type(exc).__name__
                    )
                try:
                    threading.setprofile(None)
                except BaseException as exc:
                    activation_restore_errors.append(
                        "thread:%s" % type(exc).__name__
                    )
                finally:
                    self._active_scope = None
                    self._events = []
                    self._activation_thread_id = None
                    self._activation_thread_ids = ()
                    self._profile_thread_ids = set()
                    self._preopen_regular_fds = {}
                if activation_restore_errors:
                    raise A4ControlError(
                        "G1 profiler activation failed and restoration was incomplete: %s"
                        % ",".join(activation_restore_errors)
                    ) from activation_error
                raise

    def finish(self, scope_id: str) -> dict[str, Any]:
        with self._lock:
            _require(
                self._installed and self._active_scope == scope_id,
                "G1 process observer scope mismatch",
            )
            profile_intact = sys.getprofile() is self._profile_callback
            thread_profile_intact = _thread_profile_hook() is self._profile_callback
            preopen = dict(self._preopen_regular_fds)
            postopen: dict[int, dict[str, Any]] = {}
            snapshot_error: Optional[str] = None
            restore_errors: list[str] = []
            try:
                postopen = self._regular_fd_snapshot()
                changed_preopen = [
                    fd
                    for fd, before in preopen.items()
                    if fd not in postopen
                    or any(
                        postopen[fd][field] != before[field]
                        for field in (
                            "device", "inode", "flags", "offset", "size_bytes"
                        )
                    )
                ]
                new_regular = [fd for fd in postopen if fd not in preopen]
            except Exception as exc:
                snapshot_error = type(exc).__name__
                changed_preopen = sorted(preopen)
                new_regular = []
            finally:
                rows = [dict(item) for item in self._events]
                activation_thread_id = self._activation_thread_id
                activation_thread_ids = tuple(self._activation_thread_ids)
                profile_thread_ids = tuple(sorted(self._profile_thread_ids))
                postscope_threads = tuple(threading.enumerate())
                postscope_thread_ids = tuple(
                    sorted(
                        thread.ident
                        for thread in postscope_threads
                        if thread.ident is not None
                    )
                )
                try:
                    sys.setprofile(None)
                except BaseException as exc:
                    restore_errors.append("sys:%s" % type(exc).__name__)
                try:
                    threading.setprofile(None)
                except BaseException as exc:
                    restore_errors.append("thread:%s" % type(exc).__name__)
                self._active_scope = None
                self._events = []
                self._activation_thread_id = None
                self._activation_thread_ids = ()
                self._profile_thread_ids = set()
                self._preopen_regular_fds = {}
        sys_profile_restored = sys.getprofile() is None
        thread_profile_after = _thread_profile_hook()
        thread_profile_restored = (
            thread_profile_after is not _THREAD_PROFILE_HOOK_UNAVAILABLE
            and thread_profile_after is None
        )
        unexpected_profile_threads = tuple(
            thread_id
            for thread_id in profile_thread_ids
            if thread_id not in activation_thread_ids
        )
        unexpected_live_threads = tuple(
            thread_id
            for thread_id in postscope_thread_ids
            if thread_id not in activation_thread_ids
        )
        content_opens = sum(
            int(item["regular_content_open"]) for item in rows
        )
        write_events = sum(
            int(item["write_requested"]) for item in rows
        )
        loader_events = sum(
            int(item["event"] == "c28f.data_loader_call") for item in rows
        )
        model_events = sum(
            int(item["event"] == "c28f.model_forward_call") for item in rows
        )
        subprocess_events = sum(
            int(item["event"] == "subprocess.Popen") for item in rows
        )
        return {
            "instrumentation_complete": (
                profile_intact
                and thread_profile_intact
                and snapshot_error is None
                and not restore_errors
                and not unexpected_profile_threads
                and not unexpected_live_threads
            ),
            "sys_profile_restored": sys_profile_restored,
            "thread_profile_restored": thread_profile_restored,
            "scope_id": scope_id,
            "activation_thread_id": activation_thread_id,
            "activation_thread_count": len(activation_thread_ids),
            "activation_thread_ids": list(activation_thread_ids),
            "profile_observed_thread_count": len(profile_thread_ids),
            "profile_observed_thread_ids": list(profile_thread_ids),
            "unexpected_profile_thread_count": len(unexpected_profile_threads),
            "postscope_live_thread_count": len(postscope_thread_ids),
            "postscope_live_thread_ids": list(postscope_thread_ids),
            "unexpected_live_thread_count": len(unexpected_live_threads),
            "profile_restore_errors": restore_errors,
            "observed_events": rows,
            "regular_content_open_count": content_opens,
            "write_mutation_event_count": write_events,
            "data_loader_call_count": loader_events,
            "model_forward_call_count": model_events,
            "subprocess_call_count": subprocess_events,
            "preopened_regular_fd_count": len(preopen),
            "unknown_preopened_regular_fd_count": 0,
            "preopened_regular_fd_change_count": len(changed_preopen),
            "new_regular_fd_count": len(new_regular),
            "fd_snapshot_error": snapshot_error,
            "preopened_regular_fd_snapshot_sha256": semantic_sha256(preopen),
            "postscope_regular_fd_snapshot_sha256": semantic_sha256(postopen),
        }

    def current_counts(self, scope_id: str) -> dict[str, int]:
        with self._lock:
            _require(
                self._installed and self._active_scope == scope_id,
                "G1 process observer scope mismatch",
            )
            rows = [dict(item) for item in self._events]
        return {
            "regular_content_open_count": sum(
                int(item["regular_content_open"]) for item in rows
            ),
            "write_mutation_event_count": sum(
                int(item["write_requested"]) for item in rows
            ),
            "data_loader_call_count": sum(
                int(item["event"] == "c28f.data_loader_call") for item in rows
            ),
            "model_forward_call_count": sum(
                int(item["event"] == "c28f.model_forward_call") for item in rows
            ),
            "subprocess_call_count": sum(
                int(item["event"] == "subprocess.Popen") for item in rows
            ),
        }


_A4_G1_PROCESS_OBSERVER = _A4G1ProcessObserver()


class _A4G1ObservationScope:
    __slots__ = (
        "scope_id",
        "authority_id",
        "_controller_identity",
        "_closed",
    )

    def __init__(
        self,
        *,
        scope_id: str,
        authority_id: str,
        controller_identity: int,
    ) -> None:
        self.scope_id = scope_id
        self.authority_id = authority_id
        self._controller_identity = controller_identity
        self._closed = False


class _A4G1LedgerController:
    __slots__ = (
        "_authority_id",
        "_goal_id",
        "_open_ledgers",
        "_closed_ledgers",
        "_observer",
        "_active_observation_scope",
        "_observation_scope_issued",
        "_last_observation_receipt",
    )

    def __init__(self, *, authority_id: str, goal_id: str) -> None:
        self._authority_id = authority_id
        self._goal_id = goal_id
        self._open_ledgers: dict[EvidenceLedger, EvidenceLedger] = {}
        self._closed_ledgers: set[EvidenceLedger] = set()
        self._observer = _A4_G1_PROCESS_OBSERVER
        self._active_observation_scope: Optional[_A4G1ObservationScope] = None
        self._observation_scope_issued = False
        self._last_observation_receipt: Optional[dict[str, Any]] = None

    def open_observation_scope_once(
        self,
        *,
        scope_id: str,
        authority_id: str,
    ) -> _A4G1ObservationScope:
        _require(
            not self._observation_scope_issued
            and self._active_observation_scope is None
            and authority_id == self._authority_id
            and isinstance(scope_id, str)
            and bool(scope_id),
            "G1 observation scope authority/replay",
        )
        scope = _A4G1ObservationScope(
            scope_id=scope_id,
            authority_id=authority_id,
            controller_identity=id(self),
        )
        self._observer.start(scope_id)
        self._active_observation_scope = scope
        self._observation_scope_issued = True
        return scope

    def _validate_observation_scope(
        self,
        scope: _A4G1ObservationScope,
    ) -> None:
        _require(
            type(scope) is _A4G1ObservationScope
            and scope is self._active_observation_scope
            and scope._controller_identity == id(self)
            and scope.authority_id == self._authority_id
            and not scope._closed,
            "G1 observation scope is not current",
        )

    def open_mediated_ledger(self, *, scope_id: str, authority_id: str) -> EvidenceLedger:
        _require(
            authority_id == self._authority_id
            and isinstance(scope_id, str)
            and bool(scope_id),
            "G1 mediated ledger authority/scope",
        )
        active = self._active_observation_scope
        _require(
            active is not None and not active._closed,
            "G1 mediated ledger requires active outer observation scope",
        )
        ledger = EvidenceLedger(
            scope_id=scope_id,
            goal_id=self._goal_id,
            authority_id=self._authority_id,
        )
        _require(
            ledger not in self._open_ledgers
            and ledger not in self._closed_ledgers,
            "G1 ledger identity replay",
        )
        self._open_ledgers[ledger] = ledger
        return ledger

    def close_mediated_ledger(self, ledger: EvidenceLedger) -> dict[str, Any]:
        _require(type(ledger) is EvidenceLedger, "exact EvidenceLedger required")
        _require(
            self._open_ledgers.get(ledger) is ledger
            and ledger not in self._closed_ledgers
            and not ledger.closed,
            "G1 ledger is not an open controller-issued ledger",
        )
        active = self._active_observation_scope
        _require(active is not None, "G1 observation scope missing")
        observed = self._observer.current_counts(active.scope_id)
        ledger.close(
            instrumentation_complete=True,
            unmediated_content_open_count=observed[
                "regular_content_open_count"
            ],
        )
        rows = [dict(row) for row in ledger.rows]
        content_open_calls = sum(
            int(row["counters"]["content_open_count"]) for row in rows
        )
        model_forward_calls = sum(
            int(row["counters"]["model_forward_count"]) for row in rows
        )
        _require(
            observed["regular_content_open_count"] == 0
            and observed["write_mutation_event_count"] == 0
            and observed["data_loader_call_count"] == 0
            and observed["model_forward_call_count"] == 0
            and observed["subprocess_call_count"] == 0,
            "G1 process observer detected forbidden I/O or execution",
        )
        self._open_ledgers.pop(ledger)
        self._closed_ledgers.add(ledger)
        return {
            "scope_id": ledger.scope_id,
            "rows": rows,
            "instrumentation_complete": True,
            "unmediated_content_open_count": observed[
                "regular_content_open_count"
            ],
            "io_tripwire": {
                "data_loader_calls": observed["data_loader_call_count"],
                "content_open_calls": content_open_calls,
                "model_forward_calls": model_forward_calls,
                "output_write_calls": observed["write_mutation_event_count"],
            },
        }

    def close_observation_scope_success(
        self,
        scope: _A4G1ObservationScope,
    ) -> dict[str, Any]:
        self._validate_observation_scope(scope)
        observed = self._observer.finish(scope.scope_id)
        nested_ledgers_were_open = bool(self._open_ledgers)
        nested_ledger_cleanup_failed = False
        nested_ledger_cleanup_errors: list[str] = []
        for ledger in list(self._open_ledgers):
            try:
                if not ledger.closed:
                    ledger.close(
                        instrumentation_complete=bool(
                            observed["instrumentation_complete"]
                        ),
                        unmediated_content_open_count=observed[
                            "regular_content_open_count"
                        ],
                    )
            except BaseException as exc:
                nested_ledger_cleanup_failed = True
                nested_ledger_cleanup_errors.append(
                    "%s:%s" % (type(ledger).__name__, type(exc).__name__)
                )
            finally:
                self._open_ledgers.pop(ledger)
                self._closed_ledgers.add(ledger)
        object.__setattr__(scope, "_closed", True)
        self._active_observation_scope = None
        instrumentation_ok = (
            observed["instrumentation_complete"] is True
            and observed["sys_profile_restored"] is True
            and observed["thread_profile_restored"] is True
        )
        activity_ok = (
            observed["regular_content_open_count"] == 0
            and observed["write_mutation_event_count"] == 0
            and observed["data_loader_call_count"] == 0
            and observed["model_forward_call_count"] == 0
            and observed["subprocess_call_count"] == 0
            and observed["preopened_regular_fd_change_count"] == 0
            and observed["new_regular_fd_count"] == 0
        )
        success = (
            instrumentation_ok
            and activity_ok
            and not nested_ledgers_were_open
            and not nested_ledger_cleanup_failed
        )
        base = {
            "schema_version": "c28f_a4_g1_observation_scope_receipt_v1",
            "status": (
                "CLOSED_SUCCESS" if success else "ABORTED_FAIL_CLOSED"
            ),
            "goal_id": self._goal_id,
            "authority_id": self._authority_id,
            "scope_id": scope.scope_id,
            "reason_code": (
                None
                if success
                else (
                    "NESTED_LEDGER_CLEANUP_FAILED"
                    if nested_ledger_cleanup_failed
                    else (
                        "NESTED_LEDGER_LEFT_OPEN"
                        if nested_ledgers_were_open
                        else (
                            "OBSERVER_INSTRUMENTATION_INCOMPLETE"
                            if not instrumentation_ok
                            else "OBSERVER_FORBIDDEN_ACTIVITY"
                        )
                    )
                )
            ),
            "instrumentation_complete": instrumentation_ok,
            "observer_restored": (
                observed["sys_profile_restored"]
                and observed["thread_profile_restored"]
            ),
            "nested_ledgers_were_open": nested_ledgers_were_open,
            "nested_ledger_cleanup_failed": nested_ledger_cleanup_failed,
            "nested_ledger_cleanup_errors": nested_ledger_cleanup_errors,
            "all_nested_ledgers_closed": not self._open_ledgers,
            "process_observer": observed,
        }
        receipt = {**base, "receipt_sha256": semantic_sha256(base)}
        self._last_observation_receipt = dict(receipt)
        return dict(receipt)

    def abort_observation_scope(
        self,
        scope: _A4G1ObservationScope,
        *,
        reason_code: str,
    ) -> dict[str, Any]:
        if (
            type(scope) is _A4G1ObservationScope
            and scope._closed
            and self._last_observation_receipt is not None
            and self._last_observation_receipt.get("scope_id") == scope.scope_id
            and self._last_observation_receipt.get("status")
            == "ABORTED_FAIL_CLOSED"
        ):
            return dict(self._last_observation_receipt)
        self._validate_observation_scope(scope)
        _require(
            isinstance(reason_code, str)
            and re.fullmatch(r"[A-Z][A-Z0-9_]{2,127}", reason_code) is not None,
            "G1 abort reason code",
        )
        observed = self._observer.finish(scope.scope_id)
        nested_ledgers_were_open = bool(self._open_ledgers)
        nested_ledger_cleanup_errors: list[str] = []
        try:
            for ledger in list(self._open_ledgers):
                try:
                    if not ledger.closed:
                        ledger.close(
                            instrumentation_complete=bool(
                                observed["instrumentation_complete"]
                            ),
                            unmediated_content_open_count=observed[
                                "regular_content_open_count"
                            ],
                        )
                except BaseException as exc:
                    nested_ledger_cleanup_errors.append(
                        "%s:%s"
                        % (type(ledger).__name__, type(exc).__name__)
                    )
                finally:
                    self._open_ledgers.pop(ledger, None)
                    self._closed_ledgers.add(ledger)
        finally:
            self._open_ledgers.clear()
            object.__setattr__(scope, "_closed", True)
            self._active_observation_scope = None
        base = {
            "schema_version": "c28f_a4_g1_observation_scope_receipt_v1",
            "status": "ABORTED_FAIL_CLOSED",
            "goal_id": self._goal_id,
            "authority_id": self._authority_id,
            "scope_id": scope.scope_id,
            "reason_code": reason_code,
            "instrumentation_complete": observed["instrumentation_complete"],
            "observer_restored": (
                observed["sys_profile_restored"]
                and observed["thread_profile_restored"]
            ),
            "nested_ledgers_were_open": nested_ledgers_were_open,
            "nested_ledger_cleanup_failed": bool(
                nested_ledger_cleanup_errors
            ),
            "nested_ledger_cleanup_errors": nested_ledger_cleanup_errors,
            "all_nested_ledgers_closed": not self._open_ledgers,
            "process_observer": observed,
        }
        receipt = {**base, "receipt_sha256": semantic_sha256(base)}
        self._last_observation_receipt = dict(receipt)
        return dict(receipt)

    def assert_all_ledgers_closed(self) -> None:
        _require(
            not self._open_ledgers and self._active_observation_scope is None,
            "G1 observation scope or mediated ledger remains open",
        )


class A4G1ControlHandle(_A4OpaqueControlCapability):
    __slots__ = ("_controller",)

    def __init__(
        self,
        issuer_seal: object,
        payload: Mapping[str, Any],
        controller: _A4G1LedgerController,
    ) -> None:
        super().__init__(issuer_seal, payload)
        _require(type(controller) is _A4G1LedgerController, "exact G1 controller")
        object.__setattr__(self, "_controller", controller)

    def registry_authority(self) -> dict[str, Any]:
        return dict(self.binding()["registry_authority"])

    def global_snapshot(self) -> dict[str, Any]:
        return dict(self.binding()["global_snapshot"])

    def eval_budget(self) -> EvalBudgetBook:
        payload = self.binding()["eval_budget"]
        return EvalBudgetBook(
            tokens=tuple(
                sorted(
                    (EvalBudgetToken(**dict(item)) for item in payload["tokens"]),
                    key=lambda item: item.token_id,
                )
            )
        )

    def open_observation_scope_once(
        self,
        *,
        scope_id: str,
        authority_id: str,
    ) -> _A4G1ObservationScope:
        return self._controller.open_observation_scope_once(
            scope_id=scope_id,
            authority_id=authority_id,
        )

    def close_observation_scope_success(
        self,
        scope: _A4G1ObservationScope,
    ) -> dict[str, Any]:
        return self._controller.close_observation_scope_success(scope)

    def abort_observation_scope(
        self,
        scope: _A4G1ObservationScope,
        *,
        reason_code: str,
    ) -> dict[str, Any]:
        return self._controller.abort_observation_scope(
            scope,
            reason_code=reason_code,
        )

    def open_mediated_ledger(self, *, scope_id: str, authority_id: str) -> EvidenceLedger:
        return self._controller.open_mediated_ledger(
            scope_id=scope_id,
            authority_id=authority_id,
        )

    def close_mediated_ledger(self, ledger: EvidenceLedger) -> dict[str, Any]:
        return self._controller.close_mediated_ledger(ledger)

    def assert_all_ledgers_closed(self) -> None:
        self._controller.assert_all_ledgers_closed()


