_G6_CONTROLLER_SESSION_FACTORY = object()


class _A4G6ControllerOwnedSyntheticSession:
    """Pathless, fd-relative execution surface for the fixed reviewed F1 body."""

    __slots__ = (
        "_factory", "_parent_fd", "_parent_device", "_parent_inode",
        "_parent_mount_id", "_child_name", "_directory_fd", "_directory_device",
        "_directory_inode", "_directory_mount_id", "_writer_lease",
        "_creator_pid", "_creator_thread_id", "_creator_boot_id",
        "_creator_proc_start_ticks", "_crash_point", "_operation_plan",
        "_operation_cursor", "_operation_transcript", "_state",
        "_capability_sha256",
    )

    def __init__(
        self,
        factory: object,
        *,
        parent_fd: int,
        child_name: str,
        directory_fd: int,
        writer_lease: WriterLease,
        crash_point: str,
        operation_plan: Sequence[Mapping[str, Any]],
    ) -> None:
        _require(
            factory is _G6_CONTROLLER_SESSION_FACTORY
            and type(parent_fd) is int
            and parent_fd >= 0
            and isinstance(child_name, str)
            and bool(child_name)
            and "/" not in child_name
            and type(directory_fd) is int
            and directory_fd >= 0
            and isinstance(writer_lease, WriterLease)
            and isinstance(crash_point, str)
            and bool(operation_plan),
            "G6 controller session private construction",
        )
        parent_descriptor = os.fstat(parent_fd)
        descriptor = os.fstat(directory_fd)
        named_descriptor = os.stat(
            child_name,
            dir_fd=parent_fd,
            follow_symlinks=False,
        )
        _require(
            stat.S_ISDIR(parent_descriptor.st_mode)
            and stat.S_ISDIR(descriptor.st_mode)
            and stat.S_ISDIR(named_descriptor.st_mode)
            and (int(descriptor.st_dev), int(descriptor.st_ino))
            == (int(named_descriptor.st_dev), int(named_descriptor.st_ino))
            and descriptor.st_dev == parent_descriptor.st_dev
            and _fd_mount_id(directory_fd) == _fd_mount_id(parent_fd)
            and stat.S_IMODE(descriptor.st_mode) == 0o700,
            "G6 controller session exact child directory",
        )
        object.__setattr__(self, "_factory", factory)
        object.__setattr__(self, "_parent_fd", parent_fd)
        object.__setattr__(
            self, "_parent_device", int(parent_descriptor.st_dev)
        )
        object.__setattr__(
            self, "_parent_inode", int(parent_descriptor.st_ino)
        )
        object.__setattr__(self, "_parent_mount_id", _fd_mount_id(parent_fd))
        object.__setattr__(self, "_child_name", child_name)
        object.__setattr__(self, "_directory_fd", directory_fd)
        object.__setattr__(self, "_directory_device", int(descriptor.st_dev))
        object.__setattr__(self, "_directory_inode", int(descriptor.st_ino))
        object.__setattr__(self, "_directory_mount_id", _fd_mount_id(directory_fd))
        object.__setattr__(self, "_writer_lease", writer_lease)
        object.__setattr__(self, "_creator_pid", os.getpid())
        object.__setattr__(self, "_creator_thread_id", threading.get_ident())
        object.__setattr__(self, "_creator_boot_id", _current_boot_id())
        object.__setattr__(
            self,
            "_creator_proc_start_ticks",
            _proc_start_ticks(os.getpid()),
        )
        object.__setattr__(self, "_crash_point", crash_point)
        object.__setattr__(self, "_operation_plan", tuple(operation_plan))
        object.__setattr__(self, "_operation_cursor", 0)
        object.__setattr__(self, "_operation_transcript", [])
        object.__setattr__(self, "_state", "ISSUED_UNCONSUMED")
        object.__setattr__(self, "_capability_sha256", None)

    def _activate(self, capability_sha256: str) -> None:
        _require(
            self._state == "ISSUED_UNCONSUMED"
            and isinstance(capability_sha256, str)
            and HEX64.fullmatch(capability_sha256) is not None,
            "G6 controller session activation",
        )
        object.__setattr__(self, "_capability_sha256", capability_sha256)
        object.__setattr__(self, "_state", "ACTIVE_FIXED_BODY")
        self._assert_active()

    def _assert_active(self) -> None:
        _require(
            self._factory is _G6_CONTROLLER_SESSION_FACTORY
            and self._state == "ACTIVE_FIXED_BODY"
            and os.getpid() == self._creator_pid
            and threading.get_ident() == self._creator_thread_id
            and _current_boot_id() == self._creator_boot_id
            and _proc_start_ticks(os.getpid())
            == self._creator_proc_start_ticks,
            "G6 controller session owner/runtime drift",
        )
        self._writer_lease.assert_active_capability()
        parent_descriptor = os.fstat(self._parent_fd)
        descriptor = os.fstat(self._directory_fd)
        named_descriptor = os.stat(
            self._child_name,
            dir_fd=self._parent_fd,
            follow_symlinks=False,
        )
        _require(
            stat.S_ISDIR(parent_descriptor.st_mode)
            and (int(parent_descriptor.st_dev), int(parent_descriptor.st_ino))
            == (self._parent_device, self._parent_inode)
            and _fd_mount_id(self._parent_fd) == self._parent_mount_id
            and stat.S_ISDIR(descriptor.st_mode)
            and stat.S_ISDIR(named_descriptor.st_mode)
            and (int(named_descriptor.st_dev), int(named_descriptor.st_ino))
            == (self._directory_device, self._directory_inode)
            and stat.S_IMODE(descriptor.st_mode) == 0o700
            and (int(descriptor.st_dev), int(descriptor.st_ino))
            == (self._directory_device, self._directory_inode)
            and _fd_mount_id(self._directory_fd)
            == self._directory_mount_id,
            "G6 controller session directory drift",
        )

    def _next_operation(self, operation: str) -> Mapping[str, Any]:
        self._assert_active()
        _require(
            self._operation_cursor < len(self._operation_plan),
            "G6 fixed body exceeded operation plan",
        )
        expected = self._operation_plan[self._operation_cursor]
        _require(
            isinstance(expected, Mapping)
            and expected.get("operation") == operation,
            "G6 fixed body operation order drift",
        )
        return expected

    def _commit_operation(self, record: Mapping[str, Any]) -> None:
        self._operation_transcript.append(dict(record))
        object.__setattr__(
            self,
            "_operation_cursor",
            self._operation_cursor + 1,
        )

    def _write_unique_at(self, name: str, payload: bytes) -> None:
        flags = (
            os.O_WRONLY
            | os.O_CREAT
            | os.O_EXCL
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_NOFOLLOW", 0)
        )
        fd = os.open(name, flags, 0o600, dir_fd=self._directory_fd)
        try:
            offset = 0
            while offset < len(payload):
                written = os.write(fd, payload[offset:])
                _require(written > 0, "G6 fixed body write made no progress")
                offset += written
            os.fsync(fd)
        finally:
            os.close(fd)

    def _read_regular_at(self, name: str) -> bytes:
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        fd = os.open(name, flags, dir_fd=self._directory_fd)
        try:
            before = os.fstat(fd)
            _require(
                stat.S_ISREG(before.st_mode)
                and before.st_nlink == 1
                and stat.S_IMODE(before.st_mode) == 0o600
                and before.st_dev == self._directory_device
                and _fd_mount_id(fd) == self._directory_mount_id
                and 0 < before.st_size <= 16 * 1024 * 1024,
                "G6 fixed body regular read identity",
            )
            chunks: list[bytes] = []
            remaining = int(before.st_size)
            while remaining:
                chunk = os.read(fd, min(1024 * 1024, remaining))
                _require(bool(chunk), "G6 fixed body regular read was short")
                chunks.append(chunk)
                remaining -= len(chunk)
            _require(not os.read(fd, 1), "G6 fixed body regular file grew")
            after = os.fstat(fd)
        finally:
            os.close(fd)
        stable_fields = (
            "st_dev", "st_ino", "st_size", "st_mode", "st_nlink",
            "st_mtime_ns", "st_ctime_ns",
        )
        _require(
            all(
                getattr(before, field_name) == getattr(after, field_name)
                for field_name in stable_fields
            ),
            "G6 fixed body regular file changed during read",
        )
        return b"".join(chunks)

    def atomic_replace_new(self, name: str, payload: bytes, tag: str) -> None:
        expected = self._next_operation("ATOMIC_REPLACE_NEW")
        _require(
            type(payload) is bytes
            and name == expected.get("name")
            and tag == expected.get("tag")
            and payload == expected.get("payload")
            and "/" not in name
            and "/" not in tag
            and ".." not in {name, tag},
            "G6 fixed atomic-replace arguments drift",
        )
        temporary = ".%s.%s.tmp" % (name, tag)
        try:
            os.stat(temporary, dir_fd=self._directory_fd, follow_symlinks=False)
        except FileNotFoundError:
            pass
        else:
            raise A4ControlError("G6 fixed atomic temp namespace polluted")
        self._write_unique_at(temporary, payload)
        os.replace(
            temporary,
            name,
            src_dir_fd=self._directory_fd,
            dst_dir_fd=self._directory_fd,
        )
        os.fsync(self._directory_fd)
        self._commit_operation(
            {
                "operation": "ATOMIC_REPLACE_NEW",
                "name": name,
                "tag": tag,
                "payload_size_bytes": len(payload),
                "payload_sha256": bytes_sha256(payload),
            }
        )

    def fsynced_write_unique(self, name: str, payload: bytes) -> None:
        expected = self._next_operation("FSYNCED_WRITE_UNIQUE")
        _require(
            type(payload) is bytes
            and name == expected.get("name")
            and payload == expected.get("payload")
            and "/" not in name
            and name not in {".", ".."},
            "G6 fixed unique-write arguments drift",
        )
        self._write_unique_at(name, payload)
        os.fsync(self._directory_fd)
        self._commit_operation(
            {
                "operation": "FSYNCED_WRITE_UNIQUE",
                "name": name,
                "payload_size_bytes": len(payload),
                "payload_sha256": bytes_sha256(payload),
            }
        )

    def read_regular(self, name: str) -> bytes:
        expected = self._next_operation("READ_REGULAR")
        _require(
            name == expected.get("name")
            and "/" not in name
            and name not in {".", ".."},
            "G6 fixed read arguments drift",
        )
        payload = self._read_regular_at(name)
        _require(
            payload == expected.get("payload"),
            "G6 fixed read payload drift",
        )
        self._commit_operation(
            {
                "operation": "READ_REGULAR",
                "name": name,
                "payload_size_bytes": len(payload),
                "payload_sha256": bytes_sha256(payload),
            }
        )
        return payload

    def unlink(self, name: str) -> None:
        expected = self._next_operation("UNLINK")
        _require(
            name == expected.get("name")
            and "/" not in name
            and name not in {".", ".."},
            "G6 fixed unlink arguments drift",
        )
        os.unlink(name, dir_fd=self._directory_fd)
        os.fsync(self._directory_fd)
        self._commit_operation({"operation": "UNLINK", "name": name})

    def replace(self, source_name: str, target_name: str) -> None:
        expected = self._next_operation("REPLACE")
        _require(
            source_name == expected.get("source_name")
            and target_name == expected.get("target_name")
            and all(
                "/" not in name and name not in {".", ".."}
                for name in (source_name, target_name)
            ),
            "G6 fixed rename arguments drift",
        )
        os.replace(
            source_name,
            target_name,
            src_dir_fd=self._directory_fd,
            dst_dir_fd=self._directory_fd,
        )
        os.fsync(self._directory_fd)
        self._commit_operation(
            {
                "operation": "REPLACE",
                "source_name": source_name,
                "target_name": target_name,
            }
        )

    def list_names(self) -> tuple[str, ...]:
        expected = self._next_operation("LIST_NAMES")
        names = tuple(sorted(os.listdir(self._directory_fd)))
        _require(
            names == expected.get("names"),
            "G6 fixed terminal namespace drift",
        )
        self._commit_operation(
            {
                "operation": "LIST_NAMES",
                "names": list(names),
                "names_sha256": bytes_sha256(canonical_json_bytes(list(names))),
            }
        )
        return names

    def _seal_transcript(self) -> dict[str, Any]:
        self._assert_active()
        _require(
            self._operation_cursor == len(self._operation_plan),
            "G6 fixed body operation plan incomplete",
        )
        operations = json.loads(
            canonical_json_bytes(self._operation_transcript).decode(
                "utf-8", "strict"
            )
        )
        base = {
            "schema_version": "c28f_a4_g6_controller_execution_transcript_v2",
            "executor_version": "CONTROLLER_SINGLE_WRITER_FIXED_A4_F1_BODY_V2",
            "execution_capability_sha256": self._capability_sha256,
            "crash_point": self._crash_point,
            "operation_count": len(operations),
            "operations": operations,
            "operations_sha256": bytes_sha256(canonical_json_bytes(operations)),
        }
        transcript = {
            **base,
            "transcript_sha256": semantic_sha256(base),
        }
        object.__setattr__(
            self,
            "_state",
            "BODY_SEALED_PENDING_CONTROLLER_REREAD",
        )
        return transcript

    def _close_after_controller_commit(self) -> None:
        _require(
            self._state == "BODY_SEALED_PENDING_CONTROLLER_REREAD",
            "G6 controller session close order",
        )
        os.close(self._directory_fd)
        os.close(self._parent_fd)
        object.__setattr__(self, "_directory_fd", -1)
        object.__setattr__(self, "_parent_fd", -1)
        object.__setattr__(self, "_state", "SEALED")

    def _abort(self) -> None:
        if self._state not in {"SEALED", "ABORTED"}:
            if self._directory_fd >= 0:
                os.close(self._directory_fd)
                object.__setattr__(self, "_directory_fd", -1)
            if self._parent_fd >= 0:
                os.close(self._parent_fd)
                object.__setattr__(self, "_parent_fd", -1)
            object.__setattr__(self, "_state", "ABORTED")


class A4G6ControllerExecutionCapability(_A4OpaqueControlCapability):
    """One-shot pathless authority for the fixed reviewed F1 body."""

    __slots__ = (
        "_session", "_intent", "_owner", "_previous_owners",
        "_child_descriptor",
        "_root_handle",
    )

    def __init__(
        self,
        issuer_seal: object,
        payload: Mapping[str, Any],
        *,
        session: _A4G6ControllerOwnedSyntheticSession,
        intent: Mapping[str, Any],
        owner: Mapping[str, Any],
        previous_owners: Sequence[Mapping[str, Any]],
        child_descriptor: Mapping[str, Any],
        root_handle: "A4G6SyntheticRootHandle",
    ) -> None:
        super().__init__(issuer_seal, payload)
        _require(
            type(session) is _A4G6ControllerOwnedSyntheticSession
            and isinstance(intent, Mapping)
            and isinstance(owner, Mapping)
            and isinstance(previous_owners, Sequence)
            and isinstance(child_descriptor, Mapping),
            "G6 controller execution capability private construction",
        )
        object.__setattr__(self, "_session", session)
        object.__setattr__(
            self,
            "_intent",
            json.loads(canonical_json_bytes(dict(intent)).decode("utf-8")),
        )
        object.__setattr__(
            self,
            "_owner",
            json.loads(canonical_json_bytes(dict(owner)).decode("utf-8")),
        )
        object.__setattr__(
            self,
            "_previous_owners",
            tuple(
                json.loads(
                    canonical_json_bytes(dict(item)).decode("utf-8")
                )
                for item in previous_owners
            ),
        )
        object.__setattr__(
            self,
            "_child_descriptor",
            json.loads(
                canonical_json_bytes(dict(child_descriptor)).decode("utf-8")
            ),
        )
        object.__setattr__(self, "_root_handle", root_handle)

    def consume_preacquired_child_execution_once(
        self,
    ) -> _A4G6ControllerOwnedSyntheticSession:
        validate_g6_controller_execution_capability(self)
        _consume_registered_capability_once(
            self,
            operation="CONSUME_G6_CONTROLLER_FIXED_EXECUTION",
        )
        self._session._activate(self.capability_sha256)
        return self._session


