class A4G4MinimalProjectionBatch(_A4OpaqueControlCapability):
    __slots__ = ()

    def consume_snapshot_once(self) -> dict[str, Any]:
        payload = validate_g4_minimal_projection_batch(self)
        _consume_registered_capability_once(
            self,
            operation="CONSUME_G4_MINIMAL_PROJECTION_BATCH",
        )
        return payload


_G4_PROJECTION_READER_LOCK = threading.RLock()
_G4_PROJECTION_READER_REGISTRY: dict[int, dict[str, Any]] = {}


class A4G4RunningProjectionReader:
    __slots__ = (
        "_bootstrap_lease",
        "_capability",
    )

    def __init__(
        self,
        issuer_seal: object,
        *,
        bootstrap_lease: BootstrapLease,
        capability: A4G4RunningProjectionCapability,
    ) -> None:
        if issuer_seal is not _OPAQUE_CONTROL_ISSUER_SEAL:
            raise A4ControlError("G4 projection reader is controller-issued only")
        validate_g4_running_projection_capability(capability)
        self._bootstrap_lease = bootstrap_lease
        self._capability = capability

    def running_capability(self) -> A4G4RunningProjectionCapability:
        _validate_g4_projection_reader(self, expected_state="ACTIVE")
        return self._capability

    def consume_minimal_projection_once(self) -> A4G4MinimalProjectionBatch:
        _validate_g4_projection_reader(self, expected_state="ACTIVE")
        batch = _consume_g4_projection_source_once(
            bootstrap_lease=self._bootstrap_lease,
            running_capability=self._capability,
        )
        payload = validate_g4_minimal_projection_batch(batch)
        with _G4_PROJECTION_READER_LOCK:
            record = _G4_PROJECTION_READER_REGISTRY.get(id(self))
            _require(
                isinstance(record, dict)
                and record.get("object") is self
                and record.get("state") == "ACTIVE",
                "G4 projection reader already consumed",
            )
            record["state"] = "BATCH_ISSUED"
            record["batch_object"] = batch
            record["batch_capability_sha256"] = batch.capability_sha256
            record["access_receipt_sha256"] = payload[
                "access_receipt"
            ]["receipt_sha256"]
        return batch

    def seal_projection_result(
        self,
        *,
        batch_capability_sha256: str,
        result_payload_sha256: str,
    ) -> str:
        _require(
            isinstance(batch_capability_sha256, str)
            and HEX64.fullmatch(batch_capability_sha256)
            and isinstance(result_payload_sha256, str)
            and HEX64.fullmatch(result_payload_sha256),
            "G4 projection result seal order/hash",
        )
        with _G4_PROJECTION_READER_LOCK:
            record = _G4_PROJECTION_READER_REGISTRY.get(id(self))
            _require(
                isinstance(record, dict)
                and record.get("object") is self
                and record.get("state") == "BATCH_ISSUED"
                and record.get("batch_capability_sha256")
                == batch_capability_sha256,
                "G4 projection result seal reader/batch mismatch",
            )
            access_receipt_sha256 = str(record["access_receipt_sha256"])
            batch_object = record["batch_object"]
        batch_payload = validate_g4_minimal_projection_batch(batch_object)
        batch_lineage = {
            "batch_binding_sha256": batch_payload["batch_binding_sha256"],
            "protected_manifest_contract_sha256": batch_payload[
                "protected_manifest_contract_sha256"
            ],
            "expected_desc_ids_sha256": batch_payload[
                "expected_desc_ids_sha256"
            ],
            "records_sha256": batch_payload["records_sha256"],
            "scanner_contract_sha256": batch_payload[
                "scanner_contract_sha256"
            ],
            "source_observation_receipt_sha256": batch_payload[
                "source_observation_receipt"
            ]["receipt_sha256"],
        }
        result_seal_sha256 = semantic_sha256(
            {
                "schema_version": "c28f_a4_g4_projection_result_seal_v2",
                "control_capability_sha256": (
                    self._capability.capability_sha256
                ),
                "batch_capability_sha256": batch_capability_sha256,
                "access_receipt_sha256": access_receipt_sha256,
                "result_payload_sha256": result_payload_sha256,
            }
        )
        _persist_g4_projection_result_seal(
            bootstrap_lease=self._bootstrap_lease,
            running_capability_sha256=self._capability.capability_sha256,
            batch_capability_sha256=batch_capability_sha256,
            access_receipt_sha256=access_receipt_sha256,
            batch_lineage=batch_lineage,
            result_payload_sha256=result_payload_sha256,
            result_seal_sha256=result_seal_sha256,
        )
        with _G4_PROJECTION_READER_LOCK:
            record = _G4_PROJECTION_READER_REGISTRY.get(id(self))
            _require(
                isinstance(record, dict)
                and record.get("object") is self
                and record.get("state") == "BATCH_ISSUED"
                and record.get("batch_capability_sha256")
                == batch_capability_sha256,
                "G4 projection result seal state changed during persistence",
            )
            record["state"] = "RESULT_SEALED"
            record["result_seal_sha256"] = result_seal_sha256
        return result_seal_sha256


def _register_g4_projection_reader(
    reader: A4G4RunningProjectionReader,
) -> A4G4RunningProjectionReader:
    _require(
        type(reader) is A4G4RunningProjectionReader,
        "exact G4 projection reader registration",
    )
    with _G4_PROJECTION_READER_LOCK:
        _require(
            id(reader) not in _G4_PROJECTION_READER_REGISTRY,
            "G4 projection reader identity replay",
        )
        _G4_PROJECTION_READER_REGISTRY[id(reader)] = {
            "object": reader,
            "capability_sha256": reader._capability.capability_sha256,
            "state": "ACTIVE",
            "batch_object": None,
            "batch_capability_sha256": None,
            "access_receipt_sha256": None,
            "result_seal_sha256": None,
        }
    return reader


def _validate_g4_projection_reader(
    reader: Any,
    *,
    expected_state: str,
) -> None:
    _require(
        type(reader) is A4G4RunningProjectionReader,
        "exact G4 projection reader required",
    )
    validate_g4_running_projection_capability(reader._capability)
    with _G4_PROJECTION_READER_LOCK:
        record = _G4_PROJECTION_READER_REGISTRY.get(id(reader))
        _require(
            isinstance(record, dict)
            and record.get("object") is reader
            and record.get("capability_sha256")
            == reader._capability.capability_sha256
            and record.get("state") == expected_state,
            "G4 projection reader lacks controller issuance or state",
        )


def _persist_g4_projection_result_seal(
    *,
    bootstrap_lease: BootstrapLease,
    running_capability_sha256: str,
    batch_capability_sha256: str,
    access_receipt_sha256: str,
    batch_lineage: Mapping[str, Any],
    result_payload_sha256: str,
    result_seal_sha256: str,
) -> dict[str, Any]:
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "PERSIST_G4_PROJECTION_RESULT_SEAL",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        registry, _registry_bytes = _read_canonical_json(
            CONTROL_ROOT / "protected_id_mapping_registry.json"
        )
        _require(
            registry.get("phase") == "ACCESS"
            and registry.get("control_capability_sha256")
            == running_capability_sha256
            and state.get("status") == "ID_MAPPING_ACCESS_COMMITTED"
            and state.get("transaction_id") == registry["transaction_id"],
            "G4 result seal requires current ACCESS tail",
        )
        access_receipt, _access_bytes = _read_canonical_json(
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "access_receipt.json"
        )
        _require(
            isinstance(access_receipt, dict)
            and access_receipt.get("receipt_sha256")
            == access_receipt_sha256,
            "G4 result seal/access receipt binding",
        )
        exact_batch_lineage_fields = {
            "batch_binding_sha256", "protected_manifest_contract_sha256",
            "expected_desc_ids_sha256", "records_sha256",
            "scanner_contract_sha256", "source_observation_receipt_sha256",
        }
        _require(
            set(batch_lineage) == exact_batch_lineage_fields
            and all(
                isinstance(value, str) and HEX64.fullmatch(value)
                for value in batch_lineage.values()
            ),
            "G4 result seal batch lineage",
        )
        expected_result_seal = semantic_sha256(
            {
                "schema_version": "c28f_a4_g4_projection_result_seal_v2",
                "control_capability_sha256": running_capability_sha256,
                "batch_capability_sha256": batch_capability_sha256,
                "access_receipt_sha256": access_receipt_sha256,
                "result_payload_sha256": result_payload_sha256,
            }
        )
        _require(
            result_seal_sha256 == expected_result_seal,
            "G4 result seal deterministic rebuild",
        )
        base = {
            "schema_version": "c28f_a4_g4_projection_result_seal_receipt_v1",
            "status": "FSYNCED_CONTROLLER_RESULT_SEAL",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "operation_id": registry["operation_id"],
            "access_transaction_id": registry["transaction_id"],
            "access_state_sha256": state["state_sha256"],
            "access_event_sha256": events[-1]["event_sha256"],
            "running_capability_sha256": running_capability_sha256,
            "batch_capability_sha256": batch_capability_sha256,
            "access_receipt_sha256": access_receipt_sha256,
            **dict(batch_lineage),
            "result_payload_sha256": result_payload_sha256,
            "result_seal_sha256": result_seal_sha256,
        }
        receipt = {**base, "receipt_sha256": semantic_sha256(base)}
        atomic_write_immutable(
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "result_seal_receipt.json",
            _canonical_file_bytes(receipt),
            lease=lease,
        )
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return receipt


