class A4G2PowerReplayCapability(_A4OpaqueControlCapability):
    __slots__ = ("_power_rows", "_bootstrap_lease")

    def __init__(
        self,
        issuer_seal: object,
        payload: Mapping[str, Any],
        power_rows: Sequence[Mapping[str, Any]],
        bootstrap_lease: BootstrapLease,
    ) -> None:
        super().__init__(issuer_seal, payload)
        copied = tuple(
            json.loads(canonical_json_bytes(dict(row)).decode("utf-8", "strict"))
            for row in power_rows
        )
        object.__setattr__(self, "_power_rows", copied)
        object.__setattr__(self, "_bootstrap_lease", bootstrap_lease)

    def consume_rows_once(self) -> tuple[dict[str, Any], ...]:
        payload = validate_g2_power_replay_capability(self)
        _require(
            bytes_sha256(canonical_json_bytes(list(self._power_rows)))
            == payload["power_rows_sha256"],
            "G2 private power rows differ from issued binding",
        )
        _consume_registered_capability_once(
            self,
            operation="CONSUME_G2_POWER_ROWS",
        )
        return tuple(
            json.loads(canonical_json_bytes(row).decode("utf-8", "strict"))
            for row in self._power_rows
        )

    def issue_trusted_power_computation_receipt_once(
        self,
        *,
        role_counts: Mapping[str, Mapping[str, int]],
    ) -> "A4G2PowerComputationReceiptCapability":
        return issue_g2_power_computation_receipt(
            power_replay_capability=self,
            role_counts=role_counts,
            bootstrap_lease=self._bootstrap_lease,
        )


class A4FinalizationSnapshotCapability(_A4OpaqueControlCapability):
    __slots__ = ()


def _validate_opaque_capability(
    value: Any,
    expected_type: type[_A4OpaqueControlCapability],
    *,
    allowed_issuance_states: Sequence[str] = ("ACTIVE",),
) -> dict[str, Any]:
    _require(type(value) is expected_type, f"exact {expected_type.__name__} required; duck objects forbidden")
    _require(value._issuer_seal is _OPAQUE_CONTROL_ISSUER_SEAL, "opaque capability issuer seal")
    payload = value.binding()
    _require(value.capability_sha256 == semantic_sha256(payload), "opaque capability self-hash")
    with _OPAQUE_CONTROL_ISSUANCE_LOCK:
        issuance = _OPAQUE_CONTROL_ISSUANCE_REGISTRY.get(id(value))
        _require(
            isinstance(issuance, dict)
            and issuance.get("object") is value
            and issuance.get("exact_type") is expected_type
            and issuance.get("capability_sha256") == value.capability_sha256
            and issuance.get("state") in set(allowed_issuance_states),
            "opaque capability lacks active controller issuance",
        )
    return payload


def validate_g1_control_handle(value: Any) -> dict[str, Any]:
    payload = _validate_opaque_capability(value, A4G1ControlHandle)
    _require(
        set(payload)
        == {
            "schema_version", "goal_id", "attempt_id", "committed_state_sha256",
            "committed_event_sha256", "committed_transaction_id",
            "frozen_authority_sha256", "persisted_global_snapshot_sha256",
            "mediation_ledger_sha256", "probe_detector_snapshot_sha256",
            "registry_authority", "global_snapshot", "eval_budget",
            "mediation_registry", "probe_detector_registry",
            "registry_authority_file_sha256", "global_snapshot_file_sha256",
            "mediation_registry_file_sha256",
            "probe_detector_registry_file_sha256",
        }
        and payload["schema_version"] == "c28f_a4_g1_control_handle_v1",
        "G1 control handle field set",
    )
    authority = payload["registry_authority"]
    snapshot = payload["global_snapshot"]
    mediation = payload["mediation_registry"]
    probe = payload["probe_detector_registry"]
    _require(
        isinstance(authority, dict)
        and authority.get("authority_sha256")
        == semantic_sha256(authority, excluded_fields=("authority_sha256",))
        == payload["frozen_authority_sha256"],
        "G1 authority nested binding",
    )
    _require(
        isinstance(snapshot, dict)
        and snapshot.get("snapshot_sha256")
        == semantic_sha256(snapshot, excluded_fields=("snapshot_sha256",))
        == payload["persisted_global_snapshot_sha256"],
        "G1 global snapshot nested binding",
    )
    _require(
        isinstance(mediation, dict)
        and mediation.get("registry_sha256")
        == semantic_sha256(mediation, excluded_fields=("registry_sha256",))
        == payload["mediation_ledger_sha256"],
        "G1 mediation registry nested binding",
    )
    _require(
        isinstance(probe, dict)
        and probe.get("registry_sha256")
        == semantic_sha256(probe, excluded_fields=("registry_sha256",))
        == payload["probe_detector_snapshot_sha256"],
        "G1 probe registry nested binding",
    )
    _require(
        isinstance(payload["eval_budget"], dict)
        and authority["eval_budget_sha256"]
        == bytes_sha256(canonical_json_bytes(payload["eval_budget"])),
        "G1 eval budget binding",
    )
    for field in (
        "registry_authority_file_sha256",
        "global_snapshot_file_sha256",
        "mediation_registry_file_sha256",
        "probe_detector_registry_file_sha256",
    ):
        _require(
            isinstance(payload[field], str) and HEX64.fullmatch(payload[field]),
            f"G1 registry file hash: {field}",
        )
    return payload


def validate_eval_reservation_input_handle(value: Any) -> dict[str, Any]:
    payload = _validate_opaque_capability(value, A4EvalReservationInputHandle)
    _require(
        set(payload)
        == {
            "schema_version", "goal_id", "attempt_id",
            "committed_transaction_id", "committed_state_sha256",
            "committed_event_sha256", "token_id", "eval_id", "stage",
            "authority_id", "purpose", "query_role", "query_count",
            "cas_intent", "authorization_sha256", "execution_binding",
            "source_lineage", "authority_binding_material_sha256",
        }
        and payload["schema_version"]
        == "c28f_a4_eval_reservation_input_handle_v1",
        "eval reservation input handle field set",
    )
    _validate_eval_cas_intent(payload["cas_intent"])
    _validate_eval_execution_binding(payload["execution_binding"])
    _require(
        payload["cas_intent"]["token_id"] == payload["token_id"]
        and payload["cas_intent"]["eval_id"] == payload["eval_id"]
        and payload["cas_intent"]["authority_id"] == payload["authority_id"]
        and payload["cas_intent"]["purpose"] == payload["purpose"],
        "eval reservation CAS/handle identity",
    )
    _require(
        type(payload["query_count"]) is int
        and payload["query_count"] > 0
        and isinstance(payload["source_lineage"], dict)
        and bool(payload["source_lineage"]),
        "eval reservation query/source lineage",
    )
    for field in (
        "committed_state_sha256", "committed_event_sha256",
        "authorization_sha256", "authority_binding_material_sha256",
    ):
        _require(
            isinstance(payload[field], str) and HEX64.fullmatch(payload[field]),
            f"eval reservation handle hash: {field}",
        )
    return payload


