def validate_g4_projection_completion_capability(value: Any) -> dict[str, Any]:
    payload = _validate_opaque_capability(
        value,
        A4G4ProjectionCompletionCapability,
    )
    exact_fields = {
        "schema_version", "running_anchor",
        "protected_manifest_contract_sha256", "expected_desc_ids_sha256",
        "descriptor_identity_sha256", "access_intent_sha256",
        "projection_control_capability_sha256",
        "minimal_projection_batch_capability_sha256",
        "minimal_projection_batch_binding_sha256",
        "source_observation_receipt_sha256", "access_receipt_sha256",
        "result_seal_receipt_sha256", "control_result_seal_sha256",
        "projection_manifest_sha256", "mapping_rows_sha256",
        "video_lines_sha256", "projection_mapping_rows",
        "protected_desc_ids", "protected_video_ids",
        "mapping_file_sha256", "video_file_sha256",
        "manifest_file_sha256", "access_transaction_id",
        "access_state_sha256", "access_event_sha256",
        "one_shot_state_transition", "completed_transaction_id",
        "completed_state_sha256", "completed_event_sha256",
        "completion_receipt_sha256",
    }
    _require(
        set(payload) == exact_fields
        and payload["schema_version"]
        == "c28f_a4_g4_projection_completion_capability_v2",
        "G4 projection completion capability field set",
    )
    anchor = validate_protected_id_mapping_running_anchor(
        payload["running_anchor"]
    )
    rows = payload["projection_mapping_rows"]
    _require(
        isinstance(rows, list)
        and len(rows) == PROTECTED_ID_MAPPING_UNION_COUNT
        and all(
            isinstance(row, dict)
            and set(row) == {"desc_id", "video_id"}
            and type(row["desc_id"]) is int
            and row["desc_id"] >= 0
            and isinstance(row["video_id"], str)
            and SAFE_ENTITY_ID_RE.fullmatch(row["video_id"]) is not None
            for row in rows
        )
        and rows == sorted(rows, key=lambda item: item["desc_id"])
        and len({item["desc_id"] for item in rows}) == len(rows),
        "G4 projection completion rows",
    )
    desc_ids = [item["desc_id"] for item in rows]
    video_ids = sorted({item["video_id"] for item in rows})
    hash_fields = {
        "protected_manifest_contract_sha256",
        "expected_desc_ids_sha256",
        "descriptor_identity_sha256",
        "access_intent_sha256",
        "projection_control_capability_sha256",
        "minimal_projection_batch_capability_sha256",
        "minimal_projection_batch_binding_sha256",
        "source_observation_receipt_sha256",
        "access_receipt_sha256",
        "result_seal_receipt_sha256",
        "control_result_seal_sha256",
        "projection_manifest_sha256",
        "mapping_rows_sha256",
        "video_lines_sha256",
        "mapping_file_sha256",
        "video_file_sha256",
        "manifest_file_sha256",
        "access_state_sha256",
        "access_event_sha256",
        "completed_state_sha256",
        "completed_event_sha256",
        "completion_receipt_sha256",
    }
    _require(
        all(
            isinstance(payload[field], str)
            and HEX64.fullmatch(payload[field]) is not None
            for field in hash_fields
        )
        and payload["protected_desc_ids"] == desc_ids
        and payload["protected_video_ids"] == video_ids
        and payload["expected_desc_ids_sha256"]
        == bytes_sha256(canonical_json_bytes(desc_ids))
        == PROTECTED_ID_MAPPING_UNION_SHA256
        and payload["mapping_rows_sha256"]
        == bytes_sha256(canonical_json_bytes(rows))
        and payload["video_lines_sha256"]
        == bytes_sha256(
            "".join("%s\n" % value for value in video_ids).encode("utf-8")
        )
        and payload["descriptor_identity_sha256"]
        == anchor["descriptor_identity_sha256"]
        and payload["access_intent_sha256"]
        == anchor["access_intent_sha256"]
        and payload["one_shot_state_transition"] is True
        and payload["completed_transaction_id"]
        == "%s-COMPLETE" % anchor["operation_id"],
        "G4 projection completion exact binding",
    )
    completion_receipt, _receipt_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "transactions"
        / payload["completed_transaction_id"]
        / "phase_receipt.json"
    )
    state, _state_bytes, events, _journal = _current_state_and_events()
    _require(
        isinstance(completion_receipt, dict)
        and completion_receipt.get("phase") == "COMPLETE"
        and completion_receipt.get("operation_id") == anchor["operation_id"]
        and completion_receipt.get("result_seal_sha256")
        == payload["control_result_seal_sha256"]
        and completion_receipt.get("projection_manifest_sha256")
        == payload["projection_manifest_sha256"]
        and completion_receipt.get("receipt_sha256")
        == payload["completion_receipt_sha256"]
        == semantic_sha256(
            completion_receipt,
            excluded_fields=("receipt_sha256",),
        )
        and state.get("status") == "ID_MAPPING_COMPLETE"
        and state.get("next_action") == "G4_ROLE_POLICY_LOCK"
        and state.get("transaction_id") == payload["completed_transaction_id"]
        and state.get("state_sha256") == payload["completed_state_sha256"]
        and events[-1].get("event_sha256")
        == payload["completed_event_sha256"],
        "G4 projection completion persisted tail",
    )
    return payload


def validate_train_fit_role_source_capability(value: Any) -> dict[str, Any]:
    payload = _validate_opaque_capability(value, A4TrainFitRoleSourceCapability)
    _require(
        set(payload)
        == {
            "schema_version", "goal_id", "attempt_id",
            "committed_transaction_id", "committed_state_sha256",
            "committed_event_sha256", "source_descriptor_identity_sha256",
            "source_manifest_sha256", "source_access_receipt_sha256",
            "mapping_file_sha256", "mapping_records", "mapping_sha256",
        }
        and payload["schema_version"]
        == "c28f_a4_train_fit_role_source_capability_v1",
        "train-fit role source capability field set",
    )
    records = payload["mapping_records"]
    _require(isinstance(records, list) and bool(records), "train-fit mapping records")
    for index, record in enumerate(records):
        _require(
            isinstance(record, dict)
            and set(record) == {"desc_id", "ground_truth_video_id"}
            and type(record["desc_id"]) is int
            and record["desc_id"] >= 0
            and isinstance(record["ground_truth_video_id"], str)
            and SAFE_ENTITY_ID_RE.fullmatch(record["ground_truth_video_id"])
            is not None,
            f"train-fit mapping record at {index}",
        )
    _require(
        len(records) == 60_751
        and records == sorted(records, key=lambda item: item["desc_id"])
        and len({item["desc_id"] for item in records}) == len(records)
        and payload["mapping_sha256"]
        == bytes_sha256(canonical_json_bytes(records)),
        "train-fit mapping records are not canonical/bound",
    )
    for field in (
        "committed_state_sha256", "committed_event_sha256",
        "source_descriptor_identity_sha256", "source_manifest_sha256",
        "source_access_receipt_sha256", "mapping_file_sha256",
        "mapping_sha256",
    ):
        _require(
            isinstance(payload[field], str) and HEX64.fullmatch(payload[field]),
            f"train-fit source hash: {field}",
        )
    return payload


