def _g6_fixed_body_source_sha256() -> str:
    review = validate_a4_static_review_receipt()
    digest = review["payload"]["reviewed_files"].get(
        "blueprint_e2e_v2/c28f_v5/a4_f1.py"
    )
    _require(
        isinstance(digest, str) and HEX64.fullmatch(digest) is not None,
        "G6 fixed body lacks reviewed source SHA",
    )
    return digest


def _execute_a4_reviewed_clean_module(relative: str) -> types.ModuleType:
    review = validate_a4_static_review_receipt()
    reviewed_sha256 = review["payload"]["reviewed_files"].get(relative)
    _require(
        isinstance(reviewed_sha256, str)
        and HEX64.fullmatch(reviewed_sha256) is not None,
        "A4 clean module lacks reviewed source SHA",
    )
    source_path = (REPO_ROOT / relative).resolve(strict=True)
    source_bytes, source_record = _read_bound_regular(
        REPO_ROOT,
        relative,
        max_bytes=16 * 1024 * 1024,
        forbidden_identities=_protected_identities_from_a3(),
    )
    _require(
        source_record["sha256"] == reviewed_sha256,
        "A4 clean module reviewed source drift",
    )
    try:
        compiled_module = compile(
            source_bytes,
            str(source_path),
            "exec",
            dont_inherit=True,
            optimize=-1,
        )
    except (SyntaxError, ValueError, TypeError) as exc:
        raise A4ControlError("A4 reviewed clean source is invalid") from exc
    clean_name = (
        "blueprint_e2e_v2.c28f_v5.__a4_reviewed_%s_%s"
        % (source_path.stem, reviewed_sha256[:16])
    )
    clean_module = types.ModuleType(clean_name)
    clean_module.__file__ = str(source_path)
    clean_module.__package__ = "blueprint_e2e_v2.c28f_v5"
    clean_module.__loader__ = None
    clean_module.__spec__ = None
    with _A4_REVIEWED_CLEAN_MODULE_LOCK:
        _require(
            clean_name not in sys.modules,
            "A4 reviewed clean module namespace collision",
        )
        sys.modules[clean_name] = clean_module
        try:
            _assert_a4_import_bytecode_absent()
            exec(compiled_module, clean_module.__dict__, clean_module.__dict__)
            _assert_a4_import_bytecode_absent()
        finally:
            observed = sys.modules.pop(clean_name, None)
            _require(
                observed is clean_module,
                "A4 reviewed clean module registry drift",
            )
            _assert_a4_import_bytecode_absent()
    return clean_module


def _reviewed_a4_f1_callables() -> dict[str, Any]:
    """Resolve F1 only from a fresh, reviewed-source private namespace."""

    clean_canonical = _execute_a4_reviewed_clean_module(
        "blueprint_e2e_v2/c28f_v5/canonical.py"
    )
    clean_f1 = _execute_a4_reviewed_clean_module(
        "blueprint_e2e_v2/c28f_v5/a4_f1.py"
    )
    for imported_name in ("canonical_json_bytes", "semantic_sha256"):
        imported = clean_canonical.__dict__.get(imported_name)
        _require(
            type(imported) is types.FunctionType
            and imported.__globals__ is clean_canonical.__dict__,
            f"G6 clean canonical dependency: {imported_name}",
        )
        clean_f1.__dict__[imported_name] = imported
    resolved: dict[str, Any] = {}
    for symbol in (
        "execute_controller_owned_synthetic_atomic_recovery",
        "_synthetic_atomic_recovery_expected_material",
        "build_f1_protocol_report",
    ):
        actual = clean_f1.__dict__.get(symbol)
        _require(
            type(actual) is types.FunctionType
            and actual.__globals__ is clean_f1.__dict__
            and actual.__module__ == clean_f1.__name__
            and actual.__name__ == symbol
            and actual.__qualname__ == symbol
            and actual.__defaults__ is None
            and actual.__kwdefaults__ is None
            and actual.__closure__ is None,
            f"G6 reviewed callable drift: {symbol}",
        )
        resolved[symbol] = actual
    fixed_body = resolved[
        "execute_controller_owned_synthetic_atomic_recovery"
    ]
    _require(
        (
            "_synthetic_atomic_recovery_expected_material"
            not in fixed_body.__code__.co_names
            or clean_f1.__dict__.get(
                "_synthetic_atomic_recovery_expected_material"
            )
            is resolved["_synthetic_atomic_recovery_expected_material"]
        ),
        "G6 fixed body reviewed helper closure",
    )
    visited: set[int] = set()

    def assert_clean_transitive(function: Any) -> None:
        if id(function) in visited:
            return
        visited.add(id(function))
        _require(
            type(function) is types.FunctionType
            and function.__globals__ is clean_f1.__dict__,
            "G6 transitive callable escaped clean reviewed globals",
        )
        for global_name in function.__code__.co_names:
            dependency = clean_f1.__dict__.get(global_name)
            if (
                type(dependency) is types.FunctionType
                and dependency.__module__ == clean_f1.__name__
            ):
                assert_clean_transitive(dependency)

    assert_clean_transitive(fixed_body)
    assert_clean_transitive(resolved["build_f1_protocol_report"])
    return resolved


def _reviewed_a4_f1_fixed_body_callable() -> Any:
    return _reviewed_a4_f1_callables()[
        "execute_controller_owned_synthetic_atomic_recovery"
    ]


def _reviewed_a4_f1_protocol_report_callable() -> Any:
    return _reviewed_a4_f1_callables()["build_f1_protocol_report"]


def _g6_fixed_expected_material(
    crash_point: str,
) -> dict[str, Any]:
    _require(
        crash_point in G6_FIXED_TERMINAL_NAMES,
        "G6 fixed material crash point",
    )
    state_v0 = {
        "model": {"weight": 17},
        "optimizer": {"momentum": 23},
        "scheduler": {"completed_updates": 0},
        "scaler": {"scale": 1},
        "ema": {"weight": 17},
        "rng": {
            "python": 31,
            "numpy": 37,
            "torch_cpu": 41,
            "torch_cuda": 43,
        },
        "sampler": {"query_cursor": 0},
        "candidate_snapshot": {
            "query_cursor": 0,
            "sha256": "a" * 64,
        },
    }
    state_v1 = {
        **state_v0,
        "optimizer": {"momentum": 29},
        "scheduler": {"completed_updates": 1},
        "rng": {
            "python": 47,
            "numpy": 53,
            "torch_cpu": 59,
            "torch_cuda": 61,
        },
        "sampler": {"query_cursor": 8},
        "candidate_snapshot": {
            "query_cursor": 8,
            "sha256": "b" * 64,
        },
    }
    checkpoint_v0 = canonical_json_bytes(state_v0) + b"\n"
    checkpoint_v1 = canonical_json_bytes(state_v1) + b"\n"
    manifest_v0 = canonical_json_bytes(
        {
            "checkpoint_sha256": bytes_sha256(checkpoint_v0),
            "version": 0,
        }
    ) + b"\n"
    manifest_v1 = canonical_json_bytes(
        {
            "checkpoint_sha256": bytes_sha256(checkpoint_v1),
            "version": 1,
        }
    ) + b"\n"
    eval_id = "SYNTHETIC-EVAL-ONE-SHOT"
    eval_chunk0 = canonical_json_bytes(
        {"eval_id": eval_id, "start": 0, "end": 4}
    ) + b"\n"
    eval_chunk1 = canonical_json_bytes(
        {"eval_id": eval_id, "start": 4, "end": 8}
    ) + b"\n"
    status_bytes = canonical_json_bytes(
        {
            "status": "COMMITTED",
            "artifact_sha256": bytes_sha256(checkpoint_v0),
        }
    ) + b"\n"
    if crash_point == "BEFORE_CHECKPOINT_COMMIT":
        artifacts = {
            "checkpoint.json": checkpoint_v1,
            "checkpoint.manifest.json": manifest_v1,
        }
        terminal = checkpoint_v1
    elif crash_point == "AFTER_CHECKPOINT_BEFORE_MANIFEST":
        artifacts = {
            "checkpoint.json": checkpoint_v1,
            "checkpoint.manifest.json": manifest_v1,
            "checkpoint.orphan.quarantine.json": checkpoint_v1,
        }
        terminal = checkpoint_v1
    elif crash_point == "DURING_EVAL":
        artifacts = {
            "checkpoint.json": checkpoint_v0,
            "checkpoint.manifest.json": manifest_v0,
            "eval.chunk.0000.json": eval_chunk0,
            "eval.chunk.0001.json": eval_chunk1,
        }
        terminal = checkpoint_v0
    else:
        artifacts = {
            "checkpoint.json": checkpoint_v0,
            "checkpoint.manifest.json": manifest_v0,
            "status.json": status_bytes,
        }
        terminal = checkpoint_v0
    material = {
        "checkpoint_v0": checkpoint_v0,
        "checkpoint_v1": checkpoint_v1,
        "manifest_v0": manifest_v0,
        "manifest_v1": manifest_v1,
        "eval_chunk0": eval_chunk0,
        "eval_chunk1": eval_chunk1,
        "status_bytes": status_bytes,
        "expected_artifact_bytes": artifacts,
        "recovery_action": G6_FIXED_RECOVERY_ACTION[crash_point],
        "checkpoint_terminal_sha256": bytes_sha256(terminal),
        "complete_state_components_compared": list(
            G6_FIXED_STATE_COMPONENTS
        ),
    }
    exact_fields = {
        "checkpoint_v0", "checkpoint_v1", "manifest_v0", "manifest_v1",
        "eval_chunk0", "eval_chunk1", "status_bytes",
        "expected_artifact_bytes", "recovery_action",
        "checkpoint_terminal_sha256", "complete_state_components_compared",
    }
    artifacts = material.get("expected_artifact_bytes")
    _require(
        isinstance(material, dict)
        and set(material) == exact_fields
        and all(
            type(material[field_name]) is bytes
            and 0 < len(material[field_name]) <= 1024 * 1024
            for field_name in (
                "checkpoint_v0", "checkpoint_v1", "manifest_v0",
                "manifest_v1", "eval_chunk0", "eval_chunk1",
                "status_bytes",
            )
        )
        and isinstance(artifacts, dict)
        and tuple(sorted(artifacts)) == G6_FIXED_TERMINAL_NAMES[crash_point]
        and all(
            type(name) is str
            and type(payload) is bytes
            and 0 < len(payload) <= 1024 * 1024
            for name, payload in artifacts.items()
        )
        and material["recovery_action"]
        == G6_FIXED_RECOVERY_ACTION[crash_point]
        and isinstance(material["checkpoint_terminal_sha256"], str)
        and HEX64.fullmatch(material["checkpoint_terminal_sha256"])
        is not None
        and tuple(material["complete_state_components_compared"])
        == G6_FIXED_STATE_COMPONENTS,
        "G6 reviewed fixed material exact contract",
    )
    return material


def _g6_fixed_operation_plan(
    crash_point: str,
) -> tuple[tuple[dict[str, Any], ...], dict[str, Any]]:
    material = _g6_fixed_expected_material(crash_point)
    plan: list[dict[str, Any]] = [
        {
            "operation": "ATOMIC_REPLACE_NEW",
            "name": "checkpoint.json",
            "payload": material["checkpoint_v0"],
            "tag": "genesis",
        },
        {
            "operation": "ATOMIC_REPLACE_NEW",
            "name": "checkpoint.manifest.json",
            "payload": material["manifest_v0"],
            "tag": "genesis",
        },
    ]
    if crash_point == "BEFORE_CHECKPOINT_COMMIT":
        plan.extend(
            [
                {
                    "operation": "FSYNCED_WRITE_UNIQUE",
                    "name": ".checkpoint.json.update.tmp",
                    "payload": material["checkpoint_v1"],
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "checkpoint.json",
                    "payload": material["checkpoint_v0"],
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "checkpoint.manifest.json",
                    "payload": material["manifest_v0"],
                },
                {
                    "operation": "UNLINK",
                    "name": ".checkpoint.json.update.tmp",
                },
                {
                    "operation": "ATOMIC_REPLACE_NEW",
                    "name": "checkpoint.json",
                    "payload": material["checkpoint_v1"],
                    "tag": "replay",
                },
                {
                    "operation": "ATOMIC_REPLACE_NEW",
                    "name": "checkpoint.manifest.json",
                    "payload": material["manifest_v1"],
                    "tag": "replay",
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "checkpoint.json",
                    "payload": material["checkpoint_v1"],
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "checkpoint.manifest.json",
                    "payload": material["manifest_v1"],
                },
            ]
        )
    elif crash_point == "AFTER_CHECKPOINT_BEFORE_MANIFEST":
        plan.extend(
            [
                {
                    "operation": "ATOMIC_REPLACE_NEW",
                    "name": "checkpoint.json",
                    "payload": material["checkpoint_v1"],
                    "tag": "update",
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "checkpoint.manifest.json",
                    "payload": material["manifest_v0"],
                },
                {
                    "operation": "REPLACE",
                    "source_name": "checkpoint.json",
                    "target_name": "checkpoint.orphan.quarantine.json",
                },
                {
                    "operation": "ATOMIC_REPLACE_NEW",
                    "name": "checkpoint.json",
                    "payload": material["checkpoint_v0"],
                    "tag": "restore",
                },
                {
                    "operation": "ATOMIC_REPLACE_NEW",
                    "name": "checkpoint.json",
                    "payload": material["checkpoint_v1"],
                    "tag": "replay",
                },
                {
                    "operation": "ATOMIC_REPLACE_NEW",
                    "name": "checkpoint.manifest.json",
                    "payload": material["manifest_v1"],
                    "tag": "replay",
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "checkpoint.json",
                    "payload": material["checkpoint_v1"],
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "checkpoint.manifest.json",
                    "payload": material["manifest_v1"],
                },
            ]
        )
    elif crash_point == "DURING_EVAL":
        partial = material["eval_chunk1"][
            : max(1, len(material["eval_chunk1"]) // 2)
        ]
        plan.extend(
            [
                {
                    "operation": "FSYNCED_WRITE_UNIQUE",
                    "name": "eval.chunk.0000.json",
                    "payload": material["eval_chunk0"],
                },
                {
                    "operation": "FSYNCED_WRITE_UNIQUE",
                    "name": ".eval.chunk.0001.json.partial",
                    "payload": partial,
                },
                {
                    "operation": "UNLINK",
                    "name": ".eval.chunk.0001.json.partial",
                },
                {
                    "operation": "FSYNCED_WRITE_UNIQUE",
                    "name": "eval.chunk.0001.json",
                    "payload": material["eval_chunk1"],
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "eval.chunk.0000.json",
                    "payload": material["eval_chunk0"],
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "eval.chunk.0001.json",
                    "payload": material["eval_chunk1"],
                },
            ]
        )
    else:
        plan.extend(
            [
                {
                    "operation": "FSYNCED_WRITE_UNIQUE",
                    "name": ".status.json.rename.tmp",
                    "payload": material["status_bytes"],
                },
                {
                    "operation": "REPLACE",
                    "source_name": ".status.json.rename.tmp",
                    "target_name": "status.json",
                },
                {
                    "operation": "READ_REGULAR",
                    "name": "status.json",
                    "payload": material["status_bytes"],
                },
            ]
        )
    terminal_names = tuple(sorted(material["expected_artifact_bytes"]))
    plan.append({"operation": "LIST_NAMES", "names": terminal_names})
    for name in terminal_names:
        plan.append(
            {
                "operation": "READ_REGULAR",
                "name": name,
                "payload": material["expected_artifact_bytes"][name],
            }
        )
    artifact_manifest = [
        {
            "name": name,
            "size_bytes": len(material["expected_artifact_bytes"][name]),
            "sha256": bytes_sha256(material["expected_artifact_bytes"][name]),
        }
        for name in terminal_names
    ]
    public_plan = []
    for operation in plan:
        public = {
            key: value
            for key, value in operation.items()
            if key != "payload"
        }
        if "payload" in operation:
            public.update(
                {
                    "payload_size_bytes": len(operation["payload"]),
                    "payload_sha256": bytes_sha256(operation["payload"]),
                }
            )
        if isinstance(public.get("names"), tuple):
            public["names"] = list(public["names"])
        public_plan.append(public)
    contract_base = {
        "schema_version": "c28f_a4_g6_fixed_execution_contract_v2",
        "executor_version": G6_EXECUTOR_VERSION,
        "crash_point": crash_point,
        "expected_artifact_manifest": artifact_manifest,
        "expected_artifact_manifest_sha256": bytes_sha256(
            canonical_json_bytes(artifact_manifest)
        ),
        "recovery_action": material["recovery_action"],
        "checkpoint_terminal_sha256": material[
            "checkpoint_terminal_sha256"
        ],
        "complete_state_components_compared": list(
            G6_FIXED_STATE_COMPONENTS
        ),
        "operation_plan": public_plan,
        "operation_plan_sha256": bytes_sha256(
            canonical_json_bytes(public_plan)
        ),
        "operation_count": len(public_plan),
    }
    contract = {
        **contract_base,
        "contract_sha256": semantic_sha256(contract_base),
    }
    return tuple(plan), contract


def _g6_synthetic_session_id(payload: Mapping[str, Any]) -> str:
    binding_sha = payload.get("handle_binding_sha256")
    _require(
        isinstance(binding_sha, str) and HEX64.fullmatch(binding_sha),
        "G6 synthetic handle binding SHA",
    )
    return "G6-SYNTHETIC-%s" % binding_sha[:32]


def _validate_g6_executor_death_observation(
    value: Any,
    *,
    previous_owner: Mapping[str, Any],
) -> dict[str, Any]:
    exact_fields = {
        "schema_version", "status", "checked_boot_id",
        "previous_boot_id", "previous_pid", "previous_proc_start_ticks",
        "outcome", "observed_proc_start_ticks", "observed_at_unix_ns",
        "observation_sha256",
    }
    _require(
        isinstance(value, dict)
        and set(value) == exact_fields
        and value["schema_version"]
        == "c28f_a4_g6_executor_owner_death_observation_v2"
        and value["status"] == "FSYNCED_G6_TAKEOVER_PRECONDITION"
        and value["previous_boot_id"] == previous_owner["boot_id"]
        and value["previous_pid"] == previous_owner["pid"]
        and value["previous_proc_start_ticks"]
        == previous_owner["proc_start_ticks"]
        and value["outcome"]
        in {"PID_ABSENT", "BOOT_CHANGED", "START_TICKS_MISMATCH"}
        and type(value["observed_at_unix_ns"]) is int
        and value["observed_at_unix_ns"] > 0
        and value["observation_sha256"]
        == semantic_sha256(
            value,
            excluded_fields=("observation_sha256",),
        ),
        "G6 executor death observation exact contract",
    )
    observed = value["observed_proc_start_ticks"]
    if value["outcome"] == "BOOT_CHANGED":
        _require(
            value["checked_boot_id"] != value["previous_boot_id"]
            and observed is None,
            "G6 executor boot-change proof",
        )
    elif value["outcome"] == "PID_ABSENT":
        _require(
            value["checked_boot_id"] == value["previous_boot_id"]
            and observed is None,
            "G6 executor absent-PID proof",
        )
    else:
        _require(
            value["checked_boot_id"] == value["previous_boot_id"]
            and type(observed) is int
            and observed > 0
            and observed != value["previous_proc_start_ticks"],
            "G6 executor PID-reuse proof",
        )
    return dict(value)


def _observe_g6_executor_owner_death(
    previous_owner: Mapping[str, Any],
) -> dict[str, Any]:
    checked_boot_id = _current_boot_id()
    observed_ticks: Optional[int] = None
    if checked_boot_id != previous_owner["boot_id"]:
        outcome = "BOOT_CHANGED"
    else:
        try:
            observed_ticks = _proc_start_ticks(previous_owner["pid"])
        except (FileNotFoundError, ProcessLookupError):
            outcome = "PID_ABSENT"
        else:
            _require(
                observed_ticks != previous_owner["proc_start_ticks"],
                "G6 fixed executor previous owner remains live",
            )
            outcome = "START_TICKS_MISMATCH"
    base = {
        "schema_version": (
            "c28f_a4_g6_executor_owner_death_observation_v2"
        ),
        "status": "FSYNCED_G6_TAKEOVER_PRECONDITION",
        "checked_boot_id": checked_boot_id,
        "previous_boot_id": previous_owner["boot_id"],
        "previous_pid": previous_owner["pid"],
        "previous_proc_start_ticks": previous_owner["proc_start_ticks"],
        "outcome": outcome,
        "observed_proc_start_ticks": observed_ticks,
        "observed_at_unix_ns": time.time_ns(),
    }
    observation = {
        **base,
        "observation_sha256": semantic_sha256(base),
    }
    return _validate_g6_executor_death_observation(
        observation,
        previous_owner=previous_owner,
    )


def _validate_g6_executor_owner(
    value: Any,
    *,
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
    crash_point: str,
    child_name: str,
    generation: int,
    previous_owners: Sequence[Mapping[str, Any]],
    writer_lease_binding_sha256: str,
) -> dict[str, Any]:
    exact_fields = {
        "schema_version", "status", "goal_id", "attempt_id",
        "session_id", "synthetic_root_handle_sha256", "crash_point",
        "child_root_name", "generation", "boot_id", "pid",
        "proc_start_ticks", "thread_id", "owner_nonce",
        "writer_lease_binding_sha256", "previous_owner_binding_sha256",
        "takeover_reason", "previous_owner_death_observation",
        "takeover_chain_sha256", "owner_binding_sha256",
    }
    previous = None if not previous_owners else previous_owners[-1]
    death = value.get("previous_owner_death_observation")
    _require(
        isinstance(value, dict)
        and set(value) == exact_fields
        and value["schema_version"] == "c28f_a4_g6_executor_owner_v2"
        and value["status"] == "ACTIVE_EXCLUSIVE_FIXED_EXECUTOR_OWNER"
        and value["goal_id"] == GOAL_ID
        and value["attempt_id"] == root_payload["attempt_id"]
        and value["session_id"] == _g6_synthetic_session_id(root_payload)
        and value["synthetic_root_handle_sha256"] == root_handle_sha256
        and value["crash_point"] == crash_point
        and value["child_root_name"] == child_name
        and type(value["generation"]) is int
        and value["generation"] == generation
        and isinstance(value["boot_id"], str)
        and type(value["pid"]) is int
        and value["pid"] > 0
        and type(value["proc_start_ticks"]) is int
        and value["proc_start_ticks"] > 0
        and type(value["thread_id"]) is int
        and value["thread_id"] > 0
        and isinstance(value["owner_nonce"], str)
        and HEX32.fullmatch(value["owner_nonce"]) is not None
        and value["writer_lease_binding_sha256"]
        == writer_lease_binding_sha256
        and value["previous_owner_binding_sha256"]
        == (None if previous is None else previous["owner_binding_sha256"])
        and value["takeover_reason"]
        == (
            "INITIAL_FIXED_EXECUTOR_OWNER"
            if generation == 0
            else "CONFIRMED_PREVIOUS_FIXED_EXECUTOR_OWNER_DEAD"
        )
        and (
            death is None
            if generation == 0
            else isinstance(death, dict)
        )
        and value["takeover_chain_sha256"]
        == bytes_sha256(
            canonical_json_bytes(
                [item["owner_binding_sha256"] for item in previous_owners]
            )
        )
        and value["owner_binding_sha256"]
        == semantic_sha256(
            value,
            excluded_fields=("owner_binding_sha256",),
        ),
        "G6 fixed executor owner exact contract",
    )
    if generation > 0:
        _validate_g6_executor_death_observation(
            death,
            previous_owner=previous,  # type: ignore[arg-type]
        )
    return dict(value)


def _build_g6_executor_owner(
    *,
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
    crash_point: str,
    child_name: str,
    previous_owners: Sequence[Mapping[str, Any]],
    writer_lease_binding_sha256: str,
) -> dict[str, Any]:
    generation = len(previous_owners)
    _require(generation < 8, "G6 fixed executor owner generation bound")
    previous = None if not previous_owners else previous_owners[-1]
    death = (
        None
        if previous is None
        else _observe_g6_executor_owner_death(previous)
    )
    base = {
        "schema_version": "c28f_a4_g6_executor_owner_v2",
        "status": "ACTIVE_EXCLUSIVE_FIXED_EXECUTOR_OWNER",
        "goal_id": GOAL_ID,
        "attempt_id": root_payload["attempt_id"],
        "session_id": _g6_synthetic_session_id(root_payload),
        "synthetic_root_handle_sha256": root_handle_sha256,
        "crash_point": crash_point,
        "child_root_name": child_name,
        "generation": generation,
        "boot_id": _current_boot_id(),
        "pid": os.getpid(),
        "proc_start_ticks": _proc_start_ticks(os.getpid()),
        "thread_id": threading.get_ident(),
        "owner_nonce": uuid.uuid4().hex,
        "writer_lease_binding_sha256": writer_lease_binding_sha256,
        "previous_owner_binding_sha256": (
            None if previous is None else previous["owner_binding_sha256"]
        ),
        "takeover_reason": (
            "INITIAL_FIXED_EXECUTOR_OWNER"
            if previous is None
            else "CONFIRMED_PREVIOUS_FIXED_EXECUTOR_OWNER_DEAD"
        ),
        "previous_owner_death_observation": death,
        "takeover_chain_sha256": bytes_sha256(
            canonical_json_bytes(
                [item["owner_binding_sha256"] for item in previous_owners]
            )
        ),
    }
    owner = {**base, "owner_binding_sha256": semantic_sha256(base)}
    return _validate_g6_executor_owner(
        owner,
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
        crash_point=crash_point,
        child_name=child_name,
        generation=generation,
        previous_owners=previous_owners,
        writer_lease_binding_sha256=writer_lease_binding_sha256,
    )


def _validate_g6_executor_intent(
    value: Any,
    *,
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
) -> dict[str, Any]:
    exact_fields = {
        "schema_version", "status", "goal_id", "attempt_id", "session_id",
        "committed_transaction_id", "committed_state_sha256",
        "committed_event_sha256", "synthetic_root_handle_sha256",
        "crash_point", "child_root_name", "child_root_path",
        "child_root_binding_sha256", "parent_descriptor_identity_sha256",
        "child_root_contract_sha256", "preimage_classification",
        "fixed_executor", "execution_contract", "initial_owner",
        "synthetic_only", "real_data_allowed", "model_forward_evaluations",
        "real_data_optimizer_updates", "extra_model_forward_splits",
        "intent_sha256",
    }
    crash_point = value.get("crash_point") if isinstance(value, dict) else None
    child_name = value.get("child_root_name") if isinstance(value, dict) else None
    fixed_executor = value.get("fixed_executor") if isinstance(value, dict) else None
    _plan, expected_contract = _g6_fixed_operation_plan(str(crash_point))
    writer_lease_sha = (
        fixed_executor.get("writer_lease_binding_sha256")
        if isinstance(fixed_executor, dict)
        else None
    )
    _require(
        isinstance(value, dict)
        and set(value) == exact_fields
        and value["schema_version"] == "c28f_a4_g6_controller_execution_intent_v2"
        and value["status"] == "FSYNCED_CONTROLLER_FIXED_EXECUTION_INTENT"
        and value["goal_id"] == GOAL_ID
        and value["attempt_id"] == root_payload["attempt_id"]
        and value["session_id"] == _g6_synthetic_session_id(root_payload)
        and value["committed_transaction_id"]
        == root_payload["committed_transaction_id"]
        and value["committed_state_sha256"]
        == root_payload["committed_state_sha256"]
        and value["committed_event_sha256"]
        == root_payload["committed_event_sha256"]
        and value["synthetic_root_handle_sha256"] == root_handle_sha256
        and crash_point in root_payload["permitted_crash_points"]
        and child_name == root_payload["child_root_names"][crash_point]
        and value["child_root_path"]
        == str(Path(root_payload["parent_root_path"]) / child_name)
        and value["child_root_binding_sha256"]
        == semantic_sha256(
            {
                "synthetic_root_handle_sha256": root_handle_sha256,
                "crash_point": crash_point,
                "child_root_name": child_name,
                "child_root_path": value["child_root_path"],
                "parent_descriptor_identity_sha256": root_payload[
                    "parent_descriptor_identity_sha256"
                ],
                "child_root_contract_sha256": root_payload[
                    "child_root_contract_sha256"
                ],
            }
        )
        and value["parent_descriptor_identity_sha256"]
        == root_payload["parent_descriptor_identity_sha256"]
        and value["child_root_contract_sha256"]
        == root_payload["child_root_contract_sha256"]
        and value["preimage_classification"] == "ABSENT_BEFORE_INTENT"
        and isinstance(fixed_executor, dict)
        and set(fixed_executor)
        == {
            "relative_source", "reviewed_source_sha256", "symbol",
            "invocation_mode", "callback_allowed", "path_argument_allowed",
            "path_return_allowed", "external_executor_allowed",
            "writer_lease_binding", "writer_lease_binding_sha256",
        }
        and fixed_executor["relative_source"]
        == "blueprint_e2e_v2/c28f_v5/a4_f1.py"
        and fixed_executor["reviewed_source_sha256"]
        == _g6_fixed_body_source_sha256()
        and fixed_executor["symbol"]
        == "execute_controller_owned_synthetic_atomic_recovery"
        and fixed_executor["invocation_mode"]
        == "IN_PROCESS_FIXED_PATHLESS_FD_RELATIVE_CAPABILITY"
        and fixed_executor["callback_allowed"] is False
        and fixed_executor["path_argument_allowed"] is False
        and fixed_executor["path_return_allowed"] is False
        and fixed_executor["external_executor_allowed"] is False
        and isinstance(fixed_executor["writer_lease_binding"], dict)
        and writer_lease_sha
        == semantic_sha256(fixed_executor["writer_lease_binding"])
        and value["execution_contract"] == expected_contract
        and value["synthetic_only"] is True
        and value["real_data_allowed"] is False
        and value["model_forward_evaluations"] == 0
        and value["real_data_optimizer_updates"] == 0
        and value["extra_model_forward_splits"] == 0
        and value["intent_sha256"]
        == semantic_sha256(value, excluded_fields=("intent_sha256",)),
        "G6 fixed executor intent exact contract",
    )
    _validate_g6_executor_owner(
        value["initial_owner"],
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
        crash_point=crash_point,
        child_name=child_name,
        generation=0,
        previous_owners=(),
        writer_lease_binding_sha256=writer_lease_sha,
    )
    return dict(value)


def _g6_legacy_terminal_authority_records(
    *,
    session: Path,
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
    crash_point: str,
    actual_postimage: Mapping[str, Any],
) -> dict[str, dict[str, Any]]:
    child_name = root_payload["child_root_names"][crash_point]
    current_actual = _validate_g6_actual_postimage(actual_postimage)
    _require(
        current_actual["synthetic_root_handle_sha256"]
        == root_handle_sha256
        and current_actual["crash_point"] == crash_point,
        "G6 legacy authority current postimage lineage",
    )
    expected_binding = semantic_sha256(
        {
            "synthetic_root_handle_sha256": root_handle_sha256,
            "crash_point": crash_point,
            "child_root_name": child_name,
            "child_root_path": str(
                Path(root_payload["parent_root_path"]) / child_name
            ),
            "parent_descriptor_identity_sha256": root_payload[
                "parent_descriptor_identity_sha256"
            ],
            "child_root_contract_sha256": root_payload[
                "child_root_contract_sha256"
            ],
        }
    )
    expected_child_path = str(
        Path(root_payload["parent_root_path"]) / child_name
    )
    consume_name = "consume_%s.json" % child_name
    consumption, _consumption_bytes = _read_canonical_json(
        session / consume_name
    )
    _require(
        isinstance(consumption, dict)
        and set(consumption)
        == {
            "schema_version", "status", "synthetic_root_handle_sha256",
            "crash_point", "child_root_name", "child_root_path",
            "child_root_binding_sha256", "precondition_observed",
            "receipt_sha256",
        }
        and consumption["schema_version"]
        == "c28f_a4_g6_child_root_consumption_v1"
        and consumption["status"] == "FSYNCED_ONE_SHOT_CHILD_RELEASED"
        and consumption["synthetic_root_handle_sha256"]
        == root_handle_sha256
        and consumption["crash_point"] == crash_point
        and consumption["child_root_name"] == child_name
        and consumption["child_root_path"] == expected_child_path
        and consumption["child_root_binding_sha256"] == expected_binding
        and consumption["precondition_observed"] == "ABSENT"
        and consumption["receipt_sha256"]
        == semantic_sha256(
            consumption,
            excluded_fields=("receipt_sha256",),
        ),
        "G6 legacy migration consume authority exact contract",
    )
    unstarted_name = "unstarted_reissue_%s.json" % child_name
    unstarted_consumed_name = (
        "unstarted_resume_consumed_%s.json" % child_name
    )
    rehydrate_name = "rehydrate_%s.json" % child_name
    rehydrate_access_name = "rehydrate_access_%s.json" % child_name
    unstarted_record: Optional[dict[str, Any]] = None
    unstarted: Optional[dict[str, Any]] = None
    if os.path.lexists(session / unstarted_name):
        unstarted_record, _unstarted_bytes = _read_canonical_json(
            session / unstarted_name
        )
        unstarted = (
            unstarted_record.get("payload")
            if isinstance(unstarted_record, dict)
            else None
        )
        child_descriptor = (
            unstarted.get("child_descriptor")
            if isinstance(unstarted, dict)
            else None
        )
        _require(
            isinstance(unstarted_record, dict)
            and set(unstarted_record)
            == {
                "schema_version", "status", "capability_sha256",
                "payload", "record_sha256",
            }
            and isinstance(unstarted, dict)
            and set(unstarted)
            == {
                "schema_version", "status", "goal_id", "attempt_id",
                "synthetic_root_handle_sha256", "crash_point",
                "child_root_name", "child_root_path",
                "child_root_binding_sha256",
                "consumption_receipt_sha256",
                "parent_descriptor_identity_sha256", "child_descriptor",
                "child_descriptor_identity_sha256",
                "controller_precreated_empty", "synthetic_only",
                "one_shot_per_capability", "resume_binding_sha256",
            }
            and unstarted["schema_version"]
            == "c28f_a4_g6_synthetic_unstarted_resume_capability_v1"
            and unstarted["status"]
            == "FSYNCED_CONTROLLER_PRECREATED_EMPTY_CHILD_FOR_RESUME"
            and unstarted["goal_id"] == GOAL_ID
            and unstarted["attempt_id"] == root_payload["attempt_id"]
            and unstarted["synthetic_root_handle_sha256"]
            == root_handle_sha256
            and unstarted["crash_point"] == crash_point
            and unstarted["child_root_name"] == child_name
            and unstarted["child_root_path"] == expected_child_path
            and unstarted["child_root_binding_sha256"] == expected_binding
            and unstarted["consumption_receipt_sha256"]
            == consumption["receipt_sha256"]
            and unstarted["parent_descriptor_identity_sha256"]
            == root_payload["parent_descriptor_identity_sha256"]
            and isinstance(child_descriptor, dict)
            and set(child_descriptor)
            == {
                "canonical_path", "parent_canonical_path", "device",
                "inode", "nlink", "mode", "mtime_ns", "ctime_ns",
                "mount_id", "parent_descriptor_identity_sha256",
                "child_root_binding_sha256",
            }
            and child_descriptor["canonical_path"] == expected_child_path
            and child_descriptor["parent_canonical_path"]
            == root_payload["parent_root_path"]
            and type(child_descriptor["device"]) is int
            and child_descriptor["device"] > 0
            and type(child_descriptor["inode"]) is int
            and child_descriptor["inode"] > 0
            and type(child_descriptor["nlink"]) is int
            and child_descriptor["nlink"] >= 2
            and child_descriptor["mode"] == "0o700"
            and type(child_descriptor["mtime_ns"]) is int
            and child_descriptor["mtime_ns"] > 0
            and type(child_descriptor["ctime_ns"]) is int
            and child_descriptor["ctime_ns"] > 0
            and child_descriptor["mount_id"]
            == root_payload["parent_descriptor_record"]["mount_id"]
            == current_actual["root_identity"]["mount_id"]
            and child_descriptor["device"]
            == current_actual["root_identity"]["device"]
            and child_descriptor["inode"]
            == current_actual["root_identity"]["inode"]
            and child_descriptor["nlink"]
            == current_actual["root_identity"]["nlink"]
            and child_descriptor["parent_descriptor_identity_sha256"]
            == root_payload["parent_descriptor_identity_sha256"]
            and child_descriptor["child_root_binding_sha256"]
            == expected_binding
            and unstarted["child_descriptor_identity_sha256"]
            == semantic_sha256(child_descriptor)
            and unstarted["controller_precreated_empty"] is True
            and unstarted["synthetic_only"] is True
            and unstarted["one_shot_per_capability"] is True
            and unstarted["resume_binding_sha256"]
            == semantic_sha256(
                unstarted,
                excluded_fields=("resume_binding_sha256",),
            )
            and unstarted_record["schema_version"]
            == "c28f_a4_g6_synthetic_unstarted_resume_record_v1"
            and unstarted_record["status"]
            == "FSYNCED_UNSTARTED_REISSUE_CLAIM"
            and unstarted_record["capability_sha256"]
            == semantic_sha256(unstarted)
            and unstarted_record["record_sha256"]
            == semantic_sha256(
                unstarted_record,
                excluded_fields=("record_sha256",),
            ),
            "G6 legacy migration unstarted authority exact chain",
        )
        _require(
            os.path.lexists(session / unstarted_consumed_name),
            "G6 terminal legacy unstarted claim lacks consumed marker",
        )
    if os.path.lexists(session / unstarted_consumed_name):
        _require(
            unstarted_record is not None and unstarted is not None,
            "G6 legacy unstarted consume lacks reissue authority",
        )
        marker, _marker_bytes = _read_canonical_json(
            session / unstarted_consumed_name
        )
        _require(
            isinstance(marker, dict)
            and set(marker)
            == {
                "schema_version", "status",
                "synthetic_root_handle_sha256", "crash_point",
                "child_root_name", "child_root_binding_sha256",
                "resume_capability_sha256", "resume_binding_sha256",
                "child_descriptor_identity_sha256", "receipt_sha256",
            }
            and marker["schema_version"]
            == "c28f_a4_g6_synthetic_unstarted_resume_consumption_v1"
            and marker["status"]
            == "FSYNCED_GLOBAL_ONE_SHOT_RESUME_CONSUMED"
            and marker["synthetic_root_handle_sha256"]
            == root_handle_sha256
            and marker["crash_point"] == crash_point
            and marker["child_root_name"] == child_name
            and marker["child_root_binding_sha256"] == expected_binding
            and marker["resume_capability_sha256"]
            == unstarted_record["capability_sha256"]
            and marker["resume_binding_sha256"]
            == unstarted["resume_binding_sha256"]
            and marker["child_descriptor_identity_sha256"]
            == unstarted["child_descriptor_identity_sha256"]
            and marker["receipt_sha256"]
            == semantic_sha256(marker, excluded_fields=("receipt_sha256",)),
            "G6 legacy migration unstarted consumed exact chain",
        )
    rehydrate_record: Optional[dict[str, Any]] = None
    rehydrate: Optional[dict[str, Any]] = None
    if os.path.lexists(session / rehydrate_name):
        rehydrate_record, _rehydrate_bytes = _read_canonical_json(
            session / rehydrate_name
        )
        rehydrate = (
            rehydrate_record.get("payload")
            if isinstance(rehydrate_record, dict)
            else None
        )
        _require(
            isinstance(rehydrate_record, dict)
            and set(rehydrate_record)
            == {
                "schema_version", "status", "capability_sha256",
                "payload", "record_sha256",
            }
            and isinstance(rehydrate, dict)
            and set(rehydrate)
            == {
                "schema_version", "status", "goal_id", "attempt_id",
                "synthetic_root_handle_sha256", "crash_point",
                "child_root_name", "child_root_binding_sha256",
                "consumption_receipt_sha256",
                "parent_descriptor_identity_sha256", "actual_postimage",
                "actual_postimage_sha256", "synthetic_only",
                "real_data_allowed", "read_only", "one_shot_per_capability",
                "rehydrate_binding_sha256",
            }
            and rehydrate["schema_version"]
            == "c28f_a4_g6_synthetic_postimage_rehydrate_capability_v1"
            and rehydrate["status"]
            == "CONTROLLER_VERIFIED_SYNTHETIC_POSTIMAGE_REHYDRATE"
            and rehydrate["goal_id"] == GOAL_ID
            and rehydrate["attempt_id"] == root_payload["attempt_id"]
            and rehydrate["synthetic_root_handle_sha256"]
            == root_handle_sha256
            and rehydrate["crash_point"] == crash_point
            and rehydrate["child_root_name"] == child_name
            and rehydrate["child_root_binding_sha256"] == expected_binding
            and rehydrate["consumption_receipt_sha256"]
            == consumption["receipt_sha256"]
            and rehydrate["parent_descriptor_identity_sha256"]
            == root_payload["parent_descriptor_identity_sha256"]
            and rehydrate["actual_postimage_sha256"]
            == _validate_g6_actual_postimage(
                rehydrate["actual_postimage"]
            )["postimage_sha256"]
            and rehydrate["actual_postimage"] == current_actual
            and rehydrate["actual_postimage"][
                "synthetic_root_handle_sha256"
            ] == root_handle_sha256
            and rehydrate["actual_postimage"]["crash_point"] == crash_point
            and rehydrate["actual_postimage"]["root_identity"][
                "canonical_path"
            ] == expected_child_path
            and rehydrate["actual_postimage"]["root_identity"][
                "child_root_binding_sha256"
            ] == expected_binding
            and rehydrate["synthetic_only"] is True
            and rehydrate["real_data_allowed"] is False
            and rehydrate["read_only"] is True
            and rehydrate["one_shot_per_capability"] is True
            and rehydrate["rehydrate_binding_sha256"]
            == semantic_sha256(
                rehydrate,
                excluded_fields=("rehydrate_binding_sha256",),
            )
            and rehydrate_record["schema_version"]
            == "c28f_a4_g6_synthetic_postimage_rehydrate_record_v1"
            and rehydrate_record["status"] == "FSYNCED_CONTROLLER_ISSUED"
            and rehydrate_record["capability_sha256"]
            == semantic_sha256(rehydrate)
            and rehydrate_record["record_sha256"]
            == semantic_sha256(
                rehydrate_record,
                excluded_fields=("record_sha256",),
            ),
            "G6 legacy migration rehydrate authority exact chain",
        )
    if os.path.lexists(session / rehydrate_access_name):
        _require(
            rehydrate_record is not None and rehydrate is not None,
            "G6 legacy rehydrate access lacks issued authority",
        )
        access, _access_bytes = _read_canonical_json(
            session / rehydrate_access_name
        )
        _require(
            isinstance(access, dict)
            and set(access)
            == {
                "schema_version", "status",
                "synthetic_root_handle_sha256", "crash_point",
                "child_root_binding_sha256", "consumption_receipt_sha256",
                "actual_postimage", "artifact_bytes_sha256s",
                "access_receipt_sha256",
            }
            and access["schema_version"]
            == "c28f_a4_g6_synthetic_postimage_rehydrate_access_v1"
            and access["status"]
            == "CONTROLLER_READONLY_SYNTHETIC_POSTIMAGE_REHYDRATED"
            and access["synthetic_root_handle_sha256"] == root_handle_sha256
            and access["crash_point"] == crash_point
            and access["child_root_binding_sha256"] == expected_binding
            and access["consumption_receipt_sha256"]
            == consumption["receipt_sha256"]
            and access["actual_postimage"] == rehydrate["actual_postimage"]
            and access["artifact_bytes_sha256s"]
            == {
                item["name"]: item["sha256"]
                for item in access["actual_postimage"]["artifact_inventory"]
            }
            and access["access_receipt_sha256"]
            == semantic_sha256(
                access,
                excluded_fields=("access_receipt_sha256",),
            ),
            "G6 legacy migration rehydrate access exact chain",
        )
    specifications = (
        (
            "consume_%s.json" % child_name,
            "c28f_a4_g6_child_root_consumption_v1",
            "FSYNCED_ONE_SHOT_CHILD_RELEASED",
            "receipt_sha256",
            True,
        ),
        (
            "unstarted_reissue_%s.json" % child_name,
            "c28f_a4_g6_synthetic_unstarted_resume_record_v1",
            "FSYNCED_UNSTARTED_REISSUE_CLAIM",
            "record_sha256",
            False,
        ),
        (
            "unstarted_resume_consumed_%s.json" % child_name,
            "c28f_a4_g6_synthetic_unstarted_resume_consumption_v1",
            "FSYNCED_GLOBAL_ONE_SHOT_RESUME_CONSUMED",
            "receipt_sha256",
            False,
        ),
        (
            "rehydrate_%s.json" % child_name,
            "c28f_a4_g6_synthetic_postimage_rehydrate_record_v1",
            "FSYNCED_CONTROLLER_ISSUED",
            "record_sha256",
            False,
        ),
        (
            "rehydrate_access_%s.json" % child_name,
            "c28f_a4_g6_synthetic_postimage_rehydrate_access_v1",
            "CONTROLLER_READONLY_SYNTHETIC_POSTIMAGE_REHYDRATED",
            "access_receipt_sha256",
            False,
        ),
    )
    fingerprints: dict[str, dict[str, Any]] = {}
    for name, schema, status_value, hash_field, required in specifications:
        path = session / name
        if not os.path.lexists(path):
            _require(not required, "G6 legacy migration lacks consume authority")
            continue
        record, encoded = _read_canonical_json(path)
        subject = (
            record.get("payload")
            if schema
            in {
                "c28f_a4_g6_synthetic_unstarted_resume_record_v1",
                "c28f_a4_g6_synthetic_postimage_rehydrate_record_v1",
            }
            else record
        )
        _require(
            isinstance(record, dict)
            and record.get("schema_version") == schema
            and record.get("status") == status_value
            and isinstance(subject, dict)
            and subject.get("synthetic_root_handle_sha256")
            == root_handle_sha256
            and subject.get("crash_point") == crash_point
            and subject.get("child_root_name", child_name) == child_name
            and subject.get("child_root_binding_sha256")
            == expected_binding
            and record.get(hash_field)
            == semantic_sha256(record, excluded_fields=(hash_field,)),
            f"G6 legacy terminal authority record drift: {name}",
        )
        if name.startswith("consume_"):
            _require(
                set(record)
                == {
                    "schema_version", "status",
                    "synthetic_root_handle_sha256", "crash_point",
                    "child_root_name", "child_root_path",
                    "child_root_binding_sha256", "precondition_observed",
                    "receipt_sha256",
                }
                and record["precondition_observed"] == "ABSENT",
                "G6 legacy consume authority exact contract",
            )
        if name.startswith("rehydrate_"):
            actual = subject.get("actual_postimage")
            if actual is not None:
                _validate_g6_actual_postimage(actual)
        fingerprints[name] = {
            "schema_version": schema,
            "status": status_value,
            "semantic_sha256": record[hash_field],
            "file_sha256": bytes_sha256(encoded),
            "size_bytes": len(encoded),
        }
    _require(
        bool(fingerprints)
        and "consume_%s.json" % child_name in fingerprints,
        "G6 legacy terminal migration authority prefix",
    )
    return dict(sorted(fingerprints.items()))


def _validate_g6_legacy_terminal_migration_intent(
    value: Any,
    *,
    session: Path,
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
    actual_postimage: Mapping[str, Any],
) -> dict[str, Any]:
    exact_fields = {
        "schema_version", "status", "goal_id", "attempt_id", "session_id",
        "committed_transaction_id", "committed_state_sha256",
        "committed_event_sha256", "synthetic_root_handle_sha256",
        "crash_point", "child_root_name", "child_root_path",
        "child_root_binding_sha256", "parent_descriptor_identity_sha256",
        "child_root_contract_sha256", "legacy_authority_records",
        "legacy_authority_records_sha256", "fixed_body_source_sha256",
        "execution_contract", "actual_postimage_sha256", "migration_mode",
        "body_executed", "old_owner_identity", "old_owner_death_proof",
        "takeover_claimed", "model_forward_evaluations",
        "real_data_optimizer_updates", "extra_model_forward_splits",
        "intent_sha256",
    }
    crash_point = value.get("crash_point") if isinstance(value, dict) else None
    child_name = value.get("child_root_name") if isinstance(value, dict) else None
    _require(
        crash_point in root_payload["permitted_crash_points"],
        "G6 legacy terminal migration crash point",
    )
    actual_postimage = _validate_g6_actual_postimage(actual_postimage)
    _require(
        actual_postimage["synthetic_root_handle_sha256"]
        == root_handle_sha256
        and actual_postimage["crash_point"] == crash_point,
        "G6 legacy terminal migration postimage lineage",
    )
    _plan, expected_contract = _g6_fixed_operation_plan(str(crash_point))
    expected_records = _g6_legacy_terminal_authority_records(
        session=session,
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
        crash_point=str(crash_point),
        actual_postimage=actual_postimage,
    )
    _require(
        isinstance(value, dict)
        and set(value) == exact_fields
        and value["schema_version"]
        == "c28f_a4_g6_legacy_terminal_migration_intent_v2"
        and value["status"]
        == "FSYNCED_CONTROLLER_READONLY_LEGACY_TERMINAL_MIGRATION_INTENT"
        and value["goal_id"] == GOAL_ID
        and value["attempt_id"] == root_payload["attempt_id"]
        and value["session_id"] == _g6_synthetic_session_id(root_payload)
        and value["committed_transaction_id"]
        == root_payload["committed_transaction_id"]
        and value["committed_state_sha256"]
        == root_payload["committed_state_sha256"]
        and value["committed_event_sha256"]
        == root_payload["committed_event_sha256"]
        and value["synthetic_root_handle_sha256"] == root_handle_sha256
        and crash_point in root_payload["permitted_crash_points"]
        and child_name == root_payload["child_root_names"][crash_point]
        and value["child_root_path"]
        == str(Path(root_payload["parent_root_path"]) / child_name)
        and value["child_root_binding_sha256"]
        == actual_postimage["root_identity"]["child_root_binding_sha256"]
        and value["parent_descriptor_identity_sha256"]
        == root_payload["parent_descriptor_identity_sha256"]
        and value["child_root_contract_sha256"]
        == root_payload["child_root_contract_sha256"]
        and value["legacy_authority_records"] == expected_records
        and value["legacy_authority_records_sha256"]
        == bytes_sha256(canonical_json_bytes(expected_records))
        and value["fixed_body_source_sha256"]
        == _g6_fixed_body_source_sha256()
        and value["execution_contract"] == expected_contract
        and value["actual_postimage_sha256"]
        == actual_postimage["postimage_sha256"]
        and value["migration_mode"] == "READ_ONLY_EXACT_TERMINAL"
        and value["body_executed"] is False
        and value["old_owner_identity"] is None
        and value["old_owner_death_proof"] is None
        and value["takeover_claimed"] is False
        and value["model_forward_evaluations"] == 0
        and value["real_data_optimizer_updates"] == 0
        and value["extra_model_forward_splits"] == 0
        and value["intent_sha256"]
        == semantic_sha256(value, excluded_fields=("intent_sha256",)),
        "G6 legacy terminal migration intent exact contract",
    )
    return dict(value)


def _build_g6_legacy_terminal_migration_intent(
    *,
    session: Path,
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
    crash_point: str,
    actual_postimage: Mapping[str, Any],
) -> dict[str, Any]:
    child_name = root_payload["child_root_names"][crash_point]
    records = _g6_legacy_terminal_authority_records(
        session=session,
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
        crash_point=crash_point,
        actual_postimage=actual_postimage,
    )
    _plan, execution_contract = _g6_fixed_operation_plan(crash_point)
    base = {
        "schema_version": "c28f_a4_g6_legacy_terminal_migration_intent_v2",
        "status": (
            "FSYNCED_CONTROLLER_READONLY_LEGACY_TERMINAL_MIGRATION_INTENT"
        ),
        "goal_id": GOAL_ID,
        "attempt_id": root_payload["attempt_id"],
        "session_id": _g6_synthetic_session_id(root_payload),
        "committed_transaction_id": root_payload["committed_transaction_id"],
        "committed_state_sha256": root_payload["committed_state_sha256"],
        "committed_event_sha256": root_payload["committed_event_sha256"],
        "synthetic_root_handle_sha256": root_handle_sha256,
        "crash_point": crash_point,
        "child_root_name": child_name,
        "child_root_path": str(
            Path(root_payload["parent_root_path"]) / child_name
        ),
        "child_root_binding_sha256": actual_postimage["root_identity"][
            "child_root_binding_sha256"
        ],
        "parent_descriptor_identity_sha256": root_payload[
            "parent_descriptor_identity_sha256"
        ],
        "child_root_contract_sha256": root_payload[
            "child_root_contract_sha256"
        ],
        "legacy_authority_records": records,
        "legacy_authority_records_sha256": bytes_sha256(
            canonical_json_bytes(records)
        ),
        "fixed_body_source_sha256": _g6_fixed_body_source_sha256(),
        "execution_contract": execution_contract,
        "actual_postimage_sha256": actual_postimage["postimage_sha256"],
        "migration_mode": "READ_ONLY_EXACT_TERMINAL",
        "body_executed": False,
        "old_owner_identity": None,
        "old_owner_death_proof": None,
        "takeover_claimed": False,
        "model_forward_evaluations": 0,
        "real_data_optimizer_updates": 0,
        "extra_model_forward_splits": 0,
    }
    intent = {**base, "intent_sha256": semantic_sha256(base)}
    return _validate_g6_legacy_terminal_migration_intent(
        intent,
        session=session,
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
        actual_postimage=actual_postimage,
    )


def validate_g6_controller_execution_capability(
    value: Any,
) -> dict[str, Any]:
    payload = _validate_opaque_capability(
        value,
        A4G6ControllerExecutionCapability,
    )
    exact_fields = {
        "schema_version", "status", "goal_id", "attempt_id",
        "synthetic_root_handle_sha256", "crash_point", "child_root_name",
        "child_root_binding_sha256", "parent_descriptor_identity_sha256",
        "child_descriptor_identity_sha256", "execution_intent_sha256",
        "fixed_body_source_sha256", "executor_version",
        "writer_lease_binding_sha256", "owner_identity_sha256",
        "synthetic_only", "real_data_allowed", "path_export_allowed",
        "external_executor_allowed", "one_shot", "execution_binding_sha256",
    }
    root_payload = validate_g6_synthetic_root_handle(value._root_handle)
    intent = _validate_g6_executor_intent(
        value._intent,
        root_payload=root_payload,
        root_handle_sha256=value._root_handle.capability_sha256,
    )
    fixed_executor = intent["fixed_executor"]
    owner = _validate_g6_executor_owner(
        value._owner,
        root_payload=root_payload,
        root_handle_sha256=value._root_handle.capability_sha256,
        crash_point=intent["crash_point"],
        child_name=intent["child_root_name"],
        generation=value._owner["generation"],
        previous_owners=value._previous_owners,
        writer_lease_binding_sha256=fixed_executor[
            "writer_lease_binding_sha256"
        ],
    )
    child_descriptor = value._child_descriptor
    _require(
        isinstance(payload, dict)
        and set(payload) == exact_fields
        and payload["schema_version"]
        == "c28f_a4_g6_controller_execution_capability_v2"
        and payload["status"] == "ACTIVE_CONTROLLER_FIXED_EXECUTION"
        and payload["goal_id"] == GOAL_ID
        and payload["attempt_id"] == root_payload["attempt_id"]
        and payload["synthetic_root_handle_sha256"]
        == value._root_handle.capability_sha256
        and payload["crash_point"] == intent["crash_point"]
        and payload["child_root_name"] == intent["child_root_name"]
        and payload["child_root_binding_sha256"]
        == intent["child_root_binding_sha256"]
        and payload["parent_descriptor_identity_sha256"]
        == intent["parent_descriptor_identity_sha256"]
        and payload["child_descriptor_identity_sha256"]
        == semantic_sha256(child_descriptor)
        and payload["execution_intent_sha256"] == intent["intent_sha256"]
        and payload["fixed_body_source_sha256"]
        == fixed_executor["reviewed_source_sha256"]
        and payload["executor_version"] == G6_EXECUTOR_VERSION
        and payload["writer_lease_binding_sha256"]
        == fixed_executor["writer_lease_binding_sha256"]
        and payload["owner_identity_sha256"]
        == owner["owner_binding_sha256"]
        and payload["synthetic_only"] is True
        and payload["real_data_allowed"] is False
        and payload["path_export_allowed"] is False
        and payload["external_executor_allowed"] is False
        and payload["one_shot"] is True
        and payload["execution_binding_sha256"]
        == semantic_sha256(
            payload,
            excluded_fields=("execution_binding_sha256",),
        )
        and type(value._session) is _A4G6ControllerOwnedSyntheticSession
        and value._session._state == "ISSUED_UNCONSUMED"
        and value._session._crash_point == payload["crash_point"]
        and value._session._directory_device == child_descriptor["device"]
        and value._session._directory_inode == child_descriptor["inode"]
        and value._session._directory_mount_id
        == child_descriptor["mount_id"],
        "G6 controller fixed execution capability exact contract",
    )
    _require(
        len(value._previous_owners) == owner["generation"]
        and (
            not value._previous_owners
            or value._previous_owners[0] == intent["initial_owner"]
        ),
        "G6 controller execution owner chain binding",
    )
    return dict(payload)


def validate_g6_synthetic_root_handle(value: Any) -> dict[str, Any]:
    payload = _validate_opaque_capability(
        value,
        A4G6SyntheticRootHandle,
    )
    exact_fields = {
        "schema_version", "goal_id", "attempt_id",
        "committed_transaction_id", "committed_state_sha256",
        "committed_event_sha256", "parent_root_id", "parent_root_path",
        "parent_descriptor_record", "parent_descriptor_identity_sha256",
        "child_root_names", "permitted_crash_points",
        "child_root_contract_sha256", "synthetic_only",
        "real_data_allowed", "one_shot_per_child", "handle_binding_sha256",
    }
    required_points = {
        "BEFORE_CHECKPOINT_COMMIT",
        "AFTER_CHECKPOINT_BEFORE_MANIFEST",
        "DURING_EVAL",
        "BEFORE_STATUS_RENAME",
    }
    child_names = payload.get("child_root_names")
    descriptor = payload.get("parent_descriptor_record")
    _require(
        set(payload) == exact_fields
        and payload["schema_version"]
        == "c28f_a4_g6_synthetic_root_handle_v1"
        and payload["goal_id"] == GOAL_ID
        and payload["parent_root_id"] == "g6-synthetic-recovery-parent"
        and isinstance(payload["parent_root_path"], str)
        and Path(payload["parent_root_path"]).is_absolute()
        and Path(payload["parent_root_path"])
        == Path(payload["parent_root_path"]).resolve(strict=True)
        and isinstance(descriptor, dict)
        and descriptor.get("path") == payload["parent_root_path"]
        and descriptor.get("resolved") == payload["parent_root_path"]
        and descriptor.get("type") == "directory"
        and descriptor.get("nlink") == 2
        and type(descriptor.get("mount_id")) is int
        and descriptor["mount_id"] > 0
        and payload["parent_descriptor_identity_sha256"]
        == semantic_sha256(descriptor)
        and isinstance(child_names, dict)
        and set(child_names) == required_points
        and set(payload["permitted_crash_points"]) == required_points
        and len(payload["permitted_crash_points"]) == 4
        and payload["permitted_crash_points"]
        == sorted(payload["permitted_crash_points"])
        and len(set(child_names.values())) == 4
        and all(
            isinstance(name, str)
            and re.fullmatch(r"scenario-[a-z0-9-]{3,80}", name)
            is not None
            and "/" not in name
            for name in child_names.values()
        )
        and payload["child_root_contract_sha256"]
        == semantic_sha256(
            {
                "schema_version": "c28f_a4_g6_child_root_contract_v1",
                "parent_root_id": payload["parent_root_id"],
                "parent_descriptor_identity_sha256": payload[
                    "parent_descriptor_identity_sha256"
                ],
                "child_root_names": child_names,
                "permitted_crash_points": payload[
                    "permitted_crash_points"
                ],
                "precondition": "CANONICAL_ABSOLUTE_NONEXISTENT_CHILD",
                "same_parent_descriptor_required": True,
                "same_mount_required": True,
                "one_shot_per_child": True,
            }
        )
        and payload["synthetic_only"] is True
        and payload["real_data_allowed"] is False
        and payload["one_shot_per_child"] is True
        and payload["handle_binding_sha256"]
        == semantic_sha256(
            payload,
            excluded_fields=("handle_binding_sha256",),
        ),
        "G6 synthetic root handle exact contract",
    )
    parent = Path(payload["parent_root_path"])
    current = parent.lstat()
    _require(
        stat.S_ISDIR(current.st_mode)
        and not stat.S_ISLNK(current.st_mode)
        and (int(current.st_dev), int(current.st_ino))
        == (descriptor["device"], descriptor["inode"]),
        "G6 synthetic parent current inode binding",
    )
    parent_fd = _open_directory(parent)
    try:
        _require(
            _fd_mount_id(parent_fd) == descriptor["mount_id"],
            "G6 synthetic parent mount binding",
        )
    finally:
        os.close(parent_fd)
    session_id = _g6_synthetic_session_id(payload)
    record, _record_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "transactions"
        / session_id
        / "root_handle.json"
    )
    _require(
        isinstance(record, dict)
        and set(record)
        == {
            "schema_version", "status", "capability_sha256", "payload",
            "record_sha256",
        }
        and record["schema_version"]
        == "c28f_a4_g6_synthetic_root_handle_record_v1"
        and record["status"] == "FSYNCED_CONTROLLER_ISSUED"
        and record["capability_sha256"] == value.capability_sha256
        and record["payload"] == payload
        and record["record_sha256"]
        == semantic_sha256(record, excluded_fields=("record_sha256",)),
        "G6 synthetic root handle persisted issuance",
    )
    return payload


def validate_g6_synthetic_unstarted_resume_capability(
    value: Any,
) -> dict[str, Any]:
    payload = _validate_opaque_capability(
        value,
        A4G6SyntheticUnstartedResumeCapability,
    )
    exact_fields = {
        "schema_version", "status", "goal_id", "attempt_id",
        "synthetic_root_handle_sha256", "crash_point",
        "child_root_name", "child_root_path",
        "child_root_binding_sha256", "consumption_receipt_sha256",
        "parent_descriptor_identity_sha256", "child_descriptor",
        "child_descriptor_identity_sha256", "controller_precreated_empty",
        "synthetic_only", "one_shot_per_capability", "resume_binding_sha256",
    }
    root_payload = validate_g6_synthetic_root_handle(value._root_handle)
    crash_point = payload.get("crash_point")
    child_name = payload.get("child_root_name")
    child_descriptor = payload.get("child_descriptor")
    _require(
        set(payload) == exact_fields
        and payload["schema_version"]
        == "c28f_a4_g6_synthetic_unstarted_resume_capability_v1"
        and payload["status"]
        == "FSYNCED_CONTROLLER_PRECREATED_EMPTY_CHILD_FOR_RESUME"
        and payload["goal_id"] == GOAL_ID
        and payload["attempt_id"] == root_payload["attempt_id"]
        and payload["synthetic_root_handle_sha256"]
        == value._root_handle.capability_sha256
        and crash_point in root_payload["permitted_crash_points"]
        and child_name == root_payload["child_root_names"][crash_point]
        and payload["child_root_path"]
        == str(Path(root_payload["parent_root_path"]) / child_name)
        and payload["parent_descriptor_identity_sha256"]
        == root_payload["parent_descriptor_identity_sha256"]
        and isinstance(child_descriptor, dict)
        and set(child_descriptor)
        == {
            "canonical_path", "parent_canonical_path", "device", "inode",
            "nlink", "mode", "mtime_ns", "ctime_ns", "mount_id",
            "parent_descriptor_identity_sha256",
            "child_root_binding_sha256",
        }
        and child_descriptor["canonical_path"]
        == payload["child_root_path"]
        and child_descriptor["parent_canonical_path"]
        == root_payload["parent_root_path"]
        and child_descriptor["mode"] == "0o700"
        and child_descriptor["mount_id"]
        == root_payload["parent_descriptor_record"]["mount_id"]
        and child_descriptor["parent_descriptor_identity_sha256"]
        == payload["parent_descriptor_identity_sha256"]
        and child_descriptor["child_root_binding_sha256"]
        == payload["child_root_binding_sha256"]
        and payload["child_descriptor_identity_sha256"]
        == semantic_sha256(child_descriptor)
        and payload["controller_precreated_empty"] is True
        and payload["synthetic_only"] is True
        and payload["one_shot_per_capability"] is True
        and payload["resume_binding_sha256"]
        == semantic_sha256(
            payload,
            excluded_fields=("resume_binding_sha256",),
        ),
        "G6 unstarted resume capability exact contract",
    )
    current_descriptor = _g6_empty_child_descriptor(
        root_payload=root_payload,
        root_handle_sha256=value._root_handle.capability_sha256,
        crash_point=crash_point,
        child_root_binding_sha256=payload[
            "child_root_binding_sha256"
        ],
        create_if_absent=False,
    )
    _require(
        current_descriptor == child_descriptor,
        "G6 unstarted resume child descriptor drift",
    )
    session = (
        CONTROL_ROOT
        / "transactions"
        / _g6_synthetic_session_id(root_payload)
    )
    consumption, _consume_bytes = _read_canonical_json(
        session / ("consume_%s.json" % child_name)
    )
    _require(
        consumption.get("receipt_sha256")
        == payload["consumption_receipt_sha256"]
        == semantic_sha256(
            consumption,
            excluded_fields=("receipt_sha256",),
        )
        and consumption.get("child_root_binding_sha256")
        == payload["child_root_binding_sha256"],
        "G6 unstarted resume child consumption lineage",
    )
    record, _record_bytes = _read_canonical_json(
        session / ("unstarted_reissue_%s.json" % child_name)
    )
    _require(
        set(record)
        == {
            "schema_version", "status", "capability_sha256", "payload",
            "record_sha256",
        }
        and record["schema_version"]
        == "c28f_a4_g6_synthetic_unstarted_resume_record_v1"
        and record["status"] == "FSYNCED_UNSTARTED_REISSUE_CLAIM"
        and record["capability_sha256"] == value.capability_sha256
        and record["payload"] == payload
        and record["record_sha256"]
        == semantic_sha256(record, excluded_fields=("record_sha256",)),
        "G6 persisted unstarted resume claim",
    )
    return payload


def _validate_g6_actual_postimage(value: Any) -> dict[str, Any]:
    _require(
        isinstance(value, dict)
        and set(value)
        == {
            "schema_version", "synthetic_root_handle_sha256",
            "crash_point", "root_identity", "artifact_count",
            "artifact_inventory", "artifact_inventory_sha256",
            "postimage_sha256",
        }
        and value["schema_version"]
        == "c28f_g6_synthetic_actual_postimage_v2"
        and isinstance(value["root_identity"], dict)
        and set(value["root_identity"])
        == {
            "canonical_path", "parent_canonical_path", "device", "inode",
            "nlink", "mode", "mtime_ns", "ctime_ns", "mount_id",
            "parent_descriptor_identity_sha256",
            "child_root_binding_sha256",
        }
        and Path(value["root_identity"]["canonical_path"]).is_absolute()
        and Path(value["root_identity"]["canonical_path"])
        == Path(value["root_identity"]["canonical_path"]).resolve(
            strict=True
        )
        and Path(
            value["root_identity"]["parent_canonical_path"]
        ).is_absolute()
        and Path(value["root_identity"]["canonical_path"]).parent
        == Path(value["root_identity"]["parent_canonical_path"])
        and Path(value["root_identity"]["parent_canonical_path"])
        == Path(
            value["root_identity"]["parent_canonical_path"]
        ).resolve(strict=True)
        and type(value["root_identity"]["device"]) is int
        and value["root_identity"]["device"] > 0
        and type(value["root_identity"]["inode"]) is int
        and value["root_identity"]["inode"] > 0
        and type(value["root_identity"]["nlink"]) is int
        and value["root_identity"]["nlink"] >= 2
        and value["root_identity"]["mode"] == "0o700"
        and type(value["root_identity"]["mtime_ns"]) is int
        and value["root_identity"]["mtime_ns"] > 0
        and type(value["root_identity"]["ctime_ns"]) is int
        and value["root_identity"]["ctime_ns"] > 0
        and type(value["root_identity"]["mount_id"]) is int
        and value["root_identity"]["mount_id"] > 0
        and isinstance(
            value["root_identity"][
                "parent_descriptor_identity_sha256"
            ],
            str,
        )
        and HEX64.fullmatch(
            value["root_identity"][
                "parent_descriptor_identity_sha256"
            ]
        ) is not None
        and isinstance(
            value["root_identity"]["child_root_binding_sha256"], str
        )
        and HEX64.fullmatch(
            value["root_identity"]["child_root_binding_sha256"]
        ) is not None
        and type(value["artifact_count"]) is int
        and 1 <= value["artifact_count"] <= 16
        and isinstance(value["artifact_inventory"], list)
        and len(value["artifact_inventory"]) == value["artifact_count"]
        and all(
            isinstance(item, dict)
            and set(item)
            == {
                "name", "size_bytes", "sha256", "device", "inode",
                "nlink", "mode", "mtime_ns", "ctime_ns", "mount_id",
            }
            and isinstance(item["name"], str)
            and re.fullmatch(
                r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", item["name"]
            ) is not None
            and type(item["size_bytes"]) is int
            and item["size_bytes"] > 0
            and isinstance(item["sha256"], str)
            and HEX64.fullmatch(item["sha256"]) is not None
            and type(item["device"]) is int
            and item["device"] > 0
            and type(item["inode"]) is int
            and item["inode"] > 0
            and item["nlink"] == 1
            and item["mode"] == "0o600"
            and type(item["mtime_ns"]) is int
            and item["mtime_ns"] > 0
            and type(item["ctime_ns"]) is int
            and item["ctime_ns"] > 0
            and item["device"] == value["root_identity"]["device"]
            and item["mount_id"] == value["root_identity"]["mount_id"]
            for item in value["artifact_inventory"]
        )
        and [item["name"] for item in value["artifact_inventory"]]
        == sorted({item["name"] for item in value["artifact_inventory"]})
        and len(
            {
                (item["device"], item["inode"])
                for item in value["artifact_inventory"]
            }
        ) == value["artifact_count"]
        and value["artifact_inventory_sha256"]
        == bytes_sha256(canonical_json_bytes(value["artifact_inventory"]))
        and value["postimage_sha256"]
        == semantic_sha256(value, excluded_fields=("postimage_sha256",)),
        "G6 actual postimage exact contract",
    )
    expected_bytes = _g6_fixed_expected_material(value["crash_point"])[
        "expected_artifact_bytes"
    ]
    expected_manifest = [
        {
            "name": name,
            "size_bytes": len(expected_bytes[name]),
            "sha256": bytes_sha256(expected_bytes[name]),
        }
        for name in sorted(expected_bytes)
    ]
    observed_manifest = [
        {
            "name": item["name"],
            "size_bytes": item["size_bytes"],
            "sha256": item["sha256"],
        }
        for item in value["artifact_inventory"]
    ]
    _require(
        observed_manifest == expected_manifest,
        "G6 actual postimage fixed terminal bytes manifest",
    )
    return dict(value)


def validate_g6_synthetic_postimage_rehydrate_capability(
    value: Any,
) -> dict[str, Any]:
    payload = _validate_opaque_capability(
        value,
        A4G6SyntheticPostimageRehydrateCapability,
    )
    exact_fields = {
        "schema_version", "status", "goal_id", "attempt_id",
        "synthetic_root_handle_sha256", "crash_point",
        "child_root_name", "child_root_binding_sha256",
        "consumption_receipt_sha256",
        "parent_descriptor_identity_sha256", "actual_postimage",
        "actual_postimage_sha256", "synthetic_only", "real_data_allowed",
        "read_only", "one_shot_per_capability",
        "rehydrate_binding_sha256",
    }
    root_payload = validate_g6_synthetic_root_handle(value._root_handle)
    crash_point = payload.get("crash_point")
    child_name = payload.get("child_root_name")
    _require(
        set(payload) == exact_fields
        and payload["schema_version"]
        == "c28f_a4_g6_synthetic_postimage_rehydrate_capability_v1"
        and payload["status"]
        == "CONTROLLER_VERIFIED_SYNTHETIC_POSTIMAGE_REHYDRATE"
        and payload["goal_id"] == GOAL_ID
        and payload["attempt_id"] == root_payload["attempt_id"]
        and payload["synthetic_root_handle_sha256"]
        == value._root_handle.capability_sha256
        and crash_point in root_payload["permitted_crash_points"]
        and root_payload["child_root_names"][crash_point] == child_name
        and payload["parent_descriptor_identity_sha256"]
        == root_payload["parent_descriptor_identity_sha256"]
        and payload["synthetic_only"] is True
        and payload["real_data_allowed"] is False
        and payload["read_only"] is True
        and payload["one_shot_per_capability"] is True
        and payload["rehydrate_binding_sha256"]
        == semantic_sha256(
            payload,
            excluded_fields=("rehydrate_binding_sha256",),
        ),
        "G6 postimage rehydrate capability exact contract",
    )
    actual = _validate_g6_actual_postimage(payload["actual_postimage"])
    _require(
        actual["postimage_sha256"] == payload["actual_postimage_sha256"]
        and actual["synthetic_root_handle_sha256"]
        == payload["synthetic_root_handle_sha256"]
        and actual["crash_point"] == crash_point
        and actual["root_identity"]["child_root_binding_sha256"]
        == payload["child_root_binding_sha256"]
        and actual["root_identity"][
            "parent_descriptor_identity_sha256"
        ] == payload["parent_descriptor_identity_sha256"],
        "G6 postimage rehydrate actual postimage binding",
    )
    session = (
        CONTROL_ROOT
        / "transactions"
        / _g6_synthetic_session_id(root_payload)
    )
    consumption, _consume_bytes = _read_canonical_json(
        session / ("consume_%s.json" % child_name)
    )
    _require(
        consumption.get("synthetic_root_handle_sha256")
        == payload["synthetic_root_handle_sha256"]
        and consumption.get("crash_point") == crash_point
        and consumption.get("child_root_name") == child_name
        and consumption.get("child_root_binding_sha256")
        == payload["child_root_binding_sha256"]
        and consumption.get("receipt_sha256")
        == payload["consumption_receipt_sha256"]
        == semantic_sha256(
            consumption,
            excluded_fields=("receipt_sha256",),
        ),
        "G6 postimage rehydrate child consumption lineage",
    )
    record, _record_bytes = _read_canonical_json(
        session / ("rehydrate_%s.json" % child_name)
    )
    _require(
        set(record)
        == {
            "schema_version", "status", "capability_sha256", "payload",
            "record_sha256",
        }
        and record["schema_version"]
        == "c28f_a4_g6_synthetic_postimage_rehydrate_record_v1"
        and record["status"] == "FSYNCED_CONTROLLER_ISSUED"
        and record["capability_sha256"] == value.capability_sha256
        and record["payload"] == payload
        and record["record_sha256"]
        == semantic_sha256(record, excluded_fields=("record_sha256",)),
        "G6 persisted postimage rehydrate capability",
    )
    return payload


def validate_g6_bundle_input_handle(value: Any) -> dict[str, Any]:
    payload = _validate_opaque_capability(value, A4G6BundleInputHandle)
    exact_fields = {
        "schema_version", "goal_id", "attempt_id",
        "committed_transaction_id", "committed_state_sha256",
        "committed_event_sha256", "synthetic_root_handle_sha256",
        "crash_evidence_receipts", "crash_evidence_set_sha256",
        "candidate_f1_report", "committed_global_ledger_snapshot",
        "role_lock_sha256", "g2_replay_evidence_sha256",
        "formal_policy_sha256", "input_binding_sha256",
    }
    _require(
        set(payload) == exact_fields
        and payload["schema_version"]
        == "c28f_a4_g6_bundle_input_handle_v1"
        and payload["goal_id"] == GOAL_ID
        and payload["input_binding_sha256"]
        == semantic_sha256(
            payload,
            excluded_fields=("input_binding_sha256",),
        ),
        "G6 bundle input handle field/binding contract",
    )
    receipts = payload["crash_evidence_receipts"]
    required_points = {
        "BEFORE_CHECKPOINT_COMMIT",
        "AFTER_CHECKPOINT_BEFORE_MANIFEST",
        "DURING_EVAL",
        "BEFORE_STATUS_RENAME",
    }
    _require(
        isinstance(receipts, list)
        and len(receipts) == 4
        and {receipt.get("crash_point") for receipt in receipts}
        == required_points
        and all(
            isinstance(receipt, dict)
            and set(receipt)
            == {
                "schema_version", "status", "goal_id", "attempt_id",
                "synthetic_root_handle_sha256", "crash_point",
                "child_root_name", "child_root_path",
                "parent_descriptor_identity_sha256",
                "child_root_contract_sha256", "child_root_binding_sha256",
                "evidence_sha256", "evidence_file_sha256",
                "actual_postimage", "controller_reread_postimage_sha256",
                "real_data_optimizer_updates", "extra_model_forward_splits",
                "receipt_sha256",
            }
            and receipt.get("schema_version")
            == "c28f_g6_controlled_synthetic_crash_receipt_v2"
            and receipt.get("status") == "PASS"
            and receipt.get("synthetic_root_handle_sha256")
            == payload["synthetic_root_handle_sha256"]
            and receipt.get("child_root_binding_sha256")
            == semantic_sha256(
                {
                    "synthetic_root_handle_sha256": receipt[
                        "synthetic_root_handle_sha256"
                    ],
                    "crash_point": receipt["crash_point"],
                    "child_root_name": receipt["child_root_name"],
                    "child_root_path": receipt["child_root_path"],
                    "parent_descriptor_identity_sha256": receipt[
                        "parent_descriptor_identity_sha256"
                    ],
                    "child_root_contract_sha256": receipt[
                        "child_root_contract_sha256"
                    ],
                }
            )
            and receipt.get("actual_postimage", {}).get(
                "root_identity", {}
            ).get("canonical_path") == receipt.get("child_root_path")
            and receipt.get("actual_postimage", {}).get(
                "root_identity", {}
            ).get("parent_descriptor_identity_sha256")
            == receipt.get("parent_descriptor_identity_sha256")
            and receipt.get("actual_postimage", {}).get(
                "root_identity", {}
            ).get("child_root_binding_sha256")
            == receipt.get("child_root_binding_sha256")
            and _validate_g6_actual_postimage(
                receipt.get("actual_postimage")
            )["synthetic_root_handle_sha256"]
            == payload["synthetic_root_handle_sha256"]
            and receipt.get("controller_reread_postimage_sha256")
            == receipt.get("actual_postimage", {}).get("postimage_sha256")
            and receipt.get("receipt_sha256")
            == semantic_sha256(
                receipt,
                excluded_fields=("receipt_sha256",),
            )
            for receipt in receipts
        )
        and payload["crash_evidence_set_sha256"]
        == bytes_sha256(canonical_json_bytes(receipts)),
        "G6 bundle crash receipt exact set",
    )
    candidate = payload["candidate_f1_report"]
    ledger = payload["committed_global_ledger_snapshot"]
    _require(
        isinstance(candidate, dict)
        and candidate.get("report_sha256")
        == semantic_sha256(candidate, excluded_fields=("report_sha256",))
        and candidate.get("status")
        == "SYNTHETIC_PROTOCOL_EVIDENCE_AWAITING_CONTROL_LEDGER"
        and candidate.get("real_data_optimizer_updates") == 0
        and candidate.get("extra_model_forward_splits") == 0
        and isinstance(ledger, dict)
        and ledger.get("snapshot_sha256")
        == semantic_sha256(ledger, excluded_fields=("snapshot_sha256",))
        and ledger.get("real_data_optimizer_updates") == 0
        and ledger.get("extra_model_forward_splits") == 0,
        "G6 bundle candidate/global ledger binding",
    )
    for field in (
        "committed_state_sha256", "committed_event_sha256",
        "synthetic_root_handle_sha256", "crash_evidence_set_sha256",
        "role_lock_sha256", "g2_replay_evidence_sha256",
        "formal_policy_sha256", "input_binding_sha256",
    ):
        _require(
            isinstance(payload[field], str)
            and HEX64.fullmatch(payload[field]) is not None,
            "G6 bundle input hash: %s" % field,
        )
    transactions = CONTROL_ROOT / "transactions"
    with os.scandir(transactions) as iterator:
        sessions = sorted(
            Path(entry.path)
            for entry in iterator
            if G6_SYNTHETIC_SESSION_RE.fullmatch(entry.name) is not None
            and entry.is_dir(follow_symlinks=False)
            and not entry.is_symlink()
        )
    _require(len(sessions) == 1, "G6 bundle persisted session cardinality")
    bundle_record, _bundle_bytes = _read_canonical_json(
        sessions[0] / "bundle_input.json"
    )
    _require(
        bundle_record.get("schema_version")
        == "c28f_a4_g6_bundle_input_record_v1"
        and bundle_record.get("capability_sha256") == value.capability_sha256
        and bundle_record.get("payload") == payload
        and bundle_record.get("record_sha256")
        == semantic_sha256(
            bundle_record,
            excluded_fields=("record_sha256",),
        ),
        "G6 bundle input persisted record binding",
    )
    state, _state_bytes, events, _journal = _current_state_and_events()
    _require(
        state.get("transaction_id") == payload["committed_transaction_id"]
        and state.get("state_sha256") == payload["committed_state_sha256"]
        and events[-1].get("event_sha256")
        == payload["committed_event_sha256"],
        "G6 bundle input current control anchor",
    )
    return payload


def _validate_g7_final_artifact_inputs(value: Any) -> dict[str, Any]:
    exact_fields = {
        "schema_version", "goal_id", "attempt_id", "routing_decision",
        "routing_decision_file_sha256", "eval_ledger_entries",
        "eval_ledger_entries_sha256", "role_lock_sha256",
        "role_lock_file_sha256", "formal_policy_sha256",
        "formal_policy_file_sha256", "access_summary",
        "committed_stage_artifacts",
        "committed_stage_artifacts_sha256", "inputs_sha256",
    }
    _require(
        isinstance(value, dict)
        and set(value) == exact_fields
        and value.get("schema_version")
        == "c28f_a4_g7_final_artifact_inputs_v1"
        and value.get("goal_id") == GOAL_ID
        and isinstance(value.get("attempt_id"), str)
        and A4_ATTEMPT_RE.fullmatch(value["attempt_id"]) is not None
        and value.get("inputs_sha256")
        == semantic_sha256(value, excluded_fields=("inputs_sha256",)),
        "G7 final artifact input field/self-hash contract",
    )
    for field in (
        "routing_decision_file_sha256", "eval_ledger_entries_sha256",
        "role_lock_sha256", "role_lock_file_sha256",
        "formal_policy_sha256", "formal_policy_file_sha256",
        "committed_stage_artifacts_sha256", "inputs_sha256",
    ):
        _require(
            isinstance(value[field], str)
            and HEX64.fullmatch(value[field]) is not None,
            "G7 final artifact input hash: %s" % field,
        )
    routing = value["routing_decision"]
    _require(
        isinstance(routing, dict)
        and routing.get("schema_version")
        == "c28f_f0_routing_decision_v1"
        and routing.get("status")
        in {"ROUTING_CONSISTENT", "ROUTING_AMBIGUOUS"}
        and routing.get("routing_decision_sha256")
        == semantic_sha256(
            routing,
            excluded_fields=("routing_decision_sha256",),
        )
        and routing.get("f2_or_higher_executed") is False,
        "G7 final artifact routing input",
    )
    eval_entries = value["eval_ledger_entries"]
    _require(
        isinstance(eval_entries, list)
        and len(eval_entries) == 2
        and [item.get("token_id") for item in eval_entries]
        == ["F0_A", "F0_B"],
        "G7 final eval ledger cardinality/order",
    )
    for entry in eval_entries:
        _require(
            isinstance(entry, dict)
            and isinstance(entry.get("source_file_sha256"), str)
            and HEX64.fullmatch(entry["source_file_sha256"]) is not None
            and entry.get("status")
            == "ONE_LOGICAL_EVAL_COMPLETED_NONREPLAYABLE"
            and entry.get("logical_eval_count") == 1,
            "G7 final eval ledger entry shape",
        )
        original = dict(entry)
        original.pop("source_file_sha256")
        _require(
            original.get("ledger_entry_sha256")
            == semantic_sha256(
                original,
                excluded_fields=("ledger_entry_sha256",),
            ),
            "G7 final eval ledger entry self-hash",
        )
    _require(
        value["eval_ledger_entries_sha256"]
        == bytes_sha256(canonical_json_bytes(eval_entries))
        and eval_entries[0].get("eval_id") != eval_entries[1].get("eval_id"),
        "G7 final eval ledger aggregate binding",
    )
    access = value["access_summary"]
    _require(
        isinstance(access, dict)
        and access.get("schema_version")
        == "c28f_a4_protected_data_access_summary_v1"
        and access.get("status")
        == "ZERO_FORBIDDEN_ACCESS_WITH_AUTHORIZED_ID_ONLY_MAPPING"
        and access.get("goal_id") == GOAL_ID
        and access.get("attempt_id") == value["attempt_id"]
        and access.get("summary_sha256")
        == semantic_sha256(access, excluded_fields=("summary_sha256",)),
        "G7 protected-data access summary input",
    )
    expected_access_keys = {
        "protected_model_eval", "protected_feature_get",
        "protected_prediction_read", "protected_metric_read",
        "protected_query_text_read", "protected_timestamp_read",
        "protected_label_read", "official_workflow",
        "forbidden_value_materialization", "unresolved_open_intent",
        "c28e_historical_write_bytes", "teacher_model_forward",
        "gt_support_injection", "gt_append",
        "posthoc_temperature_refit_during_eval",
        "protected_id_mapping_operations",
    }
    access_counts = access.get("access_counts")
    _require(
        isinstance(access_counts, dict)
        and set(access_counts) == expected_access_keys
        and access_counts["protected_id_mapping_operations"] == 1
        and all(
            type(access_counts[key]) is int and access_counts[key] == 0
            for key in expected_access_keys
            if key != "protected_id_mapping_operations"
        ),
        "G7 protected-data access counts",
    )
    authorized_mapping = access.get("authorized_id_mapping")
    _require(
        authorized_mapping
        == {
            "operation_count": 1,
            "physical_content_open_count": 5,
            "manifest_content_open_count": 3,
            "train_jsonl_projection_content_open_count": 2,
            "protected_desc_manifest_content_open_count": 2,
            "train_fit_manifest_content_open_count": 1,
            "protected_desc_train_jsonl_indexed_pread_content_open_count": 1,
            "train_fit_train_jsonl_indexed_pread_content_open_count": 1,
            "full_train_file_sequential_rescan_count": 0,
            "decoded_fields": ["desc_id", "vid_name"],
            "model_forward_count": 0,
            "official_eval_count": 0,
            "protected_eval_count": 0,
            "access_receipt_sha256": authorized_mapping.get(
                "access_receipt_sha256"
            ) if isinstance(authorized_mapping, dict) else None,
        }
        and isinstance(authorized_mapping["access_receipt_sha256"], str)
        and HEX64.fullmatch(authorized_mapping["access_receipt_sha256"])
        is not None,
        "G7 authorized ID-mapping exact physical-open classification",
    )
    proof_bindings = access.get("proof_bindings")
    _require(
        isinstance(proof_bindings, dict)
        and set(proof_bindings)
        == {
            "g1_safety_manifest_sha256",
            "g1_safety_manifest_file_sha256",
            "protected_mapping_manifest_sha256",
            "protected_mapping_manifest_file_sha256",
            "protected_mapping_completion_receipt_sha256",
            "protected_mapping_completion_receipt_file_sha256",
            "train_fit_mapping_file_sha256",
            "train_fit_source_receipt_file_sha256",
            "projection_stage_commit_receipt_sha256",
            "event_chain_tail_sha256",
        }
        and all(
            isinstance(value, str) and HEX64.fullmatch(value) is not None
            for value in proof_bindings.values()
        ),
        "G7 protected-data access proof bindings",
    )
    artifacts = value["committed_stage_artifacts"]
    artifact_fields = {
        "path", "sha256", "size_bytes", "producer_command",
        "producer_command_sha256", "input_lineage",
        "input_lineage_sha256", "split", "teacher_flags",
        "ground_truth_flags", "validity", "quarantined",
        "stage_action", "stage_commit_receipt_sha256",
    }
    expected_actions = {
        "G1_FAIL_CLOSED_GUARD", "G2_METRIC_CONTRACT",
        "G3_F0_A_BASELINE_FORENSICS",
        "G4_PROTECTED_ID_MAPPING_PROJECTION", "G4_ROLE_POLICY_LOCK",
        "G5_F0_B_EXPOSURE_REPLICATION",
        "G6_F1_PROTOCOL_AND_RECOVERY",
    }
    _require(
        isinstance(artifacts, list)
        and bool(artifacts)
        and artifacts == sorted(artifacts, key=lambda item: item["path"])
        and len({item["path"] for item in artifacts}) == len(artifacts),
        "G7 committed artifact inventory order/cardinality",
    )
    observed_actions: set[str] = set()
    for artifact in artifacts:
        _require(
            isinstance(artifact, dict)
            and set(artifact) == artifact_fields
            and isinstance(artifact["path"], str)
            and artifact["path"].split("/", 1)[0]
            in {"f0_forensics", "f1_protocol"}
            and ".." not in artifact["path"].split("/")
            and isinstance(artifact["sha256"], str)
            and HEX64.fullmatch(artifact["sha256"]) is not None
            and type(artifact["size_bytes"]) is int
            and artifact["size_bytes"] > 0
            and artifact["validity"] == "VALID_COMMITTED"
            and artifact["quarantined"] is False
            and artifact["stage_action"] in expected_actions
            and isinstance(artifact["stage_commit_receipt_sha256"], str)
            and HEX64.fullmatch(
                artifact["stage_commit_receipt_sha256"]
            ) is not None,
            "G7 committed artifact inventory row",
        )
        command = artifact["producer_command"]
        _require(
            isinstance(command, dict)
            and set(command)
            == {
                "launcher", "python_flag", "action", "stage_plan_sha256",
                "stage_commit_id", "stage_commit_receipt_sha256",
            }
            and command["launcher"]
            == "blueprint_e2e_v2/c28f_v5/a4_runner.py"
            and command["python_flag"] == "-B"
            and command["action"] == artifact["stage_action"]
            and command["stage_commit_receipt_sha256"]
            == artifact["stage_commit_receipt_sha256"]
            and artifact["producer_command_sha256"]
            == bytes_sha256(canonical_json_bytes(command)),
            "G7 committed artifact producer command",
        )
        lineage = artifact["input_lineage"]
        _require(
            isinstance(lineage, dict)
            and bool(lineage)
            and all(
                isinstance(digest, str)
                and HEX64.fullmatch(digest) is not None
                for digest in lineage.values()
            )
            and artifact["input_lineage_sha256"]
            == bytes_sha256(canonical_json_bytes(lineage))
            and isinstance(artifact["teacher_flags"], dict)
            and set(artifact["teacher_flags"])
            == {
                "teacher_model_forward", "teacher_candidate_used",
                "teacher_shadow_value_fabricated",
            }
            and all(
                value is False
                for value in artifact["teacher_flags"].values()
            )
            and isinstance(artifact["ground_truth_flags"], dict)
            and set(artifact["ground_truth_flags"])
            == {
                "evaluation_labels_used", "support_injected",
                "candidate_appended",
            }
            and artifact["ground_truth_flags"]["support_injected"] is False
            and artifact["ground_truth_flags"]["candidate_appended"] is False,
            "G7 committed artifact lineage/safety flags",
        )
        observed_actions.add(str(artifact["stage_action"]))
    _require(
        observed_actions == expected_actions
        and value["committed_stage_artifacts_sha256"]
        == bytes_sha256(canonical_json_bytes(artifacts)),
        "G7 committed artifact aggregate/action closure",
    )
    return dict(value)


def _validate_finalization_snapshot_payload(payload: Any) -> dict[str, Any]:
    _require(
        isinstance(payload, dict)
        and set(payload)
        == {
            "schema_version", "goal_id", "attempt_id", "committed_state_sha256",
            "committed_event_sha256", "committed_transaction_id",
            "authority_snapshot", "authority_source_path",
            "authority_source_file_sha256", "ledger_snapshot",
            "ledger_source_binding_sha256", "gates_snapshot",
            "gates_source_binding_sha256", "g6_final_report",
            "g6_final_report_file_sha256", "g6_control_binding",
            "g6_control_binding_file_sha256", "final_artifact_inputs",
            "closed_authority",
        }
        and payload["schema_version"]
        == "c28f_a4_finalization_snapshot_capability_v1"
        and payload["goal_id"] == GOAL_ID
        and isinstance(payload["attempt_id"], str)
        and A4_ATTEMPT_RE.fullmatch(payload["attempt_id"]) is not None
        and payload["authority_source_path"] == "authority_ledger.json",
        "finalization snapshot capability field set",
    )
    authority = payload["authority_snapshot"]
    ledger = payload["ledger_snapshot"]
    gates = payload["gates_snapshot"]
    final_inputs = _validate_g7_final_artifact_inputs(
        payload["final_artifact_inputs"]
    )
    closed = payload["closed_authority"]
    _require(
        isinstance(authority, dict)
        and authority.get("authority_sha256")
        == semantic_sha256(authority, excluded_fields=("authority_sha256",)),
        "finalization authority snapshot binding",
    )
    _require(
        isinstance(ledger, dict)
        and ledger.get("snapshot_sha256")
        == semantic_sha256(ledger, excluded_fields=("snapshot_sha256",)),
        "finalization ledger snapshot binding",
    )
    _require(
        isinstance(gates, dict)
        and gates.get("snapshot_sha256")
        == semantic_sha256(gates, excluded_fields=("snapshot_sha256",)),
        "finalization gate snapshot binding",
    )
    _require(
        final_inputs["attempt_id"] == payload["attempt_id"],
        "finalization/G7 artifact input attempt binding",
    )
    _require(
        isinstance(closed, dict)
        and closed.get("authority_sha256")
        == semantic_sha256(closed, excluded_fields=("authority_sha256",))
        and closed.get("reactivation_allowed") is False
        and closed.get("permissions", {})
        .get("AUTH_F0_F1_IMPLEMENTATION", {})
        .get("state")
        == "CONSUMED_CLOSED",
        "finalization closed authority binding",
    )
    for field in (
        "committed_state_sha256", "committed_event_sha256",
        "authority_source_file_sha256", "ledger_source_binding_sha256",
        "gates_source_binding_sha256", "g6_final_report_file_sha256",
        "g6_control_binding_file_sha256",
    ):
        _require(
            isinstance(payload[field], str) and HEX64.fullmatch(payload[field]),
            f"finalization snapshot hash: {field}",
        )
    return dict(payload)


def validate_finalization_snapshot_capability(value: Any) -> dict[str, Any]:
    payload = _validate_opaque_capability(
        value,
        A4FinalizationSnapshotCapability,
    )
    validated = _validate_finalization_snapshot_payload(payload)
    _state, _state_bytes, events, _journal = _current_state_and_events()
    record, _record_bytes = _read_canonical_json(
        CONTROL_ROOT / "finalization_snapshot.json"
    )
    persisted = _validate_finalization_snapshot_record(
        record,
        events=events,
    )
    _require(
        persisted == validated
        and record["capability_sha256"] == value.capability_sha256,
        "finalization capability/persisted snapshot binding",
    )
    return validated


def _validate_finalization_snapshot_record(
    value: Any,
    *,
    events: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    _require(
        isinstance(value, dict)
        and set(value)
        == {
            "schema_version", "status", "capability_sha256", "payload",
            "record_sha256",
        }
        and value["schema_version"]
        == "c28f_a4_finalization_snapshot_record_v1"
        and value["status"] == "FSYNCED_CONTROLLER_PRIVATE_SNAPSHOT"
        and value["record_sha256"]
        == semantic_sha256(value, excluded_fields=("record_sha256",)),
        "persisted finalization snapshot record fields",
    )
    payload = _validate_finalization_snapshot_payload(value["payload"])
    g6_events = [
        event
        for event in events
        if event.get("action") == "G6_F1_PROTOCOL_AND_RECOVERY"
    ]
    _require(len(g6_events) == 1, "persisted finalization unique G6 event")
    g6_event = g6_events[0]
    attempt_id = str(g6_event["attempt_id"])
    _require(
        payload["attempt_id"] == attempt_id
        and payload["committed_transaction_id"]
        == g6_event["transaction_id"]
        and payload["committed_event_sha256"] == g6_event["event_sha256"]
        and payload["committed_state_sha256"]
        == g6_event["expected_next_state_sha256"]
        and value["capability_sha256"] == semantic_sha256(payload),
        "persisted finalization snapshot G6 lineage",
    )
    authority_source, _authority_bytes, authority_record = (
        _read_a4_genesis_authority_snapshot(events)
    )
    authority, closed_authority = _finalization_authority_snapshots(
        source=authority_source,
        source_file_sha256=str(authority_record["sha256"]),
        attempt_id=attempt_id,
        mapping_token_state="COMPLETED_NONREPLAYABLE",
    )
    genesis_ledger, genesis_ledger_file_sha = (
        _read_committed_g1_genesis_registry(
            "g1_global_ledger_snapshot.json"
        )
    )
    final_report_bytes, final_report_file_sha = _committed_stage_artifact(
        attempt_id=attempt_id,
        events=events,
        relative_path="f1_protocol/f1_protocol_report.final.json",
    )
    binding_bytes, binding_file_sha = _committed_stage_artifact(
        attempt_id=attempt_id,
        events=events,
        relative_path="f1_protocol/g6_control_binding.json",
    )
    final_report = _canonical_json_artifact(
        final_report_bytes,
        label="persisted G6 final protocol report",
    )
    g6_binding = _canonical_json_artifact(
        binding_bytes,
        label="persisted G6 control binding",
    )
    _require(
        final_report.get("report_sha256")
        == semantic_sha256(
            final_report,
            excluded_fields=("report_sha256",),
        )
        and final_report.get("status")
        == "F1_COMPLETE_ONLY_WITH_G6_STAGE_COMMIT_RECEIPT"
        and final_report.get("real_data_optimizer_updates") == 0
        and final_report.get("extra_model_forward_splits") == 0
        and g6_binding.get("binding_sha256")
        == semantic_sha256(
            g6_binding,
            excluded_fields=("binding_sha256",),
        )
        and g6_binding.get("schema_version")
        == "c28f_g6_control_binding_v2"
        and g6_binding.get("final_report_sha256")
        == final_report["report_sha256"]
        and g6_binding.get("global_ledger_snapshot_sha256")
        == genesis_ledger["snapshot_sha256"]
        and g6_binding.get("real_data_optimizer_updates") == 0
        and g6_binding.get("extra_model_forward_splits") == 0,
        "persisted finalization G6 source contract",
    )
    eval_token_states = {"F0_A": "COMPLETED", "F0_B": "COMPLETED"}
    ledger_base = {
        "schema_version": "c28f_a4_finalization_ledger_snapshot_v1",
        "goal_id": GOAL_ID,
        "attempt_id": attempt_id,
        "g1_genesis_snapshot_sha256": genesis_ledger["snapshot_sha256"],
        "g1_genesis_snapshot_file_sha256": genesis_ledger_file_sha,
        "g6_global_ledger_snapshot_sha256": g6_binding[
            "global_ledger_snapshot_sha256"
        ],
        "eval_token_states": eval_token_states,
        "model_forward_counts": {
            "F0_A": 1,
            "F0_B": 1,
            "protected": 0,
            "other": 0,
        },
        "model_forward_evaluations": 2,
        "real_data_optimizer_updates": 0,
        "extra_model_forward_splits": 0,
    }
    ledger = {
        **ledger_base,
        "snapshot_sha256": semantic_sha256(ledger_base),
    }
    gates = _finalization_gate_snapshot(
        attempt_id=attempt_id,
        events=events,
    )
    g6_state, _g6_state_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "state_records"
        / (
            "%06d_%s.json"
            % (g6_event["seq"], g6_event["expected_next_state_sha256"])
        )
    )
    _require(
        isinstance(g6_state, dict)
        and g6_state.get("state_sha256")
        == g6_event["expected_next_state_sha256"],
        "persisted finalization G6 state record",
    )
    g6_event_prefix = list(events[: int(g6_event["seq"]) + 1])
    final_artifact_inputs = _g7_committed_final_artifact_inputs(
        state=g6_state,
        events=g6_event_prefix,
    )
    _validate_g7_final_artifact_inputs(final_artifact_inputs)
    expected_payload = {
        "schema_version": "c28f_a4_finalization_snapshot_capability_v1",
        "goal_id": GOAL_ID,
        "attempt_id": attempt_id,
        "committed_state_sha256": g6_event[
            "expected_next_state_sha256"
        ],
        "committed_event_sha256": g6_event["event_sha256"],
        "committed_transaction_id": g6_event["transaction_id"],
        "authority_snapshot": authority,
        "authority_source_path": "authority_ledger.json",
        "authority_source_file_sha256": authority_record["sha256"],
        "ledger_snapshot": ledger,
        "ledger_source_binding_sha256": semantic_sha256(
            {
                "g1_genesis_snapshot_file_sha256": (
                    genesis_ledger_file_sha
                ),
                "g6_control_binding_file_sha256": binding_file_sha,
            }
        ),
        "gates_snapshot": gates,
        "gates_source_binding_sha256": gates["source_binding_sha256"],
        "g6_final_report": final_report,
        "g6_final_report_file_sha256": final_report_file_sha,
        "g6_control_binding": g6_binding,
        "g6_control_binding_file_sha256": binding_file_sha,
        "final_artifact_inputs": final_artifact_inputs,
        "closed_authority": closed_authority,
    }
    _require(
        payload == expected_payload,
        "persisted finalization snapshot deterministic rebuild",
    )
    return dict(payload)


def _read_committed_g1_genesis_registry(
    name: str,
) -> tuple[dict[str, Any], str]:
    _require(
        name
        in {
            "g1_registry_authority.json",
            "g1_global_ledger_snapshot.json",
            "g1_mediation_registry.json",
            "g1_probe_detector_registry.json",
        },
        "unknown G1 Genesis registry",
    )
    payload, encoded, record = _read_bound_canonical_json(
        CONTROL_ROOT,
        name,
        max_bytes=16 * 1024 * 1024,
        forbidden_identities=_protected_identities_from_a3(),
    )
    _require(isinstance(payload, dict), f"G1 Genesis registry object: {name}")
    sidecar_relative = (
        f"registry_records/000000_{name[:-5]}_{record['sha256']}.json"
    )
    sidecar, sidecar_record = _read_bound_regular(
        CONTROL_ROOT,
        sidecar_relative,
        max_bytes=16 * 1024 * 1024,
        forbidden_identities=_protected_identities_from_a3(),
    )
    _require(
        sidecar == encoded and sidecar_record["sha256"] == record["sha256"],
        f"G1 Genesis registry/sidecar mismatch: {name}",
    )
    return dict(payload), str(record["sha256"])


def issue_g1_control_handle(
    *,
    bootstrap_lease: BootstrapLease,
) -> A4G1ControlHandle:
    """Issue only from the four immutable, sidecar-bound G0-A4 Genesis registries."""

    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_G1_CONTROL_HANDLE",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        pre_g1_control_only = all(
            CODE_CHANGE_TXN_RE.fullmatch(str(event.get("transaction_id")))
            is not None
            and event.get("action")
            in {
                "PREPARE_REVIEWED_CODE_CHANGE",
                "COMMIT_REVIEWED_CODE_CHANGE",
            }
            for event in events[1:]
        )
        _require(
            state.get("transition_seq") == len(events) - 1
            and state.get("stage") == "G0"
            and state.get("status") == "PREFLIGHT_OK"
            and state.get("next_action") == "G1_FAIL_CLOSED_GUARD"
            and state.get("protected_model_evals") == 0
            and state.get("protected_content_opens_current_attempt") == 0
            and state.get("real_data_optimizer_updates") == 0
            and pre_g1_control_only,
            "G1 handle requires the verified Genesis-plus-code-change G1 boundary",
        )
        authority, authority_file_sha = _read_committed_g1_genesis_registry(
            "g1_registry_authority.json"
        )
        snapshot, snapshot_file_sha = _read_committed_g1_genesis_registry(
            "g1_global_ledger_snapshot.json"
        )
        mediation, mediation_file_sha = _read_committed_g1_genesis_registry(
            "g1_mediation_registry.json"
        )
        probe, probe_file_sha = _read_committed_g1_genesis_registry(
            "g1_probe_detector_registry.json"
        )
        genesis_hashes = events[0]["output_hashes"]
        _require(
            genesis_hashes.get("g1_registry_authority.json") == authority_file_sha
            and genesis_hashes.get("g1_global_ledger_snapshot.json")
            == snapshot_file_sha
            and genesis_hashes.get("g1_mediation_registry.json")
            == mediation_file_sha
            and genesis_hashes.get("g1_probe_detector_registry.json")
            == probe_file_sha,
            "G1 registries are not the exact Genesis event outputs",
        )
        budget_payload = _g1_budget_payload(
            _validate_a4_intent_file()[0]
        )
        payload = {
            "schema_version": "c28f_a4_g1_control_handle_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "committed_state_sha256": state["state_sha256"],
            "committed_event_sha256": events[-1]["event_sha256"],
            "committed_transaction_id": state["transaction_id"],
            "frozen_authority_sha256": authority["authority_sha256"],
            "persisted_global_snapshot_sha256": snapshot["snapshot_sha256"],
            "mediation_ledger_sha256": mediation["registry_sha256"],
            "probe_detector_snapshot_sha256": probe["registry_sha256"],
            "registry_authority": authority,
            "global_snapshot": snapshot,
            "eval_budget": budget_payload,
            "mediation_registry": mediation,
            "probe_detector_registry": probe,
            "registry_authority_file_sha256": authority_file_sha,
            "global_snapshot_file_sha256": snapshot_file_sha,
            "mediation_registry_file_sha256": mediation_file_sha,
            "probe_detector_registry_file_sha256": probe_file_sha,
        }
        controller = _A4G1LedgerController(
            authority_id=str(authority["authority_id"]),
            goal_id=GOAL_ID,
        )
        handle = _register_opaque_capability(
            A4G1ControlHandle(
                _OPAQUE_CONTROL_ISSUER_SEAL,
                payload,
                controller,
            )
        )
        validate_g1_control_handle(handle)
        return handle


def _eval_control_contract_hashes() -> dict[str, str]:
    return {
        "cursor_contract_sha256": semantic_sha256(
            {
                "schema_version": "c28f_a4_eval_cursor_contract_v1",
                "cursor_index": "MONOTONIC_ZERO_BASED",
                "cursor_sha256": "EXACT",
                "chunks_sha256": "EXACT",
                "artifacts_sha256": "EXACT",
                "state": "RUNNING_ONLY",
            }
        ),
        "chunks_contract_sha256": semantic_sha256(
            {
                "schema_version": "c28f_a4_forward_chunks_contract_v1",
                "atomic_chunks": True,
                "resume_rehash_required": True,
                "orphan_reproduction_required": True,
            }
        ),
        "artifacts_contract_sha256": semantic_sha256(
            {
                "schema_version": "c28f_a4_forward_artifacts_contract_v1",
                "attempt_isolated": True,
                "immutable_receipts": True,
                "completion_equals_cursor_tail": True,
            }
        ),
    }


def _forward_code_source_path(name: str) -> Path:
    if name in {"a4_forward.py", "a4_security.py"}:
        return CODE_ROOT / name
    return REPO_ROOT / "blueprint_e2e_v2" / name


def _decode_train_video_meta_only(data: bytes) -> tuple[tuple[str, ...], tuple[float, ...]]:
    """Decode only the train duration/index object; syntax-skip all other splits."""

    from blueprint_e2e_v2.c28f_v5 import a4_id_projector as scanner

    offset = scanner._skip_ws(data, 0)
    offset = scanner._expect(
        data,
        offset,
        ord("{"),
        "FORWARD_VIDEO_META_TOP_LEVEL_OBJECT_REQUIRED",
    )
    train_rows: Optional[dict[int, tuple[str, float]]] = None
    offset = scanner._skip_ws(data, offset)
    while True:
        split, offset = scanner._scan_plain_ascii_string(
            data,
            offset,
            max_bytes=64,
            code="FORWARD_VIDEO_META_SPLIT_KEY_INVALID",
        )
        offset = scanner._skip_ws(data, offset)
        offset = scanner._expect(
            data,
            offset,
            ord(":"),
            "FORWARD_VIDEO_META_COLON_REQUIRED",
        )
        offset = scanner._skip_ws(data, offset)
        if split != "train":
            offset = scanner._skip_json_value(data, offset, depth=1)
        else:
            _require(train_rows is None, "duplicate train video-meta split")
            train_rows = {}
            offset = scanner._expect(
                data,
                offset,
                ord("{"),
                "FORWARD_TRAIN_VIDEO_META_OBJECT_REQUIRED",
            )
            offset = scanner._skip_ws(data, offset)
            while True:
                video_id, offset = scanner._scan_plain_ascii_string(
                    data,
                    offset,
                    max_bytes=128,
                    code="FORWARD_TRAIN_VIDEO_ID_INVALID",
                )
                _require(
                    SAFE_ENTITY_ID_RE.fullmatch(video_id) is not None,
                    "forward train video ID",
                )
                offset = scanner._skip_ws(data, offset)
                offset = scanner._expect(
                    data,
                    offset,
                    ord(":"),
                    "FORWARD_TRAIN_VIDEO_META_COLON_REQUIRED",
                )
                offset = scanner._skip_ws(data, offset)
                offset = scanner._expect(
                    data,
                    offset,
                    ord("["),
                    "FORWARD_TRAIN_VIDEO_META_ARRAY_REQUIRED",
                )
                offset = scanner._skip_ws(data, offset)
                duration_start = offset
                offset = scanner._skip_json_number(data, offset)
                duration_raw = data[duration_start:offset]
                offset = scanner._skip_ws(data, offset)
                offset = scanner._expect(
                    data,
                    offset,
                    ord(","),
                    "FORWARD_TRAIN_VIDEO_META_COMMA_REQUIRED",
                )
                offset = scanner._skip_ws(data, offset)
                index_start = offset
                offset = scanner._skip_json_number(data, offset)
                index_raw = data[index_start:offset]
                offset = scanner._skip_ws(data, offset)
                offset = scanner._expect(
                    data,
                    offset,
                    ord("]"),
                    "FORWARD_TRAIN_VIDEO_META_ARRAY_END_REQUIRED",
                )
                try:
                    duration = float(duration_raw.decode("ascii", "strict"))
                    index_text = index_raw.decode("ascii", "strict")
                except (UnicodeDecodeError, ValueError) as exc:
                    raise A4ControlError("forward train video meta number") from exc
                _require(
                    index_text.isdigit()
                    and (index_text == "0" or not index_text.startswith("0"))
                    and duration > 0.0
                    and duration == duration
                    and abs(duration) != float("inf"),
                    "forward train duration/index value",
                )
                video_index = int(index_text)
                _require(
                    video_index not in train_rows,
                    "forward train video index duplicate",
                )
                train_rows[video_index] = (video_id, duration)
                offset = scanner._skip_ws(data, offset)
                if offset < len(data) and data[offset] == ord(","):
                    offset = scanner._skip_ws(data, offset + 1)
                    continue
                offset = scanner._expect(
                    data,
                    offset,
                    ord("}"),
                    "FORWARD_TRAIN_VIDEO_META_OBJECT_END_REQUIRED",
                )
                break
        offset = scanner._skip_ws(data, offset)
        if offset < len(data) and data[offset] == ord(","):
            offset = scanner._skip_ws(data, offset + 1)
            continue
        offset = scanner._expect(
            data,
            offset,
            ord("}"),
            "FORWARD_VIDEO_META_OBJECT_END_REQUIRED",
        )
        break
    offset = scanner._skip_ws(data, offset)
    _require(
        offset == len(data)
        and train_rows is not None
        and len(train_rows) == 17_435,
        "forward train video-meta exact row count",
    )
    ordered = list(train_rows.values())
    video_ids = tuple(item[0] for item in ordered)
    durations = tuple(item[1] for item in ordered)
    _require(
        len(set(video_ids)) == 17_435
        and bytes_sha256(
            "".join("%s\n" % value for value in video_ids).encode("utf-8")
        ) == TRAIN_CORPUS_VIDEO_ID_ORDER_SHA256,
        "forward train corpus identity/order",
    )
    return video_ids, durations


def _forward_frozen_file_from_path(
    forward: Any,
    *,
    file_id: str,
    path: Path,
    authority_sha256: str,
) -> Any:
    _assert_safe_path_chain(path)
    named = path.lstat()
    _require(
        stat.S_ISREG(named.st_mode)
        and not stat.S_ISLNK(named.st_mode)
        and named.st_nlink == 1,
        "forward frozen file source",
    )
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
    flags |= getattr(os, "O_NOFOLLOW", 0)
    fd = os.open(path, flags)
    try:
        opened = os.fstat(fd)
        _require(
            (opened.st_dev, opened.st_ino) == (named.st_dev, named.st_ino),
            "forward frozen file open identity",
        )
        mount_id = _fd_mount_id(fd)
    finally:
        os.close(fd)
    return forward.FrozenFile(
        file_id=file_id,
        path=str(path.resolve(strict=True)),
        device=int(named.st_dev),
        inode=int(named.st_ino),
        mount_id=mount_id,
        size_bytes=int(named.st_size),
        mtime_ns=int(named.st_mtime_ns),
        sha256=authority_sha256,
    )


def _register_controller_forward_authority(
    *,
    handle: A4ControllerForwardAuthorityHandle,
    authority: Any,
) -> None:
    payload = validate_controller_forward_authority_handle(handle)
    with _CONTROLLER_FORWARD_AUTHORITY_LOCK:
        _require(
            id(authority) not in _CONTROLLER_FORWARD_AUTHORITY_REGISTRY,
            "controller forward authority object identity replay",
        )
        _CONTROLLER_FORWARD_AUTHORITY_REGISTRY[id(authority)] = {
            "object": authority,
            "handle": handle,
            "handle_capability_sha256": handle.capability_sha256,
            "handle_payload": payload,
            "state": "ISSUED_UNRESERVED",
            "reservation_input_object": None,
            "reservation_input_capability_sha256": None,
        }


def _controller_forward_authority_record(authority: Any) -> dict[str, Any]:
    with _CONTROLLER_FORWARD_AUTHORITY_LOCK:
        record = _CONTROLLER_FORWARD_AUTHORITY_REGISTRY.get(id(authority))
        _require(
            isinstance(record, dict) and record.get("object") is authority,
            "forward authority lacks controller object registration",
        )
        return record


def _rehydrate_unreserved_controller_forward_authority_handle(
    *,
    issuance_record: Mapping[str, Any],
    origin_transaction_id: str,
) -> A4ControllerForwardAuthorityHandle:
    """Recover one fsynced pre-reservation authority from descriptors only."""

    _assert_a4_import_bytecode_absent()
    from blueprint_e2e_v2.c28f_v5 import a4_forward

    payload, projection = (
        _validate_persisted_controller_forward_authority_record(
            dict(issuance_record),
            origin_transaction_id=origin_transaction_id,
        )
    )
    try:
        authority = a4_forward.rehydrate_active_forward_authority(
            projection
        )
    except Exception as exc:
        raise A4ControlError(
            "unreserved forward authority descriptor rehydrate failed"
        ) from exc
    handle = _register_opaque_capability(
        A4ControllerForwardAuthorityHandle(
            _OPAQUE_CONTROL_ISSUER_SEAL,
            payload,
            authority,
        )
    )
    _require(
        handle.capability_sha256 == issuance_record["capability_sha256"],
        "unreserved forward authority rehydrated handle binding",
    )
    _register_controller_forward_authority(
        handle=handle,
        authority=authority,
    )
    runtime = _controller_forward_authority_record(authority)
    _require(
        runtime["state"] == "ISSUED_UNRESERVED"
        and runtime["reservation_input_object"] is None
        and runtime["reservation_input_capability_sha256"] is None,
        "unreserved forward authority recovered runtime state",
    )
    validate_controller_forward_authority_handle(handle)
    return handle


def _validate_recovery_projection_matches_persisted_authority(
    projection: Mapping[str, Any],
    *,
    payload: Mapping[str, Any],
    role_authority: Mapping[str, Any],
) -> None:
    query_identity = payload.get("query_identity")
    _require(
        isinstance(query_identity, dict)
        and projection.get("attempt_id") == payload.get("attempt_id")
        and projection.get("token_id") == payload.get("token_id")
        and projection.get("query_role") == query_identity.get("role")
        and projection.get("split_manifest_sha256")
        == query_identity.get("split_manifest_sha256")
        and projection.get("query_count")
        == query_identity.get("query_count")
        and projection.get("query_keys_sha256")
        == query_identity.get("query_keys_sha256")
        and projection.get("query_types_sha256")
        == query_identity.get("query_types_sha256")
        and projection.get("query_text_slice_commitment_sha256")
        == payload.get("query_text_slice_commitment_sha256")
        and projection.get("selected_projection_sha256")
        == payload.get("query_source_selected_projection_sha256")
        and projection.get("role_manifest_authority_binding_sha256")
        == role_authority.get("authority_binding_sha256")
        and projection.get("source_descriptor")
        == payload.get("query_source_descriptor")
        and projection.get("source_descriptor_identity_sha256")
        == payload.get("query_source_descriptor_identity_sha256")
        and projection.get("source_index_binding_sha256")
        == payload.get("query_source_index_binding_sha256")
        and projection.get("source_index_bootstrap_receipt_sha256")
        == payload.get("query_source_index_bootstrap_receipt_sha256")
        and projection.get("source_file_sha256")
        == payload.get("query_source_file_sha256")
        and projection.get("projection_access_receipt")
        == payload.get("query_identity_source_access_receipt")
        and projection.get("projection_access_receipt_sha256")
        == payload.get("query_identity_source_access_receipt_sha256"),
        "reissued selected projection/persisted authority binding",
    )


def _consume_controller_forward_authority_after_reservation(
    handle: A4ControllerForwardAuthorityHandle,
    *,
    reservation_input_handle: Optional[A4EvalReservationInputHandle],
) -> Any:
    validate_controller_forward_authority_handle(handle)
    authority = handle._forward_authority
    record = _controller_forward_authority_record(authority)
    with _CONTROLLER_FORWARD_AUTHORITY_LOCK:
        _require(
            record["handle"] is handle
            and record["handle_capability_sha256"]
            == handle.capability_sha256
            and record["state"] == "RESERVATION_ISSUED",
            "controller forward authority release order/replay",
        )
        if reservation_input_handle is not None:
            reservation = validate_eval_reservation_input_handle(
                reservation_input_handle
            )
            _require(
                record["reservation_input_object"] is reservation_input_handle
                and record["reservation_input_capability_sha256"]
                == reservation_input_handle.capability_sha256
                and reservation["stage"] == handle.binding()["stage"]
                and reservation["token_id"] == handle.binding()["token_id"]
                and reservation["authority_binding_material_sha256"]
                == handle.binding()["authority_binding_sha256"],
                "controller forward authority reservation postimage mismatch",
            )
        else:
            _require(
                isinstance(record["reservation_input_capability_sha256"], str)
                and HEX64.fullmatch(
                    record["reservation_input_capability_sha256"]
                ) is not None,
                "controller forward authority persisted reservation absent",
            )
        record["state"] = "AUTHORITY_RELEASED"
    return authority


def validate_controller_forward_authority(
    *,
    authority: Any,
) -> dict[str, Any]:
    """Return the exact 23-field binding accepted by a4_forward."""

    _assert_a4_import_bytecode_absent()
    from blueprint_e2e_v2.c28f_v5 import a4_forward

    _require(
        type(authority) is a4_forward.FrozenInputAuthority,
        "exact controller-built FrozenInputAuthority required",
    )
    record = _controller_forward_authority_record(authority)
    with _CONTROLLER_FORWARD_AUTHORITY_LOCK:
        _require(
            record["state"] == "AUTHORITY_RELEASED"
            and record["object"] is authority,
            "controller forward authority is not reservation-bound/released",
        )
        handle_payload = dict(record["handle_payload"])
        handle_sha = str(record["handle_capability_sha256"])
        reservation_sha = str(
            record["reservation_input_capability_sha256"]
        )
    manifest = authority.manifest
    base = {
        "schema_version": "c28f_a4_controller_forward_authority_binding_v1",
        "status": "CONTROLLER_BUILT_REGISTERED_AUTHORITY",
        "goal_id": manifest.goal_id,
        "attempt_id": manifest.attempt_id,
        "authority_id": manifest.authority_id,
        "stage": manifest.stage,
        "purpose": manifest.purpose,
        "authority_handle_sha256": handle_sha,
        "reservation_input_capability_sha256": reservation_sha,
        "authority_binding_sha256": authority.authority_binding_sha256,
        "forward_manifest_sha256": manifest.manifest_sha256,
        "input_identity_sha256": manifest.input_identity_sha256,
        "query_identity_sha256": manifest.query_identity.identity_sha256,
        "query_keys_sha256": manifest.query_identity.query_keys_sha256,
        "query_types_sha256": manifest.query_identity.query_types_sha256,
        "query_rows_sha256": manifest.query_identity.query_rows_sha256,
        "split_manifest_sha256": manifest.query_identity.split_manifest_sha256,
        "corpus_identity_sha256": manifest.corpus_identity.identity_sha256,
        "video_ids_sha256": manifest.corpus_identity.video_ids_sha256,
        "durations_sha256": manifest.corpus_identity.durations_sha256,
        "query_source_descriptor_identity_sha256": handle_payload[
            "query_source_descriptor_identity_sha256"
        ],
        "query_source_selected_projection_sha256": handle_payload[
            "query_source_selected_projection_sha256"
        ],
        "query_source_index_binding_sha256": handle_payload[
            "query_source_index_binding_sha256"
        ],
        "query_source_index_bootstrap_receipt_sha256": handle_payload[
            "query_source_index_bootstrap_receipt_sha256"
        ],
        "query_source_file_sha256": handle_payload[
            "query_source_file_sha256"
        ],
        "query_identity_source_access_receipt_sha256": handle_payload[
            "query_identity_source_access_receipt_sha256"
        ],
        "video_meta_source_file_sha256": handle_payload[
            "video_meta_source_file_sha256"
        ],
    }
    binding = {
        **base,
        "controller_authority_binding_sha256": semantic_sha256(base),
    }
    _require(
        set(binding)
        == {
            "schema_version", "status", "goal_id", "attempt_id",
            "authority_id", "stage", "purpose", "authority_handle_sha256",
            "reservation_input_capability_sha256", "authority_binding_sha256",
            "forward_manifest_sha256", "input_identity_sha256",
            "query_identity_sha256", "query_keys_sha256",
            "query_types_sha256", "query_rows_sha256",
            "split_manifest_sha256", "corpus_identity_sha256",
            "video_ids_sha256", "durations_sha256",
            "query_source_descriptor_identity_sha256",
            "query_source_selected_projection_sha256",
            "query_source_index_binding_sha256",
            "query_source_index_bootstrap_receipt_sha256",
            "query_source_file_sha256",
            "query_identity_source_access_receipt_sha256",
            "video_meta_source_file_sha256",
            "controller_authority_binding_sha256",
        },
        "controller forward authority exact public binding",
    )
    return binding


def issue_controller_forward_authority_handle(
    *,
    bootstrap_lease: BootstrapLease,
    selected_query_projection_capability: Optional[
        A4TrustedSelectedQueryProjectionCapability
    ] = None,
) -> A4ControllerForwardAuthorityHandle:
    """Build all authoritative forward inputs from fixed controller sources."""

    _assert_a4_import_bytecode_absent()
    from blueprint_e2e_v2.c28f_v5 import a4_forward

    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_CONTROLLER_FORWARD_AUTHORITY",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        action_contracts = {
            "G3_F0_A_BASELINE_FORENSICS": {
                "token_id": "F0_A",
                "stage": "G3_F0_A",
                "purpose": "F0_A_TEACHER_FREE_CALIB_SELECT_FORENSICS",
                "role": "calib_select",
            },
            "G5_F0_B_EXPOSURE_REPLICATION": {
                "token_id": "F0_B",
                "stage": "G5_F0_B",
                "purpose": "F0_B_ROUTE_DEV_REPLICATION",
                "role": "train_fit_route_dev",
            },
        }
        contract = action_contracts.get(str(state.get("next_action")))
        _require(
            contract is not None
            and state.get("eval_token_states", {}).get(contract["token_id"])
            == "UNISSUED",
            "controller forward authority requires an unissued F0 action",
        )
        index_sessions = _train_jsonl_index_sessions()
        _require(
            len(index_sessions) == 1,
            "controller forward role authority index session",
        )
        role_id = "%s_FORWARD_QUERY_IDENTITY" % contract["token_id"]
        role_claim_record, _role_claim_bytes = _read_canonical_json(
            index_sessions[0]
            / ("role_authority_claim_%s.json" % role_id)
        )
        role_claim = _validate_f0_role_manifest_preopen_claim(
            role_claim_record,
            state=state,
            events=events,
            expected_token_id=contract["token_id"],
        )
        role_authority_record, _role_authority_bytes = _read_canonical_json(
            index_sessions[0] / ("role_authority_%s.json" % role_id)
        )
        role_authority, desc_ids = (
            _validate_f0_query_role_manifest_authority_record(
                role_authority_record,
                preopen_claim=role_claim,
                state=state,
                events=events,
                expected_token_id=contract["token_id"],
            )
        )
        split_manifest_sha = role_authority["manifest_sha256"]
        split_lineage = {
            "kind": role_authority["source_kind"],
            "path": role_authority["source_path"],
            "file_sha256": role_authority["source_file_sha256"],
            "semantic_sha256": split_manifest_sha,
            "role_manifest_authority_binding_sha256": role_authority[
                "authority_binding_sha256"
            ],
            "manifest_access_receipt_sha256": role_authority[
                "manifest_access_receipt"
            ]["receipt_sha256"],
        }
        _require(
            desc_ids == sorted(set(desc_ids))
            and len(desc_ids)
            >= (8_677 if contract["token_id"] == "F0_A" else 2_048)
            and (
                contract["token_id"] != "F0_A" or len(desc_ids) == 8_677
            ),
            "controller forward exact query universe",
        )
        if type(selected_query_projection_capability) is not (
            A4TrustedSelectedQueryProjectionCapability
        ):
            raise A4ControlError(
                "TRUSTED_DESCRIPTOR_BOUND_SELECTED_QUERY_PROJECTION_OR_"
                "OFFSET_INDEX_CAPABILITY_REQUIRED; TRAIN_JSONL_READ_TO_EOF_"
                "FORBIDDEN"
            )
        projection = validate_trusted_selected_query_projection_capability(
            selected_query_projection_capability
        )
        _require(
            projection["attempt_id"] == state["attempt_id"]
            and projection["token_id"] == contract["token_id"]
            and projection["query_role"] == contract["role"]
            and projection["split_manifest_sha256"] == split_manifest_sha
            and projection["query_count"] == len(desc_ids)
            and projection["role_manifest_authority_binding_sha256"]
            == role_authority["authority_binding_sha256"],
            "trusted selected query projection/control role binding",
        )
        persisted_authorities: list[
            tuple[str, dict[str, Any], dict[str, Any]]
        ] = []
        for origin_transaction_id, authority_path in (
            _controller_forward_authority_record_paths()
        ):
            issuance_record, _issuance_bytes = _read_canonical_json(
                authority_path,
                max_bytes=1024 * 1024 * 1024,
            )
            persisted_payload, _persisted_projection = (
                _validate_persisted_controller_forward_authority_record(
                    issuance_record,
                    origin_transaction_id=origin_transaction_id,
                )
            )
            if persisted_payload["token_id"] == contract["token_id"]:
                persisted_authorities.append(
                    (
                        origin_transaction_id,
                        issuance_record,
                        persisted_payload,
                    )
                )
        _require(
            len(persisted_authorities) <= 1,
            "unreserved controller authority recovery ambiguity",
        )
        if persisted_authorities:
            (
                origin_transaction_id,
                issuance_record,
                persisted_payload,
            ) = persisted_authorities[0]
            _validate_controller_forward_authority_record_lineage(
                persisted_payload,
                state=state,
                events=events,
            )
            _validate_recovery_projection_matches_persisted_authority(
                projection,
                payload=persisted_payload,
                role_authority=role_authority,
            )
            handle = _rehydrate_unreserved_controller_forward_authority_handle(
                issuance_record=issuance_record,
                origin_transaction_id=origin_transaction_id,
            )
            verify_a4_state(bootstrap_lease, active_lease=lease)
            return handle
        query_records = list(
            selected_query_projection_capability.consume_selected_records_once()
        )
        _require(
            [record["desc_id"] for record in query_records] == desc_ids,
            "trusted selected query projection exact desc-ID universe",
        )
        query_descriptor = dict(projection["source_descriptor"])
        query_selected_projection_sha = projection[
            "selected_projection_sha256"
        ]
        query_access_receipt = dict(
            projection["projection_access_receipt"]
        )
        query_keys = tuple(str(record["desc_id"]) for record in query_records)
        query_types = tuple(record["query_type"] for record in query_records)
        query_rows = [
            {"query_id": query_id, "query_type": query_type}
            for query_id, query_type in zip(query_keys, query_types)
        ]
        query_text_slice_commitments = [
            {
                "query_id": str(record["desc_id"]),
                "desc_raw_json_sha256": record[
                    "desc_raw_json_sha256"
                ],
            }
            for record in query_records
        ]
        query_text_slice_commitment_sha = bytes_sha256(
            canonical_json_bytes(query_text_slice_commitments)
        )
        _require(
            projection["query_keys_sha256"]
            == bytes_sha256(
                "".join("%s\n" % value for value in query_keys).encode(
                    "ascii"
                )
            )
            and projection["query_types_sha256"]
            == bytes_sha256(
                "".join("%s\n" % value for value in query_types).encode(
                    "ascii"
                )
            )
            and projection["query_text_slice_commitment_sha256"]
            == query_text_slice_commitment_sha,
            "trusted selected query projection content commitments",
        )
        query_identity = a4_forward.FrozenQueryIdentity(
            role=contract["role"],
            query_keys=query_keys,
            query_types=query_types,
            query_keys_sha256=bytes_sha256(
                "".join("%s\n" % value for value in query_keys).encode("utf-8")
            ),
            query_types_sha256=bytes_sha256(
                "".join("%s\n" % value for value in query_types).encode("utf-8")
            ),
            query_rows_sha256=bytes_sha256(canonical_json_bytes(query_rows)),
            split_manifest_sha256=split_manifest_sha,
        )
        video_meta_data, video_meta_record = read_regular_bytes(
            VIDEO_META,
            max_bytes=4 * 1024 * 1024,
            require_nlink_one=True,
        )
        video_ids, durations = _decode_train_video_meta_only(video_meta_data)
        duration_rows = [
            {"duration_sec": duration, "video_id": video_id}
            for video_id, duration in zip(video_ids, durations)
        ]
        feature_descriptors = {
            name: lstat_identity(path)
            for name, path in sorted(FEATURE_SOURCES.items())
        }
        _require(
            all(
                record["type"] == "file" and record["nlink"] == 1
                for record in feature_descriptors.values()
            ),
            "controller forward feature source descriptors",
        )
        feature_manifest_sha = semantic_sha256(
            {
                "schema_version": "c28f_a4_forward_feature_manifest_v1",
                "feature_descriptors": feature_descriptors,
                "train_video_count": 17_435,
                "train_video_ids_sha256": TRAIN_CORPUS_VIDEO_ID_ORDER_SHA256,
                "source_audits": {
                    "c12_feature_inventory": (
                        "57475e5a966c5ccae33453b2528f35a995464d0b3c7e6547293ae8d605e06fe1"
                    ),
                    "c12_corpus_index_audit": (
                        "a3c4e4814f1e2ee133e7ce42a68d6bb07a941366a33ec3ce1f7a89ddd32ee8ce"
                    ),
                },
            }
        )
        corpus_identity = a4_forward.FrozenCorpusIdentity(
            video_ids=video_ids,
            durations_sec=durations,
            video_ids_sha256=TRAIN_CORPUS_VIDEO_ID_ORDER_SHA256,
            durations_sha256=bytes_sha256(
                canonical_json_bytes(duration_rows)
            ),
            feature_manifest_sha256=feature_manifest_sha,
        )
        code_names = tuple(
            sorted(
                {
                    "a4_forward.py", "a4_security.py",
                    *a4_forward._REQUIRED_PACKAGE_MODULE_BY_SOURCE.keys(),
                    *a4_forward._APPROVED_BUSINESS_MODULE_BY_SOURCE.keys(),
                }
            )
        )
        reviewed_source_sha256 = validate_a4_static_review_receipt()[
            "payload"
        ]["reviewed_files"]
        code_source_sha256 = tuple(
            (
                name,
                reviewed_source_sha256[
                    _forward_code_source_path(name)
                    .relative_to(REPO_ROOT)
                    .as_posix()
                ],
            )
            for name in code_names
        )
        metric_bytes, _metric_file_sha = _committed_stage_artifact(
            attempt_id=str(state["attempt_id"]),
            events=events,
            relative_path="f0_forensics/metric_schema.json",
        )
        evaluator_bytes, _evaluator_file_sha = _committed_stage_artifact(
            attempt_id=str(state["attempt_id"]),
            events=events,
            relative_path="f1_protocol/evaluator_equivalence.json",
        )
        metric = _canonical_json_artifact(metric_bytes, label="metric schema")
        evaluator = _canonical_json_artifact(
            evaluator_bytes,
            label="evaluator equivalence",
        )
        metric_schema_sha = bytes_sha256(canonical_json_bytes(metric))
        evaluator_schema_sha = str(evaluator.get("equivalence_sha256"))
        _require(
            evaluator_schema_sha
            == semantic_sha256(
                evaluator,
                excluded_fields=("equivalence_sha256",),
            ),
            "controller evaluator equivalence commitment",
        )
        _require(
            os.environ.get("CUDA_VISIBLE_DEVICES") == "0",
            "controller forward authority requires CUDA_VISIBLE_DEVICES=0",
        )
        nvml = importlib.import_module("pynvml")
        nvml.nvmlInit()
        try:
            gpu_handle = nvml.nvmlDeviceGetHandleByIndex(0)
            gpu_uuid = nvml.nvmlDeviceGetUUID(gpu_handle)
            gpu_pci = nvml.nvmlDeviceGetPciInfo(gpu_handle).busId
        finally:
            nvml.nvmlShutdown()
        if isinstance(gpu_uuid, bytes):
            gpu_uuid = gpu_uuid.decode("ascii", "strict")
        if isinstance(gpu_pci, bytes):
            gpu_pci = gpu_pci.decode("ascii", "strict")
        gpu_identity = a4_forward.FrozenGpu0Identity.build(
            physical_index=0,
            uuid=str(gpu_uuid),
            pci_bus_id=str(gpu_pci),
            cuda_visible_devices="0",
            logical_device="cuda:0",
            gpu1_action_count=0,
        )
        environment_sha = semantic_sha256(
            {
                "schema_version": "c28f_a4_forward_environment_v1",
                "python_version": list(sys.version_info[:3]),
                "python_executable": os.path.realpath(sys.executable),
                "cuda_visible_devices": "0",
                "gpu0_identity_sha256": gpu_identity.semantic_sha256,
            }
        )
        g1_authority, _g1_authority_file_sha = (
            _read_committed_g1_genesis_registry("g1_registry_authority.json")
        )
        output_root = a4_forward.FrozenDirectory.capture(
            "g1-write-output",
            str(REPORT_ROOT / str(state["attempt_id"]) / "stage_outputs"),
        )
        cache_root = a4_forward.FrozenDirectory.capture(
            "g1-write-cache",
            str(CACHE_ROOT / str(state["attempt_id"])),
        )
        feature_sources = []
        namespace_by_name = {
            "query_lmdb": "QUERY",
            "visual_lmdb": "VISUAL",
            "subtitle_lmdb": "SUBTITLE",
        }
        for source_id, path in sorted(FEATURE_SOURCES.items()):
            descriptor_sha = semantic_sha256(
                {
                    "schema_version": "c28f_a4_shared_lmdb_descriptor_v1",
                    "descriptor": feature_descriptors[source_id],
                    "content_hash_scope": "METADATA_ONLY_SHARED_KEY_GUARDED",
                }
            )
            feature_sources.append(
                a4_forward.FrozenLmdbSource(
                    source_id=source_id,
                    namespace=namespace_by_name[source_id],
                    directory=a4_forward.FrozenDirectory.capture(
                        "%s-directory" % source_id,
                        str(path.parent),
                    ),
                    data_file=_forward_frozen_file_from_path(
                        a4_forward,
                        file_id="%s-data" % source_id,
                        path=path,
                        authority_sha256=descriptor_sha,
                    ),
                )
            )
        checkpoint = _forward_frozen_file_from_path(
            a4_forward,
            file_id="frozen-checkpoint",
            path=CHECKPOINT,
            authority_sha256=EXPECTED_CHECKPOINT_SHA256,
        )
        temporal = a4_forward.FrozenTemporalManifest.build(
            clip_len_sec=1.5,
            target_length=64,
            proposal_widths=(2, 4, 6, 8, 12, 16, 24, 32, 48, 64),
            proposal_stride_rule="max(1,width//4)",
            long_sequence_policy="mean_bin_floor_ceil_resample_all_mask_true",
            short_sequence_policy="right_zero_pad_prefix_mask_true",
            seconds_per_clip_policy=(
                "duration/64_if_raw_clips_gt_64_else_1.5"
            ),
            proposal_sampling_policy="linspace_round_half_to_even_64",
            max_proposals_per_video=64,
            metric_nms_iou_threshold=0.7,
            metric_nms_max_results=100,
        )
        features = a4_forward.FrozenFeatureContract.build(
            query_dim=768,
            visual_dim=4352,
            subtitle_dim=768,
            query_value_max_bytes=a4_forward.QUERY_VALUE_MAX_BYTES,
            visual_value_max_bytes=a4_forward.VISUAL_VALUE_MAX_BYTES,
            subtitle_value_max_bytes=a4_forward.SUBTITLE_VALUE_MAX_BYTES,
            query_sequence_max_length=a4_forward.QUERY_SEQUENCE_MAX_LENGTH,
            video_sequence_max_length=a4_forward.VIDEO_SEQUENCE_MAX_LENGTH,
            decoded_dtype="float32",
            encoded_dtype="float32",
            visual_decoder="msgpack_numpy_features_exact",
            query_subtitle_decoder="npz_allow_pickle_false_features_exact",
        )
        manifest = a4_forward.FrozenForwardManifest.build(
            goal_id=GOAL_ID,
            authority_id=g1_authority["authority_id"],
            stage=contract["stage"],
            purpose=contract["purpose"],
            query_identity=query_identity,
            corpus_identity=corpus_identity,
            checkpoint_sha256=EXPECTED_CHECKPOINT_SHA256,
            model_contract=a4_forward.FrozenModelContract(),
            query_source_id="query_lmdb",
            visual_source_id="visual_lmdb",
            subtitle_source_id="subtitle_lmdb",
            output_root_id=output_root.root_id,
            cache_root_id=cache_root.root_id,
            attempt_id=state["attempt_id"],
            temporal_manifest=temporal,
            feature_contract=features,
            gpu0_identity=gpu_identity,
            code_source_sha256=code_source_sha256,
            metric_schema_sha256=metric_schema_sha,
            evaluator_schema_sha256=evaluator_schema_sha,
            environment_sha256=environment_sha,
        )
        forbidden_roots = tuple(
            sorted(
                {
                    str(rule["canonical_path"])
                    for rule in g1_authority["canonical_path_map"][
                        "forbidden_registry"
                    ]
                }
            )
        )
        forward_authority = a4_forward.FrozenInputAuthority(
            manifest=manifest,
            checkpoint=checkpoint,
            lmdb_sources=tuple(feature_sources),
            output_root=output_root,
            cache_root=cache_root,
            forbidden_roots=forbidden_roots,
        )
        source_semantic_minimization = {
            "query_text_decoded": False,
            "query_type_decoded": True,
            "ground_truth_video_decoded_before_forward": False,
            "ground_truth_timestamp_decoded_before_forward": False,
            "nontrain_video_meta_semantic_decode_count": 0,
            "nonselected_query_payload_semantic_decode_count": 0,
            "query_source_indexed_pread": True,
            "query_source_full_content_hash_computed_during_bootstrap": True,
            "query_source_full_content_hash_computed_during_pread": False,
            "gt_not_in_forward_input": True,
        }
        base = {
            "schema_version": "c28f_a4_controller_forward_authority_handle_v1",
            "status": "CONTROLLER_BUILT_UNRESERVED",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "authority_id": g1_authority["authority_id"],
            "stage": contract["stage"],
            "purpose": contract["purpose"],
            "token_id": contract["token_id"],
            "origin_transaction_id": state["transaction_id"],
            "origin_state_sha256": state["state_sha256"],
            "origin_event_sha256": events[-1]["event_sha256"],
            "forward_manifest_sha256": manifest.manifest_sha256,
            "input_identity_sha256": manifest.input_identity_sha256,
            "authority_binding_sha256": (
                forward_authority.authority_binding_sha256
            ),
            "query_identity": query_identity.as_dict(),
            "query_text_slice_commitment_sha256": (
                query_text_slice_commitment_sha
            ),
            "query_identity_source_access_receipt": query_access_receipt,
            "query_identity_source_access_receipt_sha256": (
                query_access_receipt["receipt_sha256"]
            ),
            "corpus_identity": corpus_identity.as_dict(),
            "query_source_descriptor": query_descriptor,
            "query_source_descriptor_identity_sha256": semantic_sha256(
                query_descriptor
            ),
            "query_source_selected_projection_sha256": (
                query_selected_projection_sha
            ),
            "query_source_index_binding_sha256": projection[
                "source_index_binding_sha256"
            ],
            "query_source_index_bootstrap_receipt_sha256": projection[
                "source_index_bootstrap_receipt_sha256"
            ],
            "query_source_file_sha256": projection[
                "source_file_sha256"
            ],
            "video_meta_source_descriptor": lstat_identity(VIDEO_META),
            "video_meta_source_file_sha256": video_meta_record["sha256"],
            "split_source_lineage": split_lineage,
            "feature_source_descriptor_set_sha256": semantic_sha256(
                {"records": feature_descriptors}
            ),
            "code_source_set_sha256": semantic_sha256(
                {"records": [list(item) for item in code_source_sha256]}
            ),
            "metric_schema_sha256": metric_schema_sha,
            "evaluator_schema_sha256": evaluator_schema_sha,
            "environment_sha256": environment_sha,
            "source_semantic_minimization": source_semantic_minimization,
        }
        payload = {**base, "handle_binding_sha256": semantic_sha256(base)}
        handle = _register_opaque_capability(
            A4ControllerForwardAuthorityHandle(
                _OPAQUE_CONTROL_ISSUER_SEAL,
                payload,
                forward_authority,
            )
        )
        active_rehydrate_projection = dict(
            a4_forward.build_active_forward_authority_rehydrate_projection(
                forward_authority,
                forward_authority_handle_sha256=handle.capability_sha256,
            )
        )
        record_base = {
            "schema_version": "c28f_a4_controller_forward_authority_record_v1",
            "status": "FSYNCED_CONTROLLER_BUILT",
            "capability_sha256": handle.capability_sha256,
            "payload": payload,
            "active_rehydrate_projection": active_rehydrate_projection,
            "active_rehydrate_projection_sha256": (
                active_rehydrate_projection[
                    "projection_binding_sha256"
                ]
            ),
        }
        issuance_record = {
            **record_base,
            "record_sha256": semantic_sha256(record_base),
        }
        atomic_write_immutable(
            CONTROL_ROOT
            / "transactions"
            / state["transaction_id"]
            / "controller_forward_authority.json",
            _canonical_file_bytes(issuance_record),
            lease=lease,
        )
        _register_controller_forward_authority(
            handle=handle,
            authority=forward_authority,
        )
        validate_controller_forward_authority_handle(handle)
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return handle


def rehydrate_active_controller_forward_authority_handle(
    *,
    bootstrap_lease: BootstrapLease,
) -> A4ControllerForwardAuthorityHandle:
    """Rebuild descriptor authority for an active or just-completed eval.

    The COMPLETED branch exists only to close the process-death window between
    token completion and completed-artifact validation.  It reconstructs the
    frozen descriptors already persisted before reservation; it does not
    reopen any query, feature, checkpoint, or TRAIN source.
    """

    _assert_a4_import_bytecode_absent()
    from blueprint_e2e_v2.c28f_v5 import a4_forward

    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "REHYDRATE_ACTIVE_CONTROLLER_FORWARD_AUTHORITY",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        registry, _registry_bytes = _read_eval_registry()
        reserved_phase = (
            state.get("status") == "EVAL_TOKEN_RESERVED"
            and registry.get("token_state") == "RESERVED"
            and state.get("eval_token_states", {}).get(
                registry["token_id"]
            ) == "RESERVED"
            and state.get("transaction_id") == registry["transaction_id"]
            and events[-1].get("transaction_id")
            == registry["transaction_id"]
        )
        running_phase = (
            state.get("status") == "RUNNING"
            and registry.get("token_state") == "RUNNING"
        )
        if running_phase:
            _active_eval_running_anchor(
                state=state,
                events=events,
                registry=registry,
            )
        completed_validation_phase = (
            registry.get("token_state") == "COMPLETED"
            and state.get("eval_token_states", {}).get(
                registry["token_id"]
            )
            == "COMPLETED"
            and state.get("status") == registry.get("resume_status")
            and state.get("next_action") == registry.get("resume_action")
            and state.get("transaction_id") == registry["transaction_id"]
            and events[-1].get("transaction_id")
            == registry["transaction_id"]
            and events[-1].get("action") == "COMPLETE_EVAL_TOKEN"
        )
        _require(
            reserved_phase or running_phase or completed_validation_phase,
            "active forward authority rehydrate current eval phase",
        )
        stem = str(registry["run_id"])
        reservation_record, _reservation_bytes = _read_canonical_json(
            CONTROL_ROOT
            / "transactions"
            / (stem + "-RESERVE")
            / "reservation_input.json"
        )
        reservation = reservation_record.get("payload")
        source_lineage = (
            reservation.get("source_lineage")
            if isinstance(reservation, dict)
            else None
        )
        _require(
            isinstance(reservation, dict)
            and isinstance(source_lineage, dict)
            and reservation_record.get("capability_sha256")
            == registry["reservation_input_capability_sha256"]
            == semantic_sha256(reservation)
            and reservation.get("token_id") == registry["token_id"]
            and reservation.get("eval_id") == registry["eval_id"]
            and reservation.get("execution_binding")
            == registry["execution_binding"],
            "active forward authority rehydrate reservation lineage",
        )
        origin_transaction_id = source_lineage.get(
            "controller_forward_authority_origin_transaction_id"
        )
        _require(
            isinstance(origin_transaction_id, str)
            and bool(origin_transaction_id),
            "active forward authority origin transaction",
        )
        issuance_record, _issuance_bytes = _read_canonical_json(
            CONTROL_ROOT
            / "transactions"
            / origin_transaction_id
            / "controller_forward_authority.json",
            max_bytes=1024 * 1024 * 1024,
        )
        payload = issuance_record.get("payload")
        projection = issuance_record.get("active_rehydrate_projection")
        _require(
            isinstance(payload, dict)
            and isinstance(projection, dict)
            and issuance_record.get("schema_version")
            == "c28f_a4_controller_forward_authority_record_v1"
            and issuance_record.get("status")
            == "FSYNCED_CONTROLLER_BUILT"
            and issuance_record.get("capability_sha256")
            == source_lineage[
                "controller_forward_authority_handle_sha256"
            ]
            == projection.get("forward_authority_handle_sha256")
            and issuance_record.get(
                "active_rehydrate_projection_sha256"
            )
            == projection.get("projection_binding_sha256")
            == semantic_sha256(
                projection,
                excluded_fields=("projection_binding_sha256",),
            )
            and issuance_record.get("record_sha256")
            == semantic_sha256(
                issuance_record,
                excluded_fields=("record_sha256",),
            )
            and payload.get("origin_transaction_id")
            == origin_transaction_id
            and payload.get("token_id") == registry["token_id"]
            and payload.get("authority_binding_sha256")
            == registry["execution_binding"]["authority_binding_sha256"]
            and payload.get("forward_manifest_sha256")
            == registry["execution_binding"]["forward_manifest_sha256"]
            and payload.get("input_identity_sha256")
            == registry["execution_binding"]["input_identity_sha256"],
            "active forward authority persisted recovery projection",
        )
        try:
            authority = a4_forward.rehydrate_active_forward_authority(
                projection
            )
        except Exception as exc:
            raise A4ControlError(
                "active forward authority descriptor rehydrate failed"
            ) from exc
        handle = _register_opaque_capability(
            A4ControllerForwardAuthorityHandle(
                _OPAQUE_CONTROL_ISSUER_SEAL,
                payload,
                authority,
            )
        )
        _require(
            handle.capability_sha256
            == issuance_record["capability_sha256"],
            "active forward authority rehydrated handle binding",
        )
        _register_controller_forward_authority(
            handle=handle,
            authority=authority,
        )
        runtime = _controller_forward_authority_record(authority)
        with _CONTROLLER_FORWARD_AUTHORITY_LOCK:
            _require(
                runtime["state"] == "ISSUED_UNRESERVED",
                "active forward authority fresh runtime state",
            )
            runtime["state"] = "RESERVATION_ISSUED"
            runtime["reservation_input_object"] = None
            runtime["reservation_input_capability_sha256"] = registry[
                "reservation_input_capability_sha256"
            ]
        validate_controller_forward_authority_handle(handle)
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return handle


def rehydrate_current_completed_forward_artifact_handle(
    *,
    bootstrap_lease: BootstrapLease,
) -> Any:
    """Return the current completed handle, including the narrow-gap repair."""

    _assert_a4_import_bytecode_absent()
    from blueprint_e2e_v2.c28f_v5 import a4_forward

    verified = verify_a4_state(bootstrap_lease)
    registry, _registry_bytes = _read_eval_registry()
    _require(
        registry.get("token_state") == "COMPLETED"
        and verified.get("status") == registry.get("resume_status")
        and verified.get("next_action") == registry.get("resume_action"),
        "current completed forward artifact control tail",
    )
    run_id = str(registry["run_id"])
    sessions = _completed_forward_rehydrate_sessions()
    matching_sessions = []
    for session in sessions:
        record, _record_bytes = _read_canonical_json(
            session / "record.json"
        )
        payload = record.get("payload")
        if isinstance(payload, dict) and payload.get("run_id") == run_id:
            matching_sessions.append(session)
    _require(
        len(matching_sessions) <= 1,
        "current completed forward rehydrate session ambiguity",
    )
    adapter = A4EvalForwardControlAdapter(bootstrap_lease)
    if matching_sessions:
        rehydrate_capability = issue_completed_forward_rehydrate_capability(
            bootstrap_lease=bootstrap_lease,
            run_id=run_id,
        )
        return a4_forward.rehydrate_completed_forward_run_artifact_handle(
            control=adapter,
            rehydrate_capability=rehydrate_capability,
        )
    authority_handle = rehydrate_active_controller_forward_authority_handle(
        bootstrap_lease=bootstrap_lease,
    )
    authority = authority_handle.consume_authority_after_reservation(
        reservation_input_handle=None,
    )
    running_capability = (
        issue_persisted_eval_running_capability_for_completed_validation(
            bootstrap_lease=bootstrap_lease,
            run_id=run_id,
        )
    )
    adapter.bind_completed_historical_running_capability(
        running_capability
    )
    return (
        a4_forward.recover_completed_forward_run_artifact_handle_from_control(
            authority=authority,
            control=adapter,
            running_capability=running_capability,
        )
    )


def issue_eval_reservation_input_handle(
    *,
    bootstrap_lease: BootstrapLease,
    forward_authority_handle: A4ControllerForwardAuthorityHandle,
) -> A4EvalReservationInputHandle:
    """Reserve only the exact authority built and registered by this controller."""

    _assert_a4_import_bytecode_absent()
    from blueprint_e2e_v2.c28f_v5 import a4_forward

    controller_authority_payload = (
        validate_controller_forward_authority_handle(
            forward_authority_handle
        )
    )
    forward_authority = forward_authority_handle._forward_authority
    _require(
        type(forward_authority) is a4_forward.FrozenInputAuthority,
        "controller forward authority handle object binding",
    )
    _require(
        type(forward_authority.manifest) is a4_forward.FrozenForwardManifest,
        "exact FrozenForwardManifest required",
    )
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_EVAL_RESERVATION_INPUT_HANDLE",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        manifest = forward_authority.manifest
        action_contracts = {
            "G3_F0_A_BASELINE_FORENSICS": {
                "token_id": "F0_A",
                "stage": "G3_F0_A",
                "purpose": "F0_A_TEACHER_FREE_CALIB_SELECT_FORENSICS",
                "query_role": "calib_select",
                "minimum_query_count": 8_677,
                "maximum_query_count": 8_677,
                "split_manifest_sha256": (
                    "b2c2a6ec3386d1ff7a3ffd409a8b0f3859ddfb7edddab34d607981b0345a467d"
                ),
            },
            "G5_F0_B_EXPOSURE_REPLICATION": {
                "token_id": "F0_B",
                "stage": "G5_F0_B",
                "purpose": "F0_B_ROUTE_DEV_REPLICATION",
                "query_role": "train_fit_route_dev",
                "minimum_query_count": 2_048,
                "maximum_query_count": None,
                "split_manifest_sha256": None,
            },
        }
        contract = action_contracts.get(str(state.get("next_action")))
        _require(contract is not None, "current action cannot issue an eval reservation")
        _require(
            state["eval_token_states"].get(contract["token_id"]) == "UNISSUED"
            and manifest.goal_id == GOAL_ID
            and manifest.attempt_id == state["attempt_id"]
            and manifest.stage == contract["stage"]
            and manifest.purpose == contract["purpose"]
            and manifest.query_identity.role == contract["query_role"],
            "forward manifest does not match the unique eval action",
        )
        authority, authority_file_sha = _read_committed_g1_genesis_registry(
            "g1_registry_authority.json"
        )
        _require(
            manifest.authority_id == authority["authority_id"],
            "forward authority differs from G0 Genesis authority",
        )
        query_count = len(manifest.query_identity.query_keys)
        maximum = contract["maximum_query_count"]
        _require(
            query_count >= contract["minimum_query_count"]
            and (maximum is None or query_count <= maximum),
            "forward query count differs from the action contract",
        )
        source_lineage: dict[str, Any] = {
            "g1_registry_authority_file_sha256": authority_file_sha,
            "controller_forward_authority_handle_sha256": (
                forward_authority_handle.capability_sha256
            ),
            "controller_forward_authority_origin_transaction_id": (
                controller_authority_payload["origin_transaction_id"]
            ),
            "query_source_descriptor_identity_sha256": (
                controller_authority_payload[
                    "query_source_descriptor_identity_sha256"
                ]
            ),
            "query_source_selected_projection_sha256": (
                controller_authority_payload[
                    "query_source_selected_projection_sha256"
                ]
            ),
            "query_identity_source_access_receipt_sha256": (
                controller_authority_payload[
                    "query_identity_source_access_receipt_sha256"
                ]
            ),
            "video_meta_source_file_sha256": controller_authority_payload[
                "video_meta_source_file_sha256"
            ],
            "query_types_sha256": manifest.query_identity.query_types_sha256,
            "query_rows_sha256": manifest.query_identity.query_rows_sha256,
            "corpus_durations_sha256": manifest.corpus_identity.durations_sha256,
            "query_role_manifest_authority_binding_sha256": (
                controller_authority_payload[
                    "query_identity_source_access_receipt"
                ]["role_manifest_authority_binding_sha256"]
            ),
        }
        if contract["token_id"] == "F0_A":
            expected_split_sha = str(contract["split_manifest_sha256"])
            _require(
                manifest.query_identity.query_keys_sha256 == expected_split_sha
                and manifest.query_identity.split_manifest_sha256
                == expected_split_sha,
                "F0-A query universe/split differs from frozen calib_select",
            )
            source_lineage["query_manifest_sha256"] = expected_split_sha
        else:
            index_sessions = _train_jsonl_index_sessions()
            _require(
                len(index_sessions) == 1,
                "F0-B reservation role authority index session",
            )
            role_id = "F0_B_FORWARD_QUERY_IDENTITY"
            role_claim_record, _role_claim_bytes = _read_canonical_json(
                index_sessions[0]
                / ("role_authority_claim_%s.json" % role_id)
            )
            role_claim = _validate_f0_role_manifest_preopen_claim(
                role_claim_record,
                state=state,
                events=events,
                expected_token_id="F0_B",
            )
            role_authority_record, _role_authority_bytes = (
                _read_canonical_json(
                    index_sessions[0]
                    / ("role_authority_%s.json" % role_id)
                )
            )
            role_authority, role_desc_ids = (
                _validate_f0_query_role_manifest_authority_record(
                    role_authority_record,
                    preopen_claim=role_claim,
                    state=state,
                    events=events,
                    expected_token_id="F0_B",
                )
            )
            _require(
                len(role_desc_ids) == query_count
                and role_authority["desc_id_lines_sha256"]
                == manifest.query_identity.query_keys_sha256
                and role_authority["manifest_sha256"]
                == manifest.query_identity.split_manifest_sha256,
                "F0-B query universe differs from committed route-dev role manifest",
            )
            source_lineage["query_manifest_file_sha256"] = role_authority[
                "source_file_sha256"
            ]
            source_lineage["query_manifest_sha256"] = role_authority[
                "manifest_sha256"
            ]
        _require(
            manifest.corpus_identity.as_dict()["video_count"] == 17_435
            and manifest.corpus_identity.video_ids_sha256
            == TRAIN_CORPUS_VIDEO_ID_ORDER_SHA256,
            "forward full-corpus identity differs from frozen 17,435 corpus",
        )
        intent, _intent_bytes = _validate_a4_intent_file()
        checkpoint_authority = intent["authority_files"]["checkpoint"]
        checkpoint = forward_authority.checkpoint
        _require(
            type(checkpoint) is a4_forward.FrozenFile
            and checkpoint.path == str(CHECKPOINT)
            and checkpoint.sha256 == EXPECTED_CHECKPOINT_SHA256
            == manifest.checkpoint_sha256
            and checkpoint.device == checkpoint_authority["device"]
            and checkpoint.inode == checkpoint_authority["inode"]
            and checkpoint.size_bytes == checkpoint_authority["size_bytes"],
            "forward checkpoint differs from the G0 fully hashed authority",
        )
        forward_authority._checkpoint_parent.verify()
        checkpoint_fd = checkpoint.open_verified_readonly(
            verify_content=False,
            expected_parent=forward_authority._checkpoint_parent,
        )
        os.close(checkpoint_fd)
        expected_feature_paths = {
            "QUERY": FEATURE_SOURCES["query_lmdb"],
            "VISUAL": FEATURE_SOURCES["visual_lmdb"],
            "SUBTITLE": FEATURE_SOURCES["subtitle_lmdb"],
        }
        observed_namespaces: set[str] = set()
        feature_records = []
        for source_id, source in sorted(forward_authority.sources.items()):
            _require(
                type(source) is a4_forward.FrozenLmdbSource
                and source.namespace not in observed_namespaces
                and source.data_file.path
                == str(expected_feature_paths[source.namespace]),
                "forward LMDB source differs from the fixed feature registry",
            )
            observed_namespaces.add(source.namespace)
            source.directory.verify()
            fd = source.data_file.open_verified_readonly(
                verify_content=False,
                expected_parent=source.directory,
            )
            os.close(fd)
            feature_records.append(source.as_dict())
        _require(
            observed_namespaces == {"QUERY", "VISUAL", "SUBTITLE"},
            "forward LMDB namespace closure",
        )
        code_records = []
        forward_authority.verify_code_sources()
        for name, expected_sha in manifest.code_source_sha256:
            path = _forward_code_source_path(name)
            _data, record = read_regular_bytes(path, require_nlink_one=True)
            _require(record["sha256"] == expected_sha, f"forward code source drift: {name}")
            code_records.append({"name": name, "sha256": expected_sha})
        metric_bytes, metric_file_sha = _committed_stage_artifact(
            attempt_id=str(state["attempt_id"]),
            events=events,
            relative_path="f0_forensics/metric_schema.json",
        )
        evaluator_bytes, evaluator_file_sha = _committed_stage_artifact(
            attempt_id=str(state["attempt_id"]),
            events=events,
            relative_path="f1_protocol/evaluator_equivalence.json",
        )
        metric, _metric_encoded = _read_canonical_json(
            REPORT_ROOT
            / str(state["attempt_id"])
            / "stage_outputs/f0_forensics/metric_schema.json"
        )
        evaluator, _evaluator_encoded = _read_canonical_json(
            REPORT_ROOT
            / str(state["attempt_id"])
            / "stage_outputs/f1_protocol/evaluator_equivalence.json"
        )
        _require(metric_bytes == _canonical_file_bytes(metric), "metric schema bytes")
        _require(evaluator_bytes == _canonical_file_bytes(evaluator), "evaluator bytes")
        expected_metric_sha = bytes_sha256(canonical_json_bytes(metric))
        _require(
            manifest.metric_schema_sha256 == expected_metric_sha
            and evaluator.get("equivalence_sha256")
            == semantic_sha256(evaluator, excluded_fields=("equivalence_sha256",))
            == manifest.evaluator_schema_sha256
            and evaluator.get("schema_version_under_test")
            == metric.get("schema_version"),
            "forward evaluator differs from committed G2 metric/equivalence",
        )
        forward_authority.output_root.verify()
        forward_authority.cache_root.verify()
        authority_material = forward_authority.authority_binding_material()
        _require(
            isinstance(authority_material, dict)
            and authority_material.get("forward_manifest_sha256")
            == manifest.manifest_sha256
            and authority_material.get("lmdb_sources") == feature_records,
            "forward authority pure binding material",
        )
        authority_binding_sha256 = semantic_sha256(authority_material)
        _require(
            authority_binding_sha256 == forward_authority.authority_binding_sha256,
            "forward authority material hash drift",
        )
        source_lineage.update(
            {
                "checkpoint_sha256": EXPECTED_CHECKPOINT_SHA256,
                "feature_descriptor_set_sha256": semantic_sha256(
                    {"records": feature_records}
                ),
                "code_source_set_sha256": semantic_sha256(
                    {"records": code_records}
                ),
                "metric_schema_file_sha256": metric_file_sha,
                "evaluator_equivalence_file_sha256": evaluator_file_sha,
                "environment_sha256": manifest.environment_sha256,
            }
        )
        execution_binding = {
            "checkpoint_sha256": manifest.checkpoint_sha256,
            "split_manifest_sha256": manifest.query_identity.split_manifest_sha256,
            "corpus_manifest_sha256": manifest.corpus_identity.identity_sha256,
            "evaluator_sha256": manifest.evaluator_schema_sha256,
            **_eval_control_contract_hashes(),
            "authority_binding_sha256": authority_binding_sha256,
            "forward_manifest_sha256": manifest.manifest_sha256,
            "input_identity_sha256": manifest.input_identity_sha256,
        }
        _validate_eval_execution_binding(execution_binding)
        token_id = str(contract["token_id"])
        reservation_seed = semantic_sha256(
            {
                "committed_state_sha256": state["state_sha256"],
                "committed_event_sha256": events[-1]["event_sha256"],
                "token_id": token_id,
                "execution_binding": execution_binding,
                "source_lineage": source_lineage,
            }
        )
        eval_id = f"A4-{token_id}-EVAL-{reservation_seed[:32]}"
        budget_preimage = semantic_sha256(
            {
                "attempt_id": state["attempt_id"],
                "eval_token_states": state["eval_token_states"],
            }
        )
        post_states = dict(state["eval_token_states"])
        post_states[token_id] = "RESERVED"
        budget_postimage = semantic_sha256(
            {
                "attempt_id": state["attempt_id"],
                "eval_token_states": post_states,
                "eval_id": eval_id,
            }
        )
        cas_base = {
            "schema_version": "c28f_eval_token_cas_intent_v1",
            "token_id": token_id,
            "eval_id": eval_id,
            "goal_id": GOAL_ID,
            "authority_id": manifest.authority_id,
            "purpose": manifest.purpose,
            "expected_budget_preimage_sha256": budget_preimage,
            "proposed_budget_postimage_sha256": budget_postimage,
            "token_state_before": "UNISSUED",
            "token_state_after": "RESERVED",
        }
        cas_intent = {**cas_base, "intent_sha256": semantic_sha256(cas_base)}
        authorization_sha256 = semantic_sha256(
            {
                "schema_version": "c28f_a4_control_eval_authorization_v1",
                "committed_state_sha256": state["state_sha256"],
                "committed_event_sha256": events[-1]["event_sha256"],
                "cas_intent_sha256": cas_intent["intent_sha256"],
                "execution_binding_sha256": semantic_sha256(execution_binding),
                "source_lineage": source_lineage,
            }
        )
        payload = {
            "schema_version": "c28f_a4_eval_reservation_input_handle_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "committed_transaction_id": state["transaction_id"],
            "committed_state_sha256": state["state_sha256"],
            "committed_event_sha256": events[-1]["event_sha256"],
            "token_id": token_id,
            "eval_id": eval_id,
            "stage": manifest.stage,
            "authority_id": manifest.authority_id,
            "purpose": manifest.purpose,
            "query_role": manifest.query_identity.role,
            "query_count": query_count,
            "cas_intent": cas_intent,
            "authorization_sha256": authorization_sha256,
            "execution_binding": execution_binding,
            "source_lineage": source_lineage,
            "authority_binding_material_sha256": authority_binding_sha256,
        }
        handle = _register_opaque_capability(
            A4EvalReservationInputHandle(
                _OPAQUE_CONTROL_ISSUER_SEAL,
                payload,
            )
        )
        validate_eval_reservation_input_handle(handle)
        authority_record = _controller_forward_authority_record(
            forward_authority
        )
        with _CONTROLLER_FORWARD_AUTHORITY_LOCK:
            _require(
                authority_record["handle"] is forward_authority_handle
                and authority_record["state"] == "ISSUED_UNRESERVED",
                "controller forward authority reservation issuance replay",
            )
            authority_record["state"] = "RESERVATION_ISSUED"
            authority_record["reservation_input_object"] = handle
            authority_record["reservation_input_capability_sha256"] = (
                handle.capability_sha256
            )
        return handle


def issue_eval_reserved_capability(
    *,
    bootstrap_lease: BootstrapLease,
) -> A4EvalReservedCapability:
    """Reissue RESERVED authority only from its exact fsynced CAS chain."""

    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_EVAL_RESERVED_CAPABILITY",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        registry, registry_bytes = _read_eval_registry()
        _require(
            state.get("status") == "EVAL_TOKEN_RESERVED"
            and state.get("next_action") == "MARK_EVAL_RUNNING"
            and registry.get("token_state") == "RESERVED"
            and state["eval_token_states"].get(registry["token_id"])
            == "RESERVED"
            and events[-1].get("action") == "RESERVE_EVAL_TOKEN",
            "RESERVED capability requires current RESERVED tail",
        )
        receipt, _receipt_bytes = _read_canonical_json(
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "cas_receipt.json"
        )
        _require(
            isinstance(receipt, dict)
            and receipt == _build_eval_phase_receipt(
                registry,
                state,
                events[-1],
            ),
            "RESERVED CAS receipt rebuild",
        )
        reservation_record, _record_bytes = _read_canonical_json(
            CONTROL_ROOT
            / "transactions"
            / registry["transaction_id"]
            / "reservation_input.json"
        )
        _require(
            isinstance(reservation_record, dict)
            and reservation_record.get("capability_sha256")
            == registry["reservation_input_capability_sha256"]
            and reservation_record
            == _build_eval_reservation_input_record(
                reservation_record["payload"],
                reservation_record["capability_sha256"],
            ),
            "RESERVED input record rebuild",
        )
        payload = {
            "schema_version": "c28f_a4_eval_reserved_capability_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "run_id": registry["run_id"],
            "token_id": registry["token_id"],
            "eval_id": registry["eval_id"],
            "transaction_id": registry["transaction_id"],
            "reserved_state_sha256": state["state_sha256"],
            "reserved_event_sha256": events[-1]["event_sha256"],
            "eval_registry_sha256": bytes_sha256(registry_bytes),
            "execution_binding_sha256": registry[
                "execution_binding_sha256"
            ],
            "reservation_input_capability_sha256": registry[
                "reservation_input_capability_sha256"
            ],
            "cas_receipt_sha256": receipt["receipt_sha256"],
        }
        capability = _register_opaque_capability(
            A4EvalReservedCapability(
                _OPAQUE_CONTROL_ISSUER_SEAL,
                payload,
            )
        )
        validate_eval_reserved_capability(capability)
        return capability


def issue_eval_running_capability(
    *,
    bootstrap_lease: BootstrapLease,
) -> A4EvalRunningCapability:
    running_event_sha256 = assert_running_state_event_committed(
        bootstrap_lease=bootstrap_lease
    )
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_EVAL_RUNNING_CAPABILITY",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        registry, registry_bytes = _read_eval_registry()
        running_state, running_event, _running_position = (
            _active_eval_running_anchor(
                state=state,
                events=events,
                registry=registry,
            )
        )
        _require(
            running_event["event_sha256"] == running_event_sha256,
            "RUNNING event changed before issue",
        )
        payload = {
            "schema_version": "c28f_a4_eval_running_capability_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "run_id": registry["run_id"],
            "token_id": registry["token_id"],
            "eval_id": registry["eval_id"],
            "transaction_id": registry["transaction_id"],
            "running_state_sha256": running_state["state_sha256"],
            "running_event_sha256": running_event_sha256,
            "eval_registry_sha256": bytes_sha256(registry_bytes),
            "execution_binding_sha256": registry["execution_binding_sha256"],
            "reservation_input_capability_sha256": registry[
                "reservation_input_capability_sha256"
            ],
        }
        return _register_opaque_capability(
            A4EvalRunningCapability(_OPAQUE_CONTROL_ISSUER_SEAL, payload)
        )


def issue_persisted_eval_running_capability_for_completed_validation(
    *,
    bootstrap_lease: BootstrapLease,
    run_id: str,
) -> A4EvalRunningCapability:
    """Reissue the historical RUNNING proof after the same eval completed.

    This capability is a proof object only.  It is rebuilt from the immutable
    RUNNING transition record and cannot satisfy any current-RUNNING action.
    """

    _require(isinstance(run_id, str) and bool(run_id), "completed run ID")
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "REISSUE_COMPLETED_HISTORICAL_RUNNING_PROOF",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        complete_registry, _complete_registry_bytes = _read_eval_registry()
        _require(
            complete_registry.get("token_state") == "COMPLETED"
            and complete_registry.get("run_id") == run_id
            and state.get("transaction_id")
            == complete_registry["transaction_id"]
            and state.get("eval_token_states", {}).get(
                complete_registry["token_id"]
            )
            == "COMPLETED",
            "historical RUNNING proof requires current completed eval",
        )
        running_transaction_id = run_id + "-RUNNING"
        running_envelope, _running_envelope_bytes = _read_canonical_json(
            CONTROL_ROOT
            / "transactions"
            / running_transaction_id
            / "transition_intent.json"
        )
        running_registry = running_envelope.get("registry_payload")
        matching_events = [
            event
            for event in events
            if event.get("transaction_id") == running_transaction_id
            and event.get("action") == "MARK_EVAL_RUNNING"
        ]
        _require(
            isinstance(running_registry, dict)
            and running_registry.get("token_state") == "RUNNING"
            and running_registry.get("run_id") == run_id
            and running_registry.get("token_id")
            == complete_registry["token_id"]
            and running_registry.get("eval_id")
            == complete_registry["eval_id"]
            and running_registry.get("execution_binding")
            == complete_registry["execution_binding"]
            and running_registry.get("reservation_input_capability_sha256")
            == complete_registry["reservation_input_capability_sha256"]
            and len(matching_events) == 1,
            "historical RUNNING transition lineage",
        )
        running_event = matching_events[0]
        running_state, _running_state_bytes = _read_canonical_json(
            CONTROL_ROOT
            / "state_records"
            / (
                "%06d_%s.json"
                % (
                    running_event["seq"],
                    running_event["expected_next_state_sha256"],
                )
            )
        )
        _require(
            running_state.get("status") == "RUNNING"
            and running_state.get("next_action") == "COMPLETE_EVAL_TOKEN"
            and running_state.get("transaction_id")
            == running_transaction_id
            and running_state.get("state_sha256")
            == running_event["expected_next_state_sha256"],
            "historical RUNNING state/event binding",
        )
        payload = {
            "schema_version": "c28f_a4_eval_running_capability_v1",
            "goal_id": GOAL_ID,
            "attempt_id": running_state["attempt_id"],
            "run_id": run_id,
            "token_id": running_registry["token_id"],
            "eval_id": running_registry["eval_id"],
            "transaction_id": running_transaction_id,
            "running_state_sha256": running_state["state_sha256"],
            "running_event_sha256": running_event["event_sha256"],
            "eval_registry_sha256": bytes_sha256(
                _canonical_file_bytes(running_registry)
            ),
            "execution_binding_sha256": running_registry[
                "execution_binding_sha256"
            ],
            "reservation_input_capability_sha256": running_registry[
                "reservation_input_capability_sha256"
            ],
        }
        capability = _register_opaque_capability(
            A4EvalRunningCapability(_OPAQUE_CONTROL_ISSUER_SEAL, payload)
        )
        validate_eval_running_capability(capability)
        return capability


def completed_forward_input_rehydrate_material(
    *,
    running_capability: A4EvalRunningCapability,
    authority_binding_sha256: str,
    forward_manifest_sha256: str,
    input_identity_sha256: str,
    reservation_input_capability_sha256: str,
    controller_authority_binding_sha256: str,
    forward_run_receipt_sha256: str,
) -> dict[str, Any]:
    """Return only the exact hash/identity material for completed validation."""

    running = validate_eval_running_capability(running_capability)
    stem = str(running["run_id"])
    reservation_record, _reservation_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "transactions"
        / (stem + "-RESERVE")
        / "reservation_input.json"
    )
    reservation = reservation_record.get("payload")
    source_lineage = (
        reservation.get("source_lineage")
        if isinstance(reservation, dict)
        else None
    )
    authority_handle_sha256 = (
        source_lineage.get("controller_forward_authority_handle_sha256")
        if isinstance(source_lineage, dict)
        else None
    )
    with _CONTROLLER_FORWARD_AUTHORITY_LOCK:
        matches = [
            record
            for record in _CONTROLLER_FORWARD_AUTHORITY_REGISTRY.values()
            if record.get("handle_capability_sha256")
            == authority_handle_sha256
            and record.get("state") == "AUTHORITY_RELEASED"
        ]
    _require(
        isinstance(reservation, dict)
        and len(matches) == 1,
        "completed input rehydrate controller authority",
    )
    authority = matches[0]["object"]
    consumption, _consumption_bytes = _read_canonical_json(
        CONTROL_ROOT
        / "transactions"
        / running["transaction_id"]
        / "forward_capability_consumption.json"
    )
    material_without_id = {
        "goal_id": GOAL_ID,
        "authority_id": reservation["authority_id"],
        "run_id": running["run_id"],
        "token_id": running["token_id"],
        "eval_id": running["eval_id"],
        "purpose": reservation["purpose"],
        "stage": reservation["stage"],
        "forward_manifest_sha256": forward_manifest_sha256,
        "input_identity_sha256": input_identity_sha256,
        "authority_binding_sha256": authority_binding_sha256,
        "token_snapshot_sha256": running["eval_registry_sha256"],
        "gpu0_identity_sha256": authority.manifest.gpu0_identity.semantic_sha256,
        "control_chain_sha256": semantic_sha256(
            {
                "state_sha256": running["running_state_sha256"],
                "event_sha256": running["running_event_sha256"],
                "eval_registry_file_sha256": running[
                    "eval_registry_sha256"
                ],
                "execution_binding_sha256": running[
                    "execution_binding_sha256"
                ],
            }
        ),
        "running_commit_sha256": running["running_event_sha256"],
        "running_capability_sha256": running_capability.capability_sha256,
        "reservation_input_capability_sha256": (
            reservation_input_capability_sha256
        ),
        "controller_authority_binding_sha256": (
            controller_authority_binding_sha256
        ),
        "consume_receipt_sha256": consumption["receipt_sha256"],
    }
    capability_id = bytes_sha256(
        canonical_json_bytes(material_without_id)
    )
    material = {
        "capability_id": capability_id,
        **material_without_id,
    }
    lifecycle = validate_completed_forward_input_capability(
        running_capability=running_capability,
        run_id=running["run_id"],
        token_id=running["token_id"],
        eval_id=running["eval_id"],
        capability_id=capability_id,
        authority_binding_sha256=authority_binding_sha256,
        forward_manifest_sha256=forward_manifest_sha256,
        input_identity_sha256=input_identity_sha256,
        reservation_input_capability_sha256=(
            reservation_input_capability_sha256
        ),
        controller_authority_binding_sha256=(
            controller_authority_binding_sha256
        ),
        forward_run_receipt_sha256=forward_run_receipt_sha256,
    )
    completed_phase_receipt, _completed_phase_receipt_bytes = (
        _read_canonical_json(
            CONTROL_ROOT
            / "transactions"
            / lifecycle["completed_transaction_id"]
            / "phase_receipt.json"
        )
    )
    _require(
        isinstance(completed_phase_receipt, dict)
        and completed_phase_receipt.get("schema_version")
        == "c28f_eval_token_phase_receipt_v1"
        and completed_phase_receipt.get("status")
        == "FSYNCED_CAS_COMMITTED"
        and completed_phase_receipt.get("phase") == "COMPLETED"
        and completed_phase_receipt.get("run_id") == lifecycle["run_id"]
        and completed_phase_receipt.get("token_id")
        == lifecycle["token_id"]
        and completed_phase_receipt.get("eval_id") == lifecycle["eval_id"]
        and completed_phase_receipt.get("transaction_id")
        == lifecycle["completed_transaction_id"]
        and completed_phase_receipt.get("state_sha256")
        == lifecycle["completed_state_sha256"]
        and completed_phase_receipt.get("event_sha256")
        == lifecycle["completed_event_sha256"]
        and completed_phase_receipt.get("execution_binding_sha256")
        == lifecycle["execution_binding_sha256"]
        and completed_phase_receipt.get(
            "reservation_input_capability_sha256"
        )
        == lifecycle["reservation_input_capability_sha256"]
        and completed_phase_receipt.get("model_forward_evaluations") == 1
        and completed_phase_receipt.get("receipt_sha256")
        == semantic_sha256(
            completed_phase_receipt,
            excluded_fields=("receipt_sha256",),
        ),
        "completed input rehydrate phase receipt",
    )
    base = {
        "schema_version": (
            "c28f_a4_completed_forward_input_rehydrate_material_v1"
        ),
        "status": "VALIDATED_COMPLETED_INPUT_IDENTITY_ONLY",
        "input_capability_material": material,
        "completed_lifecycle_binding": lifecycle,
        "completed_phase_receipt": completed_phase_receipt,
        "active_source_reopened": False,
        "token_reissued": False,
        "model_forward_reexecuted": False,
    }
    return {**base, "material_binding_sha256": semantic_sha256(base)}


def issue_eval_cursor_capability(
    *,
    bootstrap_lease: BootstrapLease,
    running_capability: A4EvalRunningCapability,
) -> A4EvalCursorCapability:
    running = validate_eval_running_capability(running_capability)
    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_EVAL_CURSOR_CAPABILITY",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        registry, _registry_bytes = _read_eval_registry()
        running_state, running_event, _running_position = (
            _active_eval_running_anchor(
                state=state,
                events=events,
                registry=registry,
            )
        )
        _require(
            running_state["state_sha256"]
            == running["running_state_sha256"]
            and running_event["event_sha256"]
            == running["running_event_sha256"]
            and registry["run_id"] == running["run_id"],
            "RUNNING capability no longer matches immutable eval anchor",
        )
        _files, _directories, cursor = _validate_eval_cursor_chain(
            registry,
            running_state,
            running_event,
        )
        if cursor is None:
            raise A4EvalCursorAbsentError("EVAL_CURSOR_ABSENT")
        payload = {
            "schema_version": "c28f_a4_eval_cursor_capability_v1",
            "running_anchor": running,
            "cursor_index": cursor["cursor_index"],
            "cursor_receipt_sha256": cursor["receipt_sha256"],
            "cursor_sha256": cursor["cursor_sha256"],
            "chunks_sha256": cursor["chunks_sha256"],
            "artifacts_sha256": cursor["artifacts_sha256"],
        }
        return _register_opaque_capability(
            A4EvalCursorCapability(_OPAQUE_CONTROL_ISSUER_SEAL, payload)
        )


def _g6_parent_descriptor(parent: Path) -> dict[str, Any]:
    descriptor = lstat_identity(parent)
    _require(
        descriptor["type"] == "directory"
        and descriptor["path"] == str(parent)
        and descriptor["resolved"] == str(parent.resolve(strict=True)),
        "G6 synthetic parent descriptor",
    )
    fd = _open_directory(parent)
    try:
        return {**descriptor, "mount_id": _fd_mount_id(fd)}
    finally:
        os.close(fd)


def _g6_empty_child_descriptor(
    *,
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
    crash_point: str,
    child_root_binding_sha256: str,
    create_if_absent: bool,
) -> dict[str, Any]:
    parent = Path(str(root_payload["parent_root_path"]))
    child_name = root_payload["child_root_names"][crash_point]
    child = parent / child_name
    descriptor = dict(root_payload["parent_descriptor_record"])
    expected_binding = semantic_sha256(
        {
            "synthetic_root_handle_sha256": root_handle_sha256,
            "crash_point": crash_point,
            "child_root_name": child_name,
            "child_root_path": str(child),
            "parent_descriptor_identity_sha256": root_payload[
                "parent_descriptor_identity_sha256"
            ],
            "child_root_contract_sha256": root_payload[
                "child_root_contract_sha256"
            ],
        }
    )
    _require(
        expected_binding == child_root_binding_sha256
        and child.is_absolute()
        and child.parent == parent
        and child == child.resolve(strict=False),
        "G6 unstarted resume exact child binding",
    )
    parent_fd = _open_directory(parent)
    child_fd: Optional[int] = None
    created = False
    try:
        parent_stat = os.fstat(parent_fd)
        _require(
            (int(parent_stat.st_dev), int(parent_stat.st_ino))
            == (descriptor["device"], descriptor["inode"])
            and _fd_mount_id(parent_fd) == descriptor["mount_id"],
            "G6 unstarted resume frozen parent",
        )
        try:
            named = os.stat(
                child_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            _require(
                create_if_absent,
                "G6 unstarted resume child is absent",
            )
            os.mkdir(child_name, mode=0o700, dir_fd=parent_fd)
            os.fsync(parent_fd)
            created = True
            named = os.stat(
                child_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        flags = (
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0)
        )
        child_fd = os.open(child_name, flags, dir_fd=parent_fd)
        before = os.fstat(child_fd)
        _require(
            stat.S_ISDIR(named.st_mode)
            and stat.S_ISDIR(before.st_mode)
            and (int(before.st_dev), int(before.st_ino))
            == (int(named.st_dev), int(named.st_ino))
            and before.st_dev == parent_stat.st_dev
            and _fd_mount_id(child_fd) == descriptor["mount_id"]
            and stat.S_IMODE(before.st_mode) == 0o700
            and os.listdir(child_fd) == [],
            "G6 unstarted resume child must be exact and empty",
        )
        if created:
            os.fsync(child_fd)
        after = os.fstat(child_fd)
        stable_fields = (
            "st_dev", "st_ino", "st_mode", "st_nlink", "st_mtime_ns",
            "st_ctime_ns",
        )
        _require(
            all(
                getattr(before, field_name) == getattr(after, field_name)
                for field_name in stable_fields
            ),
            "G6 unstarted resume child descriptor changed",
        )
        return {
            "canonical_path": str(child),
            "parent_canonical_path": str(parent),
            "device": int(after.st_dev),
            "inode": int(after.st_ino),
            "nlink": int(after.st_nlink),
            "mode": oct(stat.S_IMODE(after.st_mode)),
            "mtime_ns": int(after.st_mtime_ns),
            "ctime_ns": int(after.st_ctime_ns),
            "mount_id": descriptor["mount_id"],
            "parent_descriptor_identity_sha256": root_payload[
                "parent_descriptor_identity_sha256"
            ],
            "child_root_binding_sha256": child_root_binding_sha256,
        }
    finally:
        if child_fd is not None:
            os.close(child_fd)
        os.close(parent_fd)


def _g6_executor_owner_records(
    *,
    session: Path,
    intent: Mapping[str, Any],
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
) -> list[dict[str, Any]]:
    fixed_executor = intent["fixed_executor"]
    writer_sha = fixed_executor["writer_lease_binding_sha256"]
    crash_point = intent["crash_point"]
    child_name = intent["child_root_name"]
    records = [
        _validate_g6_executor_owner(
            intent["initial_owner"],
            root_payload=root_payload,
            root_handle_sha256=root_handle_sha256,
            crash_point=crash_point,
            child_name=child_name,
            generation=0,
            previous_owners=(),
            writer_lease_binding_sha256=writer_sha,
        )
    ]
    pattern = re.compile(
        r"executor_v2_owner_%s_([0-9]{6})_([0-9a-f]{64})\.json"
        % re.escape(child_name)
    )
    with os.scandir(session) as iterator:
        entries = sorted(
            (
                entry
                for entry in iterator
                if pattern.fullmatch(entry.name) is not None
            ),
            key=lambda entry: entry.name,
        )
    _require(len(entries) <= 7, "G6 executor takeover generation bound")
    for expected_generation, entry in enumerate(entries, start=1):
        match = pattern.fullmatch(entry.name)
        _require(match is not None, "G6 executor owner filename")
        record, _record_bytes = _read_canonical_json(Path(entry.path))
        owner = record.get("payload") if isinstance(record, dict) else None
        owner = _validate_g6_executor_owner(
            owner,
            root_payload=root_payload,
            root_handle_sha256=root_handle_sha256,
            crash_point=crash_point,
            child_name=child_name,
            generation=expected_generation,
            previous_owners=records,
            writer_lease_binding_sha256=writer_sha,
        )
        _require(
            int(match.group(1)) == expected_generation
            and match.group(2) == owner["owner_binding_sha256"]
            and set(record)
            == {"schema_version", "status", "payload", "record_sha256"}
            and record["schema_version"]
            == "c28f_a4_g6_executor_owner_record_v2"
            and record["status"] == "FSYNCED_EXCLUSIVE_EXECUTOR_OWNER"
            and record["payload"] == owner
            and record["record_sha256"]
            == semantic_sha256(
                record,
                excluded_fields=("record_sha256",),
            ),
            "G6 executor owner persisted chain",
        )
        records.append(owner)
    return records


def _persist_g6_executor_takeover_owner(
    *,
    session: Path,
    intent: Mapping[str, Any],
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
    lease: WriterLease,
) -> tuple[dict[str, Any], list[dict[str, Any]]]:
    previous = _g6_executor_owner_records(
        session=session,
        intent=intent,
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
    )
    owner = _build_g6_executor_owner(
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
        crash_point=intent["crash_point"],
        child_name=intent["child_root_name"],
        previous_owners=previous,
        writer_lease_binding_sha256=intent["fixed_executor"][
            "writer_lease_binding_sha256"
        ],
    )
    record_base = {
        "schema_version": "c28f_a4_g6_executor_owner_record_v2",
        "status": "FSYNCED_EXCLUSIVE_EXECUTOR_OWNER",
        "payload": owner,
    }
    record = {
        **record_base,
        "record_sha256": semantic_sha256(record_base),
    }
    atomic_write_immutable(
        session
        / (
            "executor_v2_owner_%s_%06d_%s.json"
            % (
                intent["child_root_name"],
                owner["generation"],
                owner["owner_binding_sha256"],
            )
        ),
        _canonical_file_bytes(record),
        lease=lease,
    )
    return owner, previous


def _g6_open_controller_child(
    *,
    root_payload: Mapping[str, Any],
    child_name: str,
    child_root_binding_sha256: str,
    create_if_absent: bool,
) -> tuple[int, int, dict[str, Any], bool]:
    parent = Path(root_payload["parent_root_path"])
    parent_fd = _open_directory(parent)
    child_fd: Optional[int] = None
    created = False
    try:
        parent_stat = os.fstat(parent_fd)
        frozen = root_payload["parent_descriptor_record"]
        _require(
            (int(parent_stat.st_dev), int(parent_stat.st_ino))
            == (frozen["device"], frozen["inode"])
            and _fd_mount_id(parent_fd) == frozen["mount_id"],
            "G6 fixed executor frozen parent",
        )
        try:
            named = os.stat(
                child_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        except FileNotFoundError:
            _require(
                create_if_absent,
                "G6 fixed executor child absent outside empty-rerun",
            )
            os.mkdir(child_name, mode=0o700, dir_fd=parent_fd)
            os.fsync(parent_fd)
            created = True
            named = os.stat(
                child_name,
                dir_fd=parent_fd,
                follow_symlinks=False,
            )
        flags = (
            os.O_RDONLY
            | getattr(os, "O_CLOEXEC", 0)
            | getattr(os, "O_DIRECTORY", 0)
            | getattr(os, "O_NOFOLLOW", 0)
        )
        child_fd = os.open(child_name, flags, dir_fd=parent_fd)
        child_stat = os.fstat(child_fd)
        _require(
            stat.S_ISDIR(named.st_mode)
            and stat.S_ISDIR(child_stat.st_mode)
            and (int(named.st_dev), int(named.st_ino))
            == (int(child_stat.st_dev), int(child_stat.st_ino))
            and child_stat.st_dev == parent_stat.st_dev
            and stat.S_IMODE(child_stat.st_mode) == 0o700
            and _fd_mount_id(child_fd) == frozen["mount_id"],
            "G6 fixed executor child identity",
        )
        descriptor = {
            "canonical_path": str(parent / child_name),
            "parent_canonical_path": str(parent),
            "device": int(child_stat.st_dev),
            "inode": int(child_stat.st_ino),
            "nlink": int(child_stat.st_nlink),
            "mode": oct(stat.S_IMODE(child_stat.st_mode)),
            "mtime_ns": int(child_stat.st_mtime_ns),
            "ctime_ns": int(child_stat.st_ctime_ns),
            "mount_id": frozen["mount_id"],
            "parent_descriptor_identity_sha256": root_payload[
                "parent_descriptor_identity_sha256"
            ],
            "child_root_binding_sha256": child_root_binding_sha256,
        }
        result_child_fd = child_fd
        child_fd = None
        return parent_fd, result_child_fd, descriptor, created
    except BaseException:
        os.close(parent_fd)
        raise
    finally:
        if child_fd is not None:
            os.close(child_fd)


def _g6_read_controller_child_bytes(
    child_fd: int,
    *,
    expected_device: int,
    expected_mount_id: int,
) -> dict[str, bytes]:
    names = sorted(os.listdir(child_fd))
    _require(
        len(names) <= 16
        and names == sorted(set(names))
        and all(
            re.fullmatch(r"\.?[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", name)
            is not None
            and "/" not in name
            and name not in {".", ".."}
            for name in names
        ),
        "G6 fixed executor child namespace",
    )
    result: dict[str, bytes] = {}
    for name in names:
        named = os.stat(name, dir_fd=child_fd, follow_symlinks=False)
        flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0)
        flags |= getattr(os, "O_NOFOLLOW", 0)
        fd = os.open(name, flags, dir_fd=child_fd)
        try:
            before = os.fstat(fd)
            _require(
                stat.S_ISREG(named.st_mode)
                and stat.S_ISREG(before.st_mode)
                and (int(named.st_dev), int(named.st_ino))
                == (int(before.st_dev), int(before.st_ino))
                and int(before.st_dev) == expected_device
                and before.st_nlink == 1
                and stat.S_IMODE(before.st_mode) == 0o600
                and _fd_mount_id(fd) == expected_mount_id
                and 0 < before.st_size <= 16 * 1024 * 1024,
                "G6 fixed executor child artifact identity",
            )
            chunks: list[bytes] = []
            remaining = int(before.st_size)
            while remaining:
                chunk = os.read(fd, min(1024 * 1024, remaining))
                _require(bool(chunk), "G6 fixed executor artifact short read")
                chunks.append(chunk)
                remaining -= len(chunk)
            _require(not os.read(fd, 1), "G6 fixed executor artifact grew")
            after = os.fstat(fd)
        finally:
            os.close(fd)
        stable_fields = (
            "st_dev", "st_ino", "st_size", "st_mode", "st_nlink",
            "st_mtime_ns", "st_ctime_ns",
        )
        _require(
            all(
                getattr(before, field_name) == getattr(after, field_name)
                for field_name in stable_fields
            ),
            "G6 fixed executor artifact changed during read",
        )
        result[name] = b"".join(chunks)
    return result


def _build_g6_executor_intent(
    *,
    root_payload: Mapping[str, Any],
    root_handle_sha256: str,
    crash_point: str,
    state: Mapping[str, Any],
    event: Mapping[str, Any],
    lease: WriterLease,
) -> tuple[dict[str, Any], tuple[dict[str, Any], ...]]:
    child_name = root_payload["child_root_names"][crash_point]
    child_path = str(Path(root_payload["parent_root_path"]) / child_name)
    child_binding = semantic_sha256(
        {
            "synthetic_root_handle_sha256": root_handle_sha256,
            "crash_point": crash_point,
            "child_root_name": child_name,
            "child_root_path": child_path,
            "parent_descriptor_identity_sha256": root_payload[
                "parent_descriptor_identity_sha256"
            ],
            "child_root_contract_sha256": root_payload[
                "child_root_contract_sha256"
            ],
        }
    )
    operation_plan, execution_contract = _g6_fixed_operation_plan(
        crash_point
    )
    writer_binding = _a4_writer_binding(lease)
    writer_binding_sha = semantic_sha256(writer_binding)
    owner = _build_g6_executor_owner(
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
        crash_point=crash_point,
        child_name=child_name,
        previous_owners=(),
        writer_lease_binding_sha256=writer_binding_sha,
    )
    fixed_executor = {
        "relative_source": "blueprint_e2e_v2/c28f_v5/a4_f1.py",
        "reviewed_source_sha256": _g6_fixed_body_source_sha256(),
        "symbol": "execute_controller_owned_synthetic_atomic_recovery",
        "invocation_mode": (
            "IN_PROCESS_FIXED_PATHLESS_FD_RELATIVE_CAPABILITY"
        ),
        "callback_allowed": False,
        "path_argument_allowed": False,
        "path_return_allowed": False,
        "external_executor_allowed": False,
        "writer_lease_binding": writer_binding,
        "writer_lease_binding_sha256": writer_binding_sha,
    }
    base = {
        "schema_version": "c28f_a4_g6_controller_execution_intent_v2",
        "status": "FSYNCED_CONTROLLER_FIXED_EXECUTION_INTENT",
        "goal_id": GOAL_ID,
        "attempt_id": root_payload["attempt_id"],
        "session_id": _g6_synthetic_session_id(root_payload),
        "committed_transaction_id": state["transaction_id"],
        "committed_state_sha256": state["state_sha256"],
        "committed_event_sha256": event["event_sha256"],
        "synthetic_root_handle_sha256": root_handle_sha256,
        "crash_point": crash_point,
        "child_root_name": child_name,
        "child_root_path": child_path,
        "child_root_binding_sha256": child_binding,
        "parent_descriptor_identity_sha256": root_payload[
            "parent_descriptor_identity_sha256"
        ],
        "child_root_contract_sha256": root_payload[
            "child_root_contract_sha256"
        ],
        "preimage_classification": "ABSENT_BEFORE_INTENT",
        "fixed_executor": fixed_executor,
        "execution_contract": execution_contract,
        "initial_owner": owner,
        "synthetic_only": True,
        "real_data_allowed": False,
        "model_forward_evaluations": 0,
        "real_data_optimizer_updates": 0,
        "extra_model_forward_splits": 0,
    }
    intent = {**base, "intent_sha256": semantic_sha256(base)}
    _validate_g6_executor_intent(
        intent,
        root_payload=root_payload,
        root_handle_sha256=root_handle_sha256,
    )
    return intent, operation_plan


def _issue_g6_controller_execution_capability(
    *,
    root_handle: A4G6SyntheticRootHandle,
    root_payload: Mapping[str, Any],
    intent: Mapping[str, Any],
    owner: Mapping[str, Any],
    previous_owners: Sequence[Mapping[str, Any]],
    parent_fd: int,
    child_fd: int,
    child_descriptor: Mapping[str, Any],
    operation_plan: Sequence[Mapping[str, Any]],
    lease: WriterLease,
) -> A4G6ControllerExecutionCapability:
    session = _A4G6ControllerOwnedSyntheticSession(
        _G6_CONTROLLER_SESSION_FACTORY,
        parent_fd=parent_fd,
        child_name=intent["child_root_name"],
        directory_fd=child_fd,
        writer_lease=lease,
        crash_point=intent["crash_point"],
        operation_plan=operation_plan,
    )
    base = {
        "schema_version": "c28f_a4_g6_controller_execution_capability_v2",
        "status": "ACTIVE_CONTROLLER_FIXED_EXECUTION",
        "goal_id": GOAL_ID,
        "attempt_id": root_payload["attempt_id"],
        "synthetic_root_handle_sha256": root_handle.capability_sha256,
        "crash_point": intent["crash_point"],
        "child_root_name": intent["child_root_name"],
        "child_root_binding_sha256": intent[
            "child_root_binding_sha256"
        ],
        "parent_descriptor_identity_sha256": intent[
            "parent_descriptor_identity_sha256"
        ],
        "child_descriptor_identity_sha256": semantic_sha256(
            child_descriptor
        ),
        "execution_intent_sha256": intent["intent_sha256"],
        "fixed_body_source_sha256": intent["fixed_executor"][
            "reviewed_source_sha256"
        ],
        "executor_version": G6_EXECUTOR_VERSION,
        "writer_lease_binding_sha256": intent["fixed_executor"][
            "writer_lease_binding_sha256"
        ],
        "owner_identity_sha256": owner["owner_binding_sha256"],
        "synthetic_only": True,
        "real_data_allowed": False,
        "path_export_allowed": False,
        "external_executor_allowed": False,
        "one_shot": True,
    }
    payload = {
        **base,
        "execution_binding_sha256": semantic_sha256(base),
    }
    capability = _register_opaque_capability(
        A4G6ControllerExecutionCapability(
            _OPAQUE_CONTROL_ISSUER_SEAL,
            payload,
            session=session,
            intent=intent,
            owner=owner,
            previous_owners=previous_owners,
            child_descriptor=child_descriptor,
            root_handle=root_handle,
        )
    )
    try:
        validate_g6_controller_execution_capability(capability)
    except BaseException:
        session._abort()
        raise
    return capability


def _validate_g6_fixed_body_result(
    value: Any,
    *,
    intent: Mapping[str, Any],
) -> dict[str, Any]:
    exact_fields = {
        "schema_version", "status", "executor_version", "crash_point",
        "expected_artifact_manifest",
        "expected_artifact_manifest_sha256", "recovery_action",
        "checkpoint_terminal_sha256",
        "complete_state_components_compared", "model_forward_executed",
        "real_data_optimizer_updates", "path_returned",
        "external_executor_used", "result_sha256",
    }
    contract = intent["execution_contract"]
    _require(
        isinstance(value, Mapping)
        and set(value) == exact_fields
        and value["schema_version"]
        == "c28f_g6_controller_fixed_body_result_v2"
        and value["status"]
        == "FIXED_BODY_TERMINAL_AWAITING_CONTROLLER_POSTIMAGE"
        and value["executor_version"] == G6_EXECUTOR_VERSION
        and value["crash_point"] == intent["crash_point"]
        and value["expected_artifact_manifest"]
        == contract["expected_artifact_manifest"]
        and value["expected_artifact_manifest_sha256"]
        == contract["expected_artifact_manifest_sha256"]
        and value["recovery_action"] == contract["recovery_action"]
        and value["checkpoint_terminal_sha256"]
        == contract["checkpoint_terminal_sha256"]
        and value["complete_state_components_compared"]
        == contract["complete_state_components_compared"]
        and value["model_forward_executed"] is False
        and value["real_data_optimizer_updates"] == 0
        and value["path_returned"] is False
        and value["external_executor_used"] is False
        and value["result_sha256"]
        == semantic_sha256(value, excluded_fields=("result_sha256",)),
        "G6 fixed body result exact contract",
    )
    return dict(value)


def issue_g6_synthetic_root_handle(
    *,
    bootstrap_lease: BootstrapLease,
) -> A4G6SyntheticRootHandle:
    """Issue four one-shot, nonexistent synthetic crash-scenario roots."""

    with WriterLease(
        CONTROL_ROOT / "single_writer.lock",
        CONTROL_ROOT / "single_writer.heartbeat.json",
        GOAL_ID,
        "ISSUE_G6_SYNTHETIC_ROOT_HANDLE",
    ) as lease:
        verify_a4_state(bootstrap_lease, active_lease=lease)
        state, _state_bytes, events, _journal = _current_state_and_events()
        _require(
            state.get("stage") == "G6"
            and state.get("status") == "F0B_COMPLETE"
            and state.get("next_action")
            == "G6_F1_PROTOCOL_AND_RECOVERY"
            and state.get("eval_token_states")
            == {"F0_A": "COMPLETED", "F0_B": "COMPLETED"}
            and state.get("model_forward_evaluations") == 2,
            "G6 synthetic roots require the exact post-G5 control tail",
        )
        with os.scandir(CONTROL_ROOT / "transactions") as iterator:
            existing_sessions = sorted(
                Path(entry.path)
                for entry in iterator
                if G6_SYNTHETIC_SESSION_RE.fullmatch(entry.name) is not None
                and entry.is_dir(follow_symlinks=False)
                and not entry.is_symlink()
            )
        _require(
            len(existing_sessions) <= 1,
            "G6 synthetic session rehydration cardinality",
        )
        if existing_sessions:
            existing_record, _existing_bytes = _read_canonical_json(
                existing_sessions[0] / "root_handle.json"
            )
            existing_payload = existing_record.get("payload")
            _require(
                isinstance(existing_payload, dict)
                and existing_payload.get("committed_transaction_id")
                == state["transaction_id"]
                and existing_payload.get("committed_state_sha256")
                == state["state_sha256"]
                and existing_payload.get("committed_event_sha256")
                == events[-1]["event_sha256"]
                and existing_record.get("capability_sha256")
                == semantic_sha256(existing_payload),
                "G6 persisted synthetic root handle/current tail",
            )
            handle = _register_opaque_capability(
                A4G6SyntheticRootHandle(
                    _OPAQUE_CONTROL_ISSUER_SEAL,
                    existing_payload,
                    bootstrap_lease,
                )
            )
            consumed: set[str] = set()
            committed: set[str] = set()
            for crash_point, child_name in existing_payload[
                "child_root_names"
            ].items():
                if os.path.lexists(
                    existing_sessions[0] / ("consume_%s.json" % child_name)
                ):
                    consumed.add(crash_point)
                if os.path.lexists(
                    existing_sessions[0]
                    / ("crash_receipt_%s.json" % child_name)
                ):
                    committed.add(crash_point)
            with _G6_SYNTHETIC_RUNTIME_LOCK:
                _G6_SYNTHETIC_RUNTIME_REGISTRY[id(handle)] = {
                    "object": handle,
                    "session_id": existing_sessions[0].name,
                    "consumed_crash_points": consumed,
                    "committed_crash_points": committed,
                    "rehydrated_handle": True,
                    "unstarted_resume_issued": set(),
                }
            validate_g6_synthetic_root_handle(handle)
            verify_a4_state(bootstrap_lease, active_lease=lease)
            return handle
        parent = (
            CACHE_ROOT
            / str(state["attempt_id"])
            / "g6_synthetic_recovery"
        )
        ensure_directory(parent)
        _assert_safe_path_chain(parent)
        descriptor = _g6_parent_descriptor(parent)
        child_names = {
            "AFTER_CHECKPOINT_BEFORE_MANIFEST": (
                "scenario-after-checkpoint-before-manifest"
            ),
            "BEFORE_CHECKPOINT_COMMIT": (
                "scenario-before-checkpoint-commit"
            ),
            "BEFORE_STATUS_RENAME": "scenario-before-status-rename",
            "DURING_EVAL": "scenario-during-eval",
        }
        permitted = sorted(child_names)
        _require(
            descriptor["nlink"] == 2
            and all(
                not os.path.lexists(parent / child_name)
                for child_name in child_names.values()
            ),
            "G6 synthetic root parent must be pristine",
        )
        child_contract = {
            "schema_version": "c28f_a4_g6_child_root_contract_v1",
            "parent_root_id": "g6-synthetic-recovery-parent",
            "parent_descriptor_identity_sha256": semantic_sha256(
                descriptor
            ),
            "child_root_names": child_names,
            "permitted_crash_points": permitted,
            "precondition": "CANONICAL_ABSOLUTE_NONEXISTENT_CHILD",
            "same_parent_descriptor_required": True,
            "same_mount_required": True,
            "one_shot_per_child": True,
        }
        base = {
            "schema_version": "c28f_a4_g6_synthetic_root_handle_v1",
            "goal_id": GOAL_ID,
            "attempt_id": state["attempt_id"],
            "committed_transaction_id": state["transaction_id"],
            "committed_state_sha256": state["state_sha256"],
            "committed_event_sha256": events[-1]["event_sha256"],
            "parent_root_id": "g6-synthetic-recovery-parent",
            "parent_root_path": str(parent.resolve(strict=True)),
            "parent_descriptor_record": descriptor,
            "parent_descriptor_identity_sha256": semantic_sha256(
                descriptor
            ),
            "child_root_names": child_names,
            "permitted_crash_points": permitted,
            "child_root_contract_sha256": semantic_sha256(child_contract),
            "synthetic_only": True,
            "real_data_allowed": False,
            "one_shot_per_child": True,
        }
        payload = {
            **base,
            "handle_binding_sha256": semantic_sha256(base),
        }
        handle = _register_opaque_capability(
            A4G6SyntheticRootHandle(
                _OPAQUE_CONTROL_ISSUER_SEAL,
                payload,
                bootstrap_lease,
            )
        )
        session_id = _g6_synthetic_session_id(payload)
        record_base = {
            "schema_version": (
                "c28f_a4_g6_synthetic_root_handle_record_v1"
            ),
            "status": "FSYNCED_CONTROLLER_ISSUED",
            "capability_sha256": handle.capability_sha256,
            "payload": payload,
        }
        record = {
            **record_base,
            "record_sha256": semantic_sha256(record_base),
        }
        atomic_write_immutable(
            CONTROL_ROOT
            / "transactions"
            / session_id
            / "root_handle.json",
            _canonical_file_bytes(record),
            lease=lease,
        )
        with _G6_SYNTHETIC_RUNTIME_LOCK:
            _G6_SYNTHETIC_RUNTIME_REGISTRY[id(handle)] = {
                "object": handle,
                "session_id": session_id,
                "consumed_crash_points": set(),
                "committed_crash_points": set(),
                "rehydrated_handle": False,
                "unstarted_resume_issued": set(),
            }
        validate_g6_synthetic_root_handle(handle)
        verify_a4_state(bootstrap_lease, active_lease=lease)
        return handle


